-- Alice's Library -- traduções em português (leitura bilíngue).
-- Gerado por scripts/build-traducoes-sql.mjs a partir de public/alices-library/livros/*.pt.json. Não edite à mão.
-- Rodar DEPOIS de livros.sql e livros_texto.sql, na ordem dos números dos arquivos (00, 01, 02 ... e o último). Pode repetir: é um "upsert".
--
-- IMPORTANTE: o leitor do iPad lê as traduções dos arquivos livros/<slug>.pt.json que vão no app; rodar este SQL
-- NÃO é necessário para a leitura bilíngue funcionar. Ele guarda a mesma tradução no banco (consulta, backup,
-- revisão) e marca em public.livros quais livros têm tradução.

-- parte 1 de 10: 7 livros
begin;

-- anna-sewell_black-beauty (40 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('anna-sewell_black-beauty', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"myearlyhome":"Meu primeiro lar","thehunt":"A Caçada","mybreakingin":"Meu Adestramento"}$tr$::jsonb, $tr${"thefirstplacethaticanwellrememberwasalar~rookoverhungbyasteepbank~346":"O primeiro lugar de que consigo me lembrar bem era um grande e agradável pasto com um tanque de água limpa. Algumas árvores de boa sombra se debruçavam sobre ele, e juncos e ninfeias cresciam na parte funda. Do outro lado da cerca viva, de um lado, avistávamos um campo arado; do outro, por cima de um portão, a casa do nosso patrão, que ficava à beira da estrada. No alto do pasto havia um bosque de abetos, e embaixo um riacho corrente, sob a sombra de uma barranca íngreme.","whileiwasyoungiliveduponmymothersmilkasi~nicewarmshednearthegrove~209":"Enquanto eu era pequeno, vivia do leite de minha mãe, pois ainda não conseguia comer capim. De dia eu corria ao lado dela, e à noite me deitava bem junto a ela. Quando fazia calor, ficávamos junto ao tanque, à sombra das árvores, e quando fazia frio tínhamos um bom abrigo quente perto do bosque.","assoonasiwasoldenoughtoeatgrassmymotheru~eandcomebackintheevening~91":"Assim que tive idade para comer capim, minha mãe passou a sair para o trabalho durante o dia e a voltar à tardinha.","thereweresixyoungcoltsinthemeadowbesides~iteandkickaswellasgallop~270":"Havia no pasto, além de mim, seis potros; eram mais velhos do que eu, e alguns quase tão grandes quanto cavalos adultos. Eu corria com eles e me divertia muito; galopávamos todos juntos, voltas e mais voltas pelo campo, o mais depressa que podíamos. Às vezes a brincadeira era bastante rude, pois eles volta e meia mordiam e davam coices, além de galopar.","onedaywhentherewasagooddealofkickingmymo~ocometoherandthenshesaid~81":"Um dia, quando havia muito coice no ar, minha mãe relinchou para que eu fosse ter com ela, e então disse:","iwishyoutopayattentiontowhatiamgoingtosa~everbiteorkickeveninplay~482":"“Quero que você preste atenção ao que vou lhe dizer. Os potros que vivem aqui são muito bons potros, mas são potros de cavalo de carga e, naturalmente, não aprenderam boas maneiras. Você foi bem criado e nasceu de boa linhagem; seu pai tem grande nome por estas bandas, e seu avô ganhou a taça duas vezes nas corridas de Newmarket; sua avó tinha o gênio mais doce de todos os cavalos que conheci, e creio que você nunca me viu dar um coice ou uma mordida. Espero que cresça gentil e bom, e que nunca aprenda maus costumes; faça seu trabalho de boa vontade, levante bem as patas quando trotar, e nunca morda nem dê coices, nem mesmo de brincadeira.”","ihaveneverforgottenmymothersadviceiknews~ssbutheoftencalledherpet~131":"Nunca esqueci o conselho de minha mãe; eu sabia que ela era uma velha égua sensata, e o nosso patrão a tinha em alta conta. Chamava-se Duquesa, mas ele muitas vezes a chamava de Querida.","ourmasterwasagoodkindmanhegaveusgoodfood~nonamarketdayinalightgig~494":"O nosso patrão era um homem bom e gentil. Dava-nos boa comida, bom alojamento e palavras gentis; falava conosco com a mesma delicadeza com que falava com os filhinhos. Todos gostávamos dele, e minha mãe o amava muito. Quando o via no portão, relinchava de alegria e trotava até ele. Ele a afagava e acariciava e dizia: “Então, minha velha Querida, como vai o seu Escurinho?” Eu era de um preto fosco, por isso ele me chamava de Escurinho; depois me dava um pedaço de pão, que era uma delícia, e às vezes trazia uma cenoura para minha mãe. Todos os cavalos vinham ter com ele, mas acho que éramos os seus preferidos. Minha mãe sempre levava o patrão à cidade nos dias de feira, num cabriolé leve.","therewasaplowboydickwhosometimescameinto~sastonewouldhitandhurtus~260":"Havia um menino do arado, Dick, que às vezes entrava em nosso campo para colher amoras da cerca viva. Depois de comer quanto queria, fazia o que chamava de diversão com os potros, atirando pedras e paus para que galopassem. Não nos importávamos muito com ele, pois podíamos sair galopando; mas às vezes uma pedra nos acertava e machucava.","onedayhewasatthisgameanddidnotknowthatth~dupnearertoseewhatwenton~263":"Um dia ele estava nessa brincadeira e não sabia que o patrão estava no campo vizinho; mas ele estava ali, observando o que se passava; num pulo, transpôs a cerca viva e, agarrando Dick pelo braço, deu-lhe tamanho tapa no ouvido que o fez berrar de dor e de susto. Assim que vimos o patrão, trotamos mais para perto, para ver o que acontecia.","badboyhesaidbadboytochasethecoltsthisisn~ourmastersowewerewelloff~243":"“Menino mau!”, disse ele, “menino mau! Perseguir os potros! Não é a primeira vez, nem a segunda, mas será a última. Tome — pegue o seu dinheiro e vá para casa; não quero mais você na minha fazenda.” Assim, nunca mais vimos Dick. O velho Daniel, o homem que cuidava dos cavalos, era tão gentil quanto o nosso patrão, de modo que vivíamos bem.","beforeiwastwoyearsoldacircumstancehappen~ndseemedtoknowallaboutit~550":"Antes de eu completar dois anos, aconteceu uma coisa de que nunca me esqueci. Era o começo da primavera; tinha havido uma leve geada durante a noite, e uma névoa fina ainda pairava sobre os bosques e os prados. Eu e os outros potros pastávamos na parte baixa do campo quando ouvimos, bem ao longe, o que parecia ser o latido de cães. O mais velho dos potros ergueu a cabeça, empinou as orelhas e disse: “Lá vêm os cães de caça!” E logo saiu a meio galope, seguido por todos nós, até a parte alta do campo, de onde podíamos olhar por cima da sebe e ver vários campos mais adiante. Minha mãe e um velho cavalo de sela do nosso patrão também estavam por perto e pareciam saber tudo a respeito.","theyhavefoundaharesaidmymotherandiftheyc~thiswayweshallseethehunt~67":"“Eles levantaram uma lebre”, disse minha mãe, “e, se vierem para este lado, veremos a caçada.”","andsoonthedogswerealltearingdownthefield~iththeirnosestotheground~478":"E logo os cães desciam em disparada pelo trigal novo ao lado do nosso. Nunca ouvi barulho igual ao que faziam. Não latiam, nem uivavam, nem ganiam, mas seguiam com um “iô! iô, ô, ô! iô! iô, ô, ô!” a plenos pulmões. Depois deles veio uma porção de homens a cavalo, alguns de casaca verde, todos galopando o mais depressa que podiam. O velho cavalo bufou e acompanhou-os com o olhar ansioso, e nós, os potros, queríamos galopar com eles, mas logo sumiram pelos campos mais abaixo; ali pareceu que haviam parado; os cães deixaram de latir e corriam em todas as direções com o focinho rente ao chão.","theyhavelostthescentsaidtheoldhorseperha~perhapstheharewillgetoff~59":"“Perderam o rastro”, disse o velho cavalo. “Talvez a lebre escape.”","whathareisaid~whathareisaid~13":"“Que lebre?”, perguntei.","ohidontknowwhatharelikelyenoughitmaybeon~andhedgeoverhangthebrook~269":"“Ah! Não sei que lebre; bem pode ser uma das nossas lebres do bosque; qualquer lebre que encontrem serve para os cães e os homens correrem atrás”; e, pouco depois, os cães recomeçaram o seu “iô! iô, ô, ô!”, e voltaram todos juntos a toda a velocidade, direto para o nosso prado, no ponto em que o barranco alto e a sebe pendem sobre o riacho.","nowweshallseetheharesaidmymotherandjustt~ntlemenseemedwellpleased~553":"“Agora vamos ver a lebre”, disse minha mãe; e naquele instante uma lebre, louca de pavor, passou correndo e tomou o rumo do bosque. Vieram os cães; irromperam por cima do barranco, saltaram o riacho e atravessaram o campo em desabalada, seguidos pelos caçadores. Seis ou oito homens fizeram os cavalos saltar limpamente, bem colados aos cães. A lebre tentou passar pela cerca; era espessa demais, e ela deu meia-volta bruscamente para ganhar a estrada, mas era tarde; os cães caíram sobre ela com seus gritos selvagens; ouvimos um só guincho, e foi o fim dela. Um dos caçadores aproximou-se e afastou a chicotadas os cães, que logo a teriam feito em pedaços. Ergueu-a pela pata, dilacerada e sangrando, e todos os cavalheiros pareciam muito satisfeitos.","asformeiwassoastonishedthatididnotatfirs~mudtheotherlayquitestill~252":"Quanto a mim, estava tão atônito que no começo não vi o que se passava junto ao riacho; mas, quando olhei, vi uma cena triste: dois belos cavalos tinham caído, um debatia-se na água e o outro gemia sobre a relva. Um dos cavaleiros saía da água coberto de lama; o outro jazia imóvel.","hisneckisbrokesaidmymother~sneckisbrokesaidmymother~26":"“Quebrou o pescoço”, disse minha mãe.","andservehimrighttoosaidoneofthecolts~ighttoosaidoneofthecolts~36":"“E bem feito”, disse um dos potros.","ithoughtthesamebutmymotherdidnotjoinwith~mymotherdidnotjoinwithus~42":"Pensei o mesmo, mas minha mãe não nos acompanhou.","wellnoshesaidyoumustnotsaythatbutthoughi~areonlyhorsesanddontknow~283":"“Pois não”, disse ela, “não devem dizer isso; mas, embora eu seja um cavalo velho e tenha visto e ouvido muita coisa, nunca consegui entender por que os homens gostam tanto desse esporte; muitas vezes se machucam, muitas vezes estragam bons cavalos e destroem os campos, e tudo por uma lebre, uma raposa ou um veado que poderiam obter mais facilmente de outro modo; mas nós somos apenas cavalos e não entendemos.”","whilemymotherwassayingthiswestoodandlook~anandtheprideofhisfamily~406":"Enquanto minha mãe dizia isso, ficamos olhando. Muitos dos cavaleiros haviam ido até o rapaz; mas foi o nosso patrão, que acompanhava tudo, o primeiro a levantá-lo. A cabeça pendeu para trás e os braços caíram, e todos ficaram muito sérios. Já não havia barulho; até os cães se aquietaram, como se soubessem que algo andava mal. Levaram-no para a casa do nosso patrão. Soube depois que era o jovem George Gordon, filho único do fidalgo, um rapaz alto e bonito, orgulho da família.","therewasnowridingoffinalldirectionstothe~theblackhorsemovednomore~366":"Agora cavaleiros partiam em todas as direções, para a casa do médico, para a do ferrador e, sem dúvida, para a do fidalgo Gordon, a fim de avisá-lo sobre o filho. Quando o sr. Bond, o ferrador, veio examinar o cavalo preto que jazia gemendo na relva, apalpou-o todo e sacudiu a cabeça: uma das pernas estava quebrada. Então alguém correu à casa do nosso patrão e voltou com uma espingarda; logo houve um estampido forte e um grito horrível, e depois tudo ficou em silêncio; o cavalo preto não se mexeu mais.","mymotherseemedmuchtroubledshesaidshehadk~tpartofthefieldafterward~165":"Minha mãe pareceu muito abalada; disse que conhecia aquele cavalo havia anos, que se chamava Rob Roy, que era um bom cavalo e não tinha vício algum. Nunca mais quis ir àquela parte do campo.","notmanydaysafterweheardthechurchbelltoll~ttwasallforonelittlehare~369":"Poucos dias depois ouvimos o sino da igreja dobrar por muito tempo, e, olhando por cima da porteira, vimos uma carruagem comprida e estranha, toda coberta de pano preto e puxada por cavalos pretos; depois dela veio outra, e outra, e outra, todas negras, enquanto o sino não parava de dobrar, dobrar. Levavam o jovem Gordon ao cemitério para enterrá-lo. Nunca mais montaria. O que fizeram de Rob Roy, nunca soube; mas foi tudo por causa de uma pobre lebre.","iwasnowbeginningtogrowhandsomemycoathadg~tilltheywerequitegrownup~271":"Eu começava a ficar bonito; a pelagem tornara-se fina e macia, de um preto brilhante. Tinha um pé branco e uma linda estrela branca na testa. Achavam-me muito belo; meu patrão não quis me vender antes dos quatro anos; dizia que os rapazes não deviam trabalhar como homens, nem os potros como cavalos, até estarem completamente crescidos.","wheniwasfouryearsoldsquiregordoncametolo~utitforthenextdayhebegan~317":"Quando fiz quatro anos, o fidalgo Gordon veio me ver. Examinou meus olhos, minha boca e minhas pernas; apalpou-as de alto a baixo; depois tive de andar, trotar e galopar diante dele. Pareceu gostar de mim e disse: “Quando estiver bem adestrado, servirá muito bem.” Meu patrão disse que ele mesmo me adestraria, pois não queria que eu me assustasse ou me machucasse, e não perdeu tempo, pois no dia seguinte começou.","everyonemaynotknowwhatbreakinginistheref~sbreakinginisagreatthing~649":"Nem todos sabem o que é adestrar um cavalo, por isso vou descrever. Significa ensinar o cavalo a usar sela e freio, e a levar nas costas um homem, uma mulher ou uma criança; a ir exatamente como desejam e a ir tranquilo. Além disso, tem de aprender a usar a coleira, a retranca e o apoio de quadril, e a ficar parado enquanto os põem; depois, a ter uma carroça ou uma charrete atrelada atrás de si, de modo que não possa andar nem trotar sem arrastá-la; e deve ir depressa ou devagar, conforme queira o condutor. Nunca deve se espantar com o que vê, nem falar com outros cavalos, nem morder, nem dar coices, nem ter vontade própria; deve sempre fazer a vontade do patrão, ainda que esteja muito cansado ou com fome; mas o pior de tudo é que, uma vez posto o arreio, não pode saltar de alegria nem deitar-se de cansaço. Veja, pois, que adestrar é coisa séria.","ihadofcourselongbeenusedtoahalterandahea~igottowearmybitandbridle~775":"Eu, é claro, havia muito estava habituado ao cabresto e à cabeçada, e a ser levado calmamente pelos campos e caminhos, mas agora ia ter freio e rédeas; meu patrão me deu aveia como de costume e, depois de muito agrado, conseguiu pôr-me o freio na boca e ajustar as rédeas, mas que coisa desagradável! Quem nunca teve um freio na boca não imagina como é horrível: um grande pedaço de aço frio e duro, grosso como um dedo de homem, enfiado na boca, entre os dentes e por cima da língua, com as pontas saindo pelos cantos da boca e presas ali por correias que passam sobre a cabeça, sob a garganta, em volta do focinho e sob o queixo; de modo que não há meio no mundo de livrar-se da coisa dura e nojenta; é muito ruim! Sim, muito ruim! Pelo menos pensei assim; mas sabia que minha mãe sempre usava um quando saía, e que todos os cavalos o faziam depois de crescidos; e assim, entre a boa aveia e os afagos, as palavras bondosas e os modos gentis do meu patrão, acabei me acostumando ao freio e às rédeas.","nextcamethesaddlebutthatwasnothalfsobadm~soonbecameaccustomedtoit~459":"Depois veio a sela, mas essa não foi nem a metade de tão ruim; meu patrão a pôs nas minhas costas com muita delicadeza, enquanto o velho Daniel segurava minha cabeça; em seguida apertou as cilhas sob o meu corpo, afagando-me e falando comigo o tempo todo; depois me deu um pouco de aveia, depois um passeio puxado pela rédea; e fez isso todos os dias até que eu passasse a esperar pela aveia e pela sela. Por fim, certa manhã, meu patrão montou em mim e me levou a passeio pelo prado, sobre a relva macia. Certamente era estranho; mas devo dizer que me senti bastante orgulhoso de carregar meu patrão, e, como ele continuou a me montar um pouco todos os dias, logo me acostumei.","thenextunpleasantbusinesswasputtingonthe~avybutintimeigotusedtoit~441":"O incômodo seguinte foi pôr as ferraduras de ferro; isso também foi muito duro no começo. Meu patrão foi comigo à forja do ferreiro, para ver que eu não me ferisse nem me assustasse. O ferreiro tomou meus cascos na mão, um depois do outro, e aparou um pouco do casco. Não doeu, e fiquei parado sobre três pernas até ele terminar todos. Depois pegou uma peça de ferro do feitio do meu pé e a aplicou, e cravou alguns pregos através da ferradura, até dentro do casco, de modo que ficasse bem firme. Meus pés pareciam rígidos e pesados, mas com o tempo me acostumei.","andnowhavinggotsofarmymasterwentontobrea~domyworkaswellasmymother~547":"E agora, tendo chegado até ali, meu patrão passou a me adestrar para o arreio; havia mais coisas novas para usar. Primeiro, uma coleira dura e pesada no pescoço, e uma cabeçada com grandes abas laterais junto aos olhos, chamadas antolhos, e antolhos eram mesmo, pois eu não podia ver nada dos lados, apenas à frente; depois, uma pequena sela com uma correia dura e desagradável que passava bem por baixo da cauda; era a retranca. Eu odiava a retranca; ter a cauda comprida dobrada e enfiada naquela correia era quase tão ruim quanto o freio. Nunca tive tanta vontade de dar coices, mas é claro que não podia dar coices num patrão tão bom, e assim, com o tempo, acostumei-me a tudo e passei a fazer meu trabalho tão bem quanto minha mãe.","imustnotforgettomentiononepartofmytraini~andiwasturnedinamongthem~232":"Não devo esquecer de mencionar uma parte do meu adestramento que sempre considerei uma grande vantagem. Meu patrão me mandou por quinze dias à casa de um fazendeiro vizinho, que tinha um prado margeado de um lado pela estrada de ferro. Havia ali algumas ovelhas e vacas, e fui solto no meio delas.","ishallneverforgetthefirsttrainthatranbyi~mepuffingandgrindingpast~653":"Nunca esquecerei o primeiro trem que passou. Eu pastava tranquilo perto da cerca que separava o prado da ferrovia quando ouvi um som estranho ao longe, e, antes que soubesse de onde vinha — com um estrondo e um chacoalhar, soltando fumaça —, uma comprida coisa negra passou voando e sumiu quase antes que eu pudesse tomar fôlego. Dei meia-volta e galopei até o outro extremo do prado o mais depressa que pude, e ali fiquei, bufando de espanto e medo. No decorrer do dia passaram muitos outros trens, alguns mais devagar; estes paravam na estação ali perto e às vezes davam um guincho e um gemido terríveis antes de parar. Achei tudo muito assustador, mas as vacas continuavam a comer muito sossegadas e mal erguiam a cabeça quando a coisa negra e pavorosa passava bufando e rangendo.","forthefirstfewdaysicouldnotfeedinpeacebu~rainasthecowsandsheepdid~195":"Nos primeiros dias não consegui pastar em paz; mas, vendo que aquela criatura terrível nunca entrava no campo nem me fazia mal, passei a ignorá-la, e muito em breve ligava tão pouco para a passagem de um trem quanto as vacas e as ovelhas.","sincethenihaveseenmanyhorsesmuchalarmeda~ystationsasinmyownstable~153":"Desde então vi muitos cavalos muito assustados e arredios à vista ou ao som de uma locomotiva; mas, graças aos cuidados do meu bom patrão, sou tão destemido nas estações de trem quanto na minha própria cocheira.","nowifanyonewantstobreakinayounghorsewell~unghorsewellthatistheway~52":"Pois bem, se alguém quiser adestrar bem um cavalo jovem, é assim que se faz.","mymasteroftendrovemeindoubleharnesswithm~tisandkeepupyourgoodname~703":"Meu patrão me atrelava muitas vezes em parelha com minha mãe, porque ela era firme e podia me ensinar a andar melhor do que um cavalo desconhecido. Ela me dizia que, quanto melhor eu me comportasse, melhor seria tratado, e que o mais sensato era sempre me esforçar por agradar ao patrão, “mas”, dizia ela, “há muitas espécies de homens; há homens bons e ponderados como o nosso patrão, a quem qualquer cavalo pode se orgulhar de servir; e há homens maus e cruéis, que jamais deveriam ter um cavalo ou um cão para chamar de seu. Além disso, há muitos homens tolos, vaidosos, ignorantes e descuidados, que nunca se dão ao trabalho de pensar; esses estragam mais cavalos do que todos, só por falta de juízo; não é por querer, mas fazem-no assim mesmo. Espero que você caia em boas mãos; mas um cavalo nunca sabe quem o vai comprar, nem quem o vai conduzir; é tudo sorte para nós; mas, ainda assim, digo: faça o melhor que puder onde quer que esteja, e mantenha o seu bom nome.”"}$tr$::jsonb, 40)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- arthur-conan-doyle_a-study-in-scarlet (231 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('arthur-conan-doyle_a-study-in-scarlet', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"mrsherlockholmes":"O sr. Sherlock Holmes","thescienceofdeduction":"A Ciência da Dedução","thelauristongardensmystery":"O Mistério de Lauriston Gardens"}$tr$::jsonb, $tr${"intheyear1878itookmydegreeofdoctorofmedi~ceentereduponmynewduties~581":"No ano de 1878 recebi o grau de Doutor em Medicina pela Universidade de Londres e segui para Netley, a fim de fazer o curso prescrito para os cirurgiões do exército. Concluídos ali os estudos, fui devidamente designado Cirurgião Assistente do Quinto Regimento de Fuzileiros de Northumberland. O regimento estava então estacionado na Índia e, antes que eu pudesse juntar-me a ele, estourou a segunda guerra afegã. Ao desembarcar em Bombaim, soube que meu corpo de tropas havia avançado através dos desfiladeiros e já se achava bem dentro do território inimigo. Segui-o, contudo, com muitos outros oficiais que estavam na mesma situação que eu, e consegui chegar a salvo a Candahar, onde encontrei meu regimento e logo assumi as novas funções.","thecampaignbroughthonoursandpromotiontom~esafelytothebritishlines~449":"A campanha trouxe honrarias e promoções a muitos, mas para mim nada trouxe além de infortúnio e desastre. Fui retirado de minha brigada e destacado para os Berkshires, com os quais servi na fatídica batalha de Maiwand. Ali fui atingido no ombro por uma bala de Jezail, que me estilhaçou o osso e roçou a artéria subclávia. Teria caído nas mãos dos sanguinários Ghazis, não fosse a dedicação e a coragem de Murray, meu ordenança, que me atirou sobre um cavalo de carga e conseguiu levar-me são e salvo até as linhas britânicas.","wornwithpainandweakfromtheprolongedhards~sinattemptingtoimproveit~671":"Consumido pela dor e fraco pelos longos sofrimentos que suportara, fui removido, com um grande comboio de feridos, para o hospital da base em Peshawar. Ali me recuperei e já havia melhorado o bastante para andar pelas enfermarias, e até para tomar um pouco de sol na varanda, quando fui derrubado pela febre entérica, essa praga de nossas possessões indianas. Durante meses desesperaram de minha vida e, quando por fim voltei a mim e entrei em convalescença, estava tão fraco e emaciado que uma junta médica determinou que não se perdesse um só dia em me mandar de volta à Inglaterra. Fui, portanto, despachado no navio de transporte de tropas Orontes e desembarquei, um mês depois, no cais de Portsmouth, com a saúde irremediavelmente arruinada, mas com licença de um governo paternal para passar os nove meses seguintes tentando melhorá-la.","ihadneitherkithnorkininenglandandwasther~andlessexpensivedomicile~706":"Não tinha na Inglaterra parentes nem amigos e era, por isso, livre como o ar — ou tão livre quanto uma renda de onze xelins e seis pence por dia permite que um homem seja. Em tais circunstâncias, gravitei naturalmente para Londres, esse grande esgoto para onde são irresistivelmente drenados todos os ociosos e vadios do Império. Fiquei ali algum tempo num hotel particular na Strand, levando uma existência sem conforto e sem sentido, e gastando o dinheiro que tinha de modo bem mais liberal do que devia. O estado de minhas finanças tornou-se tão alarmante que logo percebi que precisava ou deixar a metrópole e ir me enterrar em algum recanto do campo, ou mudar por completo meu estilo de vida. Escolhendo a segunda alternativa, comecei por decidir deixar o hotel e instalar-me em alguma morada menos pretensiosa e menos dispendiosa.","ontheverydaythatihadcometothisconclusion~rtedofftogetherinahansom~468":"No mesmo dia em que cheguei a essa conclusão, eu estava de pé no bar do Criterion quando alguém me tocou o ombro e, voltando-me, reconheci o jovem Stamford, que fora meu auxiliar de curativos em Barts. A visão de um rosto amigo no grande ermo de Londres é coisa deveras agradável para um homem solitário. Nos velhos tempos, Stamford nunca fora um companheiro particularmente íntimo, mas agora o saudei com entusiasmo e ele, por sua vez, pareceu encantado em me ver. Na exuberância de minha alegria, convidei-o para almoçar comigo no Holborn, e partimos juntos num cabriolé.","whateverhaveyoubeendoingwithyourselfwats~nasalathandasbrownasanut~144":"“Que diabo você andou fazendo consigo mesmo, Watson?”, perguntou ele, com um espanto sem disfarce, enquanto nosso carro sacolejava pelas ruas apinhadas de Londres. “Você está magro como uma ripa e moreno como uma noz.”","igavehimashortsketchofmyadventuresandhad~twereachedourdestination~93":"Fiz-lhe um breve resumo das minhas aventuras, e mal o havia concluído quando chegamos ao nosso destino.","poordevilhesaidcommiseratinglyafterhehad~ortuneswhatareyouuptonow~80":"“Pobre diabo!”, disse ele, compadecido, depois de ouvir minhas desventuras. “E o que anda fazendo agora?”","lookingforlodgingsiansweredtryingtosolve~eroomsatareasonableprice~112":"“Procurando alojamento”, respondi. “Tentando resolver o problema de saber se é possível conseguir quartos confortáveis por um preço razoável.”","thatsastrangethingremarkedmycompanionyou~asusedthatexpressiontome~89":"“Que coisa curiosa”, observou meu companheiro; “você é o segundo homem, hoje, que usa essa expressão comigo.”","andwhowasthefirstiasked~andwhowasthefirstiasked~23":"“E quem foi o primeiro?”, perguntei.","afellowwhoisworkingatthechemicallaborato~chweretoomuchforhispurse~193":"“Um sujeito que trabalha no laboratório de química do hospital. Lamentava-se esta manhã porque não conseguia arranjar alguém que dividisse com ele uns bons aposentos que encontrou, e que são demais para o seu bolso.”","byjoveicriedifhereallywantssomeonetoshar~vingapartnertobeingalone~120":"“Por Júpiter!”, exclamei, “se ele realmente quer alguém para dividir os aposentos e a despesa, eu sou o homem certo. Prefiro ter um companheiro a ficar sozinho.”","youngstamfordlookedratherstrangelyatmeov~rhimasaconstantcompanion~136":"O jovem Stamford olhou-me de um jeito algo estranho por cima da taça de vinho. “Você ainda não conhece Sherlock Holmes”, disse ele; “talvez não lhe agradasse como companhia constante.”","whywhatisthereagainsthim~whywhatisthereagainsthim~24":"“Ora, o que há contra ele?”","ohididntsaytherewasanythingagainsthimhei~wheisadecentfellowenough~133":"“Oh, não disse que houvesse algo contra ele. Tem ideias um tanto esquisitas; é um entusiasta de certos ramos da ciência. Até onde sei, é um sujeito bastante decente.”","amedicalstudentisupposesaidi~icalstudentisupposesaidi~28":"“Um estudante de medicina, suponho?”, disse eu.","noihavenoideawhatheintendstogoinforibeli~uldastonishhisprofessors~257":"“Não; não faço ideia do que pretende seguir. Creio que entende bem de anatomia, e é um químico de primeira ordem; mas, até onde sei, nunca frequentou cursos regulares de medicina. Seus estudos são muito desordenados e excêntricos, mas acumulou um bocado de conhecimentos fora do comum que espantariam seus professores.”","didyouneveraskhimwhathewasgoinginforiask~hathewasgoinginforiasked~42":"“Nunca lhe perguntou o que pretende seguir?”, indaguei.","noheisnotamanthatitiseasytodrawoutthough~ughwhenthefancyseizeshim~87":"“Não; não é homem fácil de fazer falar, embora possa ser bastante comunicativo quando lhe dá na veneta.”","ishouldliketomeethimisaidifiamtolodgewit~ldimeetthisfriendofyours~239":"“Gostaria de conhecê-lo”, disse eu. “Se vou morar com alguém, prefiro um homem de hábitos estudiosos e tranquilos. Ainda não tenho forças para suportar muito barulho ou agitação. Tive de ambos no Afeganistão o bastante para o resto da minha existência natural. Como poderia conhecer esse seu amigo?”","heissuretobeatthelaboratoryreturnedmycom~undtogetherafterluncheon~159":"“Com certeza está no laboratório”, respondeu meu companheiro. “Ou evita o lugar por semanas, ou trabalha lá da manhã à noite. Se quiser, iremos juntos depois do almoço.”","certainlyiansweredandtheconversationdrif~tedawayintootherchannels~64":"“Certamente”, respondi, e a conversa derivou para outros assuntos.","aswemadeourwaytothehospitalafterleavingt~sedtotakeasafellowlodger~133":"Enquanto seguíamos para o hospital depois de deixar o Holborn, Stamford me deu mais alguns pormenores sobre o cavalheiro que eu me propunha tomar como companheiro de moradia.","youmustntblamemeifyoudontgetonwithhimhes~mustnotholdmeresponsible~176":"“Não me culpe se não se der bem com ele”, disse. “Nada sei dele além do que aprendi encontrando-o de vez em quando no laboratório. A proposta do arranjo foi sua, portanto não me responsabilize.”","ifwedontgetonitwillbeeasytopartcompanyia~ontbemealymouthedaboutit~213":"“Se não nos dermos bem, será fácil nos separarmos”, respondi. “Parece-me, Stamford”, acrescentei, fitando firmemente meu companheiro, “que você tem algum motivo para lavar as mãos do assunto. O gênio do homem é assim tão temível, ou o que é? Não seja evasivo.”","itisnoteasytoexpresstheinexpressiblehean~efiniteandexactknowledge~409":"“Não é fácil exprimir o inexprimível”, respondeu ele rindo. “Holmes é um pouco científico demais para o meu gosto; chega às raias da frieza. Eu o imagino dando a um amigo uma pitada do mais recente alcaloide vegetal, não por maldade, entenda, mas simplesmente por espírito de investigação, para ter uma ideia exata dos efeitos. Para ser justo com ele, creio que tomaria a dose com a mesma presteza. Parece ter paixão pelo conhecimento definido e exato.”","veryrighttoo~veryrighttoo~12":"“E com toda a razão.”","yesbutitmaybepushedtoexcesswhenitcomesto~akingratherabizarreshape~126":"“Sim, mas pode ser levado ao excesso. Quando chega ao ponto de espancar com uma vara os cadáveres nas salas de dissecação, toma sem dúvida uma forma bastante bizarra.”","beatingthesubjects~beatingthesubjects~18":"“Espancar os cadáveres!”","yestoverifyhowfarbruisesmaybeproducedaft~isawhimatitwithmyowneyes~71":"“Sim, para verificar até que ponto se podem produzir contusões depois da morte. Vi-o fazer isso com meus próprios olhos.”","andyetyousayheisnotamedicalstudent~ayheisnotamedicalstudent~34":"“E no entanto você diz que ele não é estudante de medicina?”","noheavenknowswhattheobjectsofhisstudiesa~dtothechemicallaboratory~431":"“Não. Só Deus sabe quais são os objetivos de seus estudos. Mas aqui estamos, e você deve formar suas próprias impressões sobre ele.” Enquanto falava, entramos por uma ruela estreita e atravessamos uma pequena porta lateral, que dava para uma ala do grande hospital. Era terreno familiar para mim, e não precisei de guia quando subimos a árida escadaria de pedra e percorremos o longo corredor, com sua perspectiva de paredes caiadas e portas cor de terra. Perto da outra extremidade, uma passagem baixa em arco desviava-se dele e levava ao laboratório de química.","thiswasaloftychamberlinedandlitteredwith~haveshoneuponhisfeatures~534":"Era uma sala alta, forrada e atulhada de incontáveis frascos. Mesas largas e baixas estavam espalhadas pelo recinto, eriçadas de retortas, tubos de ensaio e pequenos bicos de Bunsen, com suas chamas azuis tremulantes. Havia apenas um estudante na sala, debruçado sobre uma mesa distante, absorto em seu trabalho. Ao som de nossos passos, olhou em volta e ergueu-se de um salto, com um grito de prazer. “Achei! Achei!”, gritou para meu companheiro, correndo em nossa direção com um tubo de ensaio na mão. “Descobri um reagente que é precipitado pela hemoglobina, e por nada mais.” Se tivesse descoberto uma mina de ouro, não poderia brilhar em seu rosto maior deleite.","drwatsonmrsherlockholmessaidstamfordintr~aidstamfordintroducingus~49":"“Dr. Watson, Sr. Sherlock Holmes”, disse Stamford, apresentando-nos.","howareyouhesaidcordiallygrippingmyhandwi~eninafghanistaniperceive~123":"“Como vai?”, disse ele cordialmente, apertando minha mão com uma força que eu mal lhe teria atribuído. “O senhor esteve no Afeganistão, percebo.”","howonearthdidyouknowthatiaskedinastonish~thatiaskedinastonishment~44":"“Como diabos soube disso?”, perguntei, atônito.","nevermindsaidhechucklingtohimselftheques~nceofthisdiscoveryofmine~114":"“Não importa”, disse ele, rindo consigo mesmo. “A questão agora é a hemoglobina. Sem dúvida vê a importância desta minha descoberta?”","itisinterestingchemicallynodoubtianswere~tiansweredbutpractically~55":"“É interessante, quimicamente, sem dúvida”, respondi, “mas na prática...”","whymanitisthemostpracticalmedicolegaldis~tothebottomoftheglassjar~735":"“Ora, homem, é a descoberta médico-legal mais prática em anos. Não vê que nos dá um teste infalível para manchas de sangue? Venha cá!” Agarrou-me pela manga do casaco, em seu entusiasmo, e puxou-me até a mesa em que trabalhava. “Vamos ter um pouco de sangue fresco”, disse, enterrando uma longa agulha no dedo e recolhendo a gota resultante numa pipeta química. “Agora acrescento esta pequena quantidade de sangue a um litro de água. Vê que a mistura resultante tem o aspecto de água pura. A proporção de sangue não pode passar de um para um milhão. No entanto, não tenho dúvida de que conseguiremos obter a reação característica.” Enquanto falava, lançou no recipiente alguns cristais brancos e depois acrescentou algumas gotas de um fluido transparente. Num instante o conteúdo assumiu uma cor opaca de mogno, e um pó acastanhado precipitou-se ao fundo do jarro de vidro.","hahahecriedclappinghishandsandlookingasd~wtoywhatdoyouthinkofthat~87":"“Ha! ha!”, gritou, batendo palmas e parecendo tão deliciado quanto uma criança com um brinquedo novo. “O que acha disso?”","itseemstobeaverydelicatetestiremarked~erydelicatetestiremarked~37":"“Parece ser um teste muito delicado”, comentei.","beautifulbeautifultheoldguiacumtestwasve~dthepenaltyoftheircrimes~311":"“Lindo! Lindo! O velho teste do guáiaco era muito grosseiro e incerto. O mesmo vale para o exame microscópico dos glóbulos de sangue. Este último não tem valor se as manchas têm algumas horas. Ora, este parece agir igualmente bem, seja o sangue velho ou novo. Se este teste tivesse sido inventado, há centenas de homens que hoje andam sobre a terra que há muito teriam pago a pena de seus crimes.”","indeedimurmured~indeedimurmured~15":"“Verdade!”, murmurei.","criminalcasesarecontinuallyhinginguponth~lnolongerbeanydifficulty~381":"“Casos criminais dependem continuamente desse único ponto. Um homem é suspeito de um crime talvez meses depois de cometido. Examinam-lhe a roupa branca ou as vestes e descobrem manchas acastanhadas. São manchas de sangue, ou de lama, ou de ferrugem, ou de fruta, ou o que são? Essa é uma questão que intrigou muitos peritos, e por quê? Porque não havia um teste confiável. Agora temos o teste de Sherlock Holmes, e não haverá mais dificuldade.”","hiseyesfairlyglitteredashespokeandheputh~njuredupbyhisimagination~117":"Seus olhos literalmente cintilavam enquanto falava, e ele pôs a mão sobre o coração e fez uma reverência, como a uma multidão aplaudindo, conjurada por sua imaginação.","youaretobecongratulatediremarkedconsider~surprisedathisenthusiasm~68":"“Merece ser felicitado”, comentei, consideravelmente surpreso com seu entusiasmo.","therewasthecaseofvonbischoffatfrankfortl~hitwouldhavebeendecisive~246":"“Houve o caso de Von Bischoff em Frankfurt, no ano passado. Teria sido certamente enforcado se este teste existisse. Depois houve Mason, de Bradford, e o famigerado Muller, e Lefevre, de Montpellier, e Samson, de Nova Orleans. Poderia citar uma vintena de casos em que teria sido decisivo.”","youseemtobeawalkingcalendarofcrimesaidst~itthepolicenewsofthepast~115":"“Você parece um calendário ambulante do crime”, disse Stamford rindo. “Podia fundar um jornal nesses moldes. Chamá-lo de Notícias Policiais do Passado.”","veryinterestingreadingitmightbemadetoore~scolouredwithstrongacids~303":"“Poderia fazer-se também uma leitura muito interessante”, observou Sherlock Holmes, colando um pequeno pedaço de esparadrapo sobre a picada no dedo. “Preciso ter cuidado”, continuou, voltando-se para mim com um sorriso, “pois mexo bastante com venenos.” Estendeu a mão ao falar, e notei que estava toda salpicada de pedaços de esparadrapo semelhantes e descorada por ácidos fortes.","wecamehereonbusinesssaidstamfordsittingd~adbetterbringyoutogether~239":"“Viemos aqui a negócios”, disse Stamford, sentando-se num alto banco de três pernas e empurrando outro na minha direção com o pé. “Meu amigo aqui quer alugar um alojamento, e como você se queixava de não achar ninguém para dividir as despesas, pensei que o melhor era juntá-los.”","sherlockholmesseemeddelightedattheideaof~mellofstrongtobaccoihope~168":"Sherlock Holmes pareceu encantado com a ideia de dividir seus aposentos comigo. “Tenho em vista uns cômodos na Baker Street”, disse, “que nos serviriam às mil maravilhas. Não se importa com o cheiro de fumo forte, espero?”","ialwayssmokeshipsmyselfianswered~mokeshipsmyselfianswered~32":"“Eu mesmo sempre fumo o ‘de bordo’”, respondi.","thatsgoodenoughigenerallyhavechemicalsab~rimentswouldthatannoyyou~88":"“Está ótimo. Em geral tenho produtos químicos por perto e de vez em quando faço experiências. Isso o incomodaria?”","bynomeans~bynomeans~9":"“De modo algum.”","letmeseewhataremyothershortcomingsigetin~etheybegintolivetogether~254":"“Deixe-me ver, quais são meus outros defeitos? Fico abatido às vezes e não abro a boca por dias seguidos. Não pense que estou emburrado quando faço isso. Deixe-me em paz e logo estarei bem. E o senhor, o que tem a confessar? É bom que dois sujeitos conheçam o pior um do outro antes de começarem a viver juntos.”","ilaughedatthiscrossexaminationikeepabull~heprincipalonesatpresent~208":"Ri-me desse interrogatório. “Tenho um buldogue filhote”, disse, “e sou contra brigas porque meus nervos estão abalados, levanto-me a todo tipo de horas indecentes e sou extremamente preguiçoso. Tenho outro conjunto de vícios quando estou bem, mas esses são os principais no momento.”","doyouincludeviolinplayinginyourcategoryo~ryofrowsheaskedanxiously~61":"“Inclui o violino na sua categoria de barulhos?”, perguntou ele, ansioso.","itdependsontheplayeriansweredawellplayed~orthegodsabadlyplayedone~79":"“Depende do tocador”, respondi. “Um violino bem tocado é um regalo para os deuses; um mal tocado...”","ohthatsallrighthecriedwithamerrylaughith~heroomsareagreeabletoyou~106":"“Oh, está tudo certo”, exclamou, com uma risada alegre. “Penso que podemos considerar a coisa resolvida, isto é, se os aposentos lhe agradarem.”","whenshallweseethem~whenshallweseethem~18":"“Quando poderemos vê-los?”","callformehereatnoontomorrowandwellgotoge~ttleeverythingheanswered~73":"“Passe aqui para me buscar amanhã ao meio-dia, e iremos juntos resolver tudo”, respondeu.","allrightnoonexactlysaidishakinghishand~actlysaidishakinghishand~38":"“Muito bem, meio-dia em ponto”, disse eu, apertando-lhe a mão.","welefthimworkingamonghischemicalsandwewa~edtogethertowardsmyhotel~66":"Deixamo-lo trabalhando entre seus produtos químicos e seguimos juntos em direção ao meu hotel.","bythewayiaskedsuddenlystoppingandturning~tihadcomefromafghanistan~99":"“A propósito”, perguntei de repente, parando e voltando-me para Stamford, “como diabos ele soube que eu vinha do Afeganistão?”","mycompanionsmiledanenigmaticalsmilethats~oknowhowhefindsthingsout~120":"Meu companheiro sorriu um sorriso enigmático. “Essa é justamente a sua pequena peculiaridade”, disse. “Muita gente já quis saber como ele descobre as coisas.”","ohamysteryisiticriedrubbingmyhandsthisis~udyofmankindismanyouknow~126":"“Oh! Então é um mistério?”, exclamei, esfregando as mãos. “Isto é muito picante. Fico-lhe muito grato por nos ter juntado. ‘O estudo próprio da humanidade é o homem’, como sabe.”","youmuststudyhimthenstamfordsaidashebadem~outhanyouabouthimgoodbye~130":"“Então terá de estudá-lo”, disse Stamford, ao se despedir de mim. “Mas vai achá-lo um problema espinhoso. Aposto que ele aprenderá mais sobre você do que você sobre ele. Até logo.”","goodbyeiansweredandstrolledontomyhotelco~estedinmynewacquaintance~79":"“Até logo”, respondi, e caminhei sem pressa até meu hotel, consideravelmente interessado em meu novo conhecido.","wemetnextdayashehadarrangedandinspectedt~lvestoournewsurroundings~664":"Encontramo-nos no dia seguinte, como ele combinara, e inspecionamos os cômodos do nº 221B da Baker Street, de que ele falara em nosso encontro. Consistiam em um par de quartos confortáveis e uma única sala de estar ampla e arejada, alegremente mobiliada e iluminada por duas janelas largas. Tão desejáveis em todos os aspectos eram os aposentos, e tão moderadas pareciam as condições quando divididas entre nós, que o negócio foi fechado ali mesmo e tomamos posse de imediato. Naquela mesma noite mudei minhas coisas do hotel e, na manhã seguinte, Sherlock Holmes me seguiu com várias caixas e malas. Por um ou dois dias ficamos atarefados desembalando e dispondo nossos pertences da melhor maneira. Feito isso, começamos aos poucos a nos assentar e a nos acomodar ao novo ambiente.","holmeswascertainlynotadifficultmantolive~lifeforbiddensuchanotion~724":"Holmes certamente não era um homem difícil de se conviver. Era tranquilo em seus modos, e seus hábitos eram regulares. Raramente estava de pé depois das dez da noite, e invariavelmente já tomara o desjejum e saíra antes de eu me levantar pela manhã. Às vezes passava o dia no laboratório de química, às vezes nas salas de dissecação e, ocasionalmente, em longas caminhadas que pareciam levá-lo aos bairros mais baixos da City. Nada podia exceder sua energia quando o acesso de trabalho o dominava; mas de vez em quando uma reação o tomava e, por dias seguidos, ele ficava deitado no sofá da sala, mal pronunciando uma palavra ou movendo um músculo da manhã à noite. Nessas ocasiões notei em seus olhos uma expressão tão sonhadora e vazia que eu poderia suspeitar de que fosse viciado em algum narcótico, não fosse a temperança e a limpeza de toda a sua vida proibirem tal ideia.","astheweekswentbymyinterestinhimandmycuri~philosophicalinstruments~672":"Com o passar das semanas, meu interesse por ele e minha curiosidade quanto aos seus objetivos na vida foram gradualmente se aprofundando e crescendo. Sua própria pessoa e aparência eram de molde a chamar a atenção do observador mais casual. Em altura tinha pouco mais de seis pés, e era tão excessivamente magro que parecia consideravelmente mais alto. Seus olhos eram agudos e penetrantes, exceto durante aqueles intervalos de torpor a que aludi; e o nariz fino, de ave de rapina, dava a toda a sua expressão um ar de alerta e decisão. O queixo também tinha a proeminência e o aspecto quadrado que marcam o homem de determinação. As mãos viviam manchadas de tinta e de produtos químicos, e no entanto ele possuía uma extraordinária delicadeza de toque, como tive frequente ocasião de observar quando o via manipular seus frágeis instrumentos filosóficos.","thereadermaysetmedownasahopelessbusybody~nendeavouringtounravelit~547":"O leitor poderá me classificar como um xereta incorrigível, quando confesso o quanto esse homem estimulava minha curiosidade, e quantas vezes tentei romper a reserva que ele mantinha sobre tudo o que lhe dizia respeito. Antes de pronunciar o julgamento, porém, lembre-se de como era sem objetivo a minha vida e quão pouco havia que me ocupasse a atenção. Minha saúde me proibia de aventurar-me fora de casa, a menos que o tempo estivesse excepcionalmente ameno, e eu não tinha amigos que me visitassem e quebrassem a monotonia de minha existência diária. Nessas circunstâncias, saudei avidamente o pequeno mistério que rondava meu companheiro e passei grande parte do tempo tentando desvendá-lo.","hewasnotstudyingmedicinehehadhimselfinre~verygoodreasonfordoingso~625":"Ele não estudava medicina. Ele próprio, em resposta a uma pergunta, confirmara a opinião de Stamford a esse respeito. Tampouco parecia ter seguido qualquer curso de leituras que pudesse habilitá-lo a um grau em ciências ou a qualquer outro portal reconhecido que lhe desse entrada no mundo erudito. Contudo seu zelo por certos estudos era notável e, dentro de limites excêntricos, seu conhecimento era tão extraordinariamente amplo e minucioso que suas observações me deixaram francamente pasmo. Certamente nenhum homem trabalharia tão duro ou alcançaria informações tão precisas sem ter algum fim definido em vista. Leitores desordenados raramente se distinguem pela exatidão de sua erudição. Nenhum homem sobrecarrega o espírito com ninharias sem ter para isso algum motivo muito bom.","hisignorancewasasremarkableashisknowledg~haticouldhardlyrealizeit~481":"Sua ignorância era tão notável quanto seu saber. Da literatura, filosofia e política contemporâneas parecia saber quase nada. Ao eu citar Thomas Carlyle, perguntou do modo mais ingênuo quem era e o que havia feito. Minha surpresa atingiu o auge, porém, quando descobri por acaso que ele ignorava a teoria copernicana e a composição do Sistema Solar. Que um ser humano civilizado, neste século XIX, não soubesse que a Terra gira em torno do Sol parecia-me um fato tão extraordinário que mal consegui compreendê-lo.","youappeartobeastonishedhesaidsmilingatmy~ishalldomybesttoforgetit~100":"“O senhor parece espantado”, disse ele, sorrindo ante minha expressão de surpresa. “Agora que o sei, farei o possível para esquecê-lo.”","toforgetit~toforgetit~10":"“Esquecê-lo!”","youseeheexplainediconsiderthatamansbrain~elbowingouttheusefulones~746":"“Veja”, explicou, “considero que o cérebro de um homem é originalmente como um pequeno sótão vazio, e é preciso abastecê-lo com a mobília que se escolhe. O tolo recolhe todo o entulho de toda espécie que encontra, de modo que o conhecimento que lhe poderia ser útil acaba espremido para fora ou, na melhor das hipóteses, misturado a muitas outras coisas, de forma que tem dificuldade em pôr a mão nele. Ora, o operário hábil é muitíssimo cuidadoso quanto ao que admite em seu sótão cerebral. Não aceitará senão as ferramentas que possam ajudá-lo em seu trabalho, mas dessas tem um grande sortimento, e tudo na mais perfeita ordem. É um erro pensar que aquele quartinho tem paredes elásticas e pode dilatar-se indefinidamente. Fique certo de que chega um tempo em que, para cada acréscimo de conhecimento, esquecemos algo que sabíamos antes. É da maior importância, portanto, não deixar que fatos inúteis expulsem a cotoveladas os úteis.”","butthesolarsystemiprotested~thesolarsystemiprotested~27":"“Mas o Sistema Solar!”, protestei.","whatthedeuceisittomeheinterruptedimpatie~differencetomeortomywork~140":"“Que diabo me importa ele?”, interrompeu com impaciência. “O senhor diz que giramos em torno do Sol. Se girássemos em torno da Lua, não faria a menor diferença para mim ou para o meu trabalho.”","iwasonthepointofaskinghimwhatthatworkmig~ompletedititraninthisway~514":"Eu estava a ponto de lhe perguntar qual poderia ser esse trabalho, mas algo em seus modos me mostrou que a pergunta seria mal recebida. Refleti, porém, sobre nossa breve conversa e procurei tirar dela as minhas deduções. Ele dissera que não adquiriria conhecimento que não se relacionasse com seu objetivo. Portanto, todo o conhecimento que possuía era do tipo que lhe seria útil. Enumerei mentalmente os vários pontos em que me mostrara estar excepcionalmente bem informado. Cheguei a pegar um lápis e anotá-los. Não pude deixar de sorrir diante do documento quando o completei. Dizia o seguinte:","sherlockholmeshislimits~sherlockholmeshislimits~23":"Sherlock Holmes — Seus Limites.","1knowledgeofliteraturenil~knowledgeofliteraturenil~25":"1. Conhecimento de Literatura. — Nulo.","2philosophynil~2philosophynil~14":"2. Filosofia. — Nulo.","3astronomynil~3astronomynil~13":"3. Astronomia. — Nulo.","4politicsfeeble~4politicsfeeble~15":"4. Política. — Fraco.","5botanyvariablewellupinbelladonnaopiuman~hingofpracticalgardening~89":"5. Botânica. — Variável. Bem versado em beladona, ópio e venenos em geral. Nada sabe de jardinagem prática.","6geologypracticalbutlimitedtellsataglanc~flondonhehadreceivedthem~182":"6. Geologia. — Prática, mas limitada. Distingue à primeira vista um solo de outro. Após passeios, mostrou-me respingos em suas calças e disse-me, pela cor e consistência, em que parte de Londres os recebera.","7chemistryprofound~7chemistryprofound~18":"7. Química. — Profunda.","8anatomyaccuratebutunsystematic~yaccuratebutunsystematic~31":"8. Anatomia. — Exata, mas pouco sistemática.","9sensationalliteratureimmenseheappearsto~rperpetratedinthecentury~91":"9. Literatura Sensacionalista. — Imensa. Parece conhecer cada pormenor de cada horror perpetrado no século.","10playstheviolinwell~10playstheviolinwell~20":"10. Toca bem violino.","11isanexpertsinglestickplayerboxerandswo~kplayerboxerandswordsman~46":"11. É exímio jogador de bastão, pugilista e espadachim.","12hasagoodpracticalknowledgeofbritishlaw~calknowledgeofbritishlaw~40":"12. Tem bom conhecimento prático da lei britânica.","whenihadgotsofarinmylistithrewitintothef~llgiveuptheattemptatonce~210":"Quando cheguei a esse ponto da lista, atirei-a ao fogo, em desespero. “Se eu apenas pudesse descobrir aonde o sujeito quer chegar, conciliando todos esses dotes e descobrindo uma ocupação que precise de todos eles”, disse a mim mesmo, “melhor seria desistir da tentativa de uma vez.”","iseethatihavealludedabovetohispowersupon~orthetrialuponmypatience~854":"Vejo que aludi acima às suas habilidades ao violino. Eram muito notáveis, mas tão excêntricas quanto todos os seus outros talentos. Que ele sabia tocar peças, e peças difíceis, eu bem sabia, porque a meu pedido tocou-me alguns Lieder de Mendelssohn e outras de minhas favoritas. Entregue a si mesmo, porém, raramente produzia música ou tentava alguma ária conhecida. Recostado na poltrona à noite, fechava os olhos e arranhava despreocupadamente o violino atirado sobre os joelhos. Às vezes os acordes eram sonoros e melancólicos. Ocasionalmente eram fantásticos e alegres. Claramente refletiam os pensamentos que o possuíam, mas se a música ajudava esses pensamentos ou se o tocar era simples fruto de um capricho ou fantasia, era mais do que eu podia determinar. Poderia ter me rebelado contra esses solos exasperantes, se ele não costumasse terminá-los tocando em rápida sucessão toda uma série de minhas árias favoritas, como ligeira compensação pela prova a que submetia minha paciência.","duringthefirstweekorsowehadnocallersandi~thesubjectofhisownaccord~1129":"Durante a primeira semana, mais ou menos, não tivemos visitas, e eu começara a pensar que meu companheiro era um homem tão sem amigos quanto eu mesmo. Logo, porém, descobri que tinha muitos conhecidos, e das classes mais diferentes da sociedade. Havia um sujeitinho amarelado, de cara de rato e olhos escuros, que me foi apresentado como o Sr. Lestrade, e que veio três ou quatro vezes numa só semana. Certa manhã uma moça, vestida na moda, veio visitá-lo e ficou meia hora ou mais. Na mesma tarde veio um visitante grisalho e surrado, com ar de mascate judeu, que me pareceu muito excitado, e que foi seguido de perto por uma mulher idosa e desleixada. Em outra ocasião um velho cavalheiro de cabelos brancos teve uma entrevista com meu companheiro; e em outra, um carregador de estrada de ferro em seu uniforme de veludilho. Quando algum desses indivíduos indefinidos aparecia, Sherlock Holmes costumava pedir o uso da sala de estar, e eu me retirava para o quarto. Ele sempre se desculpava comigo por me causar esse inconveniente. “Tenho de usar esta sala como local de negócios”, dizia, “e essas pessoas são meus clientes.” Mais uma vez tive oportunidade de lhe fazer uma pergunta à queima-roupa, e mais uma vez minha delicadeza me impediu de forçar outro homem a confiar em mim. Imaginei na época que ele tinha forte razão para não aludir ao assunto, mas ele logo dissipou a ideia, abordando o tema por iniciativa própria.","itwasuponthe4thofmarchasihavegoodreasont~begantorunmyeyethroughit~501":"Foi no dia 4 de março, como tenho boas razões para lembrar, que me levantei um pouco mais cedo que de costume e encontrei Sherlock Holmes ainda sem ter terminado o desjejum. A senhoria se acostumara tanto aos meus hábitos tardios que meu lugar não fora posto nem meu café preparado. Com a irrazoável impertinência da humanidade, toquei a campainha e fiz saber, secamente, que estava pronto. Depois apanhei uma revista da mesa e tentei passar o tempo com ela, enquanto meu companheiro mastigava em silêncio a torrada. Um dos artigos trazia uma marca de lápis no título, e naturalmente comecei a percorrê-lo com os olhos.","itssomewhatambitioustitlewasthebookoflif~onsiderhimasanecromancer~677":"Seu título um tanto ambicioso era “O Livro da Vida”, e procurava mostrar quanto um homem observador poderia aprender por um exame exato e sistemático de tudo o que lhe aparecesse no caminho. Pareceu-me uma notável mistura de sagacidade e absurdo. O raciocínio era cerrado e intenso, mas as deduções pareciam-me forçadas e exageradas. O autor pretendia, por uma expressão momentânea, um tremor de músculo ou um olhar, sondar os pensamentos mais íntimos de um homem. O engano, segundo ele, era uma impossibilidade no caso de alguém treinado na observação e na análise. Suas conclusões eram tão infalíveis quanto as proposições de Euclides. Tão surpreendentes pareceriam seus resultados aos não iniciados que, até conhecerem os processos pelos quais chegara a eles, bem poderiam considerá-lo um necromante.","fromadropofwatersaidthewriteralogicianco~aseisalmostinconceivable~988":"“De uma gota d’água”, dizia o autor, “um lógico poderia inferir a possibilidade de um Atlântico ou de um Niágara, sem ter visto ou ouvido falar de um ou de outro. Assim, toda a vida é uma grande cadeia, cuja natureza se conhece sempre que nos mostram um único elo dela. Como todas as outras artes, a Ciência da Dedução e da Análise é uma que só se adquire por longo e paciente estudo, e a vida não é longa o bastante para permitir a qualquer mortal alcançar nela a mais alta perfeição possível. Antes de passar àqueles aspectos morais e mentais da matéria, que apresentam as maiores dificuldades, comece o investigador por dominar problemas mais elementares. Aprenda, ao encontrar um semelhante, a distinguir de relance a história do homem e o ofício ou profissão a que pertence. Por pueril que tal exercício possa parecer, aguça as faculdades de observação e ensina onde olhar e o que procurar. Pelas unhas de um homem, pela manga do casaco, pela bota, pelos joelhos das calças, pelos calos do indicador e do polegar, pela expressão, pelos punhos da camisa, por cada uma dessas coisas a ocupação de um homem se revela claramente. Que todas reunidas deixem de esclarecer o investigador competente, em qualquer caso, é quase inconcebível.”","whatineffabletwaddleicriedslappingthemag~rreadsuchrubbishinmylife~88":"“Que tolice inefável!”, exclamei, atirando a revista sobre a mesa. “Nunca li tamanho disparate em minha vida.”","whatisitaskedsherlockholmes~tisitaskedsherlockholmes~27":"“O que é?”, perguntou Sherlock Holmes.","whythisarticleisaidpointingatitwithmyegg~athousandtooneagainsthim~429":"“Ora, este artigo”, disse eu, apontando-o com a colher de ovo ao sentar-me para o desjejum. “Vejo que o leu, pois o marcou. Não nego que esteja escrito com esperteza. Irrita-me, porém. É evidentemente a teoria de algum ocioso de poltrona, que elabora todos esses paradoxinhos bem arrumados no recolhimento do próprio gabinete. Não é prática. Gostaria de vê-lo enfiado num vagão de terceira classe do metropolitano e instado a dizer os ofícios de todos os seus companheiros de viagem. Apostaria mil contra um contra ele.”","youwouldloseyourmoneysherlockholmesremar~thearticleiwroteitmyself~78":"“Perderia seu dinheiro”, observou Sherlock Holmes calmamente. “Quanto ao artigo, fui eu mesmo que o escrevi.”","you~you~3":"“O senhor!”","yesihaveaturnbothforobservationandforded~nthemformybreadandcheese~192":"“Sim, tenho jeito tanto para a observação quanto para a dedução. As teorias que expus ali, e que lhe parecem tão quiméricas, são na verdade extremamente práticas; tão práticas que dependo delas para o meu pão de cada dia.”","andhowiaskedinvoluntarily~ndhowiaskedinvoluntarily~25":"“E como?”, perguntei involuntariamente.","wellihaveatradeofmyownisupposeiamtheonly~hatwaswhatbroughthimhere~584":"“Bem, tenho um ofício só meu. Suponho que sou o único no mundo. Sou detetive consultor, se é que compreende o que isso seja. Aqui em Londres temos muitos detetives do Governo e muitos particulares. Quando esses sujeitos se perdem, vêm a mim, e consigo pô-los na pista certa. Expõem diante de mim todas as provas, e geralmente consigo, com a ajuda do meu conhecimento da história do crime, endireitá-los. Há uma forte semelhança de família entre os delitos, e se se tem na ponta dos dedos todos os pormenores de mil, é estranho que não se consiga deslindar o milésimo primeiro. Lestrade é um detetive bem conhecido. Meteu-se recentemente numa neblina por causa de um caso de falsificação, e foi isso que o trouxe aqui.”","andtheseotherpeople~andtheseotherpeople~19":"“E essas outras pessoas?”","theyaremostlysentonbyprivateinquiryagenc~mentsandthenipocketmyfee~174":"“São em sua maioria enviadas por agências particulares de informações. São todas pessoas que estão em apuros por alguma coisa e precisam de um pouco de esclarecimento. Ouço sua história, elas ouvem meus comentários e depois embolso meus honorários.”","butdoyoumeantosayisaidthatwithoutleaving~everydetailforthemselves~142":"“Mas quer dizer”, disse eu, “que sem sair do seu quarto o senhor pode desatar algum nó de que outros homens nada conseguem fazer, embora tenham visto por si mesmos todos os pormenores?”","quitesoihaveakindofintuitionthatwaynowan~ouhadcomefromafghanistan~431":"“Exatamente. Tenho uma espécie de intuição nesse sentido. De vez em quando surge um caso um pouco mais complexo. Então tenho de me agitar e ver as coisas com meus próprios olhos. Veja, tenho um monte de conhecimentos especiais que aplico ao problema, e que facilitam maravilhosamente as coisas. Aquelas regras de dedução estabelecidas no artigo que despertou o seu desprezo são inestimáveis para mim no trabalho prático. A observação é, para mim, uma segunda natureza. O senhor pareceu surpreso quando lhe disse, em nosso primeiro encontro, que vinha do Afeganistão.”","youweretoldnodoubt~youweretoldnodoubt~18":"“Disseram-lhe, sem dúvida.”","nothingofthesortiknewyoucamefromafghanis~stanandyouwereastonished~709":"“Nada disso. Eu sabia que vinha do Afeganistão. Por longo hábito, a sequência de pensamentos passou tão depressa por minha mente que cheguei à conclusão sem ter consciência dos passos intermediários. Havia tais passos, no entanto. O raciocínio foi: ‘Eis um cavalheiro de tipo médico, mas com ar de militar. Claramente um médico do exército, então. Acaba de chegar dos trópicos, pois tem o rosto escuro, e esse não é o tom natural de sua pele, pois os pulsos são claros. Passou por provações e doença, como seu rosto macilento diz claramente. Feriu o braço esquerdo. Segura-o de modo rígido e pouco natural. Em que parte dos trópicos poderia um médico militar inglês ter passado por tantas provações e ter o braço ferido? Claramente no Afeganistão.’ Toda a cadeia de pensamento não ocupou um segundo. Observei então que vinha do Afeganistão, e o senhor ficou espantado.”","itissimpleenoughasyouexplainitisaidsmili~didexistoutsideofstories~127":"“É bastante simples, como o senhor explica”, disse eu, sorrindo. “Lembra-me o Dupin, de Edgar Allan Poe. Não fazia ideia de que tais indivíduos existissem fora das histórias.”","sherlockholmesroseandlithispipenodoubtyo~onaspoeappearedtoimagine~353":"Sherlock Holmes levantou-se e acendeu o cachimbo. “Sem dúvida pensa que me elogia ao me comparar com Dupin”, observou. “Ora, em minha opinião, Dupin era um sujeito muito inferior. Aquele truque dele, de irromper nos pensamentos dos amigos com uma observação oportuna depois de um quarto de hora de silêncio, é realmente muito vistoso e superficial. Tinha algum gênio analítico, sem dúvida; mas não era de modo algum o fenômeno que Poe parecia imaginar.”","haveyoureadgaboriausworksiaskeddoeslecoq~uptoyourideaofadetective~68":"“Leu as obras de Gaboriau?”, perguntei. “Lecoq corresponde à sua ideia de detetive?”","sherlockholmessniffedsardonicallylecoqwa~estoteachthemwhattoavoid~311":"Sherlock Holmes fungou sardonicamente. “Lecoq era um desastrado miserável”, disse, em voz irritada. “Só tinha uma coisa a seu favor, e era a energia. Aquele livro me deixou positivamente enjoado. A questão era como identificar um prisioneiro desconhecido. Eu o teria feito em vinte e quatro horas. Lecoq levou uns seis meses. Poderia servir de manual para os detetives, para ensiná-los o que evitar.”","ifeltratherindignantathavingtwocharacter~iscertainlyveryconceited~206":"Senti-me bastante indignado por ver dois personagens que eu admirava tratados com tal desenvoltura. Fui até a janela e fiquei olhando a rua movimentada. “Este sujeito pode ser muito inteligente”, disse a mim mesmo, “mas é certamente muito presunçoso.”","therearenocrimesandnocriminalsintheseday~dofficialcanseethroughit~387":"“Não há crimes nem criminosos nos dias de hoje”, disse ele, queixoso. “De que serve ter cérebro em nossa profissão? Sei bem que tenho em mim o necessário para tornar famoso o meu nome. Não vive nem jamais viveu homem que tenha trazido à detecção do crime a mesma quantidade de estudo e talento natural que eu. E qual é o resultado? Não há crime a detectar ou, no máximo, alguma vilania desajeitada, com um motivo tão transparente que até um funcionário da Scotland Yard consegue enxergá-lo.”","iwasstillannoyedathisbumptiousstyleofcon~htitbesttochangethetopic~79":"Eu ainda estava irritado com seu estilo de conversa presunçoso. Achei melhor mudar de assunto.","iwonderwhatthatfellowislookingforiaskedp~entlythebearerofamessage~222":"“Pergunto-me o que aquele sujeito procura”, disse, apontando para um indivíduo robusto e de roupas simples, que descia lentamente o outro lado da rua, olhando ansioso os números. Trazia na mão um grande envelope azul e era evidentemente portador de uma mensagem.","youmeantheretiredsergeantofmarinessaidsh~arinessaidsherlockholmes~52":"“Refere-se ao sargento de fuzileiros navais reformado”, disse Sherlock Holmes.","bragandbouncethoughtitomyselfheknowsthat~haticannotverifyhisguess~61":"“Fanfarronice e bazófia!”, pensei comigo. “Sabe que não posso verificar o seu palpite.”","thethoughthadhardlypassedthroughmymindwh~vystepsascendingthestair~188":"O pensamento mal me passara pela mente quando o homem que observávamos avistou o número em nossa porta e atravessou rapidamente a rua. Ouvimos uma batida forte, uma voz grave lá embaixo e passos pesados subindo a escada.","formrsherlockholmeshesaidsteppingintothe~handingmyfriendtheletter~71":"“Para o Sr. Sherlock Holmes”, disse ele, entrando na sala e entregando a carta a meu amigo.","herewasanopportunityoftakingtheconceitou~tvoicewhatyourtrademaybe~144":"Eis uma oportunidade de lhe tirar a presunção. Ele pouco imaginava isso ao dar aquele tiro ao acaso. “Posso perguntar, meu rapaz”, disse eu, na voz mais suave, “qual é o seu ofício?”","commissionairesirhesaidgrufflyuniformawa~flyuniformawayforrepairs~51":"“Comissário, senhor”, disse ele, rudemente. “Uniforme em conserto.”","andyouwereiaskedwithaslightlymaliciousgl~ciousglanceatmycompanion~57":"“E o que era antes?”, perguntei, com um olhar ligeiramente malicioso para meu companheiro.","asergeantsirroyalmarinelightinfantrysirn~antrysirnoanswerrightsir~55":"“Sargento, senhor, Infantaria Ligeira dos Fuzileiros Navais Reais, senhor. Sem resposta? Certo, senhor.”","heclickedhisheelstogetherraisedhishandin~shandinasaluteandwasgone~57":"Bateu os calcanhares, ergueu a mão numa continência e foi-se.","iconfessthatiwasconsiderablystartledbyth~hshowedmentalabstraction~442":"Confesso que fiquei consideravelmente espantado com essa nova prova da natureza prática das teorias de meu companheiro. Meu respeito por seus poderes de análise cresceu maravilhosamente. Restava, porém, em minha mente certa suspeita latente de que tudo fora um episódio combinado de antemão, destinado a me deslumbrar, embora que objetivo possível ele poderia ter em me enganar escapasse à minha compreensão. Quando olhei para ele, havia terminado de ler o bilhete, e seus olhos tinham assumido a expressão vazia e sem brilho que denotava abstração mental.","howintheworlddidyoudeducethatiasked~lddidyoudeducethatiasked~35":"“Como diabos deduziu isso?”, perguntei.","deducewhatsaidhepetulantly~ducewhatsaidhepetulantly~26":"“Deduzi o quê?”, disse ele, impaciente.","whythathewasaretiredsergeantofmarines~retiredsergeantofmarines~37":"“Ora, que ele era um sargento de fuzileiros navais reformado.”","ihavenotimefortriflesheansweredbrusquely~manwasasergeantofmarines~180":"“Não tenho tempo para ninharias”, respondeu bruscamente; depois, com um sorriso: “Perdoe minha grosseria. O senhor quebrou o fio de meus pensamentos; mas talvez seja melhor assim. Então realmente não conseguiu ver que aquele homem era sargento de fuzileiros navais?”","noindeed~noindeed~8":"“Não, de fato.”","itwaseasiertoknowitthantoexplainwhyiknew~vethathehadbeenasergeant~529":"“Era mais fácil saber do que explicar por que eu sabia. Se lhe pedissem para provar que dois e dois são quatro, poderia achar alguma dificuldade, e no entanto está plenamente certo do fato. Mesmo do outro lado da rua pude ver uma grande âncora azul tatuada no dorso da mão do sujeito. Isso cheirava a mar. Tinha, porém, porte militar e suíças regulamentares. Aí temos o fuzileiro. Era um homem com certa dose de importância própria e um certo ar de comando. O senhor deve ter reparado no modo como mantinha a cabeça e balançava a bengala. Um homem firme, respeitável, de meia-idade, pelo aspecto também; todos fatos que me levaram a crer que fora sargento.”","wonderfuliejaculated~wonderfuliejaculated~20":"“Maravilhoso!”, exclamei.","commonplacesaidholmesthoughithoughtfromh~commissionairehadbrought~219":"“Banal”, disse Holmes, embora eu julgasse, por sua expressão, que se agradava de minha evidente surpresa e admiração. “Há pouco eu disse que não havia criminosos. Parece que me enganei; veja isto!” Atirou-me o bilhete que o comissário trouxera.","whyicriedasicastmyeyeoveritthisisterribl~yeyeoveritthisisterrible~41":"“Ora”, exclamei, ao correr os olhos por ele, “isto é terrível!”","itdoesseemtobealittleoutofthecommonherem~oumindreadingittomealoud~81":"“Parece de fato um pouco fora do comum”, observou calmamente. “Importar-se-ia de lê-lo em voz alta para mim?”","thisistheletterwhichireadtohim~theletterwhichireadtohim~30":"Esta é a carta que li para ele:","mydearmrsherlockholmes~mydearmrsherlockholmes~22":"Meu caro Sr. Sherlock Holmes,","therehasbeenabadbusinessduringthenightat~dfavourmewithyouropinion~762":"Houve um caso grave durante a noite no nº 3 de Lauriston Gardens, perto da Brixton Road. Nosso guarda de ronda viu ali uma luz por volta das duas da manhã e, como a casa estava vazia, suspeitou de que algo andava errado. Encontrou a porta aberta e, na sala da frente, que está sem mobília, descobriu o corpo de um cavalheiro, bem vestido, trazendo no bolso cartões com o nome “Enoch J. Drebber, Cleveland, Ohio, E.U.A.”. Não houve roubo, nem há qualquer indício de como o homem encontrou a morte. Há marcas de sangue na sala, mas nenhum ferimento em seu corpo. Estamos sem saber como ele entrou na casa vazia; na verdade, todo o caso é um enigma. Se puder passar pela casa a qualquer hora antes do meio-dia, o senhor me encontrará lá. Deixei tudo in statu quo até ter notícias suas. Se não puder vir, darei detalhes mais completos, e consideraria um grande favor se me honrasse com sua opinião.","yoursfaithfully~yoursfaithfully~15":"Seu fiel,","tobiasgregson~tobiasgregson~13":"Tobias Gregson","gregsonisthesmartestofthescotlandyarders~eyarebothputuponthescent~282":"“Gregson é o mais esperto dos homens da Scotland Yard”, observou meu amigo; “ele e Lestrade são o que há de melhor num mau lote. Ambos são rápidos e enérgicos, mas convencionais, chocantemente convencionais. Têm também as facas afiadas um contra o outro. São tão ciumentos quanto um par de beldades profissionais. Haverá divertimento com este caso, se os dois forem postos na pista.”","iwasamazedatthecalmwayinwhichherippledon~dshalligoandorderyouacab~100":"Fiquei pasmo com a calma com que ele continuava a tagarelar. “Certamente não há um momento a perder”, exclamei. “Quer que eu vá chamar-lhe um coche?”","imnotsureaboutwhetherishallgoiamthemosti~ricanbespryenoughattimes~131":"“Não tenho certeza se irei. Sou o demônio mais incuravelmente preguiçoso que já calçou sapatos, isto é, quando o acesso me toma, pois posso ser bastante ágil às vezes.”","whyitisjustsuchachanceasyouhavebeenlongi~easyouhavebeenlongingfor~45":"“Ora, é justamente a oportunidade que o senhor desejava.”","mydearfellowwhatdoesitmattertomesupposin~inganunofficialpersonage~158":"“Meu caro amigo, que me importa isso? Suponha que eu desvende todo o caso; pode estar certo de que Gregson, Lestrade & Cia. embolsarão todo o crédito. É o que dá ser um personagem não oficial.”","buthebegsyoutohelphim~buthebegsyoutohelphim~21":"“Mas ele lhe pede que o ajude.”","yesheknowsthatiamhissuperiorandacknowled~ifihavenothingelsecomeon~210":"“Sim. Sabe que sou seu superior e o reconhece diante de mim; mas cortaria a língua antes de admiti-lo a qualquer terceiro. Seja como for, podemos muito bem ir dar uma olhada. Resolverei por conta própria. Posso rir-me deles, se não tiver nada mais. Vamos!”","hehustledonhisovercoatandbustledaboutina~upersededtheapatheticone~99":"Apressou-se em vestir o sobretudo e agitou-se de um modo que mostrava que um acesso de energia suplantara o apático.","getyourhathesaid~getyourhathesaid~16":"“Pegue o chapéu”, disse.","youwishmetocome~youwishmetocome~15":"“Quer que eu vá?”","yesifyouhavenothingbettertodoaminutelate~riouslyforthebrixtonroad~93":"“Sim, se não tem nada melhor a fazer.” Um minuto depois estávamos ambos num cabriolé, correndo furiosamente para a Brixton Road.","itwasafoggycloudymorningandaduncolouredv~ngageddepressedmyspirits~331":"Era uma manhã nevoenta e nublada, e um véu cor de terra pairava sobre os telhados, como o reflexo das ruas lamacentas lá embaixo. Meu companheiro estava no melhor dos humores e tagarelava sobre violinos de Cremona e a diferença entre um Stradivarius e um Amati. Quanto a mim, estava calado, pois o tempo sombrio e o triste assunto que nos ocupava me deprimiam o ânimo.","youdontseemtogivemuchthoughttothematteri~olmesmusicaldisquisition~93":"“O senhor não parece dar muita atenção ao assunto em questão”, disse eu por fim, interrompendo a dissertação musical de Holmes.","nodatayetheanswereditisacapitalmistaketo~denceitbiasesthejudgment~94":"“Ainda não há dados”, respondeu. “É um erro capital teorizar antes de ter todas as provas. Enviesa o juízo.”","youwillhaveyourdatasooniremarkedpointing~ifiamnotverymuchmistaken~113":"“Terá seus dados em breve”, observei, apontando com o dedo; “esta é a Brixton Road, e aquela é a casa, se não me engano muito.”","soitisstopdriverstopwewerestillahundredy~nishedourjourneyuponfoot~114":"“É mesmo. Pare, cocheiro, pare!” Estávamos ainda a uns cem metros dela, mas ele insistiu que descêssemos, e terminamos a viagem a pé.","number3lauristongardensworeanillomenedan~seoftheproceedingswithin~802":"O número 3 de Lauriston Gardens tinha um aspecto agourento e ameaçador. Era uma de quatro casas recuadas um pouco da rua, duas ocupadas e duas vazias. Estas últimas miravam a rua com três fileiras de janelas vazias e melancólicas, desoladas e sem vida, exceto onde aqui e ali um cartaz de “Aluga-se” se formara como uma catarata nas vidraças embaçadas. Um pequeno jardim, salpicado de uma erupção esparsa de plantas doentias, separava cada uma dessas casas da rua e era cortado por um estreito caminho, de cor amarelada, feito aparentemente de uma mistura de argila e cascalho. Todo o lugar estava encharcado da chuva que caíra durante a noite. O jardim era delimitado por um muro de tijolos de um metro, com uma franja de ripas de madeira no topo, e contra esse muro se encostava um robusto policial, cercado por um pequeno grupo de vadios, que esticavam os pescoços e forçavam a vista na vã esperança de apanhar algum vislumbre do que se passava lá dentro.","ihadimaginedthatsherlockholmeswouldatonc~dealwhichwashiddenfromme~814":"Eu imaginara que Sherlock Holmes correria de imediato para dentro da casa e mergulharia no estudo do mistério. Nada parecia mais longe de sua intenção. Com um ar de indiferença que, nas circunstâncias, me pareceu beirar a afetação, vagueou de um lado para outro da calçada e fitou distraidamente o chão, o céu, as casas fronteiriças e a fileira de grades. Terminado o escrutínio, seguiu devagar pelo caminho, ou antes, pela franja de relva que ladeava o caminho, mantendo os olhos cravados no chão. Duas vezes parou, e uma vez o vi sorrir e ouvi-o proferir uma exclamação de satisfação. Havia muitas marcas de pegadas no solo argiloso e úmido, mas, como a polícia andara indo e vindo por cima, não consegui ver como meu companheiro podia esperar aprender algo dali. Ainda assim eu tivera prova tão extraordinária da rapidez de suas faculdades perceptivas que não duvidava de que ele pudesse ver muito do que me estava oculto.","atthedoorofthehouseweweremetbyatallwhite~deverythingleftuntouched~196":"À porta da casa recebeu-nos um homem alto, de rosto pálido e cabelos cor de linho, com um caderno de notas na mão, que correu para a frente e apertou efusivamente a mão do meu companheiro. “É deveras gentil de sua parte vir”, disse ele. “Deixei tudo intocado.”","exceptthatmyfriendansweredpointingatthep~onbeforeyoupermittedthis~177":"“Exceto aquilo!”, respondeu meu amigo, apontando o caminho. “Se uma manada de búfalos tivesse passado por ali, não poderia haver maior desordem. Sem dúvida, porém, já havia tirado suas próprias conclusões, Gregson, antes de permitir isto.”","ihavehadsomuchtodoinsidethehousethedetec~eduponhimtolookafterthis~116":"“Tive tanto a fazer dentro da casa”, disse o detetive evasivamente. “Meu colega, o Sr. Lestrade, está aqui. Confiei nele para cuidar disto.”","holmesglancedatmeandraisedhiseyebrowssar~hirdpartytofindouthesaid~144":"Holmes olhou para mim e ergueu as sobrancelhas sardonicamente. “Com dois homens como o senhor e Lestrade no local, não restará muito para um terceiro descobrir”, disse.","gregsonrubbedhishandsinaselfsatisfiedway~ewyourtasteforsuchthings~131":"Gregson esfregou as mãos, satisfeito consigo mesmo. “Penso que fizemos tudo o que pode ser feito”, respondeu; “é um caso estranho, porém, e eu sabia de seu gosto por tais coisas.”","youdidnotcomehereinacabaskedsherlockholm~nacabaskedsherlockholmes~42":"“O senhor não veio aqui de coche?”, perguntou Sherlock Holmes.","nosir~nosir~5":"“Não, senhor.”","norlestrade~norlestrade~11":"“Nem Lestrade?”","thenletusgoandlookattheroomwithwhichinco~expressedhisastonishment~130":"“Então vamos ver a sala.” Com essa observação sem nexo, entrou a passos largos na casa, seguido por Gregson, cujas feições exprimiam o espanto.","ashortpassagebareplankedanddustyledtothe~epresenceofdeathinspires~323":"Um curto corredor, de tábuas nuas e empoeiradas, conduzia à cozinha e às dependências. Duas portas se abriam dele, à esquerda e à direita. Uma delas estivera obviamente fechada por muitas semanas. A outra era a da sala de jantar, o aposento em que o misterioso caso ocorrera. Holmes entrou, e eu o segui, com aquele sentimento abafado no coração que a presença da morte inspira.","itwasalargesquareroomlookingallthelarger~hcoatedthewholeapartment~506":"Era uma sala grande e quadrada, parecendo ainda maior pela ausência de toda mobília. Um papel vulgar e berrante adornava as paredes, mas estava manchado de mofo em alguns pontos, e aqui e ali grandes tiras haviam se soltado e pendiam, expondo o reboco amarelo por baixo. Em frente à porta havia uma lareira vistosa, encimada por um console de falso mármore branco. Num canto dele estava espetado o toco de uma vela de cera vermelha. A única janela era tão suja que a luz era turva e incerta, dando um matiz cinzento e apagado a tudo, intensificado pela espessa camada de poeira que cobria todo o aposento.","allthesedetailsiobservedafterwardsatpres~arteriesofsuburbanlondon~1024":"Todos esses detalhes observei depois. No momento minha atenção estava concentrada na única figura sinistra e imóvel que jazia estendida sobre as tábuas, com olhos vazios e cegos fitando o teto descorado. Era a de um homem de uns quarenta e três ou quarenta e quatro anos, de estatura média, ombros largos, cabelos negros crespos e encaracolados e uma barba curta e espetada. Vestia uma pesada sobrecasaca de pano fino e colete, com calças de cor clara e colarinho e punhos imaculados. Uma cartola, bem escovada e asseada, fora posta no chão a seu lado. As mãos estavam cerradas e os braços lançados para os lados, enquanto os membros inferiores estavam entrelaçados, como se a luta da agonia tivesse sido penosa. No rosto rígido estampava-se uma expressão de horror e, ao que me pareceu, de ódio, como nunca vi em feições humanas. Essa contorção maligna e terrível, combinada com a testa baixa, o nariz achatado e a mandíbula proeminente, dava ao morto um aspecto singularmente simiesco, que se acentuava pela postura retorcida e antinatural. Vi a morte sob muitas formas, mas nunca ela me apareceu sob aspecto mais temível do que naquele aposento escuro e sórdido, que dava para uma das principais artérias dos subúrbios de Londres.","lestradeleanandferretlikeaseverwasstandi~etedmycompanionandmyself~84":"Lestrade, magro e furtivo como sempre, estava de pé junto à porta e saudou meu companheiro e a mim.","thiscasewillmakeastirsirheremarkeditbeat~ihaveseenandiamnochicken~73":"“Este caso vai causar sensação, senhor”, observou. “Supera tudo o que já vi, e não sou nenhum novato.”","thereisnocluesaidgregson~thereisnocluesaidgregson~24":"“Nenhuma pista?”, disse Gregson.","noneatallchimedinlestrade~oneatallchimedinlestrade~25":"“Nenhuma”, secundou Lestrade.","sherlockholmesapproachedthebodyandkneeli~sofbloodwhichlayallround~156":"Sherlock Holmes aproximou-se do corpo e, ajoelhando-se, examinou-o atentamente. “Tem certeza de que não há ferimento?”, perguntou, apontando as numerosas gotas e respingos de sangue que havia em volta.","positivecriedbothdetectives~itivecriedbothdetectives~27":"“Certeza absoluta!”, gritaram ambos os detetives.","thenofcoursethisbloodbelongstoasecondind~ourememberthecasegregson~198":"“Então, claro, este sangue pertence a um segundo indivíduo, presumivelmente o assassino, se houve assassinato. Lembra-me as circunstâncias da morte de Van Jansen, em Utrecht, no ano de 34. Lembra-se do caso, Gregson?”","readitupyoureallyshouldthereisnothingnew~unithasallbeendonebefore~73":"“Leia a respeito; realmente deveria. Não há nada novo sob o sol. Tudo já foi feito antes.”","ashespokehisnimblefingerswereflyingheret~sofhispatentleatherboots~334":"Enquanto falava, seus dedos ágeis voavam aqui, ali e por toda parte, apalpando, pressionando, desabotoando, examinando, enquanto seus olhos tinham a mesma expressão distante que já notei. Tão rápido foi o exame que mal se adivinharia a minúcia com que era conduzido. Por fim, cheirou os lábios do morto e depois olhou as solas de suas botas de verniz.","hehasnotbeenmovedatallheasked~notbeenmovedatallheasked~29":"“Ele não foi movido de modo algum?”, perguntou.","nomorethanwasnecessaryforthepurposesofou~purposesofourexamination~52":"“Não mais do que o necessário para os propósitos do nosso exame.”","youcantakehimtothemortuarynowhesaidthere~isnothingmoretobelearned~64":"“Podem levá-lo ao necrotério agora”, disse. “Não há mais nada a aprender.”","gregsonhadastretcherandfourmenathandathi~redatitwithmystifiedeyes~202":"Gregson tinha à mão uma maca e quatro homens. A seu chamado entraram na sala, e o desconhecido foi erguido e levado. Quando o levantaram, um anel tilintou ao cair e rolou pelo chão. Lestrade o apanhou e ficou a olhá-lo com olhos perplexos.","theresbeenawomanherehecrieditsawomanswed~ieditsawomansweddingring~48":"“Houve uma mulher aqui”, gritou. “É uma aliança de mulher.”","hehelditoutashespokeuponthepalmofhishand~adornedthefingerofabride~149":"Estendeu-a, ao falar, na palma da mão. Todos nos reunimos em volta dele e a contemplamos. Não podia haver dúvida de que aquele aro de ouro liso um dia adornara o dedo de uma noiva.","thiscomplicatesmatterssaidgregsonheavenk~ecomplicatedenoughbefore~75":"“Isso complica as coisas”, disse Gregson. “Deus sabe que já eram complicadas o bastante.”","youresureitdoesntsimplifythemobservedhol~atdidyoufindinhispockets~106":"“Tem certeza de que não as simplifica?”, observou Holmes. “Nada se aprende ficando a olhá-la. O que encontrou nos bolsos dele?”","wehaveitallheresaidgregsonpointingtoalit~andonetojosephstangerson~487":"“Temos tudo aqui”, disse Gregson, apontando um amontoado de objetos num dos degraus inferiores da escada. “Um relógio de ouro, nº 97163, de Barraud, de Londres. Corrente Albert de ouro, muito pesada e sólida. Anel de ouro, com emblema maçônico. Alfinete de ouro: cabeça de buldogue, com rubis como olhos. Porta-cartões de couro da Rússia, com cartões de Enoch J. Drebber de Cleveland, correspondendo às iniciais E. J. D. na roupa branca. Nenhuma bolsa, mas dinheiro solto no valor de sete libras e treze. Edição de bolso do Decamerão de Boccaccio, com o nome de Joseph Stangerson na folha de guarda. Duas cartas, uma endereçada a E. J. Drebber e outra a Joseph Stangerson.”","atwhataddress~atwhataddress~13":"“Em que endereço?”","americanexchangestrandtobelefttillcalled~asabouttoreturntonewyork~183":"“American Exchange, Strand, para ficar retida até ser reclamada. Ambas são da Guion Steamship Company e se referem à partida de seus navios de Liverpool. É claro que esse infeliz estava prestes a voltar a Nova York.”","haveyoumadeanyinquiriesastothismanstange~iesastothismanstangerson~44":"“Fez alguma investigação sobre esse homem, Stangerson?”","ididitatoncesirsaidgregsonihavehadadvert~gebuthehasnotreturnedyet~133":"“Fiz de imediato, senhor”, disse Gregson. “Mandei publicar anúncios em todos os jornais, e um dos meus homens foi à American Exchange, mas ainda não voltou.”","haveyousenttocleveland~haveyousenttocleveland~22":"“Mandou perguntar a Cleveland?”","wetelegraphedthismorning~wetelegraphedthismorning~24":"“Telegrafamos esta manhã.”","howdidyouwordyourinquiries~wdidyouwordyourinquiries~26":"“Como redigiu suas indagações?”","wesimplydetailedthecircumstancesandsaidt~ormationwhichcouldhelpus~89":"“Simplesmente expusemos as circunstâncias e dissemos que ficaríamos gratos por qualquer informação que pudesse nos ajudar.”","youdidnotaskforparticularsonanypointwhic~appearedtoyoutobecrucial~65":"“Não pediu pormenores sobre algum ponto que lhe parecesse crucial?”","iaskedaboutstangerson~iaskedaboutstangerson~21":"“Perguntei sobre Stangerson.”","nothingelseistherenocircumstanceonwhicht~willyounottelegraphagain~90":"“Mais nada? Não há nenhuma circunstância em que todo este caso pareça se apoiar? Não vai telegrafar de novo?”","ihavesaidallihavetosaysaidgregsoninanoff~gregsoninanoffendedvoice~50":"“Já disse tudo o que tinha a dizer”, disse Gregson, em voz ofendida.","sherlockholmeschuckledtohimselfandappear~usandselfsatisfiedmanner~215":"Sherlock Holmes riu consigo mesmo e parecia prestes a fazer alguma observação, quando Lestrade, que estivera na sala da frente enquanto mantínhamos essa conversa no vestíbulo, reapareceu em cena, esfregando as mãos de um modo pomposo e satisfeito consigo mesmo.","mrgregsonhesaidihavejustmadeadiscoveryof~fulexaminationofthewalls~134":"“Sr. Gregson”, disse, “acabo de fazer uma descoberta da mais alta importância, e que teria passado despercebida se eu não tivesse feito um exame cuidadoso das paredes.”","thelittlemanseyessparkledashespokeandhew~pointagainsthiscolleague~120":"Os olhos do homenzinho faiscavam ao falar, e ele estava evidentemente num estado de júbilo contido por ter marcado um ponto contra o colega.","comeherehesaidbustlingbackintotheroomthe~astlyinmatenowstandthere~114":"“Venham cá”, disse, voltando apressado à sala, cuja atmosfera parecia mais clara desde a remoção de seu medonho ocupante. “Agora, fiquem ali!”","hestruckamatchonhisbootandhelditupagains~ndhelditupagainstthewall~48":"Acendeu um fósforo na bota e ergueu-o contra a parede.","lookatthathesaidtriumphantly~atthathesaidtriumphantly~28":"“Vejam isto!”, disse, triunfante.","ihaveremarkedthatthepaperhadfallenawayin~oodredlettersasingleword~200":"Já observei que o papel se soltara em partes. Naquele canto específico da sala um grande pedaço descolara, deixando um quadrado amarelo de reboco grosseiro. Sobre esse espaço nu estava rabiscada, em letras vermelhas como sangue, uma única palavra:","rache~rache~5":"Rache","whatdoyouthinkofthatcriedthedetectivewit~edarkestportionofthewall~447":"“Que acham disso?”, gritou o detetive, com o ar de um apresentador exibindo o seu espetáculo. “Isto passou despercebido porque estava no canto mais escuro da sala, e ninguém pensou em olhar ali. O assassino ou a assassina escreveu-o com o próprio sangue. Vejam esta mancha onde escorreu pela parede! Isso afasta de qualquer modo a ideia de suicídio. Por que escolheu aquele canto para escrever? Eu lhes digo. Vejam aquela vela no console. Estava acesa na ocasião, e, se estava acesa, este canto seria a parte mais clara, e não a mais escura, da parede.”","andwhatdoesitmeannowthatyouhavefounditas~gsoninadepreciatoryvoice~70":"“E o que significa agora que o senhor o encontrou?”, perguntou Gregson em voz depreciativa.","meanwhyitmeansthatthewriterwasgoingtoput~bestwhenallissaidanddone~312":"“Significa? Ora, significa que o autor ia escrever o nome feminino Rachel, mas foi perturbado antes de ter tempo de terminar. Marquem minhas palavras: quando este caso for esclarecido, descobrirão que uma mulher chamada Rachel tem algo a ver com ele. Está muito bem o senhor rir, Sr. Sherlock Holmes. Pode ser muito esperto e inteligente, mas o velho cão de caça é o melhor, no fim das contas.”","ireallybegyourpardonsaidmycompanionwhoha~rpermissionishalldosonow~314":"“Peço realmente perdão!”, disse meu companheiro, que irritara o humor do homenzinho ao explodir numa gargalhada. “O senhor tem certamente o mérito de ser o primeiro de nós a descobrir isto e, como diz, tem todas as marcas de ter sido escrito pelo outro participante do mistério da noite passada. Ainda não tive tempo de examinar esta sala, mas, com sua permissão, vou fazê-lo agora.”","ashespokehewhippedatapemeasureandalarger~peandhisglassinhispocket~1046":"Enquanto falava, tirou do bolso uma fita métrica e uma grande lupa redonda. Com esses dois instrumentos percorreu a sala a passos silenciosos, às vezes parando, ocasionalmente ajoelhando-se e uma vez deitando-se de bruços. Estava tão absorto em sua ocupação que parecia ter esquecido nossa presença, pois tagarelava baixinho consigo mesmo o tempo todo, mantendo uma fuzilaria contínua de exclamações, gemidos, assobios e pequenos gritos que sugeriam encorajamento e esperança. Ao observá-lo, lembrei-me irresistivelmente de um cão de caça de raça pura e bem treinado, que corre para a frente e para trás pela mata, ganindo de ansiedade, até topar com o rastro perdido. Por vinte minutos ou mais continuou suas pesquisas, medindo com o mais exato cuidado a distância entre marcas que me eram inteiramente invisíveis e aplicando ocasionalmente sua fita às paredes de modo igualmente incompreensível. Num ponto recolheu com muito cuidado um pequeno monte de pó cinzento do chão e o guardou num envelope. Por fim examinou com a lupa a palavra na parede, percorrendo cada letra dela com a mais minuciosa exatidão. Feito isso, pareceu satisfeito, pois guardou no bolso a fita e a lupa.","theysaythatgeniusisaninfinitecapacityfor~doesapplytodetectivework~121":"“Dizem que o gênio é uma capacidade infinita de se dar ao trabalho”, observou com um sorriso. “É uma definição muito ruim, mas aplica-se ao trabalho de detetive.”","gregsonandlestradehadwatchedthemanoeuvre~edefiniteandpracticalend~247":"Gregson e Lestrade haviam observado as manobras de seu companheiro amador com considerável curiosidade e algum desprezo. Evidentemente não percebiam o fato, que eu começara a compreender, de que as menores ações de Sherlock Holmes se dirigiam todas a algum fim definido e prático.","whatdoyouthinkofitsirtheybothasked~hinkofitsirtheybothasked~34":"“Que pensa disso, senhor?”, perguntaram ambos.","itwouldberobbingyouofthecreditofthecasei~ugivemehisnameandaddress~353":"“Seria roubar-lhes o mérito do caso se eu presumisse ajudá-los”, observou meu amigo. “Estão se saindo tão bem que seria pena alguém interferir.” Havia um mundo de sarcasmo em sua voz ao falar. “Se me avisarem como andam suas investigações”, continuou, “terei prazer em dar qualquer ajuda que puder. Entretanto, gostaria de falar com o guarda que encontrou o corpo. Podem me dar seu nome e endereço?”","lestradeglancedathisnotebookjohnrancehes~ycourtkenningtonparkgate~104":"Lestrade consultou o caderno. “John Rance”, disse. “Está de folga agora. O senhor o encontrará no nº 46 de Audley Court, Kennington Park Gate.”","holmestookanoteoftheaddress~mestookanoteoftheaddress~27":"Holmes anotou o endereço.","comealongdoctorhesaidweshallgoandlookhim~tionsbuttheymayassistyou~523":"“Venha, Doutor”, disse; “vamos procurá-lo. Digo-lhes uma coisa que pode ajudá-los no caso”, continuou, voltando-se para os dois detetives. “Houve um assassinato, e o assassino foi um homem. Tinha mais de um metro e oitenta, estava na flor da idade, tinha pés pequenos para a altura, usava botas grosseiras de bico quadrado e fumava um charuto de Trichinopoly. Veio aqui com a vítima num coche de quatro rodas, puxado por um cavalo com três ferraduras velhas e uma nova na pata dianteira direita. É muito provável que o assassino tivesse o rosto corado, e as unhas da mão direita eram notavelmente compridas. São apenas alguns indícios, mas podem auxiliá-los.”","lestradeandgregsonglancedateachotherwith~erwithanincreduloussmile~58":"Lestrade e Gregson entreolharam-se com um sorriso incrédulo.","ifthismanwasmurderedhowwasitdoneaskedthe~wwasitdoneaskedtheformer~46":"“Se esse homem foi assassinado, como foi feito?”, perguntou o primeiro.","poisonsaidsherlockholmescurtlyandstrodeo~timelookingformissrachel~155":"“Veneno”, disse Sherlock Holmes secamente, e afastou-se a passos largos. “Mais uma coisa, Lestrade”, acrescentou, voltando-se à porta: “Rache é o alemão para ‘vingança’; portanto, não percam tempo procurando a senhorita Rachel.”","withwhichparthianshothewalkedawayleaving~valsopenmouthedbehindhim~72":"Com essa flecha de parto, foi-se embora, deixando os dois rivais de boca aberta atrás de si."}$tr$::jsonb, 231)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- arthur-conan-doyle_the-adventures-of-sherlock-holmes (608 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('arthur-conan-doyle_the-adventures-of-sherlock-holmes', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"ascandalinbohemia":"Um escândalo na Boêmia","theredheadedleague":"A Liga dos Cabeças-Vermelhas","acaseofidentity":"Um Caso de Identidade"}$tr$::jsonb, $tr${"i~i~1":"I","tosherlockholmessheisalwaysthewomanihave~ousandquestionablememory~915":"Para Sherlock Holmes, ela é sempre a mulher. Raramente o ouvi mencioná-la por outro nome. Aos olhos dele, ela eclipsa e supera todo o seu sexo. Não que ele sentisse por Irene Adler qualquer emoção semelhante ao amor. Todas as emoções, e essa em particular, eram abomináveis para a sua mente fria, precisa, mas admiravelmente equilibrada. Era, creio eu, a mais perfeita máquina de raciocinar e observar que o mundo já viu, mas, como amante, ele se teria colocado numa posição falsa. Jamais falava das paixões mais ternas, a não ser com um gracejo e um sorriso de escárnio. Eram coisas admiráveis para o observador, excelentes para erguer o véu dos motivos e das ações dos homens. Mas, para o raciocinador treinado, admitir tais intrusões em seu temperamento delicado e finamente ajustado era introduzir um fator perturbador, que poderia lançar dúvida sobre todos os seus resultados mentais. Um grão de areia num instrumento sensível, ou uma rachadura numa de suas lentes de alta potência, não seria mais perturbador do que uma emoção forte numa natureza como a dele. E, no entanto, só havia uma mulher para ele, e essa mulher era a falecida Irene Adler, de memória duvidosa e questionável.","ihadseenlittleofholmeslatelymymarriageha~formerfriendandcompanion~1053":"Eu vira pouco de Holmes nos últimos tempos. O casamento nos afastara um do outro. Minha completa felicidade e os interesses domésticos que surgem em torno do homem que pela primeira vez se vê senhor de sua própria casa bastavam para absorver toda a minha atenção, enquanto Holmes, que detestava toda forma de vida em sociedade com toda a sua alma boêmia, permanecia em nossos aposentos da Baker Street, enterrado entre seus velhos livros, alternando de semana em semana entre a cocaína e a ambição, entre a sonolência da droga e a energia feroz de sua natureza aguda. Continuava, como sempre, profundamente atraído pelo estudo do crime, e empregava suas imensas faculdades e extraordinários poderes de observação em seguir pistas e esclarecer mistérios que a polícia oficial abandonara por desesperançados. De tempos em tempos chegava-me algum vago relato de suas atividades: de sua convocação a Odessa no caso do assassinato Trepoff, do esclarecimento da singular tragédia dos irmãos Atkinson em Trincomalee e, por fim, da missão que cumprira de modo tão delicado e bem-sucedido em favor da família reinante da Holanda. Além desses sinais de sua atividade, porém, que eu apenas partilhava com todos os leitores da imprensa diária, eu sabia pouco do meu antigo amigo e companheiro.","onenightitwasonthetwentiethofmarch1888iw~dformerlybeeninpartmyown~763":"Certa noite — era o dia vinte de março de 1888 — eu voltava de uma visita a um paciente (pois havia retomado a clínica civil) quando o caminho me levou pela Baker Street. Ao passar pela porta bem lembrada, que sempre há de estar associada em minha mente ao meu namoro e aos sombrios incidentes do Estudo em Vermelho, fui tomado por um vivo desejo de rever Holmes e saber em que empregava seus extraordinários poderes. Seus aposentos estavam brilhantemente iluminados e, mesmo enquanto eu olhava para cima, vi sua figura alta e magra passar duas vezes, em silhueta escura, contra a cortina. Ele andava de um lado para o outro, rápido, ansioso, com a cabeça afundada no peito e as mãos cruzadas às costas. Para mim, que conhecia todos os seus humores e hábitos, a atitude e o jeito dele contavam sua própria história. Estava de novo trabalhando. Erguera-se de seus sonhos provocados pela droga e seguia, ardente, o rastro de algum novo problema. Toquei a campainha e fui conduzido ao cômodo que outrora fora em parte meu.","hismannerwasnoteffusiveitseldomwasbuthew~ularintrospectivefashion~262":"Seu modo não foi efusivo. Raramente era; mas ele ficou contente, penso eu, em me ver. Quase sem dizer palavra, mas com um olhar bondoso, fez-me sinal para uma poltrona, atirou-me sua caixa de charutos e indicou um porta-licores e um gasogênio no canto. Depois ficou de pé diante do fogo e me examinou à sua singular maneira introspectiva.","wedlocksuitsyouheremarkedithinkwatsontha~dahalfpoundssinceisawyou~84":"“O casamento lhe faz bem”, observou ele. “Creio, Watson, que o senhor ganhou sete libras e meia desde que o vi.”","sevenianswered~sevenianswered~14":"“Sete!”, respondi.","indeedishouldhavethoughtalittlemorejusta~uintendedtogointoharness~133":"“De fato, eu teria pensado um pouco mais. Apenas uma ninharia mais, imagino, Watson. E de novo em atividade, observo. O senhor não me disse que pretendia voltar à lida.”","thenhowdoyouknow~thenhowdoyouknow~16":"“Então, como sabe?”","iseeitideduceithowdoiknowthatyouhavebeen~syandcarelessservantgirl~115":"“Vejo, deduzo. Como sei que tem se molhado muito ultimamente, e que tem uma criada extremamente desajeitada e descuidada?”","mydearholmessaidithisistoomuchyouwouldce~failtoseehowyouworkitout~297":"“Meu caro Holmes”, disse eu, “isto é demais. Certamente teria sido queimado vivo se tivesse vivido alguns séculos atrás. É verdade que fiz um passeio pelo campo na quinta-feira e voltei para casa num estado deplorável, mas, como mudei de roupa, não imagino como o deduz. Quanto a Mary Jane, é incorrigível, e minha mulher já a avisou de que vai ser despedida, mas, também aqui, não vejo como chegou a isso.”","hechuckledtohimselfandrubbedhislongnervo~longnervoushandstogether~55":"Ele riu consigo mesmo e esfregou as longas mãos nervosas uma na outra.","itissimplicityitselfsaidhemyeyestellmeth~erofthemedicalprofession~648":"“É a simplicidade em pessoa”, disse; “meus olhos me dizem que, no lado interno do seu sapato esquerdo, justamente onde o clarão do fogo o atinge, o couro está riscado por seis cortes quase paralelos. Obviamente foram causados por alguém que raspou muito descuidadamente em volta das bordas da sola para remover a lama endurecida. Daí, vê o senhor, minha dupla dedução de que esteve fora em tempo péssimo e de que possui um exemplar particularmente maligno, retalhador de botas, da criadinha londrina. Quanto à sua clínica, se um cavalheiro entra em meus aposentos cheirando a iodofórmio, com uma mancha negra de nitrato de prata no indicador direito e um volume no lado direito da cartola, que mostra onde escondeu o estetoscópio, eu teria de ser muito obtuso para não declará-lo membro ativo da profissão médica.”","icouldnothelplaughingattheeasewithwhichh~atmyeyesareasgoodasyours~303":"Não pude deixar de rir da facilidade com que explicava seu processo de dedução. “Quando o ouço dar as suas razões”, observei, “a coisa me parece sempre tão ridiculamente simples que eu mesmo poderia fazê-la com facilidade, embora a cada exemplo sucessivo do seu raciocínio fique desconcertado até que o senhor explique o processo. E no entanto creio que meus olhos são tão bons quanto os seus.”","quitesoheansweredlightingacigaretteandth~dupfromthehalltothisroom~187":"“Exatamente”, respondeu, acendendo um cigarro e atirando-se numa poltrona. “O senhor vê, mas não observa. A distinção é clara. Por exemplo, o senhor viu frequentemente os degraus que sobem do vestíbulo até esta sala.”","frequently~frequently~10":"“Frequentemente.”","howoften~howoften~8":"“Quantas vezes?”","wellsomehundredsoftimes~wellsomehundredsoftimes~23":"“Bem, algumas centenas de vezes.”","thenhowmanyarethere~thenhowmanyarethere~19":"“Então quantos são?”","howmanyidontknow~howmanyidontknow~16":"“Quantos? Não sei.”","quitesoyouhavenotobservedandyetyouhavese~astpostsaidhereaditaloud~376":"“Exatamente! Não observou. E no entanto viu. Esse é justamente o meu ponto. Pois bem, eu sei que são dezessete degraus, porque vi e observei. A propósito, já que se interessa por esses pequenos problemas, e já que tem a bondade de narrar uma ou duas das minhas insignificantes experiências, talvez lhe interesse isto.” Atirou-lhe uma folha de papel de carta grosso, de tom rosado, que estivera aberta sobre a mesa. “Veio pelo último correio”, disse. “Leia em voz alta.”","thenotewasundatedandwithouteithersignatu~eithersignatureoraddress~51":"O bilhete não tinha data, nem assinatura, nem endereço.","therewillcalluponyoutonightataquartertoe~ssifyourvisitorwearamask~386":"“Visitá-lo-á esta noite, às oito menos um quarto”, dizia, “um cavalheiro que deseja consultá-lo sobre um assunto da mais profunda gravidade. Os seus recentes serviços a uma das casas reais da Europa demonstraram que o senhor é pessoa a quem se podem confiar com segurança matérias de uma importância que dificilmente se poderia exagerar. Esta informação a seu respeito recebemo-la de todos os lados. Esteja então em seu gabinete a essa hora e não leve a mal se o visitante usar máscara.”","thisisindeedamysteryiremarkedwhatdoyouim~tdoyouimaginethatitmeans~56":"“Isto é de fato um mistério”, observei. “Que imagina que signifique?”","ihavenodatayetitisacapitalmistaketotheor~elfwhatdoyoudeducefromit~169":"“Ainda não tenho dados. É um erro capital teorizar antes de ter dados. Insensivelmente começamos a torcer os fatos para se ajustarem às teorias, em vez de teorias para se ajustarem aos fatos. Mas o bilhete em si. O que deduz dele?”","icarefullyexaminedthewritingandthepaperu~peruponwhichitwaswritten~60":"Examinei cuidadosamente a escrita e o papel em que fora escrita.","themanwhowroteitwaspresumablywelltodoire~peculiarlystrongandstiff~163":"“O homem que o escreveu era presumivelmente abastado”, observei, procurando imitar os processos do meu companheiro. “Tal papel não se compraria por menos de meia coroa o maço. É peculiarmente forte e rígido.”","peculiarthatistheverywordsaidholmesitisn~ratallholdituptothelight~79":"“Peculiar, essa é exatamente a palavra”, disse Holmes. “Não é de modo algum um papel inglês. Segure-o contra a luz.”","ididsoandsawalargeewithasmallgapandalarg~intothetextureofthepaper~82":"Assim fiz, e vi um E grande com um g pequeno, um P e um G grande com um t pequeno entretecidos na textura do papel.","whatdoyoumakeofthataskedholmes~youmakeofthataskedholmes~30":"“Que conclui disso?”, perguntou Holmes.","thenameofthemakernodoubtorhismonogramrat~doubtorhismonogramrather~43":"“O nome do fabricante, sem dúvida; ou antes, seu monograma.”","notatallthegwiththesmalltstandsforgesell~antcloudfromhiscigarette~487":"“Absolutamente. O G com o t pequeno significa ‘Gesellschaft’, que é o alemão para ‘Companhia’. É uma contração habitual, como o nosso ‘Cia.’ P, claro, significa ‘Papier’. Agora o ‘Eg’. Demos uma olhada em nosso Dicionário Geográfico Continental.” Tirou da estante um pesado volume marrom. “Eglow, Eglonitz... aqui estamos, Egria. Fica num país de língua alemã, na Boêmia, não longe de Carlsbad. ‘Notável por ter sido o cenário da morte de Wallenstein e por suas numerosas fábricas de vidro e fábricas de papel.’ Ha, ha, meu rapaz, que conclui disso?” Seus olhos faiscaram, e ele soltou uma grande nuvem azul triunfante do cigarro.","thepaperwasmadeinbohemiaisaid~perwasmadeinbohemiaisaid~29":"“O papel foi feito na Boêmia”, disse eu.","preciselyandthemanwhowrotethenoteisagerm~kentoresolveallourdoubts~386":"“Precisamente. E o homem que escreveu o bilhete é alemão. Repara na construção peculiar da frase: ‘Esta informação a seu respeito recebemo-la de todos os lados.’ Um francês ou um russo não poderia ter escrito isso. É o alemão que é tão descortês com seus verbos. Resta, portanto, apenas descobrir o que quer este alemão que escreve em papel boêmio e prefere usar máscara a mostrar o rosto. E aí vem ele, se não me engano, para resolver todas as nossas dúvidas.”","ashespoketherewasthesharpsoundofhorsesho~latthebellholmeswhistled~116":"Enquanto falava, ouviu-se o som agudo de cascos de cavalos e de rodas raspando o meio-fio, seguido de um puxão brusco na campainha. Holmes assobiou.","apairbythesoundsaidheyeshecontinuedglanc~tsonifthereisnothingelse~170":"“Uma parelha, pelo som”, disse. “Sim”, continuou, olhando pela janela. “Uma bela caleche pequena e um par de belezas. Cento e cinquenta guinéus cada um. Há dinheiro neste caso, Watson, se não houver mais nada.”","ithinkthatihadbettergoholmes~nkthatihadbettergoholmes~28":"“Acho que é melhor eu ir, Holmes.”","notabitdoctorstaywhereyouareiamlostwitho~ngitwouldbeapitytomissit~103":"“Nada disso, Doutor. Fique onde está. Estou perdido sem o meu Boswell. E isto promete ser interessante. Seria uma pena perdê-lo.”","butyourclient~butyourclient~13":"“Mas o seu cliente...”","nevermindhimimaywantyourhelpandsomayhehe~dgiveusyourbestattention~102":"“Não se importe com ele. Posso precisar de sua ajuda, e ele também. Aí vem. Sente-se naquela poltrona, Doutor, e dê-nos sua melhor atenção.”","aslowandheavystepwhichhadbeenhearduponth~aloudandauthoritativetap~129":"Um passo lento e pesado, que se ouvira na escada e no corredor, deteve-se imediatamente do lado de fora da porta. Depois ouviu-se uma batida forte e autoritária.","comeinsaidholmes~comeinsaidholmes~16":"“Entre!”, disse Holmes.","amanenteredwhocouldhardlyhavebeenlesstha~edtothelengthofobstinacy~902":"Entrou um homem que dificilmente teria menos de um metro e noventa e cinco de altura, com o peito e os membros de um Hércules. Sua roupa era rica, de uma riqueza que na Inglaterra seria tida como próxima do mau gosto. Pesadas faixas de astracã cortavam as mangas e a frente do casaco de peito duplo, enquanto a capa azul-escura lançada sobre os ombros era forrada de seda cor de chama e presa no pescoço por um broche formado de um único berilo flamejante. Botas que subiam até a metade das panturrilhas, guarnecidas no alto de rico pelo marrom, completavam a impressão de opulência bárbara sugerida por toda a sua aparência. Trazia na mão um chapéu de abas largas, enquanto usava, sobre a parte superior do rosto, descendo além das maçãs, uma máscara negra de veludo, que aparentemente ajustara naquele mesmo instante, pois a mão ainda estava erguida para ela ao entrar. Pela parte inferior do rosto parecia um homem de caráter forte, com um lábio grosso e pendente e um queixo longo e reto, sugestivo de uma resolução levada ao extremo da obstinação.","youhadmynoteheaskedwithadeepharshvoicean~funcertainwhichtoaddress~146":"“Recebeu meu bilhete?”, perguntou com voz grave e áspera e um forte sotaque alemão. “Eu disse que o visitaria.” Olhou de um para outro de nós, como se incerto a quem se dirigir.","praytakeaseatsaidholmesthisismyfriendand~mhaveithehonourtoaddress~128":"“Por favor, sente-se”, disse Holmes. “Este é meu amigo e colega, o Dr. Watson, que ocasionalmente tem a bondade de me ajudar em meus casos. A quem tenho a honra de me dirigir?”","youmayaddressmeasthecountvonkrammabohemi~ocommunicatewithyoualone~212":"“Pode dirigir-se a mim como o Conde Von Kramm, nobre boêmio. Entendo que este cavalheiro, seu amigo, é homem de honra e discrição, em quem posso confiar um assunto da mais extrema importância. Se não, preferiria muito comunicar-me com o senhor a sós.”","irosetogobutholmescaughtmebythewristandp~ythingwhichyoumaysaytome~136":"Levantei-me para sair, mas Holmes me agarrou pelo pulso e empurrou-me de volta à poltrona. “Ou ambos, ou nenhum”, disse. “Pode dizer diante deste cavalheiro tudo o que puder dizer a mim.”","thecountshruggedhisbroadshouldersthenimu~uenceuponeuropeanhistory~231":"O Conde encolheu os largos ombros. “Então devo começar”, disse, “obrigando os dois ao mais absoluto sigilo por dois anos; ao fim desse tempo, o assunto não terá importância. Por ora não é exagero dizer que é de tal peso que pode influir na história da Europa.”","ipromisesaidholmes~ipromisesaidholmes~18":"“Prometo”, disse Holmes.","andi~andi~4":"“E eu.”","youwillexcusethismaskcontinuedourstrange~dmyselfisnotexactlymyown~181":"“Desculpará esta máscara”, continuou o estranho visitante. “A augusta pessoa que me emprega deseja que seu agente seja desconhecido do senhor, e posso confessar desde já que o título pelo qual acabo de me chamar não é exatamente o meu.”","iwasawareofitsaidholmesdryly~awareofitsaidholmesdryly~28":"“Eu o sabia”, disse Holmes secamente.","thecircumstancesareofgreatdelicacyandeve~hereditarykingsofbohemia~239":"“As circunstâncias são de grande delicadeza, e todas as precauções devem ser tomadas para sufocar o que poderia crescer até se tornar um imenso escândalo e comprometer seriamente uma das famílias reinantes da Europa. Para falar com clareza, o assunto implica a grande Casa de Ormstein, reis hereditários da Boêmia.”","iwasalsoawareofthatmurmuredholmessettlin~rmchairandclosinghiseyes~82":"“Isso também eu sabia”, murmurou Holmes, acomodando-se na poltrona e fechando os olhos.","ourvisitorglancedwithsomeapparentsurpris~entlyathisgiganticclient~225":"Nosso visitante olhou, com alguma surpresa aparente, para a figura lânguida e indolente do homem que lhe fora sem dúvida descrito como o raciocinador mais incisivo e o agente mais enérgico da Europa. Holmes reabriu lentamente os olhos e fitou com impaciência o gigantesco cliente.","ifyourmajestywouldcondescendtostateyourc~dbebetterabletoadviseyou~83":"“Se Vossa Majestade se dignasse expor o seu caso”, observou, “eu estaria em melhores condições de aconselhá-lo.”","themansprangfromhischairandpacedupanddow~houldiattempttoconcealit~206":"O homem ergueu-se de um salto da cadeira e andou de um lado para outro da sala em agitação incontrolável. Então, com um gesto de desespero, arrancou a máscara do rosto e atirou-a ao chão. “Tem razão”, gritou; “sou o Rei. Por que tentaria ocultá-lo?”","whyindeedmurmuredholmesyourmajestyhadnot~dhereditarykingofbohemia~167":"“Por quê, de fato?”, murmurou Holmes. “Vossa Majestade ainda não havia falado e eu já sabia que me dirigia a Wilhelm Gottsreich Sigismond von Ormstein, Grão-Duque de Cassel-Felstein e Rei hereditário da Boêmia.”","butyoucanunderstandsaidourstrangevisitor~hepurposeofconsultingyou~310":"“Mas pode compreender”, disse nosso estranho visitante, sentando-se mais uma vez e passando a mão pela alta fronte branca, “pode compreender que não estou habituado a tratar de tais negócios pessoalmente. Contudo o assunto era tão delicado que não podia confiá-lo a um agente sem me pôr em seu poder. Vim incógnito de Praga com o propósito de consultá-lo.”","thenprayconsultsaidholmesshuttinghiseyes~sshuttinghiseyesoncemore~48":"“Então, queira consultar”, disse Holmes, fechando os olhos de novo.","thefactsarebrieflythesesomefiveyearsagod~meisnodoubtfamiliartoyou~150":"“Os fatos são brevemente estes: há cerca de cinco anos, durante uma longa estada em Varsóvia, travei conhecimento com a conhecida aventureira Irene Adler. O nome sem dúvida lhe é familiar.”","kindlylookherupinmyindexdoctormurmuredho~raphuponthedeepseafishes~358":"“Faça a gentileza de procurá-la no meu índice, Doutor”, murmurou Holmes sem abrir os olhos. Por muitos anos adotara um sistema de catalogar todos os parágrafos sobre homens e coisas, de modo que era difícil nomear um assunto ou uma pessoa sobre a qual não pudesse de pronto fornecer informações. Neste caso achei sua biografia espremida entre a de um rabino hebreu e a de um comandante de estado-maior que escrevera uma monografia sobre os peixes de águas profundas.","letmeseesaidholmeshumborninnewjerseyinth~fgettingthoselettersback~282":"“Vejamos!”, disse Holmes. “Hum! Nascida em Nova Jersey no ano de 1858. Contralto, hum! La Scala, hum! Prima-dona da Ópera Imperial de Varsóvia, sim! Retirada dos palcos de ópera, ah! Vivendo em Londres, exatamente! Vossa Majestade, segundo entendo, envolveu-se com essa jovem, escreveu-lhe algumas cartas comprometedoras e deseja agora reaver essas cartas.”","preciselysobuthow~preciselysobuthow~17":"“Precisamente. Mas como...”","wasthereasecretmarriage~wasthereasecretmarriage~23":"“Houve casamento secreto?”","none~none~4":"“Nenhuma.”","nolegalpapersorcertificates~egalpapersorcertificates~27":"“Nenhum documento legal ou certidão?”","thenifailtofollowyourmajestyifthisyoungp~toprovetheirauthenticity~130":"“Então não acompanho Vossa Majestade. Se essa jovem apresentar suas cartas para chantagem ou outros fins, como provará a autenticidade delas?”","thereisthewriting~thereisthewriting~17":"“Há a letra.”","poohpoohforgery~poohpoohforgery~15":"“Bah, bah! Falsificação.”","myprivatenotepaper~myprivatenotepaper~18":"“Meu papel de carta particular.”","stolen~stolen~6":"“Roubado.”","myownseal~myownseal~9":"“Meu próprio selo.”","imitated~imitated~8":"“Imitado.”","myphotograph~myphotograph~12":"“Minha fotografia.”","bought~bought~6":"“Comprada.”","wewerebothinthephotograph~ewerebothinthephotograph~25":"“Estávamos os dois na fotografia.”","ohdearthatisverybadyourmajestyhasindeedc~dcommittedanindiscretion~62":"“Oh, céus! Isso é muito mau! Vossa Majestade cometeu de fato uma indiscrição.”","iwasmadinsane~iwasmadinsane~13":"“Eu estava louco, insano.”","youhavecompromisedyourselfseriously~romisedyourselfseriously~35":"“Comprometeu-se seriamente.”","iwasonlycrownprincetheniwasyoungiambutth~iwasyoungiambutthirtynow~47":"“Eu era apenas Príncipe Herdeiro então. Era jovem. Tenho agora apenas trinta anos.”","itmustberecovered~itmustberecovered~17":"“Deve ser recuperada.”","wehavetriedandfailed~wehavetriedandfailed~20":"“Tentamos e fracassamos.”","yourmajestymustpayitmustbebought~stymustpayitmustbebought~32":"“Vossa Majestade deve pagar. Deve ser comprada.”","shewillnotsell~shewillnotsell~14":"“Ela não quer vender.”","stolenthen~stolenthen~10":"“Roubada, então.”","fiveattemptshavebeenmadetwiceburglarsinm~laidtherehasbeennoresult~143":"“Fizeram-se cinco tentativas. Por duas vezes assaltantes a meu soldo reviraram a casa dela. Uma vez desviamos sua bagagem quando viajava. Duas vezes foi emboscada. Não houve resultado.”","nosignofit~nosignofit~10":"“Nenhum sinal dela?”","absolutelynone~absolutelynone~14":"“Absolutamente nenhum.”","holmeslaugheditisquiteaprettylittleprobl~rettylittleproblemsaidhe~48":"Holmes riu. “É um problemazinho bem bonito”, disse.","butaveryseriousonetomereturnedthekingrep~rnedthekingreproachfully~50":"“Mas muito sério para mim”, retrucou o Rei em tom de censura.","veryindeedandwhatdoessheproposetodowitht~osetodowiththephotograph~52":"“Muito, de fato. E que pretende ela fazer com a fotografia?”","toruinme~toruinme~8":"“Arruinar-me.”","buthow~buthow~6":"“Mas como?”","iamabouttobemarried~iamabouttobemarried~19":"“Estou prestes a casar-me.”","soihaveheard~soihaveheard~12":"“Assim ouvi dizer.”","toclotildelothmanvonsaxemeningensecondda~uldbringthemattertoanend~195":"“Com Clotilde Lothman von Saxe-Meningen, segunda filha do Rei da Escandinávia. O senhor talvez conheça os rígidos princípios da família dela. Ela própria é a própria alma da delicadeza. Uma sombra de dúvida quanto à minha conduta poria fim ao assunto.”","andireneadler~andireneadler~13":"“E Irene Adler?”","threatenstosendthemthephotographandshewi~towhichshewouldnotgonone~247":"“Ameaça enviar-lhes a fotografia. E o fará. Sei que o fará. O senhor não a conhece, mas ela tem uma alma de aço. Tem o rosto da mais bela das mulheres e a mente do mais resoluto dos homens. Para evitar que eu me case com outra mulher, não há extremos a que não chegue; nenhum.”","youaresurethatshehasnotsentityet~rethatshehasnotsentityet~32":"“Tem certeza de que ela ainda não a enviou?”","iamsure~iamsure~7":"“Tenho certeza.”","andwhy~andwhy~6":"“E por quê?”","becauseshehassaidthatshewouldsenditonthe~imedthatwillbenextmonday~100":"“Porque disse que a enviaria no dia em que o noivado fosse publicamente proclamado. Será na próxima segunda-feira.”","ohthenwehavethreedaysyetsaidholmeswithay~tayinlondonforthepresent~167":"“Oh, então ainda temos três dias”, disse Holmes com um bocejo. “Isso é muito feliz, pois tenho uma ou duas questões importantes a examinar justamente agora. Vossa Majestade permanecerá, é claro, em Londres por ora?”","certainlyyouwillfindmeatthelanghamundert~henameofthecountvonkramm~64":"“Certamente. O senhor me encontrará no Langham, sob o nome de Conde Von Kramm.”","thenishalldropyoualinetoletyouknowhowwep~oletyouknowhowweprogress~47":"“Então lhe enviarei algumas linhas para informá-lo de como progredimos.”","praydosoishallbeallanxiety~aydosoishallbeallanxiety~26":"“Faça-o, por favor. Estarei em plena ansiedade.”","thenastomoney~thenastomoney~13":"“Quanto ao dinheiro, então?”","youhavecarteblanche~youhavecarteblanche~19":"“Tem carta branca.”","absolutely~absolutely~10":"“Absolutamente?”","itellyouthatiwouldgiveoneoftheprovinceso~gdomtohavethatphotograph~70":"“Digo-lhe que daria uma das províncias do meu reino por essa fotografia.”","andforpresentexpenses~andforpresentexpenses~21":"“E para as despesas imediatas?”","thekingtookaheavychamoisleatherbagfromun~cloakandlaiditonthetable~70":"O Rei tirou de baixo da capa uma pesada bolsa de camurça e a pôs sobre a mesa.","therearethreehundredpoundsingoldandseven~evenhundredinnoteshesaid~60":"“Há trezentas libras em ouro e setecentas em notas”, disse.","holmesscribbledareceiptuponasheetofhisno~notebookandhandedittohim~62":"Holmes rabiscou um recibo numa folha de seu caderno e entregou-lho.","andmademoisellesaddressheasked~emoisellesaddressheasked~30":"“E o endereço da Mademoiselle?”, perguntou.","isbrionylodgeserpentineavenuestjohnswood~pentineavenuestjohnswood~40":"“É Briony Lodge, Serpentine Avenue, St. John’s Wood.”","holmestookanoteofitoneotherquestionsaidh~wasthephotographacabinet~65":"Holmes anotou. “Mais uma pergunta”, disse. “A fotografia era formato gabinete?”","itwas~itwas~5":"“Era.”","thengoodnightyourmajestyanditrustthatwes~slittlematteroverwithyou~244":"“Então, boa noite, Majestade, e confio em que logo teremos boas notícias para o senhor. E boa noite, Watson”, acrescentou, enquanto as rodas da caleche real rolavam rua abaixo. “Se tiver a bondade de passar aqui amanhã à tarde, às três horas, gostaria de conversar com o senhor sobre este pequeno caso.”","ii~ii~2":"II","atthreeoclockpreciselyiwasatbakerstreetb~dceasedtoenterintomyhead~816":"Às três em ponto eu estava na Baker Street, mas Holmes ainda não voltara. A senhoria informou-me que ele saíra de casa pouco depois das oito da manhã. Sentei-me, contudo, junto ao fogo, com a intenção de esperá-lo, por mais que demorasse. Eu já estava profundamente interessado em sua investigação, pois, embora não a cercasse nenhum dos traços sinistros e estranhos associados aos dois crimes que já registrei, ainda assim a natureza do caso e a elevada posição de seu cliente lhe davam um caráter próprio. Na verdade, à parte a natureza da investigação que meu amigo tinha em mãos, havia algo em seu domínio magistral de uma situação e em seu raciocínio arguto e incisivo que me fazia um prazer estudar seu sistema de trabalho e seguir os métodos rápidos e sutis com que desenredava os mistérios mais inextricáveis. Tão acostumado estava eu ao seu invariável êxito que a própria possibilidade de falhar deixara de me passar pela cabeça.","itwascloseuponfourbeforethedooropenedand~edheartilyforsomeminutes~444":"Eram quase quatro horas quando a porta se abriu e um cavalariço de aspecto embriagado, desgrenhado e de suíças, com o rosto inflamado e roupas indecentes, entrou na sala. Habituado como eu estava aos assombrosos poderes de meu amigo no uso de disfarces, tive de olhar três vezes até ter certeza de que era de fato ele. Com um aceno, desapareceu no quarto, de onde saiu cinco minutos depois de terno de tweed e respeitável, como outrora. Pondo as mãos nos bolsos, estendeu as pernas diante do fogo e riu de bom grado por alguns minutos.","wellreallyhecriedandthenhechokedandlaugh~impandhelplessinthechair~98":"“Bem, realmente!”, exclamou, e depois engasgou-se e riu de novo até ser obrigado a recostar-se, frouxo e indefeso, na poltrona.","whatisit~whatisit~8":"“O que foi?”","itsquitetoofunnyiamsureyoucouldnevergues~rningorwhatiendedbydoing~81":"“É engraçado demais. Tenho certeza de que o senhor nunca adivinharia como empreguei a manhã, nem o que acabei fazendo.”","icantimagineisupposethatyouhavebeenwatch~thehouseofmissireneadler~86":"“Não consigo imaginar. Suponho que tenha estado observando os hábitos, e talvez a casa, da Srta. Irene Adler.”","quitesobutthesequelwasratherunusualiwill~nganythingelseofinterest~670":"“Exatamente; mas o desfecho foi bastante insólito. Contarei, porém. Saí de casa um pouco depois das oito desta manhã, no papel de um cavalariço sem emprego. Há uma maravilhosa simpatia e maçonaria entre os homens ligados a cavalos. Seja um deles e saberá tudo o que há para saber. Logo encontrei Briony Lodge. É uma vila bijou, com um jardim nos fundos, mas construída na frente até rente à estrada, de dois andares. Fechadura Chubb na porta. Grande sala de estar no lado direito, bem mobiliada, com janelas longas quase até o chão e aqueles ridículos fechos de janela ingleses que uma criança abriria. Atrás não havia nada de notável, exceto que a janela do corredor podia ser alcançada do alto da cocheira. Rodeei-a e examinei-a de perto de todos os pontos de vista, mas sem notar mais nada de interesse.","ithenloungeddownthestreetandfoundasiexpe~siwascompelledtolistento~390":"“Então vadiei rua abaixo e descobri, como esperava, que havia uma cocheira de aluguel numa viela que corre ao longo de um dos muros do jardim. Dei uma mão aos cavalariços esfregando os cavalos e recebi em troca dois pence, um copo de meio a meio, duas cargas de fumo cortado e toda a informação que pudesse desejar sobre a Srta. Adler, sem falar de meia dúzia de outras pessoas da vizinhança por quem eu não tinha o menor interesse, mas cujas biografias fui obrigado a ouvir.”","andwhatofireneadleriasked~ndwhatofireneadleriasked~25":"“E o que há sobre Irene Adler?”, perguntei.","ohshehasturnedallthemensheadsdowninthatp~hinkovermyplanofcampaign~595":"“Oh, ela virou a cabeça de todos os homens daquela região. É a coisa mais delicada que existe sob uma touca neste planeta. Assim dizem, até o último homem, as cocheiras de Serpentine. Vive tranquilamente, canta em concertos, sai de carro às cinco todos os dias e volta às sete em ponto para o jantar. Raramente sai em outras horas, exceto quando canta. Tem apenas um visitante masculino, mas bastante assíduo. É moreno, bonito e garboso, nunca visita menos de uma vez por dia e muitas vezes duas. É um certo Sr. Godfrey Norton, do Inner Temple. Veja as vantagens de um cocheiro como confidente. Já o haviam levado para casa uma dúzia de vezes, saindo das cocheiras de Serpentine, e sabiam tudo a seu respeito. Depois de ouvir tudo o que tinham a contar, comecei a andar de novo para cima e para baixo perto de Briony Lodge e a refletir sobre meu plano de campanha.","thisgodfreynortonwasevidentlyanimportant~tounderstandthesituation~553":"“Esse Godfrey Norton era evidentemente um fator importante no caso. Era advogado. Isso soava agourento. Qual era a relação entre eles, e qual o objetivo de suas visitas repetidas? Era ela cliente dele, amiga ou amante? Se a primeira hipótese, provavelmente lhe transferira a fotografia para guarda. Se a última, era menos provável. Da resposta a essa pergunta dependia que eu continuasse meu trabalho em Briony Lodge ou voltasse a atenção para as salas do cavalheiro no Temple. Era um ponto delicado, e ampliava o campo de minha investigação. Receio aborrecê-lo com esses pormenores, mas tenho de lhe mostrar as minhas pequenas dificuldades, se quiser compreender a situação.”","iamfollowingyoucloselyianswered~owingyoucloselyianswered~31":"“Estou acompanhando de perto”, respondi.","iwasstillbalancingthematterinmymindwhena~anwhowasthoroughlyathome~299":"“Eu ainda sopesava a questão em minha mente quando um cabriolé parou em Briony Lodge e um cavalheiro saltou dele. Era um homem notavelmente bonito, moreno, de nariz aquilino e de bigode, evidentemente o homem de quem eu ouvira falar. Parecia ter muita pressa, gritou ao cocheiro que esperasse e passou rente pela criada que abriu a porta, com o ar de um homem completamente à vontade.","hewasinthehouseabouthalfanhourandicouldc~ifyoudoitintwentyminutes~417":"“Esteve na casa cerca de meia hora, e eu podia apanhar vislumbres dele nas janelas da sala, andando de um lado para outro, falando excitado e agitando os braços. Dela nada pude ver. Logo saiu, parecendo ainda mais atarantado do que antes. Ao subir no cabriolé, tirou do bolso um relógio de ouro e olhou-o com ansiedade. ‘Dirija como o diabo’, gritou, ‘primeiro à Gross & Hankey, na Regent Street, e depois à Igreja de Santa Mônica, na Edgeware Road. Meia guinéu se o fizer em vinte minutos!’","awaytheywentandiwasjustwonderingwhetheri~afacethatamanmightdiefor~350":"“Lá se foram, e eu estava justamente me perguntando se não faria bem em segui-los quando subiu pela viela um elegante landau pequeno, o cocheiro com o casaco só meio abotoado e a gravata sob a orelha, enquanto todas as pontas do arreio saíam das fivelas. Mal havia parado, ela disparou pela porta do vestíbulo e entrou nele. Só a vi de relance naquele momento, mas era uma mulher encantadora, com um rosto pelo qual um homem poderia morrer.","thechurchofstmonicajohnshecriedandhalfas~oureachitintwentyminutes~75":"“ ‘À Igreja de Santa Mônica, John’, gritou ela, ‘e meio soberano se chegar em vinte minutos.’","thiswasquitetoogoodtolosewatsoniwasjustb~arenoughwhatwasinthewind~343":"“Aquilo era bom demais para perder, Watson. Eu estava sopesando se devia correr atrás ou se devia empoleirar-me atrás do landau, quando um cabriolé passou pela rua. O cocheiro olhou duas vezes para um passageiro tão maltrapilho, mas pulei para dentro antes que pudesse objetar. ‘À Igreja de Santa Mônica’, disse eu, ‘e meio soberano se chegar em vinte minutos.’ Eram doze menos vinte e cinco, e é claro que estava bem claro o que se tramava.","mycabbydrovefastidontthinkieverdrovefast~ashardashecouldtowardsme~495":"“Meu cocheiro dirigiu depressa. Não creio que jamais tenha andado mais rápido, mas os outros chegaram antes de nós. O cabriolé e o landau, com os cavalos fumegantes, estavam diante da porta quando cheguei. Paguei o homem e corri para dentro da igreja. Não havia viva alma ali, exceto os dois que eu seguira e um clérigo de sobrepeliz, que parecia estar discutindo com eles. Estavam os três reunidos num grupo diante do altar. Fui vadiando pela nave lateral, como qualquer outro desocupado que entrou numa igreja. De repente, para minha surpresa, os três no altar voltaram-se para mim, e Godfrey Norton veio correndo o mais depressa que podia em minha direção.","thankgodhecriedyoulldocomecome~odhecriedyoulldocomecome~30":"“ ‘Graças a Deus’, gritou. ‘Serve. Venha! Venha!’","whattheniasked~whattheniasked~14":"“ ‘Que é?’, perguntei.","comemancomeonlythreeminutesoritwontbeleg~eeminutesoritwontbelegal~42":"“ ‘Venha, homem, venha, só três minutos, ou não será legal.’","iwashalfdraggeduptothealtarandbeforeikne~aininmemoryoftheoccasion~753":"“Fui meio arrastado até o altar e, antes que soubesse onde estava, vi-me murmurando respostas que me sopravam ao ouvido e atestando coisas de que nada sabia, e de modo geral auxiliando no firme enlace de Irene Adler, solteira, com Godfrey Norton, solteiro. Foi tudo feito num instante, e ali estava o cavalheiro me agradecendo de um lado e a dama do outro, enquanto o clérigo sorria para mim de frente. Foi a posição mais disparatada em que já me vi na vida, e foi o pensamento dela que me fez começar a rir agora há pouco. Parece que havia alguma irregularidade na licença deles, que o clérigo recusou-se terminantemente a casá-los sem uma testemunha qualquer e que minha aparição providencial poupou o noivo de ter de sair pelas ruas em busca de um padrinho. A noiva me deu um soberano, e pretendo usá-lo na corrente do relógio em lembrança da ocasião.”","thisisaveryunexpectedturnofaffairssaidia~faffairssaidiandwhatthen~50":"“É uma reviravolta muito inesperada”, disse eu; “e depois?”","wellifoundmyplansveryseriouslymenaceditl~ftomakemyownarrangements~352":"“Bem, vi meus planos muito seriamente ameaçados. Parecia que o par poderia partir imediatamente, o que exigiria medidas muito rápidas e enérgicas de minha parte. À porta da igreja, porém, separaram-se, ele voltando de carro ao Temple e ela à sua própria casa. ‘Passearei no parque às cinco, como de costume’, disse ela ao deixá-lo. Não ouvi mais. Partiram em direções diferentes, e fui fazer meus próprios arranjos.”","whichare~whichare~8":"“Quais são?”","somecoldbeefandaglassofbeerheansweredrin~shallwantyourcooperation~157":"“Um pouco de rosbife frio e um copo de cerveja”, respondeu, tocando a campainha. “Estive ocupado demais para pensar em comida, e é provável que esteja mais ocupado ainda esta noite. A propósito, Doutor, precisarei de sua cooperação.”","ishallbedelighted~ishallbedelighted~17":"“Terei prazer.”","youdontmindbreakingthelaw~oudontmindbreakingthelaw~25":"“Não se importa de infringir a lei?”","notintheleast~notintheleast~13":"“Nem um pouco.”","norrunningachanceofarrest~orrunningachanceofarrest~25":"“Nem de correr o risco de ser preso?”","notinagoodcause~notinagoodcause~15":"“Não por uma boa causa.”","ohthecauseisexcellent~ohthecauseisexcellent~21":"“Oh, a causa é excelente!”","theniamyourman~theniamyourman~14":"“Então sou o seu homem.”","iwassurethatimightrelyonyou~ssurethatimightrelyonyou~27":"“Tinha certeza de que podia contar com o senhor.”","butwhatisityouwish~butwhatisityouwish~18":"“Mas o que deseja?”","whenmrsturnerhasbroughtinthetrayiwillmak~beatbrionylodgetomeether~295":"“Quando a Sra. Turner tiver trazido a bandeja, deixarei claro. Agora”, disse, voltando-se faminto para a simples refeição que nossa senhoria preparara, “devo discutir enquanto como, pois não tenho muito tempo. São quase cinco agora. Em duas horas devemos estar no local da ação. A Srta. Irene, ou Madame, antes, volta do passeio às sete. Devemos estar em Briony Lodge para recebê-la.”","andwhatthen~andwhatthen~11":"“E depois?”","youmustleavethattomeihavealreadyarranged~comewhatmayyouunderstand~133":"“Deixe isso por minha conta. Já arranjei o que vai ocorrer. Há apenas um ponto em que devo insistir. O senhor não deve interferir, aconteça o que acontecer. Entende?”","iamtobeneutral~iamtobeneutral~14":"“Devo ficar neutro?”","todonothingwhatevertherewillprobablybeso~elfclosetothatopenwindow~211":"“Não fazer absolutamente nada. Provavelmente haverá algum pequeno desagrado. Não tome parte. Terminará com eu ser levado para dentro da casa. Quatro ou cinco minutos depois a janela da sala de estar se abrirá. O senhor deve se colocar bem junto dessa janela aberta.”","yes~yes~3":"“Sim.”","youaretowatchmeforiwillbevisibletoyou~meforiwillbevisibletoyou~37":"“Deve me observar, pois eu estarei visível para o senhor.”","andwheniraisemyhandsoyouwillthrowintothe~ryoffireyouquitefollowme~116":"“E quando eu levantar a mão, assim, o senhor lançará na sala o que eu lhe der para lançar e, ao mesmo tempo, levantará o grito de fogo. Acompanha-me bem?”","entirely~entirely~8":"“Inteiramente.”","itisnothingveryformidablehesaidtakingalo~thatihavemademyselfclear~325":"“Não é nada muito formidável”, disse, tirando do bolso um longo rolo em forma de charuto. “É um foguete de fumaça comum de encanador, munido de uma cápsula em cada extremidade para se acender sozinho. Sua tarefa se limita a isso. Quando levantar o grito de fogo, será retomado por um bom número de pessoas. O senhor pode então caminhar até o fim da rua, e eu me reunirei a você em dez minutos. Espero ter sido claro.”","iamtoremainneutraltogetnearthewindowtowa~ouatthecornerofthestreet~136":"“Devo permanecer neutro, aproximar-me da janela, observá-lo e, ao sinal, lançar este objeto, depois levantar o grito de fogo e esperá-lo na esquina da rua.”","precisely~precisely~9":"“Precisamente.”","thenyoumayentirelyrelyonme~enyoumayentirelyrelyonme~26":"“Então pode confiar inteiramente em mim.”","thatisexcellentithinkperhapsitisalmostti~forthenewroleihavetoplay~78":"“Excelente. Creio que talvez esteja quase na hora de me preparar para o novo papel que devo desempenhar.”","hedisappearedintohisbedroomandreturnedin~becameaspecialistincrime~463":"Desapareceu em seu quarto e voltou em poucos minutos no papel de um clérigo inconformista, amável e de espírito simples. O chapéu preto de abas largas, as calças folgadas, a gravata branca, o sorriso simpático e o ar geral de curiosidade perscrutadora e benevolente eram tais que só o Sr. John Hare poderia igualar. Não era apenas que Holmes mudasse de traje. Sua expressão, seus modos, sua própria alma pareciam variar a cada novo papel que assumia. O teatro perdeu um grande ator, tal como a ciência perdeu um raciocinador agudo, quando ele se tornou especialista em crime.","itwasaquarterpastsixwhenweleftbakerstree~nwithcigarsintheirmouths~631":"Eram seis e quinze quando deixamos a Baker Street, e ainda faltavam dez minutos para a hora quando nos vimos na Serpentine Avenue. Já era crepúsculo, e os lampiões estavam sendo acesos enquanto andávamos de um lado para outro diante de Briony Lodge, esperando a chegada de sua ocupante. A casa era exatamente como eu a imaginara pela sucinta descrição de Sherlock Holmes, mas o local parecia menos reservado do que eu esperava. Ao contrário, para uma rua pequena num bairro tranquilo, era notavelmente animada. Havia um grupo de homens malvestidos fumando e rindo numa esquina, um amolador de tesouras com sua roda, dois guardas conversando com uma babá e vários jovens bem vestidos que vadiavam de um lado para outro com charutos na boca.","youseeremarkedholmesaswepacedtoandfroinf~arewetofindthephotograph~287":"“Veja”, observou Holmes, enquanto andávamos de um lado para outro diante da casa, “este casamento simplifica bastante as coisas. A fotografia torna-se agora uma arma de dois gumes. É provável que ela seja tão avessa a que o Sr. Godfrey Norton a veja quanto o nosso cliente a que chegue aos olhos de sua princesa. Agora a questão é: onde havemos de encontrar a fotografia?”","whereindeed~whereindeed~11":"“Onde, de fato?”","itismostunlikelythatshecarriesitaboutwit~esnotcarryitaboutwithher~246":"“É muito improvável que ela a traga consigo. É de tamanho gabinete. Grande demais para ocultar com facilidade nas roupas de uma mulher. Ela sabe que o Rei é capaz de mandar emboscá-la e revistá-la. Já foram feitas duas tentativas desse tipo. Podemos, portanto, dar por certo que não a traz consigo.”","wherethen~wherethen~9":"“Onde, então?”","herbankerorherlawyerthereisthatdoublepos~nititmustbeinherownhouse~396":"“Seu banqueiro ou seu advogado. Há essa dupla possibilidade. Mas inclino-me a pensar que nenhum dos dois. As mulheres são naturalmente reservadas e gostam de fazer elas mesmas o seu ocultamento. Por que a entregaria a outrem? Poderia confiar em sua própria guarda, mas não poderia saber que influência indireta ou política poderia ser exercida sobre um homem de negócios. Além disso, lembre-se de que ela resolvera usá-la dentro de poucos dias. Deve estar onde ela possa pôr as mãos nela. Deve estar em sua própria casa.”","butithastwicebeenburgled~butithastwicebeenburgled~24":"“Mas ela foi assaltada duas vezes.”","pshawtheydidnotknowhowtolook~wtheydidnotknowhowtolook~28":"“Bah! Não souberam procurar.”","buthowwillyoulook~buthowwillyoulook~17":"“Mas como o senhor procurará?”","iwillnotlook~iwillnotlook~12":"“Não procurarei.”","whatthen~whatthen~8":"“A quê, então?”","iwillgethertoshowme~iwillgethertoshowme~19":"“Farei com que ela me mostre.”","butshewillrefuse~butshewillrefuse~16":"“Mas ela se recusará.”","shewillnotbeabletobutiheartherumbleofwhe~ryoutmyorderstotheletter~88":"“Não poderá. Mas ouço o ruído de rodas. É a carruagem dela. Agora cumpra minhas ordens à risca.”","ashespokethegleamofthesidelightsofacarri~lookingbackintothestreet~1067":"Enquanto falava, o brilho das lanternas laterais de uma carruagem surgiu na curva da avenida. Era um elegante landau pequeno que chocalhou até a porta de Briony Lodge. Quando parou, um dos vadios da esquina precipitou-se para abrir a porta na esperança de ganhar um cobre, mas foi afastado a cotoveladas por outro vadio, que acorrera com a mesma intenção. Rompeu uma briga feroz, aumentada pelos dois guardas, que tomaram o partido de um dos vadios, e pelo amolador de tesouras, igualmente exaltado do outro lado. Foi desferido um golpe e, num instante, a dama, que descera da carruagem, era o centro de um pequeno grupo de homens afogueados e em luta, que se golpeavam ferozmente com os punhos e os porretes. Holmes lançou-se na multidão para proteger a dama; mas, justamente quando a alcançou, deu um grito e caiu ao chão, com o sangue escorrendo abundante pelo rosto. À sua queda, os guardas fugiram numa direção e os vadios na outra, enquanto algumas pessoas mais bem vestidas, que haviam observado a briga sem tomar parte, acorreram para ajudar a dama e atender ao ferido. Irene Adler, como ainda a chamarei, subira apressada os degraus; mas parou no alto, com sua figura soberba desenhada contra as luzes do vestíbulo, olhando de volta para a rua.","isthepoorgentlemanmuchhurtsheasked~entlemanmuchhurtsheasked~34":"“O pobre cavalheiro está muito ferido?”, perguntou.","heisdeadcriedseveralvoices~isdeadcriedseveralvoices~26":"“Está morto”, gritaram várias vozes.","nonothereslifeinhimshoutedanotherbuthell~reyoucangethimtohospital~74":"“Não, não, ainda há vida nele!”, gritou outro. “Mas se vai antes que o levem ao hospital.”","hesabravefellowsaidawomantheywouldhaveha~honetooahhesbreathingnow~126":"“É um bravo”, disse uma mulher. “Teriam levado a bolsa e o relógio da dama se não fosse por ele. Eram uma quadrilha, e das brutas. Ah, está respirando agora.”","hecantlieinthestreetmaywebringhiminmarm~treetmaywebringhiminmarm~39":"“Não pode ficar deitado na rua. Podemos levá-lo para dentro, senhora?”","surelybringhimintothesittingroomthereisa~ortablesofathiswayplease~68":"“Certamente. Levem-no para a sala de estar. Há um sofá confortável. Por aqui, por favor!”","slowlyandsolemnlyhewasborneintobrionylod~ngherfrominjuringanother~677":"Lenta e solenemente foi carregado para dentro de Briony Lodge e estendido na sala principal, enquanto eu ainda observava o desenrolar dos fatos de meu posto junto à janela. Os lampiões haviam sido acesos, mas as persianas não estavam fechadas, de modo que eu podia ver Holmes deitado no divã. Não sei se ele foi tomado de remorso naquele momento pelo papel que representava, mas sei que nunca me senti mais sinceramente envergonhado de mim mesmo em toda a minha vida do que ao ver a bela criatura contra a qual eu conspirava, ou a graça e bondade com que atendia o ferido. E no entanto seria a mais negra traição a Holmes recuar agora do papel que ele me confiara. Endureci o coração e tirei o foguete de fumaça de debaixo do meu capote. Afinal, pensei, não a estamos prejudicando. Estamos apenas impedindo que ela prejudique outro.","holmeshadsatupuponthecouchandisawhimmoti~adtowardstheedgewareroad~751":"Holmes sentara-se no divã, e vi-o fazer um gesto como quem precisa de ar. Uma criada correu e escancarou a janela. No mesmo instante vi-o erguer a mão e, ao sinal, lancei meu foguete para dentro da sala com um grito de “Fogo!”. Mal a palavra saíra de minha boca, toda a multidão de espectadores, bem vestidos e malvestidos, cavalheiros, cavalariços e criadas, juntou-se num grito geral de “Fogo!” Espessas nuvens de fumaça rodopiaram pela sala e saíram pela janela aberta. Apanhei um vislumbre de vultos correndo e, um momento depois, a voz de Holmes lá de dentro, assegurando-lhes que era alarme falso. Esgueirando-me pela multidão aos gritos, cheguei à esquina da rua e, em dez minutos, tive a alegria de sentir o braço de meu amigo no meu e de me afastar da cena do tumulto. Ele caminhou depressa e em silêncio por alguns minutos, até que tínhamos virado por uma das ruas tranquilas que levam à Edgeware Road.","youdiditverynicelydoctorheremarkednothin~vebeenbetteritisallright~72":"“O senhor se saiu muito bem, doutor”, comentou ele. “Nada poderia ter sido melhor. Está tudo certo.”","youhavethephotograph~youhavethephotograph~20":"“O senhor tem a fotografia?”","iknowwhereitis~iknowwhereitis~14":"“Sei onde ela está.”","andhowdidyoufindout~andhowdidyoufindout~19":"“E como descobriu?”","sheshowedmeasitoldyoushewould~owedmeasitoldyoushewould~29":"“Ela mesma me mostrou, como eu lhe disse que faria.”","iamstillinthedark~iamstillinthedark~17":"“Continuo às escuras.”","idonotwishtomakeamysterysaidhelaughingth~eallengagedfortheevening~148":"“Não desejo fazer mistério”, disse ele, rindo. “O caso era perfeitamente simples. O senhor, naturalmente, percebeu que todos na rua eram cúmplices. Estavam todos contratados para a noite.”","iguessedasmuch~iguessedasmuch~14":"“Foi o que imaginei.”","thenwhentherowbrokeoutihadalittlemoistre~sspectacleitisanoldtrick~146":"“Então, quando a briga estourou, eu trazia na palma da mão um pouco de tinta vermelha, ainda úmida. Precipitei-me para a frente, caí, levei a mão ao rosto e me tornei um espetáculo lastimável. É um truque velho.”","thatalsoicouldfathom~thatalsoicouldfathom~20":"“Isso também eu consegui deduzir.”","thentheycarriedmeinshewasboundtohavemein~indowandyouhadyourchance~253":"“Então me carregaram para dentro. Ela não podia deixar de me acolher. Que mais poderia fazer? E para a sua sala de estar, que era justamente o aposento que eu suspeitava. Ficava entre ela e o quarto de dormir, e eu estava decidido a descobrir qual dos dois. Deitaram-me num divã, fiz sinal pedindo ar, viram-se obrigados a abrir a janela, e o senhor teve a sua oportunidade.”","howdidthathelpyou~howdidthathelpyou~17":"“E em que isso o ajudou?”","itwasallimportantwhenawomanthinksthather~erprecipitancemayruinall~981":"“Foi da maior importância. Quando uma mulher pensa que a casa está pegando fogo, seu instinto é correr de imediato para aquilo que mais preza. É um impulso absolutamente irresistível, e já me aproveitei dele mais de uma vez. No caso do escândalo da Substituição de Darlington, ele me foi útil, e também no caso do Castelo de Arnsworth. A mulher casada agarra o bebê; a solteira alcança o porta-joias. Ora, estava claro para mim que a nossa dama de hoje não tinha em casa nada mais precioso do que aquilo que buscamos. Ela correria para pô-lo a salvo. O alarme de incêndio foi admiravelmente executado. A fumaça e os gritos bastavam para abalar nervos de aço. Ela reagiu primorosamente. A fotografia está num nicho atrás de um painel deslizante, logo acima do cordão da campainha da direita. Ela estava lá num instante, e eu a vislumbrei quando a puxou pela metade. Quando gritei que era alarme falso, ela a recolocou, olhou para o foguete, saiu apressada da sala, e não a vi mais. Levantei-me e, apresentando minhas desculpas, escapei da casa. Hesitei se devia tentar apoderar-me da fotografia de imediato; mas o cocheiro havia entrado e, como me vigiava de perto, pareceu-me mais seguro esperar. Um pouco de precipitação pode estragar tudo.”","andnowiasked~andnowiasked~12":"“E agora?”, perguntei.","ourquestispracticallyfinishedishallcallw~oregainitwithhisownhands~261":"“Nossa busca está praticamente concluída. Irei amanhã com o Rei, e com o senhor, se quiser nos acompanhar. Seremos conduzidos à sala de estar para esperar a dama, mas é provável que, quando ela vier, não encontre nem a nós nem a fotografia. Talvez seja uma satisfação para Sua Majestade recuperá-la com as próprias mãos.”","andwhenwillyoucall~andwhenwillyoucall~18":"“E quando irá?”","ateightinthemorningshewillnotbeupsothatw~iretothekingwithoutdelay~167":"“Às oito da manhã. Ela não estará de pé, de modo que teremos campo livre. Além disso, precisamos ser rápidos, pois esse casamento pode significar uma mudança completa na vida e nos hábitos dela. Devo telegrafar ao Rei sem demora.”","wehadreachedbakerstreetandhadstoppedatth~eywhensomeonepassingsaid~100":"Havíamos chegado à Baker Street e parado à porta. Ele procurava a chave nos bolsos quando alguém que passava disse:","goodnightmistersherlockholmes~ightmistersherlockholmes~29":"“Boa noite, Mister Sherlock Holmes.”","therewereseveralpeopleonthepavementatthe~nanulsterwhohadhurriedby~111":"Havia várias pessoas na calçada naquele momento, mas a saudação parecia vir de um rapaz esguio, de sobretudo comprido, que passara apressado.","iveheardthatvoicebeforesaidholmesstaring~hedeucethatcouldhavebeen~99":"“Já ouvi essa voz antes”, disse Holmes, fitando a rua mal iluminada. “Quem diabos será que era?”","iii~iii~3":"III","isleptatbakerstreetthatnightandwewereeng~bohemiarushedintotheroom~114":"Dormi na Baker Street naquela noite, e estávamos ocupados com torradas e café, pela manhã, quando o Rei da Boêmia irrompeu na sala.","youhavereallygotithecriedgraspingsherloc~ookingeagerlyintohisface~91":"“O senhor realmente o conseguiu!”, exclamou, agarrando Sherlock Holmes pelos dois ombros e olhando ansioso para o seu rosto.","notyet~notyet~6":"“Ainda não.”","butyouhavehopes~butyouhavehopes~15":"“Mas tem esperanças?”","ihavehopes~ihavehopes~10":"“Tenho esperanças.”","thencomeiamallimpatiencetobegone~iamallimpatiencetobegone~32":"“Então venha. Estou impaciente para partir.”","wemusthaveacab~wemusthaveacab~14":"“Precisamos de um cabriolé.”","nomybroughamiswaiting~nomybroughamiswaiting~21":"“Não, minha carruagem está à espera.”","thenthatwillsimplifymatterswedescendedan~ffoncemoreforbrionylodge~73":"“Então isso simplificará as coisas.” Descemos e partimos mais uma vez para Briony Lodge.","ireneadlerismarriedremarkedholmes~rismarriedremarkedholmes~33":"“Irene Adler está casada”, observou Holmes.","marriedwhen~marriedwhen~11":"“Casada! Quando?”","yesterday~yesterday~9":"“Ontem.”","buttowhom~buttowhom~9":"“Mas com quem?”","toanenglishlawyernamednorton~englishlawyernamednorton~28":"“Com um advogado inglês chamado Norton.”","butshecouldnotlovehim~butshecouldnotlovehim~21":"“Mas ela não pode amá-lo.”","iaminhopesthatshedoes~iaminhopesthatshedoes~21":"“Espero que ame.”","andwhyinhopes~andwhyinhopes~13":"“E por que espera?”","becauseitwouldspareyourmajestyallfearoff~ferewithyourmajestysplan~186":"“Porque isso pouparia Vossa Majestade de todo receio de futuros aborrecimentos. Se a dama ama o marido, não ama Vossa Majestade. Se não ama Vossa Majestade, não há razão para que interfira nos planos de Vossa Majestade.”","itistrueandyetwelliwishshehadbeenofmyown~drewupinserpentineavenue~148":"“É verdade. E no entanto...! Pois bem! Quisera que ela fosse de minha condição! Que rainha teria sido!” Recaiu num silêncio sombrio, que só foi rompido quando paramos na Serpentine Avenue.","thedoorofbrionylodgewasopenandanelderlyw~westeppedfromthebrougham~115":"A porta de Briony Lodge estava aberta, e uma mulher idosa estava nos degraus. Observou-nos com olhar sardônico quando descemos da carruagem.","mrsherlockholmesibelievesaidshe~ockholmesibelievesaidshe~31":"“O senhor é o Sr. Sherlock Holmes, creio?”, disse ela.","iammrholmesansweredmycompanionlookingath~ingandratherstartledgaze~79":"“Sou o Sr. Holmes”, respondeu meu companheiro, fitando-a com um olhar interrogativo e bastante surpreso.","indeedmymistresstoldmethatyouwerelikelyt~ringcrossforthecontinent~121":"“De fato! Minha patroa me disse que o senhor provavelmente viria. Ela partiu esta manhã com o marido, no trem das 5h15 de Charing Cross, para o Continente.”","whatsherlockholmesstaggeredbackwhitewith~eanthatshehasleftengland~88":"“Quê!” Sherlock Holmes recuou cambaleando, branco de despeito e surpresa. “A senhora quer dizer que ela deixou a Inglaterra?”","nevertoreturn~nevertoreturn~13":"“Para nunca mais voltar.”","andthepapersaskedthekinghoarselyallislos~thekinghoarselyallislost~41":"“E os papéis?”, perguntou o Rei, com voz rouca. “Está tudo perdido.”","weshallseehepushedpasttheservantandrushe~dingnightandraninthisway~531":"“Veremos.” Empurrou a criada para o lado e precipitou-se na sala de visitas, seguido pelo Rei e por mim. A mobília estava espalhada em todas as direções, com prateleiras desmontadas e gavetas abertas, como se a dama as tivesse revistado às pressas antes de fugir. Holmes correu ao cordão da campainha, arrancou um pequeno postigo deslizante e, enfiando a mão, retirou uma fotografia e uma carta. A fotografia era da própria Irene Adler em traje de noite; a carta trazia o sobrescrito: “Sherlock Holmes, Esq. Para ser retirada quando reclamada.” Meu amigo a rasgou, e os três a lemos juntos. Estava datada da meia-noite da véspera e dizia o seguinte:","mydearmrsherlockholmesyoureallydiditvery~amedownjustasyoudeparted~619":"“Meu caro Sr. Sherlock Holmes — O senhor realmente se saiu muito bem. Enganou-me por completo. Até depois do alarme de incêndio, eu não tinha suspeita alguma. Mas então, quando percebi como me traíra, comecei a pensar. Haviam-me prevenido contra o senhor meses atrás. Haviam-me dito que, se o Rei empregasse um agente, certamente seria o senhor. E o seu endereço me fora dado. Contudo, apesar de tudo isso, o senhor me fez revelar o que desejava saber. Mesmo depois de ficar desconfiada, custava-me pensar mal de um clérigo tão querido e bondoso. Mas, sabe, também fui treinada como atriz. O traje masculino não é novidade para mim. Muitas vezes aproveito a liberdade que ele proporciona. Mandei John, o cocheiro, vigiá-lo, corri para cima, vesti minhas roupas de passeio, como as chamo, e desci justo quando o senhor partia.","wellifollowedyoutoyourdoorandsomadesuret~rthetempletoseemyhusband~178":"“Pois bem, segui-o até a sua porta e assim me certifiquei de que eu era realmente objeto de interesse do célebre Sr. Sherlock Holmes. Então, de modo um tanto imprudente, desejei-lhe boa noite e parti para o Temple, a fim de ver meu marido.","weboththoughtthebestresourcewasflightwhe~maindearmrsherlockholmes~442":"“Ambos achamos que o melhor recurso era a fuga, quando perseguidos por tão formidável antagonista; de modo que o senhor encontrará o ninho vazio quando vier amanhã. Quanto à fotografia, seu cliente pode ficar em paz. Amo e sou amada por um homem melhor do que ele. O Rei pode fazer o que quiser, sem estorvo da parte de alguém a quem tão cruelmente ofendeu. Guardo-a apenas para me proteger e para conservar uma arma que sempre me assegurará contra quaisquer medidas que ele possa tomar no futuro. Deixo uma fotografia que ele talvez queira possuir; e permaneço, caro Sr. Sherlock Holmes,","verytrulyyours~verytrulyyours~14":"“Sinceramente sua,","irenenortonneeadler~irenenortonneeadler~19":"“Irene Norton, née Adler.”","whatawomanohwhatawomancriedthekingofbohe~tythatshewasnotonmylevel~183":"“Que mulher... oh, que mulher!”, exclamou o Rei da Boêmia, quando os três terminamos de ler a epístola. “Não lhe disse como era rápida e resoluta? Não teria sido uma rainha admirável? Não é uma pena que não fosse do meu nível?”","fromwhatihaveseenoftheladysheseemsindeed~moresuccessfulconclusion~176":"“Pelo que vi da dama, ela parece de fato estar num nível muito diferente do de Vossa Majestade”, disse Holmes friamente. “Lamento não ter podido levar o assunto de Vossa Majestade a uma conclusão mais bem-sucedida.”","onthecontrarymydearsircriedthekingnothin~ssafeasifitwereinthefire~132":"“Pelo contrário, meu caro senhor”, exclamou o Rei; “nada poderia ter sido mais bem-sucedido. Sei que a palavra dela é inviolável. A fotografia agora está tão segura como se estivesse no fogo.”","iamgladtohearyourmajestysayso~adtohearyourmajestysayso~29":"“Alegro-me em ouvir Vossa Majestade dizer isso.”","iamimmenselyindebtedtoyoupraytellmeinwha~toutuponthepalmofhishand~137":"“Estou imensamente em dívida com o senhor. Peço-lhe que diga de que modo posso recompensá-lo. Este anel...” Tirou do dedo um anel em forma de serpente, de esmeralda, e estendeu-o na palma da mão.","yourmajestyhassomethingwhichishouldvalue~evenmorehighlysaidholmes~64":"“Vossa Majestade possui algo que eu estimaria ainda mais”, disse Holmes.","youhavebuttonameit~youhavebuttonameit~18":"“Basta nomeá-lo.”","thisphotograph~thisphotograph~14":"“Esta fotografia!”","thekingstaredathiminamazement~ngstaredathiminamazement~29":"O Rei fitou-o, atônito.","irenesphotographhecriedcertainlyifyouwis~riedcertainlyifyouwishit~43":"“A fotografia de Irene!”, exclamou. “Certamente, se o senhor a deseja.”","ithankyourmajestythenthereisnomoretobedo~nmycompanyforhischambers~201":"“Agradeço a Vossa Majestade. Então nada mais há a fazer neste assunto. Tenho a honra de lhe desejar um ótimo dia.” Inclinou-se e, virando-se sem notar a mão que o Rei lhe estendera, partiu em minha companhia para seus aposentos.","andthatwashowagreatscandalthreatenedtoaf~onourabletitleofthewoman~290":"E foi assim que um grande escândalo ameaçou atingir o reino da Boêmia, e que os melhores planos do Sr. Sherlock Holmes foram derrotados pela argúcia de uma mulher. Ele costumava zombar da esperteza das mulheres, mas não o tenho ouvido fazê-lo ultimamente. E quando fala de Irene Adler, ou quando se refere à fotografia dela, é sempre sob o honroso título de a mulher.","ihadcalleduponmyfriendmrsherlockholmeson~andclosedthedoorbehindme~258":"Eu visitara meu amigo, o Sr. Sherlock Holmes, num dia do outono do ano passado e o encontrara em profunda conversa com um cavalheiro idoso, muito robusto, de rosto afogueado e cabelos de um vermelho flamejante. Com um pedido de desculpas pela intromissão, eu ia me retirar quando Holmes me puxou bruscamente para dentro da sala e fechou a porta atrás de mim.","youcouldnotpossiblyhavecomeatabettertime~earwatsonhesaidcordially~67":"“O senhor não poderia ter chegado em melhor hora, meu caro Watson”, disse ele cordialmente.","iwasafraidthatyouwereengaged~afraidthatyouwereengaged~28":"“Receei que estivesse ocupado.”","soiamverymuchso~soiamverymuchso~15":"“E estou. Muitíssimo.”","thenicanwaitinthenextroom~henicanwaitinthenextroom~25":"“Então posso esperar na sala ao lado.”","notatallthisgentlemanmrwilsonhasbeenmypa~utmostusetomeinyoursalso~139":"“De modo algum. Este cavalheiro, o Sr. Wilson, foi meu sócio e auxiliar em muitos dos meus casos mais bem-sucedidos, e não duvido de que será da maior utilidade para mim também no seu.”","thestoutgentlemanhalfrosefromhischairand~hissmallfatencircledeyes~119":"O cavalheiro corpulento ergueu-se pela metade da cadeira e fez uma mesura de cumprimento, com um rápido olhar interrogativo de seus olhinhos cercados de gordura.","trythesetteesaidholmesrelapsingintohisar~yofmyownlittleadventures~366":"“Experimente o canapé”, disse Holmes, recaindo na poltrona e juntando as pontas dos dedos, como era seu costume quando em disposição judicativa. “Sei, meu caro Watson, que o senhor partilha do meu amor por tudo o que é bizarro e foge às convenções e à rotina enfadonha da vida cotidiana. O senhor demonstrou seu gosto por isso no entusiasmo que o levou a registrar, e, se me permite dizê-lo, a embelezar um tanto, tantas das minhas pequenas aventuras.”","yourcaseshaveindeedbeenofthegreatestinte~estinteresttomeiobserved~57":"“Seus casos realmente me interessaram imensamente”, observei.","youwillrememberthatiremarkedtheotherdayj~nyeffortoftheimagination~232":"“O senhor se lembrará de que comentei outro dia, pouco antes de nos ocuparmos do problema muito simples apresentado pela Srta. Mary Sutherland, que, para efeitos estranhos e combinações extraordinárias, devemos recorrer à própria vida, sempre muito mais ousada do que qualquer esforço da imaginação.”","apropositionwhichitookthelibertyofdoubti~tookthelibertyofdoubting~42":"“Uma proposição que tomei a liberdade de pôr em dúvida.”","youdiddoctorbutnonethelessyoumustcomerou~othebestofmybeliefunique~1097":"“Pôs, doutor, mas nem por isso deixará de vir a adotar a minha opinião, pois do contrário continuarei empilhando fato sobre fato até que a sua razão ceda sob eles e reconheça que estou certo. Pois bem, o Sr. Jabez Wilson, aqui presente, teve a bondade de me visitar esta manhã e de iniciar uma narrativa que promete ser uma das mais singulares que ouvi em muito tempo. O senhor me ouviu dizer que as coisas mais estranhas e únicas muito frequentemente se ligam não aos crimes maiores, mas aos menores, e ocasionalmente, na verdade, a casos em que há margem para dúvida sobre se algum crime positivo foi cometido. Pelo que ouvi até agora, é-me impossível dizer se o presente caso é ou não um crime, mas o curso dos acontecimentos está certamente entre os mais singulares que já ouvi. Talvez, Sr. Wilson, tivesse a grande bondade de recomeçar a sua narrativa. Peço-lhe isso não somente porque meu amigo, o Dr. Watson, não ouviu a parte inicial, mas também porque a natureza peculiar da história me deixa ansioso por obter de seus lábios todos os pormenores possíveis. Via de regra, quando ouvi alguma ligeira indicação do curso dos acontecimentos, consigo guiar-me pelos milhares de outros casos semelhantes que me ocorrem à memória. No presente caso, sou forçado a admitir que os fatos são, até onde alcança minha crença, únicos.”","theportlyclientpuffedouthischestwithanap~edbyhisdressorappearance~355":"O corpulento cliente estufou o peito com ar de algum orgulho e tirou do bolso interno do capote um jornal sujo e amarrotado. Enquanto percorria a coluna de anúncios, com a cabeça projetada para a frente e o jornal aberto sobre o joelho, observei bem o homem e esforcei-me, à maneira de meu companheiro, por ler os indícios que seu traje ou aparência pudessem oferecer.","ididnotgainverymuchhoweverbymyinspection~iscontentuponhisfeatures~531":"Não ganhei muito, contudo, com a minha inspeção. Nosso visitante trazia todas as marcas de um comerciante britânico comum e corriqueiro, obeso, pomposo e lento. Usava calças largas e um tanto folgadas, de xadrez cinzento de pastor, uma sobrecasaca preta não muito limpa, desabotoada na frente, e um colete pardacento com uma pesada corrente Albert de aspecto latonado, da qual pendia, como adorno, um pedaço quadrado e vazado de metal. Uma cartola surrada e um sobretudo marrom desbotado, de gola de veludo enrugada, jaziam numa cadeira ao lado. No conjunto, por mais que eu olhasse, nada havia de notável no homem, exceto a cabeça de um vermelho ardente e a expressão de extremo desgosto e descontentamento em seu rosto.","sherlockholmesquickeyetookinmyoccupation~elyicandeducenothingelse~279":"O olho rápido de Sherlock Holmes percebeu minha ocupação, e ele balançou a cabeça com um sorriso ao notar meus olhares interrogativos. “Além dos fatos óbvios de que ele já fez trabalho manual, de que toma rapé, de que é maçom, de que esteve na China e de que escreveu muito ultimamente, nada mais posso deduzir.”","mrjabezwilsonstartedupinhischairwithhisf~uthiseyesuponmycompanion~86":"O Sr. Jabez Wilson sobressaltou-se na cadeira, com o indicador sobre o jornal, mas os olhos fixos em meu companheiro.","howinthenameofgoodfortunedidyouknowallth~ribeganasashipscarpenter~143":"“Como, por todos os santos, soube de tudo isso, Sr. Holmes?”, perguntou. “Como soube, por exemplo, que eu fiz trabalho manual? É verdade como o Evangelho, pois comecei como carpinteiro naval.”","yourhandsmydearsiryourrighthandisquiteas~emusclesaremoredeveloped~109":"“Suas mãos, meu caro senhor. A sua mão direita é um bom tamanho maior que a esquerda. O senhor trabalhou com ela, e os músculos são mais desenvolvidos.”","wellthesnuffthenandthefreemasonry~uffthenandthefreemasonry~33":"“Bem, e o rapé, e a maçonaria?”","iwontinsultyourintelligencebytellingyouh~anarcandcompassbreastpin~131":"“Não insultarei sua inteligência dizendo-lhe como li isso, sobretudo porque, um tanto contra as regras estritas da sua ordem, o senhor usa um alfinete de peito com arco e compasso.”","ahofcourseiforgotthatbutthewriting~iforgotthatbutthewriting~34":"“Ah, claro, esqueci disso. Mas o escrever?”","whatelsecanbeindicatedbythatrightcuffsov~hereyourestituponthedesk~129":"“O que mais pode indicar esse punho direito, tão lustroso por cinco polegadas, e o esquerdo, com a mancha lisa perto do cotovelo, onde o senhor o apoia na escrivaninha?”","wellbutchina~wellbutchina~12":"“Bem, mas a China?”","thefishthatyouhavetattooedimmediatelyabo~terbecomesevenmoresimple~322":"“O peixe que o senhor tem tatuado logo acima do punho direito só poderia ter sido feito na China. Fiz um pequeno estudo das marcas de tatuagem e cheguei a contribuir para a literatura do assunto. Esse artifício de tingir as escamas dos peixes de um delicado rosa é bastante peculiar à China. Quando, além disso, vejo uma moeda chinesa pendurada na sua corrente de relógio, o caso se torna ainda mais simples.”","mrjabezwilsonlaughedheavilywellineversai~rewasnothinginitafterall~125":"O Sr. Jabez Wilson riu pesadamente. “Ora, essa!”, disse. “A princípio pensei que o senhor tinha feito algo inteligente, mas vejo que afinal não havia nada nisso.”","ibegintothinkwatsonsaidholmesthatimakeam~theadvertisementmrwilson~192":"“Começo a pensar, Watson”, disse Holmes, “que cometo um erro ao explicar. ‘Omne ignotum pro magnifico’, o senhor sabe, e a minha pobre reputaçãozinha, tal como é, naufragará se eu for tão franco. O senhor não consegue achar o anúncio, Sr. Wilson?”","yesihavegotitnowheansweredwithhisthickre~justreaditforyourselfsir~129":"“Sim, já o achei”, respondeu, com o grosso dedo vermelho plantado na metade da coluna. “Aqui está. Foi isto que deu início a tudo. Leia o senhor mesmo.”","itookthepaperfromhimandreadasfollows~rfromhimandreadasfollows~36":"Tomei o jornal de suas mãos e li o seguinte:","totheredheadedleagueonaccountofthebeques~ue7popescourtfleetstreet~360":"“À Liga dos Cabeças-Vermelhas: Em virtude do legado do falecido Ezekiah Hopkins, de Lebanon, Pensilvânia, E.U.A., acha-se agora aberta mais uma vaga, que dá direito a um membro da Liga a um salário de £4 por semana por serviços puramente nominais. Todos os homens de cabelos vermelhos, sãos de corpo e de espírito e maiores de vinte e um anos, são elegíveis. Candidatar-se pessoalmente na segunda-feira, às onze horas, a Duncan Ross, nos escritórios da Liga, 7 Pope’s Court, Fleet Street.”","whatonearthdoesthismeaniejaculatedafteri~xtraordinaryannouncement~84":"“Que diabos significa isto?”, exclamei, depois de ler duas vezes o extraordinário anúncio.","holmeschuckledandwriggledinhischairaswas~ctorofthepaperandthedate~274":"Holmes soltou uma risadinha e remexeu-se na poltrona, como era seu hábito quando de excelente humor. “É um pouco fora do comum, não é?”, disse. “E agora, Sr. Wilson, comece do começo e conte-nos tudo sobre o senhor, sua casa e o efeito que esse anúncio teve sobre a sua sorte. O senhor, doutor, tome primeiro nota do jornal e da data.”","itisthemorningchronicleofapril271890just~il271890justtwomonthsago~52":"“É o The Morning Chronicle de 27 de abril de 1890. Faz justamente dois meses.”","verygoodnowmrwilson~verygoodnowmrwilson~19":"“Muito bem. Agora, Sr. Wilson?”","wellitisjustasihavebeentellingyoumrsherl~essoastolearnthebusiness~343":"“Pois bem, é exatamente como eu vinha lhe dizendo, Sr. Sherlock Holmes”, disse Jabez Wilson, enxugando a testa; “tenho uma pequena casa de penhores na Coburg Square, perto da City. Não é um negócio muito grande, e nos últimos anos não me deu mais do que o sustento. Antes eu podia manter dois ajudantes, mas agora mantenho só um; e teria dificuldade em pagá-lo, não fosse ele disposto a vir por meio salário, para aprender o ofício.”","whatisthenameofthisobligingyouthaskedshe~youthaskedsherlockholmes~51":"“Qual é o nome desse moço prestimoso?”, perguntou Sherlock Holmes.","hisnameisvincentspauldingandhesnotsuchay~shouldiputideasinhishead~232":"“Chama-se Vincent Spaulding, e não é tão moço assim. É difícil dizer a idade dele. Não desejaria ajudante mais esperto, Sr. Holmes; e sei muito bem que ele poderia melhorar de situação e ganhar o dobro do que eu posso lhe dar. Mas, afinal, se ele está satisfeito, por que eu haveria de pôr ideias na cabeça dele?”","whyindeedyouseemmostfortunateinhavingane~kableasyouradvertisement~187":"“Por que, de fato? O senhor parece muito afortunado em ter um empregado que se contenta com menos que o preço de mercado. Não é experiência comum entre os patrões desta época. Não sei se o seu ajudante não é tão notável quanto o seu anúncio.”","ohhehashisfaultstoosaidmrwilsonneverwass~dworkertheresnoviceinhim~252":"“Ah, ele também tem os seus defeitos”, disse o Sr. Wilson. “Nunca vi sujeito assim para a fotografia. Fica batendo chapas com a máquina quando devia estar aperfeiçoando o espírito, e depois mergulha no porão como coelho na toca para revelar as fotos. Esse é o principal defeito, mas no conjunto é bom trabalhador. Não tem vício nenhum.”","heisstillwithyouipresume~heisstillwithyouipresume~24":"“Presumo que ainda esteja com o senhor.”","yessirheandagirloffourteenwhodoesabitofs~urdebtsifwedonothingmore~219":"“Sim, senhor. Ele e uma moça de catorze anos, que faz uma cozinha simples e mantém o lugar limpo, é só o que tenho em casa, pois sou viúvo e nunca tive família. Vivemos muito quietos, senhor, nós três; e mantemos um teto sobre a cabeça e pagamos nossas dívidas, se nada mais fizermos.","thefirstthingthatputusoutwasthatadvertis~ypaperinhishandandhesays~133":"“A primeira coisa que nos tirou do prumo foi esse anúncio. Spaulding desceu ao escritório, faz hoje oito semanas, com este mesmo jornal na mão, e diz:","iwishtothelordmrwilsonthatiwasaredheaded~sonthatiwasaredheadedman~43":"“ ‘Quisera Deus, Sr. Wilson, que eu fosse ruivo.’","whythatiasks~whythatiasks~12":"“ ‘Por quê?’, pergunto eu.","whysaysheheresanothervacancyontheleagueo~ballreadyformetostepinto~280":"“ ‘Ora’, diz ele, ‘aqui está outra vaga na Liga dos Homens de Cabelo Vermelho. Vale uma pequena fortuna para quem a conseguir, e pelo que entendo há mais vagas do que homens, de modo que os curadores não sabem mais o que fazer com o dinheiro. Se ao menos o meu cabelo mudasse de cor, aqui está um belo empreguinho pronto para eu entrar.’","whywhatisittheniaskedyouseemrholmesiamav~asalwaysgladofabitofnews~232":"“ ‘Mas o que é isso, então?’, perguntei. O senhor vê, Sr. Holmes, sou um homem muito caseiro, e como o negócio vinha a mim, em vez de eu ter de ir a ele, ficava muitas vezes semanas inteiras sem pôr o pé fora do capacho. Assim, não sabia muito do que se passava lá fora, e sempre me alegrava com uma notícia.","haveyouneverheardoftheleagueoftheredhead~enheaskedwithhiseyesopen~67":"“ ‘O senhor nunca ouviu falar da Liga dos Homens de Cabelo Vermelho?’, perguntou ele, de olhos arregalados.","never~never~5":"“ ‘Nunca.’","whyiwonderatthatforyouareeligibleyoursel~selfforoneofthevacancies~61":"“ ‘Pois me admira, porque o senhor mesmo é elegível para uma das vagas.’","andwhataretheyworthiasked~ndwhataretheyworthiasked~25":"“ ‘E quanto valem elas?’, perguntei.","ohmerelyacoupleofhundredayearbuttheworki~withonesotheroccupations~100":"“ ‘Ah, apenas umas duzentas por ano, mas o trabalho é leve e não precisa atrapalhar muito as outras ocupações.’","wellyoucaneasilythinkthatthatmademeprick~edwouldhavebeenveryhandy~139":"“Bem, o senhor pode imaginar que isso me fez aguçar as orelhas, pois o negócio não ia lá muito bem havia alguns anos, e uns duzentos a mais viriam bem a calhar.","tellmeallaboutitsaidi~tellmeallaboutitsaidi~21":"“ ‘Conte-me tudo’, disse eu.","wellsaidheshowingmetheadvertisementyouca~ndidpayandverylittletodo~499":"“ ‘Bem’, disse ele, mostrando-me o anúncio, ‘o senhor pode ver por si mesmo que a Liga tem uma vaga, e aí está o endereço onde deve se apresentar para obter pormenores. Até onde posso entender, a Liga foi fundada por um milionário americano, Ezekiah Hopkins, que era muito singular em seus modos. Ele próprio era ruivo e tinha grande simpatia por todos os homens ruivos; assim, quando morreu, descobriu-se que deixara sua enorme fortuna nas mãos de curadores, com instruções para aplicar os juros em proporcionar boas colocações a homens cujo cabelo fosse dessa cor. Por tudo o que ouço, a paga é esplêndida e há muito pouco a fazer.’","butsaiditherewouldbemillionsofredheadedm~edheadedmenwhowouldapply~55":"“ ‘Mas’, disse eu, ‘haveria milhões de ruivos se candidatando.’","notsomanyasyoumightthinkheansweredyousee~esakeofafewhundredpounds~407":"“ ‘Não tantos quanto o senhor pensa’, respondeu. ‘Veja, é realmente restrito a londrinos e a homens feitos. Esse americano partira de Londres quando jovem e queria fazer um bem à velha cidade. Além disso, ouvi dizer que não adianta candidatar-se se o cabelo for ruivo-claro, ou ruivo-escuro, ou qualquer coisa que não seja um vermelho de verdade, vivo, ardente, flamejante. Ora, se o senhor quisesse se candidatar, Sr. Wilson, entraria sem esforço; mas talvez quase não valesse a pena sair do seu caminho por umas poucas centenas de libras.’","nowitisafactgentlemenasyoumayseeforyours~ivenusintheadvertisement~430":"“Ora, é um fato, senhores, como podem ver por si mesmos, que o meu cabelo é de um tom muito cheio e rico, de modo que me pareceu que, se houvesse alguma competição no caso, eu teria tanta chance quanto qualquer homem que eu já tivesse conhecido. Vincent Spaulding parecia saber tanto a respeito que pensei que poderia ser útil, e então mandei-o simplesmente fechar as venezianas por aquele dia e vir logo comigo. Ele ficou muito contente com o feriado, e assim fechamos o negócio e partimos para o endereço que nos fora dado no anúncio.","ineverhopetoseesuchasightasthatagainmrho~oundourselvesintheoffice~801":"“Nunca espero ver outra vista como aquela, Sr. Holmes. Do norte, do sul, do leste e do oeste, todo homem que tinha um matiz de vermelho no cabelo marchara para a cidade a fim de responder ao anúncio. A Fleet Street estava entupida de gente ruiva, e Pope’s Court parecia um carrinho de laranjas de verdureiro. Eu não teria acreditado que houvesse tantos em todo o país quantos foram reunidos por esse único anúncio. Eram de todos os matizes: palha, limão, laranja, tijolo, setter-irlandês, fígado, argila; mas, como disse Spaulding, não eram muitos os que tinham o verdadeiro tom vivo, cor de chama. Quando vi quantos esperavam, teria desistido em desespero; mas Spaulding não quis nem ouvir falar disso. Como o conseguiu, não pude imaginar, mas empurrou, puxou e cabeceou até me fazer atravessar a multidão e chegar bem junto aos degraus que levavam ao escritório. Havia uma corrente dupla na escada, uns subindo cheios de esperança, outros descendo abatidos; mas nos metemos como pudemos e logo nos vimos no escritório.”","yourexperiencehasbeenamostentertainingon~veryinterestingstatement~154":"“Sua experiência foi das mais divertidas”, comentou Holmes, enquanto o cliente fazia uma pausa e refrescava a memória com uma enorme pitada de rapé. “Continue, por favor, sua interessantíssima exposição.”","therewasnothingintheofficebutacoupleofwo~hthaveaprivatewordwithus~426":"“Não havia nada no escritório além de duas cadeiras de madeira e uma mesa de pinho, atrás da qual sentava-se um homem pequeno, de cabeça ainda mais vermelha que a minha. Dizia algumas palavras a cada candidato que se aproximava e depois sempre dava um jeito de achar neles algum defeito que os desqualificasse. Conseguir uma vaga não parecia, afinal, coisa tão fácil. No entanto, quando chegou a nossa vez, o homenzinho foi muito mais favorável a mim do que a qualquer dos outros, e fechou a porta quando entramos, para poder trocar uma palavra em particular conosco.","thisismrjabezwilsonsaidmyassistantandhei~ofillavacancyintheleague~73":"“ ‘Este é o Sr. Jabez Wilson’, disse meu ajudante, ‘e ele está disposto a preencher uma vaga na Liga.’","andheisadmirablysuitedforittheotheranswe~latedmewarmlyonmysuccess~257":"“ ‘E é admiravelmente adequado para ela’, respondeu o outro. ‘Tem todos os requisitos. Não me lembro de quando vi algo tão belo.’ Deu um passo atrás, inclinou a cabeça para um lado e contemplou meu cabelo até eu ficar bem encabulado. Então, de repente, precipitou-se para a frente, apertou-me a mão e felicitou-me calorosamente pelo meu sucesso.","itwouldbeinjusticetohesitatesaidheyouwil~myownandthatofthemanager~591":"“ ‘Seria injustiça hesitar’, disse ele. ‘O senhor, contudo, haverá de me desculpar, tenho certeza, por tomar uma precaução óbvia.’ Com isso agarrou meu cabelo com as duas mãos e puxou até eu gritar de dor. ‘Há lágrimas nos seus olhos’, disse ele ao me soltar. ‘Vejo que está tudo como deve ser. Mas temos de ser cuidadosos, pois já fomos enganados duas vezes por perucas e uma por tinta. Poderia lhe contar histórias de cera de sapateiro que o fariam ter nojo da natureza humana.’ Aproximou-se da janela e gritou por ela, a plenos pulmões, que a vaga estava preenchida. Um gemido de desapontamento subiu lá de baixo, e o povo todo se dispersou em diferentes direções, até não restar um só ruivo à vista, exceto o meu e o do gerente.","mynamesaidheismrduncanrossandiammyselfon~anmrwilsonhaveyouafamily~130":"“ ‘Meu nome’, disse ele, ‘é Duncan Ross, e sou eu mesmo um dos pensionistas do fundo deixado por nosso nobre benfeitor. O senhor é casado, Sr. Wilson? Tem família?’","iansweredthatihadnot~iansweredthatihadnot~20":"“Respondi que não.","hisfacefellimmediately~hisfacefellimmediately~22":"“O rosto dele desabou imediatamente.","dearmehesaidgravelythatisveryseriousinde~thatyoushouldbeabachelor~200":"“ ‘Meu Deus!’, disse gravemente, ‘isso é muito sério mesmo! Lamento ouvi-lo dizer isso. O fundo era, naturalmente, para a propagação e difusão dos ruivos tanto quanto para o seu sustento. É extremamente desafortunado que o senhor seja solteiro.’","myfacelengthenedatthismrholmesforithough~aidthatitwouldbeallright~139":"“Meu rosto se alongou com isso, Sr. Holmes, pois pensei que afinal não ficaria com a vaga; mas depois de refletir uns minutos ele disse que ficaria tudo bem.","inthecaseofanothersaidhetheobjectionmigh~toenteruponyournewduties~152":"“ ‘No caso de outro’, disse, ‘a objeção poderia ser fatal, mas devemos abrir uma exceção em favor de um homem com uma cabeleira como a sua. Quando poderá assumir seus novos deveres?’","wellitisalittleawkwardforihaveabusinessa~aveabusinessalreadysaidi~51":"“ ‘Bem, é um pouco embaraçoso, pois já tenho um negócio’, disse eu.","ohnevermindaboutthatmrwilsonsaidvincents~bletolookafterthatforyou~82":"“ ‘Ah, não se preocupe com isso, Sr. Wilson!’, disse Vincent Spaulding. ‘Eu poderei cuidar dele para o senhor.’","whatwouldbethehoursiasked~hatwouldbethehoursiasked~25":"“ ‘Qual seria o horário?’, perguntei.","tentotwo~tentotwo~8":"“ ‘Das dez às duas.’","nowapawnbrokersbusinessismostlydoneofane~eetoanythingthatturnedup~237":"“Ora, o negócio de penhores se faz sobretudo à noite, Sr. Holmes, especialmente nas noites de quinta e sexta, que antecedem o dia de pagamento; de modo que me convinha muito bem ganhar um pouco nas manhãs. Além disso, eu sabia que meu ajudante era bom homem e que cuidaria de qualquer coisa que surgisse.","thatwouldsuitmeverywellsaidiandthepay~meverywellsaidiandthepay~37":"“ ‘Isso me conviria muito bem’, disse eu. ‘E a paga?’","is4aweek~is4aweek~8":"“ ‘São £4 por semana.’","andthework~andthework~10":"“ ‘E o trabalho?’","ispurelynominal~ispurelynominal~15":"“ ‘É puramente nominal.’","whatdoyoucallpurelynominal~atdoyoucallpurelynominal~26":"“ ‘O que o senhor chama de puramente nominal?’","wellyouhavetobeintheofficeoratleastinthe~mtheofficeduringthattime~202":"“ ‘Bem, o senhor tem de estar no escritório, ou pelo menos no prédio, o tempo todo. Se sair, perde o cargo para sempre. O testamento é muito claro nesse ponto. Não cumpre as condições se se afastar do escritório durante esse tempo.’","itsonlyfourhoursadayandishouldnotthinkof~ldnotthinkofleavingsaidi~52":"“ ‘São só quatro horas por dia, e eu nem pensaria em sair’, disse eu.","noexcusewillavailsaidmrduncanrossneither~tstayoryouloseyourbillet~109":"“ ‘Nenhuma desculpa valerá’, disse o Sr. Duncan Ross; ‘nem doença, nem negócios, nem coisa alguma. Ali o senhor deve ficar, ou perde a colocação.’","istocopyouttheencyclopediabritannicather~irwillyoubereadytomorrow~164":"“ ‘É copiar a Enciclopédia Britânica. Ali naquele armário está o primeiro volume. O senhor deve providenciar a própria tinta, as penas e o mata-borrão, mas nós fornecemos esta mesa e esta cadeira. Estará pronto amanhã?’","certainlyianswered~certainlyianswered~18":"“ ‘Certamente’, respondi.","thengoodbyemrjabezwilsonandletmecongratu~leasedatmyowngoodfortune~219":"“ ‘Então, adeus, Sr. Jabez Wilson, e deixe-me felicitá-lo mais uma vez pelo importante posto que teve a boa sorte de obter.’ Conduziu-me para fora da sala com uma mesura, e voltei para casa com meu ajudante, mal sabendo o que dizer ou fazer, de tão contente que estava com a minha boa fortuna.","wellithoughtoverthematteralldayandbyeven~istartedoffforpopescourt~555":"“Pois bem, pensei no assunto o dia inteiro, e à noite estava de novo abatido; pois me convencera por completo de que a coisa toda devia ser uma grande farsa ou fraude, embora não pudesse imaginar qual seria o objetivo. Parecia totalmente inacreditável que alguém pudesse fazer um testamento assim, ou que pagassem tal quantia por algo tão simples quanto copiar a Enciclopédia Britânica. Vincent Spaulding fez o que pôde para me animar, mas na hora de dormir eu já me havia convencido, por raciocínio, a abandonar a coisa toda. No entanto, de manhã resolvi dar uma olhada de qualquer modo, e comprei um frasco de tinta de um pêni e, com uma pena de ganso e sete folhas de papel almaço, parti para Pope’s Court.","welltomysurpriseanddelighteverythingwasa~hedooroftheofficeafterme~332":"“Pois bem, para minha surpresa e deleite, tudo estava o mais certo possível. A mesa estava posta à minha espera, e o Sr. Duncan Ross estava lá para ver se eu começava direito o trabalho. Pôs-me a copiar a letra A e depois me deixou; mas aparecia de tempos em tempos para ver se tudo ia bem comigo. Às duas horas desejou-me bom dia, elogiou a quantidade que eu escrevera e trancou a porta do escritório atrás de mim.","thiswentondayafterdaymrholmesandonsaturd~iwouldnotriskthelossofit~441":"“Isso continuou dia após dia, Sr. Holmes, e no sábado o gerente entrou e depositou na mesa quatro soberanos de ouro pelo trabalho da minha semana. Foi igual na semana seguinte, e igual na outra. Toda manhã eu estava lá às dez, e toda tarde saía às duas. Aos poucos o Sr. Duncan Ross passou a vir só uma vez por manhã, e depois, passado algum tempo, não veio mais. Ainda assim, é claro, jamais ousei sair da sala por um instante, pois não sabia quando ele poderia chegar, e a colocação era tão boa, e me convinha tanto, que eu não quis arriscar perdê-la.","eightweekspassedawaylikethisandihadwritt~wholebusinesscametoanend~267":"“Oito semanas se passaram assim, e eu escrevera sobre Abades e Arquearia e Armaduras e Arquitetura e Ática, e esperava, com diligência, chegar aos B’s dentro de pouco tempo. Custou-me algo em papel almaço, e eu já havia quase enchido uma prateleira com meus escritos. E então, de repente, o negócio todo chegou ao fim.”","toanend~toanend~7":"“Ao fim?”","yessirandnolaterthanthismorningiwenttomy~andyoucanreadforyourself~188":"“Sim, senhor. E não mais tarde que esta manhã. Fui ao trabalho como de costume às dez horas, mas a porta estava fechada e trancada, com um quadradinho de papelão pregado no meio do painel com uma tachinha. Aqui está, e o senhor pode ler por si mesmo.”","heheldupapieceofwhitecardboardaboutthesi~paperitreadinthisfashion~80":"Ergueu um pedaço de papelão branco, do tamanho de uma folha de papel de carta. Dizia assim:","theredheadedleagueisdissolvedoctober9189~eisdissolvedoctober91890~41":"A Liga dos Cabeças-Vermelhas está dissolvida. 9 de outubro de 1890.","sherlockholmesandisurveyedthiscurtannoun~stoutintoaroaroflaughter~182":"Sherlock Holmes e eu examinamos aquele aviso lacônico e o rosto desolado por trás dele, até que o lado cômico do caso sobrepujou de tal modo qualquer outra consideração que ambos explodimos numa gargalhada.","icannotseethatthereisanythingveryfunnycr~laughatmeicangoelsewhere~139":"“Não vejo que haja nada de muito engraçado”, exclamou nosso cliente, corando até a raiz da cabeça flamejante. “Se o senhor não pode fazer coisa melhor que rir de mim, posso ir a outro lugar.”","nonocriedholmesshovinghimbackintothechai~ufoundthecarduponthedoor~248":"“Não, não”, exclamou Holmes, empurrando-o de volta para a cadeira da qual ele se levantara pela metade. “Realmente não perderia o seu caso por nada deste mundo. É refrescantemente incomum. Mas há nele, se me permite dizê-lo, algo um pouquinho engraçado. Diga-me, que providências tomou ao encontrar o cartão na porta?”","iwasstaggeredsirididnotknowwhattodotheni~edthatthenamewasnewtohim~328":"“Fiquei pasmo, senhor. Não sabia o que fazer. Então fui aos escritórios vizinhos, mas nenhum deles parecia saber coisa alguma. Por fim, fui ao senhorio, que é um contador e mora no andar térreo, e perguntei-lhe se podia me dizer o que fora feito da Liga dos Cabeças-Vermelhas. Disse que nunca ouvira falar de tal entidade. Então perguntei quem era o Sr. Duncan Ross. Respondeu que o nome lhe era novo.","wellsaidithegentlemanatno4~llsaidithegentlemanatno4~26":"“ ‘Ora’, disse eu, ‘o cavalheiro do nº 4.’","whattheredheadedman~whattheredheadedman~19":"“ ‘O quê, o homem ruivo?’","ohsaidhehisnamewaswilliammorrishewasasol~readyhemovedoutyesterday~133":"“ ‘Ah’, disse ele, ‘o nome dele era William Morris. Era advogado e usava minha sala como conveniência temporária até que suas novas instalações ficassem prontas. Mudou-se ontem.’","wherecouldifindhim~wherecouldifindhim~18":"“ ‘Onde poderia encontrá-lo?’","ohathisnewofficeshedidtellmetheaddressye~gedwardstreetnearstpauls~70":"“ ‘Ah, nos novos escritórios. Ele me deu o endereço. Sim, King Edward Street, 17, perto de St. Paul.’","istartedoffmrholmesbutwhenigottothataddr~liammorrisormrduncanross~141":"“Parti, Sr. Holmes, mas, quando cheguei àquele endereço, era uma manufatura de rótulas artificiais, e ninguém lá jamais ouvira falar do Sr. William Morris nem do Sr. Duncan Ross.”","andwhatdidyoudothenaskedholmes~tdidyoudothenaskedholmes~30":"“E o que fez então?”, perguntou Holmes.","iwenthometosaxecoburgsquareanditookthead~dofiticamerightawaytoyou~299":"“Fui para casa, na Saxe-Coburg Square, e pedi conselho a meu ajudante. Mas ele não pôde me ajudar de forma alguma. Só soube dizer que, se eu esperasse, receberia notícias pelo correio. Mas isso não era bom o bastante, Sr. Holmes. Não queria perder tal colocação sem lutar, e então, como ouvira dizer que o senhor tinha a bondade de aconselhar gente pobre que precisasse, vim direto ao senhor.”","andyoudidverywiselysaidholmesyourcaseisa~nmightatfirstsightappear~189":"“E agiu muito sabiamente”, disse Holmes. “Seu caso é extremamente notável, e terei prazer em examiná-lo. Pelo que o senhor me contou, creio ser possível que questões mais graves dependam dele do que à primeira vista pareceria.”","graveenoughsaidmrjabezwilsonwhyihavelost~yihavelostfourpoundaweek~54":"“Graves o bastante!”, disse o Sr. Jabez Wilson. “Ora, perdi quatro libras por semana.”","asfarasyouarepersonallyconcernedremarked~youhavelostnothingbythem~267":"“No que diz respeito ao senhor pessoalmente”, observou Holmes, “não vejo que tenha queixa alguma contra essa extraordinária liga. Pelo contrário, está, segundo entendo, mais rico em cerca de £30, para não falar do conhecimento minucioso que adquiriu sobre todos os assuntos que caem sob a letra A. O senhor nada perdeu com eles.”","nosirbutiwanttofindoutaboutthemandwhothe~stthemtwoandthirtypounds~165":"“Não, senhor. Mas quero descobrir a respeito deles, quem são e qual era o objetivo de me pregarem essa peça, se foi uma peça. Foi uma brincadeira bem cara para eles, pois lhes custou trinta e duas libras.”","weshallendeavourtoclearupthesepointsfory~thowlonghadhebeenwithyou~163":"“Esforçar-nos-emos por esclarecer esses pontos para o senhor. E, primeiro, uma ou duas perguntas, Sr. Wilson. Esse seu ajudante, que primeiro chamou sua atenção para o anúncio, havia quanto tempo estava com o senhor?”","aboutamonththen~aboutamonththen~15":"“Cerca de um mês então.”","howdidhecome~howdidhecome~12":"“Como veio?”","inanswertoanadvertisement~nanswertoanadvertisement~25":"“Em resposta a um anúncio.”","washetheonlyapplicant~washetheonlyapplicant~21":"“Era o único candidato?”","noihadadozen~noihadadozen~12":"“Não, tive uma dúzia.”","whydidyoupickhim~whydidyoupickhim~16":"“Por que o escolheu?”","becausehewashandyandwouldcomecheap~ashandyandwouldcomecheap~34":"“Porque era hábil e viria barato.”","athalfwagesinfact~athalfwagesinfact~17":"“A meio salário, na verdade.”","whatishelikethisvincentspaulding~likethisvincentspaulding~32":"“Como é ele, esse Vincent Spaulding?”","smallstoutbuiltveryquickinhiswaysnohairo~ashofaciduponhisforehead~109":"“Pequeno, de constituição robusta, muito ágil nos modos, sem pelos no rosto, embora não tenha menos de trinta. Tem uma mancha branca de ácido na testa.”","holmessatupinhischairinconsiderableexcit~arsarepiercedforearrings~116":"Holmes endireitou-se na poltrona, em considerável excitação. “Foi o que pensei”, disse. “O senhor já observou que as orelhas dele são furadas para brincos?”","yessirhetoldmethatagipsyhaddoneitforhimw~oneitforhimwhenhewasalad~52":"“Sim, senhor. Disse-me que uma cigana lhe fizera isso quando era rapaz.”","humsaidholmessinkingbackindeepthoughthei~pthoughtheisstillwithyou~53":"“Hum!”, disse Holmes, afundando de novo, em profundo pensamento. “Ele ainda está com o senhor?”","ohyessirihaveonlyjustlefthim~ssirihaveonlyjustlefthim~28":"“Ah, sim, senhor; acabo de deixá-lo.”","andhasyourbusinessbeenattendedtoinyourab~nattendedtoinyourabsence~45":"“E seu negócio foi atendido na sua ausência?”","nothingtocomplainofsirtheresneververymuc~erverymuchtodoofamorning~55":"“Nada de que reclamar, senhor. Nunca há muito que fazer de manhã.”","thatwilldomrwilsonishallbehappytogiveyou~aywemaycometoaconclusion~142":"“Isso basta, Sr. Wilson. Terei prazer em dar-lhe uma opinião sobre o assunto dentro de um ou dois dias. Hoje é sábado, e espero que até segunda-feira possamos chegar a uma conclusão.”","wellwatsonsaidholmeswhenourvisitorhadlef~ftuswhatdoyoumakeofitall~63":"“Bem, Watson”, disse Holmes quando nosso visitante nos deixou, “o que acha disso tudo?”","imakenothingofitiansweredfranklyitisamos~samostmysteriousbusiness~59":"“Não acho nada”, respondi com franqueza. “É um negócio misteriosíssimo.”","asarulesaidholmesthemorebizarreathingist~stbepromptoverthismatter~206":"“Via de regra”, disse Holmes, “quanto mais bizarra a coisa, menos misteriosa ela se revela. São os crimes banais, sem traços marcantes, que são realmente intrigantes, assim como um rosto banal é o mais difícil de identificar. Mas devo ser pronto neste assunto.”","whatareyougoingtodotheniasked~reyougoingtodotheniasked~29":"“O que vai fazer, então?”, perguntei.","tosmokeheanswereditisquiteathreepipeprob~pedownuponthemantelpiece~418":"“Fumar”, respondeu. “É um problema de bem três cachimbos, e peço que não me dirija a palavra por cinquenta minutos.” Enroscou-se na poltrona, com os joelhos magros encolhidos até o nariz de gavião, e ali ficou, de olhos fechados e o cachimbo preto de barro projetando-se como o bico de alguma estranha ave. Eu chegara à conclusão de que ele adormecera, e eu próprio já cabeceava, quando de repente saltou da poltrona com o gesto de quem tomou uma decisão e pousou o cachimbo no console da lareira.","sarasateplaysatthestjamesshallthisaftern~entsspareyouforafewhours~110":"“Sarasate toca hoje à tarde no St. James’s Hall”, comentou. “Que acha, Watson? Seus pacientes poderiam dispensá-lo por algumas horas?”","ihavenothingtodotodaymypracticeisneverve~ticeisneververyabsorbing~51":"“Não tenho nada a fazer hoje. Minha clínica nunca é muito absorvente.”","thenputonyourhatandcomeiamgoingthroughth~anttointrospectcomealong~225":"“Então ponha o chapéu e venha. Vou primeiro atravessar a City, e podemos almoçar no caminho. Observo que há bastante música alemã no programa, o que me agrada mais que a italiana ou a francesa. É introspectiva, e quero introspectar. Vamos!”","wetravelledbytheundergroundasfarasalders~ellowwhoaskedhimtostepin~899":"Viajamos de metrô até Aldersgate; e uma curta caminhada nos levou à Saxe-Coburg Square, cenário da singular história que ouvíramos pela manhã. Era um lugarzinho acanhado, de uma elegância pobre, onde quatro fileiras de casas de tijolo encardidas, de dois andares, davam para um pequeno recinto gradeado, em que um gramado de capim ralo e algumas touceiras de loureiros desbotados travavam dura luta contra uma atmosfera carregada de fumaça e desfavorável. Três bolas douradas e uma tabuleta marrom com “Jabez Wilson” em letras brancas, numa casa de esquina, anunciavam o lugar onde nosso cliente ruivo exercia seu negócio. Sherlock Holmes parou diante dela, com a cabeça inclinada, e examinou tudo, os olhos brilhando vivamente entre as pálpebras franzidas. Depois caminhou lentamente rua acima e voltou até a esquina, sempre olhando atentamente as casas. Por fim retornou à casa de penhores e, depois de bater com vigor na calçada duas ou três vezes com a bengala, foi até a porta e bateu. Foi instantaneamente aberta por um rapaz de aspecto vivo e barba feita, que lhe pediu que entrasse.","thankyousaidholmesionlywishedtoaskyouhow~uldgofromheretothestrand~69":"“Obrigado”, disse Holmes, “eu só queria perguntar como se vai daqui até o Strand.”","thirdrightfourthleftansweredtheassistant~ntpromptlyclosingthedoor~62":"“Terceira à direita, quarta à esquerda”, respondeu prontamente o ajudante, fechando a porta.","smartfellowthatobservedholmesaswewalkeda~nownsomethingofhimbefore~166":"“Sujeito esperto, esse”, observou Holmes enquanto nos afastávamos. “É, a meu ver, o quarto homem mais esperto de Londres, e, em ousadia, não sei se não tem direito ao terceiro lugar. Já sabia algo dele antes.”","evidentlysaidimrwilsonsassistantcountsfo~norderthatyoumightseehim~143":"“Evidentemente”, disse eu, “o ajudante do Sr. Wilson conta muito nesse mistério da Liga dos Cabeças-Vermelhas. Estou certo de que o senhor perguntou o caminho apenas para vê-lo.”","nothim~nothim~6":"“Não a ele.”","thekneesofhistrousers~thekneesofhistrousers~21":"“Aos joelhos das calças dele.”","andwhatdidyousee~andwhatdidyousee~16":"“E o que viu?”","whatiexpectedtosee~whatiexpectedtosee~18":"“O que esperava ver.”","whydidyoubeatthepavement~whydidyoubeatthepavement~24":"“Por que bateu na calçada?”","mydeardoctorthisisatimeforobservationnot~thepartswhichliebehindit~146":"“Meu caro doutor, este é tempo de observar, não de falar. Somos espiões em país inimigo. Sabemos algo sobre a Saxe-Coburg Square. Exploremos agora as partes que ficam por trás dela.”","theroadinwhichwefoundourselvesasweturned~arewhichwehadjustquitted~529":"A rua em que nos achamos ao dobrar a esquina da retirada Saxe-Coburg Square apresentava tão grande contraste com ela quanto a frente de um quadro com o verso. Era uma das artérias principais que escoavam o tráfego da City para o norte e o oeste. A pista estava bloqueada pela imensa corrente do comércio, que fluía em dupla maré, para dentro e para fora, enquanto as calçadas estavam negras do enxame apressado de pedestres. Era difícil perceber, ao olhar a fileira de belas lojas e imponentes casas comerciais, que elas realmente confinavam, do outro lado, com a praça desbotada e estagnada que acabáramos de deixar.","letmeseesaidholmesstandingatthecornerand~vexuswiththeirconundrums~527":"“Vejamos”, disse Holmes, parado na esquina e correndo os olhos pela fileira, “gostaria só de recordar a ordem das casas aqui. É um passatempo meu ter conhecimento exato de Londres. Há a tabacaria Mortimer’s, a pequena banca de jornais, a agência Coburg do City and Suburban Bank, o Restaurante Vegetariano e o depósito de carruagens McFarlane’s. Isso nos leva direto ao outro quarteirão. E agora, doutor, fizemos o nosso trabalho, é hora de brincar um pouco. Um sanduíche e uma xícara de café, e depois rumo à terra dos violinos, onde tudo é doçura, delicadeza e harmonia, e onde não há clientes ruivos para nos vexar com seus enigmas.”","myfriendwasanenthusiasticmusicianbeinghi~ehadsethimselftohuntdown~1134":"Meu amigo era um músico entusiasta, sendo ele próprio não apenas um executante muito capaz, mas um compositor de mérito nada comum. Durante toda a tarde ficou sentado na plateia, envolto na mais perfeita felicidade, agitando suavemente os dedos longos e finos no compasso da música, enquanto o rosto de sorriso brando e os olhos lânguidos e sonhadores eram tão diferentes dos de Holmes o cão de caça, Holmes o implacável, arguto e expedito agente contra o crime, quanto era possível conceber. Em seu caráter singular a natureza dual afirmava-se alternadamente, e sua extrema exatidão e argúcia representavam, como muitas vezes pensei, a reação contra o estado de espírito poético e contemplativo que ocasionalmente nele predominava. O balanço de sua natureza o levava da extrema languidez à energia devoradora; e, como eu bem sabia, nunca era tão verdadeiramente formidável como quando, por dias a fio, estivera refestelado na poltrona entre as suas improvisações e as suas edições em caracteres góticos. Era então que a sede da caçada de súbito se apossava dele, e que seu brilhante poder de raciocínio se elevava ao nível da intuição, até que aqueles que não conheciam seus métodos o olhavam de través, como a um homem cujo saber não era o dos outros mortais. Quando o vi naquela tarde tão envolto na música no St. James’s Hall, senti que talvez tempos maus se aproximassem daqueles que ele se propusera a caçar.","youwanttogohomenodoubtdoctorheremarkedas~torheremarkedasweemerged~49":"“O senhor quer ir para casa, sem dúvida, doutor”, comentou ele ao sairmos.","yesitwouldbeaswell~yesitwouldbeaswell~18":"“Sim, seria melhor.”","andihavesomebusinesstodowhichwilltakesom~satcoburgsquareisserious~81":"“E tenho negócios a tratar que tomarão algumas horas. Este caso de Coburg Square é sério.”","whyserious~whyserious~10":"“Por que sério?”","aconsiderablecrimeisincontemplationihave~shallwantyourhelptonight~157":"“Um crime considerável está em preparo. Tenho todos os motivos para crer que chegaremos a tempo de detê-lo. Mas o fato de ser hoje sábado complica um pouco as coisas. Precisarei da sua ajuda esta noite.”","atwhattime~atwhattime~10":"“A que horas?”","tenwillbeearlyenough~tenwillbeearlyenough~20":"“Dez horas será cedo o bastante.”","ishallbeatbakerstreetatten~hallbeatbakerstreetatten~26":"“Estarei na Baker Street às dez.”","verywellandisaydoctortheremaybesomelittl~inaninstantamongthecrowd~153":"“Muito bem. E, escute, doutor, pode haver algum pequeno perigo, de modo que tenha a bondade de pôr no bolso o seu revólver de exército.” Acenou com a mão, girou nos calcanhares e desapareceu num instante em meio à multidão.","itrustthatiamnotmoredensethanmyneighbour~shouldbringanexplanation~777":"Confio em não ser mais obtuso que meus vizinhos, mas sempre me oprimia o sentimento da minha própria estupidez em meus tratos com Sherlock Holmes. Ali eu ouvira o que ele ouvira, vira o que ele vira, e no entanto, pelas suas palavras, era evidente que ele enxergava claramente não só o que acontecera, mas o que estava prestes a acontecer, ao passo que para mim o negócio todo continuava confuso e grotesco. Enquanto seguia de carruagem para casa, em Kensington, repassei tudo na mente, desde a extraordinária história do copista ruivo da Enciclopédia até a visita à Saxe-Coburg Square e as palavras ominosas com que ele se despedira de mim. Que expedição noturna era aquela, e por que eu devia ir armado? Para onde iríamos, e o que faríamos? Recebera de Holmes a insinuação de que esse ajudante imberbe do penhorista era um homem formidável, um homem capaz de jogar um jogo profundo. Tentei decifrar o enigma, mas desisti em desespero e pus o assunto de lado até que a noite trouxesse uma explicação.","itwasaquarterpastninewhenistartedfromhom~velyrespectablefrockcoat~391":"Eram nove e quinze quando saí de casa e atravessei o Parque, passando depois pela Oxford Street até a Baker Street. Dois cabriolés estavam à porta e, ao entrar no corredor, ouvi o som de vozes lá em cima. Ao entrar no quarto dele, encontrei Holmes em animada conversa com dois homens, um dos quais reconheci como Peter Jones, o agente oficial da polícia, enquanto o outro era um homem alto, magro, de rosto triste, com um chapéu muito lustroso e uma sobrecasaca opressivamente respeitável.","haourpartyiscompletesaidholmesbuttoningu~anionintonightsadventure~205":"“Ha! Nosso grupo está completo”, disse Holmes, abotoando o casaco de marinheiro e tirando do suporte o pesado chicote de caça. “Watson, creio que conhece o Sr. Jones, da Scotland Yard? Deixe-me apresentá-lo ao Sr. Merryweather, que será nosso companheiro na aventura desta noite.”","werehuntingincouplesagaindoctoryouseesai~elphimtodotherunningdown~159":"“Estamos caçando em dupla de novo, doutor, como vê”, disse Jones com seu jeito arrogante. “Nosso amigo aqui é um homem maravilhoso para iniciar uma perseguição. Tudo de que precisa é um cão velho que o ajude a correr atrás da presa.”","ihopeawildgoosemaynotprovetobetheendofou~edmrmerryweathergloomily~76":"“Espero que uma caça ao ganso selvagem não venha a ser o fim da nossa perseguição”, observou o Sr. Merryweather, sombriamente.","youmayplaceconsiderableconfidenceinmrhol~rectthantheofficialforce~328":"“O senhor pode depositar considerável confiança no Sr. Holmes”, disse o agente da polícia com altivez. “Ele tem seus métodos próprios, que são, se ele não se importar que eu diga, um tanto teóricos e fantasiosos demais, mas tem a matéria de que se fazem os detetives. Não é exagero dizer que uma ou duas vezes, como naquele caso do assassinato de Sholto e do tesouro de Agra, ele esteve mais perto da verdade que a força oficial.”","ohifyousaysomrjonesitisallrightsaidthest~sthatihavenothadmyrubber~159":"“Oh, se o senhor o diz, Sr. Jones, está tudo bem”, disse o desconhecido com deferência. “Ainda assim, confesso que sinto falta do meu uíste. É o primeiro sábado à noite em vinte e sete anos em que fico sem o meu uíste.”","ithinkyouwillfindsaidsherlockholmesthaty~homyouwishtolayyourhands~226":"“Creio que o senhor verá”, disse Sherlock Holmes, “que esta noite jogará por uma aposta mais alta do que jamais jogou, e que o jogo será mais emocionante. Para o senhor, Sr. Merryweather, a aposta serão cerca de £30.000; e para o senhor, Jones, será o homem em quem deseja pôr as mãos.”","johnclaythemurdererthiefsmasherandforger~haveneverseteyesonhimyet~487":"“John Clay, o assassino, ladrão, passador de moeda falsa e falsário. É um homem jovem, Sr. Merryweather, mas está à frente de sua profissão, e preferiria ter minhas algemas nele a ter em qualquer criminoso de Londres. É um homem notável, o jovem John Clay. O avô dele era um duque da família real, e ele próprio estudou em Eton e Oxford. O cérebro dele é tão astuto quanto os dedos, e embora encontremos sinais dele a cada passo, nunca sabemos onde achar o próprio homem. Numa semana arromba uma casa na Escócia, e na seguinte está levantando fundos para construir um orfanato na Cornualha. Estou na pista dele há anos e ainda não pus os olhos nele.”","ihopethatimayhavethepleasureofintroducin~ndiwillfollowinthesecond~246":"“Espero ter o prazer de apresentá-lo ao senhor esta noite. Também tive um ou dois pequenos encontros com o Sr. John Clay, e concordo com o senhor em que ele está à frente de sua profissão. São mais de dez horas, contudo, e já é tempo de partirmos. Se os dois senhores tomarem o primeiro cabriolé, Watson e eu seguiremos no segundo.”","sherlockholmeswasnotverycommunicativedur~rgedintofarringtonstreet~200":"Sherlock Holmes não foi muito comunicativo durante a longa viagem e ficou recostado no carro, cantarolando as melodias que ouvira à tarde. Chacoalhamos por um interminável labirinto de ruas iluminadas a gás até desembocarmos na Farrington Street.","weareclosetherenowmyfriendremarkedthisfe~reandtheyarewaitingforus~322":"“Estamos perto agora”, observou meu amigo. “Esse Merryweather é diretor de banco e tem interesse pessoal no caso. Achei bom levar Jones também. Não é mau sujeito, embora seja um imbecil absoluto na profissão. Tem uma virtude positiva. É valente como um buldogue e tenaz como uma lagosta, se agarrar alguém com as garras. Chegamos, e eles estão à nossa espera.”","wehadreachedthesamecrowdedthoroughfarein~ithcratesandmassiveboxes~527":"Tínhamos chegado à mesma via apinhada em que nos encontráramos pela manhã. Dispensamos os cabriolés e, seguindo a orientação do Sr. Merryweather, descemos por uma passagem estreita e entramos por uma porta lateral, que ele abriu para nós. Lá dentro havia um pequeno corredor, que terminava em um portão de ferro muito maciço. Este também foi aberto e dava para um lance de degraus de pedra em caracol, que terminava em outro portão formidável. O Sr. Merryweather parou para acender uma lanterna e depois nos conduziu por um corredor escuro, de cheiro de terra, e assim, depois de abrir uma terceira porta, a um enorme porão ou cofre subterrâneo, que estava empilhado em toda a volta com caixotes e baús maciços.","youarenotveryvulnerablefromaboveholmesre~elanternandgazedabouthim~82":"“O senhor não é muito vulnerável por cima”, comentou Holmes, erguendo a lanterna e olhando em torno.","norfrombelowsaidmrmerryweatherstrikinghi~arkedlookingupinsurprise~133":"“Nem por baixo”, disse o Sr. Merryweather, batendo com a bengala nas lajes que revestiam o chão. “Ora, meu Deus, soa bem oco!”, observou, olhando para cima com surpresa.","imustreallyaskyoutobealittlemorequietsai~seboxesandnottointerfere~190":"“Realmente preciso lhe pedir que faça um pouco mais de silêncio!”, disse Holmes severamente. “O senhor já pôs em perigo todo o sucesso da nossa expedição. Poderia pedir-lhe que tenha a bondade de sentar-se sobre uma daquelas caixas e de não interferir?”","thesolemnmrmerryweatherperchedhimselfupo~ndputhisglassinhispocket~286":"O solene Sr. Merryweather empoleirou-se sobre um caixote, com uma expressão muito ofendida no rosto, enquanto Holmes se punha de joelhos no chão e, com a lanterna e uma lente de aumento, começava a examinar minuciosamente as frestas entre as pedras. Poucos segundos bastaram para satisfazê-lo, pois pôs-se de pé novamente e guardou a lente no bolso.","wehaveatleastanhourbeforeusheremarkedfor~estinthiscellaratpresent~454":"“Temos pelo menos uma hora pela frente”, comentou, “pois eles dificilmente tomarão qualquer providência antes que o bom penhorista esteja bem deitado. Depois não perderão um minuto, pois quanto mais cedo fizerem o serviço, mais tempo terão para a fuga. Estamos neste momento, doutor, como sem dúvida adivinhou, no porão da agência da City de um dos principais bancos de Londres. O Sr. Merryweather é o presidente da diretoria e lhe explicará que há razões para que os criminosos mais ousados de Londres tenham, no momento, considerável interesse neste porão.”","itisourfrenchgoldwhisperedthedirectorweh~attemptmightbemadeuponit~91":"“É o nosso ouro francês”, sussurrou o diretor. “Recebemos vários avisos de que uma tentativa poderia ser feita contra ele.”","yourfrenchgold~yourfrenchgold~14":"“O seu ouro francês?”","yeswehadoccasionsomemonthsagotostrengthe~misgivingsuponthesubject~396":"“Sim. Tivemos ocasião, alguns meses atrás, de reforçar nossos recursos e tomamos emprestados, para esse fim, 30.000 napoleões do Banco da França. Soube-se que nunca tivemos ocasião de desembalar o dinheiro e que ele ainda está em nosso porão. O caixote em que me sento contém 2.000 napoleões acondicionados entre camadas de folha de chumbo. Nossa reserva de ouro em barras é, no momento, muito maior do que costuma ser mantida numa única agência, e os diretores têm tido receios a esse respeito.”","whichwereverywelljustifiedobservedholmes~creenoverthatdarklantern~191":"“Que eram muito bem justificados”, observou Holmes. “E agora é tempo de acertarmos nossos pequenos planos. Espero que dentro de uma hora as coisas cheguem ao auge. Entrementes, Sr. Merryweather, precisamos pôr o anteparo sobre essa lanterna cega.”","andsitinthedark~andsitinthedark~15":"“E ficar sentados no escuro?”","iamafraidsoihadbroughtapackofcardsinmypo~ionaboutshootingthemdown~478":"“Receio que sim. Eu trouxera um baralho no bolso e pensei que, como éramos uma partie carrée, o senhor poderia ter o seu uíste, afinal. Mas vejo que os preparativos do inimigo foram tão longe que não podemos arriscar a presença de uma luz. E, antes de tudo, devemos escolher nossas posições. Esses homens são ousados e, embora os tomemos em desvantagem, podem nos causar algum mal se não tivermos cuidado. Ficarei atrás deste caixote, e os senhores se escondam atrás daqueles. Então, quando eu projetar uma luz sobre eles, fechem o cerco depressa. Se atirarem, Watson, não tenha escrúpulo em abatê-los a tiros.”","iplacedmyrevolvercockeduponthetopofthewo~thecolddankairofthevault~406":"Coloquei meu revólver, engatilhado, sobre a tampa da caixa de madeira atrás da qual me agachei. Holmes correu a portinhola diante da lanterna e nos deixou em escuridão total, uma escuridão tão absoluta como nunca experimentei. O cheiro de metal quente permanecia para nos assegurar de que a luz ainda estava ali, pronta para irromper a qualquer momento. Para mim, com os nervos tensos até o auge da expectativa, havia algo de deprimente e opressor na súbita penumbra e no ar frio e úmido do porão.","theyhavebutoneretreatwhisperedholmesthat~vedonewhatiaskedyoujones~119":"“Eles têm uma só retirada”, sussurrou Holmes. “Que é de volta pela casa até a Saxe-Coburg Square. Espero que tenha feito o que lhe pedi, Jones?”","ihaveaninspectorandtwoofficerswaitingatt~erswaitingatthefrontdoor~51":"“Tenho um inspetor e dois guardas à espera na porta da frente.”","thenwehavestoppedalltheholesandnowwemust~nowwemustbesilentandwait~55":"“Então tapamos todos os buracos. E agora devemos calar-nos e esperar.”","whatatimeitseemedfromcomparingnotesafter~escaughttheglintofalight~513":"Que tempo pareceu! Comparando as notas depois, foi apenas uma hora e quinze minutos, mas a mim pareceu que a noite devia estar quase no fim e a aurora raiando acima de nós. Meus membros estavam cansados e rígidos, pois eu temia mudar de posição; no entanto, meus nervos estavam tensos ao máximo, e minha audição tão aguda que eu não só ouvia a respiração suave dos companheiros, como distinguia o inspirar mais profundo e pesado do corpulento Jones da nota fina e suspirante do diretor do banco. De onde estava, eu podia olhar por cima da caixa em direção ao chão. De repente meus olhos captaram o lampejo de uma luz.","atfirstitwasbutaluridsparkuponthestonepa~edachinkbetweenthestones~404":"A princípio era apenas uma faísca lívida no piso de pedra. Depois alongou-se até tornar-se uma linha amarela e então, sem aviso nem ruído, pareceu abrir-se um talho e apareceu uma mão, uma mão branca, quase feminina, que tateou no centro da pequena área de luz. Por um minuto ou mais a mão, com seus dedos contorcendo-se, projetou-se para fora do chão. Depois foi retirada tão de súbito como surgira, e tudo ficou escuro de novo, exceto a única faísca lívida que marcava uma fresta entre as pedras.","itsdisappearancehoweverwasbutmomentarywi~ceandashockofveryredhair~469":"Seu desaparecimento, contudo, foi apenas momentâneo. Com um som de rasgar e arrancar, uma das largas pedras brancas virou de lado e deixou um buraco quadrado e escancarado, pelo qual jorrava a luz de uma lanterna. Sobre a borda espiou um rosto de traços nítidos, juvenil, que olhou atentamente em torno e depois, com uma mão de cada lado da abertura, ergueu-se até a altura dos ombros e da cintura, até que um joelho repousou na borda. Num instante estava de pé ao lado do buraco e puxava atrás de si um companheiro, ágil e pequeno como ele, de rosto pálido e uma cabeleira muito vermelha.","itsallclearhewhisperedhaveyouthechiselan~chiejumpandillswingforit~88":"“Está tudo limpo”, sussurrou. “Trouxe o cinzel e os sacos? Santo Deus! Pule, Archie, pule, que eu pago por isso!”","sherlockholmeshadsprungoutandseizedthein~clinkeduponthestonefloor~255":"Sherlock Holmes saltara à frente e agarrara o intruso pela gola. O outro mergulhou buraco abaixo, e ouvi o som de pano rasgando quando Jones lhe agarrou as abas. A luz faiscou no cano de um revólver, mas o chicote de caça de Holmes desceu sobre o pulso do homem, e a pistola tilintou no piso de pedra.","itsnousejohnclaysaidholmesblandlyyouhave~ndlyyouhavenochanceatall~53":"“É inútil, John Clay”, disse Holmes suavemente. “O senhor não tem a menor chance.”","soiseetheotheransweredwiththeutmostcooln~eeyouhavegothiscoattails~100":"“É o que vejo”, respondeu o outro com a maior frieza. “Imagino que meu camarada esteja a salvo, embora veja que o senhor ficou com as abas do casaco dele.”","therearethreemenwaitingforhimatthedoorsa~orhimatthedoorsaidholmes~48":"“Há três homens à espera dele na porta”, disse Holmes.","ohindeedyouseemtohavedonethethingverycom~letelyimustcomplimentyou~65":"“Oh, de fato! O senhor parece ter feito tudo muito completamente. Devo cumprimentá-lo.”","andiyouholmesansweredyourredheadedideawa~eawasverynewandeffective~60":"“E eu ao senhor”, respondeu Holmes. “A sua ideia dos cabeças-vermelhas foi muito nova e eficaz.”","youllseeyourpalagainpresentlysaidjoneshe~ldoutwhileifixthederbies~104":"“O senhor verá seu camarada de novo daqui a pouco”, disse Jones. “Ele é mais rápido que eu em descer buracos. Fique quieto enquanto ajusto as pulseiras.”","ibegthatyouwillnottouchmewithyourfilthyh~ealwaystosaysirandplease~201":"“Peço que não me toque com essas mãos imundas”, observou nosso prisioneiro enquanto as algemas tilintavam em seus pulsos. “Talvez o senhor não saiba que tenho sangue real nas veias. Tenha também a bondade de, quando se dirigir a mim, dizer sempre ‘senhor’ e ‘por favor’. ”","allrightsaidjoneswithastareandasniggerwe~ghnesstothepolicestation~126":"“Está bem”, disse Jones, com um olhar fixo e uma risadinha. “Pois bem, o senhor poderia, por favor, senhor, marchar escada acima, onde poderemos arranjar um cabriolé para levar Vossa Alteza à delegacia?”","thatisbettersaidjohnclayserenelyhemadeas~thecustodyofthedetective~109":"“Assim é melhor”, disse John Clay serenamente. Fez uma ampla reverência a nós três e saiu calmamente sob a custódia do detetive.","reallymrholmessaidmrmerryweatheraswefoll~ercomewithinmyexperience~246":"“Realmente, Sr. Holmes”, disse o Sr. Merryweather, enquanto os seguíamos para fora do porão, “não sei como o banco poderá agradecer-lhe ou recompensá-lo. Não há dúvida de que o senhor descobriu e derrotou da maneira mais completa uma das mais obstinadas tentativas de roubo a banco que já chegaram ao meu conhecimento.”","ihavehadoneortwolittlescoresofmyowntoset~tiveoftheredheadedleague~271":"“Eu tinha uma ou duas pequenas contas minhas a acertar com o Sr. John Clay”, disse Holmes. “Tive algumas pequenas despesas neste caso, que espero que o banco reembolse, mas além disso estou amplamente pago por ter vivido uma experiência que é em muitos aspectos única e por ter ouvido a notabilíssima narrativa da Liga dos Cabeças-Vermelhas.”","youseewatsonheexplainedintheearlyhoursof~eforsecuringthesituation~815":"“Veja, Watson”, explicou ele nas primeiras horas da manhã, enquanto estávamos sentados com um copo de uísque com soda na Baker Street, “estava perfeitamente óbvio desde o início que o único objetivo possível desse negócio um tanto fantástico do anúncio da Liga e da cópia da Enciclopédia devia ser afastar esse penhorista pouco brilhante por um certo número de horas todos os dias. Foi um modo curioso de arranjá-lo, mas, realmente, seria difícil sugerir melhor. O método foi sem dúvida sugerido à mente engenhosa de Clay pela cor do cabelo do seu cúmplice. As £4 por semana eram uma isca que devia atraí-lo, e o que eram elas para quem jogava por milhares? Puseram o anúncio, um malandro ficou com o escritório temporário, o outro incitou o homem a candidatar-se, e juntos conseguiram assegurar a ausência dele toda manhã da semana. Desde o momento em que soube que o ajudante viera por meio salário, ficou-me óbvio que ele tinha algum forte motivo para assegurar a colocação.”","buthowcouldyouguesswhatthemotivewas~youguesswhatthemotivewas~35":"“Mas como podia adivinhar qual era o motivo?”","hadtherebeenwomeninthehouseishouldhavesu~unneltosomeotherbuilding~673":"“Se houvesse mulheres na casa, eu suspeitaria de uma mera e vulgar intriga. Isso, porém, estava fora de questão. O negócio do homem era pequeno, e nada havia em sua casa que explicasse tão elaborados preparativos e a despesa em que estavam metidos. Devia ser, então, algo fora da casa. O que poderia ser? Pensei na predileção do ajudante pela fotografia e em seu truque de desaparecer no porão. O porão! Ali estava a ponta desse fio emaranhado. Fiz então indagações sobre esse misterioso ajudante e descobri que tinha de lidar com um dos criminosos mais frios e ousados de Londres. Ele estava fazendo algo no porão, algo que tomava muitas horas por dia durante meses a fio. O que podia ser, uma vez mais? Não pude pensar em nada, a não ser que estava cavando um túnel até algum outro edifício.","sofarihadgotwhenwewenttovisitthesceneofa~theresultthatyouhaveseen~689":"“Até aí eu chegara quando fomos visitar o cenário da ação. Surpreendi o senhor batendo na calçada com a bengala. Eu estava verificando se o porão se estendia para a frente ou para trás. Não era para a frente. Então toquei a campainha e, como eu esperava, o ajudante atendeu. Já tivemos algumas escaramuças, mas nunca havíamos posto os olhos um no outro. Mal olhei seu rosto. Eram os joelhos que eu queria ver. O senhor próprio deve ter notado como estavam gastos, enrugados e manchados. Falavam daquelas horas de escavação. O único ponto restante era para que estavam escavando. Dobrei a esquina, vi que o City and Suburban Bank confinava com as instalações do nosso amigo e senti que resolvera meu problema. Quando o senhor foi para casa depois do concerto, visitei a Scotland Yard e o presidente da diretoria do banco, com o resultado que o senhor viu.”","andhowcouldyoutellthattheywouldmaketheir~heirattempttonightiasked~60":"“E como pôde saber que tentariam esta noite?”, perguntei.","wellwhentheyclosedtheirleagueofficesthat~xpectedthemtocometonight~350":"“Bem, quando fecharam os escritórios da Liga, foi sinal de que não se importavam mais com a presença do Sr. Jabez Wilson, em outras palavras, de que haviam concluído o túnel. Mas era essencial que o usassem logo, pois ele poderia ser descoberto, ou o ouro poderia ser removido. O sábado lhes convinha mais que qualquer outro dia, pois lhes daria dois dias para a fuga. Por todas essas razões esperei que viessem esta noite.”","youreasoneditoutbeautifullyiexclaimedinu~andyeteverylinkringstrue~98":"“O senhor raciocinou admiravelmente”, exclamei, com admiração sincera. “É uma cadeia tão longa, e no entanto cada elo soa verdadeiro.”","itsavedmefromennuiheansweredyawningalasi~ttleproblemshelpmetodoso~165":"“Livrou-me do tédio”, respondeu, bocejando. “Ai de mim! Já o sinto se fechando sobre mim. Minha vida é gasta num longo esforço para escapar das banalidades da existência. Esses pequenos problemas ajudam-me a fazê-lo.”","andyouareabenefactoroftheracesaidi~benefactoroftheracesaidi~34":"“E o senhor é um benfeitor da raça humana”, disse eu.","heshruggedhisshoulderswellperhapsafteral~laubertwrotetogeorgesand~133":"Ele deu de ombros. “Bem, talvez, afinal, seja de alguma pequena utilidade”, observou. “ ‘L’homme c’est rien—l’oeuvre c’est tout’, como escreveu Gustave Flaubert a George Sand.”","mydearfellowsaidsherlockholmesaswesatone~moststaleandunprofitable~564":"“Meu caro amigo”, disse Sherlock Holmes, enquanto nos sentávamos um de cada lado da lareira em seus aposentos na Baker Street, “a vida é infinitamente mais estranha do que qualquer coisa que a mente do homem pudesse inventar. Não ousaríamos conceber as coisas que são, na realidade, meros lugares-comuns da existência. Se pudéssemos voar por aquela janela, de mãos dadas, pairar sobre esta grande cidade, remover suavemente os telhados e espiar as coisas estranhas que se passam, as coincidências singulares, os planos, os desencontros de propósitos, as maravilhosas cadeias de acontecimentos, operando através de gerações e conduzindo aos resultados mais outré, isso tornaria toda a ficção, com suas convenções e conclusões previsíveis, sumamente insípida e inútil.”","andyetiamnotconvincedofitiansweredthecas~erfascinatingnorartistic~222":"“E no entanto não estou convencido disso”, respondi. “Os casos que vêm à luz nos jornais são, via de regra, bastante nus e bastante vulgares. Temos em nossos relatórios policiais o realismo levado ao extremo, e contudo o resultado, é preciso confessar, não é nem fascinante nem artístico.”","acertainselectionanddiscretionmustbeused~nnaturalasthecommonplace~297":"“É preciso usar certa seleção e discrição para produzir um efeito realista”, observou Holmes. “Isso falta ao relatório policial, onde se dá talvez mais ênfase às banalidades do magistrado do que aos pormenores, que para um observador contêm a essência vital de todo o assunto. Pode estar certo de que nada há tão antinatural quanto o lugar-comum.”","ismiledandshookmyheadicanquiteunderstand~ldinventnothingmorecrude~565":"Sorri e balancei a cabeça. “Posso compreender perfeitamente que o senhor pense assim”, disse. “Claro, em sua posição de conselheiro e auxiliar extraoficial de todos os que se encontram absolutamente perplexos, nos três continentes, o senhor é posto em contato com tudo o que é estranho e bizarro. Mas aqui”, apanhei do chão o jornal da manhã, “submetamos isto a uma prova prática. Eis o primeiro título com que dou. ‘A crueldade de um marido para com a esposa.’ Há meia coluna impressa, mas sei, sem ler, que tudo me é perfeitamente familiar. Há, naturalmente, a outra mulher, a bebida, o empurrão, o golpe, a contusão, a irmã ou a senhoria compassiva. O mais tosco dos escritores nada poderia inventar de mais tosco.”","indeedyourexampleisanunfortunateoneforyo~oredoveryouinyourexample~517":"“Na verdade, seu exemplo é infeliz para o seu argumento”, disse Holmes, tomando o jornal e correndo os olhos por ele. “Este é o caso da separação Dundas e, por acaso, eu estava ocupado em esclarecer alguns pequenos pontos a ele ligados. O marido era abstêmio, não havia outra mulher, e a conduta de que se queixavam era que ele caíra no hábito de encerrar cada refeição tirando a dentadura postiça e arremessando-a contra a esposa, o que, o senhor há de admitir, não é ação que ocorra facilmente à imaginação do contador de histórias comum. Tome uma pitada de rapé, doutor, e reconheça que marquei um ponto contra o senhor no seu exemplo.”","heheldouthissnuffboxofoldgoldwithagreata~dnothelpcommentinguponit~156":"Estendeu a tabaqueira de ouro antigo, com uma grande ametista no centro da tampa. Seu esplendor contrastava tanto com seus modos simples e sua vida modesta que não pude deixar de comentá-lo.","ahsaidheiforgotthatihadnotseenyouforsome~aseoftheireneadlerpapers~137":"“Ah”, disse ele, “esqueci que não o via havia algumas semanas. É uma pequena lembrança do Rei da Boêmia, em troca de minha ajuda no caso dos papéis de Irene Adler.”","andtheringiaskedglancingataremarkablebri~ichsparkleduponhisfinger~72":"“E o anel?”, perguntei, olhando um notável brilhante que faiscava em seu dedo.","itwasfromthereigningfamilyofhollandthoug~eortwoofmylittleproblems~172":"“Veio da família reinante da Holanda, embora o assunto em que os servi fosse de tal delicadeza que não posso confiá-lo nem mesmo ao senhor, que teve a bondade de registrar um ou dois dos meus pequenos problemas.”","andhaveyouanyonhandjustnowiaskedwithinte~ustnowiaskedwithinterest~44":"“E tem algum em mãos agora?”, perguntei com interesse.","sometenortwelvebutnonewhichpresentanyfea~clientsoriammuchmistaken~594":"“Uns dez ou doze, mas nenhum que apresente qualquer traço de interesse. São importantes, o senhor entende, sem ser interessantes. De fato, descobri que é geralmente nos assuntos sem importância que há campo para a observação e para a rápida análise de causa e efeito que dá o encanto a uma investigação. Os crimes maiores tendem a ser os mais simples, pois quanto maior o crime, mais óbvio é, via de regra, o motivo. Nesses casos, salvo um assunto bastante intrincado que me foi encaminhado de Marselha, nada há que apresente traços de interesse. É possível, contudo, que eu tenha algo melhor antes que passem muitos minutos, pois este é um dos meus clientes, ou muito me engano.”","hehadrisenfromhischairandwasstandingbetw~rdthesharpclangofthebell~570":"Levantara-se da poltrona e estava de pé entre as persianas entreabertas, olhando para a monótona rua londrina de tons neutros. Olhando por cima do ombro dele, vi que na calçada fronteira estava uma mulher grande, com uma pesada estola de pele ao pescoço e uma grande pluma vermelha encaracolada num chapéu de abas largas, inclinado, à maneira coquete da Duquesa de Devonshire, sobre a orelha. Debaixo dessa grande panóplia, espiava nossas janelas de modo nervoso e hesitante, enquanto o corpo oscilava para a frente e para trás e os dedos remexiam nos botões da luva. De repente, com um mergulho, como o do nadador que deixa a margem, atravessou a rua apressada, e ouvimos o toque agudo da campainha.","ihaveseenthosesymptomsbeforesaidholmesth~persontoresolveourdoubts~453":"“Já vi esses sintomas”, disse Holmes, atirando o cigarro ao fogo. “A oscilação na calçada significa sempre uma affaire de coeur. Ela gostaria de um conselho, mas não tem certeza de que o assunto não seja delicado demais para ser comunicado. E no entanto, mesmo aqui podemos discriminar. Quando uma mulher foi gravemente ofendida por um homem, já não oscila, e o sintoma usual é um fio de campainha arrebentado. Aqui podemos tomar por certo que se trata de questão amorosa, mas que a donzela não está tanto zangada quanto perplexa ou aflita. Mas aí vem ela em pessoa para dirimir nossas dúvidas.”","ashespoketherewasatapatthedoorandtheboyi~ionwhichwaspeculiartohim~363":"Enquanto ele falava, ouviu-se uma batida à porta, e o moço de botões entrou para anunciar a Srta. Mary Sutherland, enquanto a própria dama assomava atrás de sua pequena figura negra como um mercante de velas pandas atrás de um minúsculo barco-piloto. Sherlock Holmes recebeu-a com a fácil cortesia pela qual era notável e, depois de fechar a porta e conduzi-la com uma mesura a uma poltrona, examinou-a de modo minucioso e, no entanto, distraído, que lhe era peculiar.","doyounotfindhesaidthatwithyourshortsight~ingtodosomuchtypewriting~78":"“Não acha”, disse ele, “que com a sua vista curta é um tanto penoso fazer tanto trabalho de datilografia?”","ididatfirstsheansweredbutnowiknowwhereth~sehowcouldyouknowallthat~251":"“No início achava”, respondeu ela, “mas agora sei onde estão as letras sem olhar.” Então, percebendo de súbito todo o alcance das palavras dele, teve um violento sobressalto e ergueu os olhos, com medo e espanto no rosto largo e bonachão. “O senhor ouviu falar de mim, Sr. Holmes”, exclamou, “senão como poderia saber tudo isso?”","nevermindsaidholmeslaughingitismybusines~shouldyoucometoconsultme~133":"“Não faz mal”, disse Holmes, rindo; “é meu ofício saber das coisas. Talvez eu tenha me treinado para ver o que os outros deixam passar. Se não, por que viria a senhorita me consultar?”","icametoyousirbecauseiheardofyoufrommrset~hasbecomeofmrhosmerangel~288":"“Vim ao senhor, senhor, porque ouvi falar de si pela Sra. Etherege, cujo marido o senhor encontrou com tanta facilidade quando a polícia e todos o davam por morto. Oh, Sr. Holmes, queria que fizesse outro tanto por mim. Não sou rica, mas ainda assim tenho cem libras por ano por direito próprio, além do pouco que ganho com a máquina, e daria tudo para saber o que foi feito do Sr. Hosmer Angel.”","whydidyoucomeawaytoconsultmeinsuchahurry~erandhiseyestotheceiling~106":"“Por que saiu com tanta pressa para me consultar?”, perguntou Sherlock Holmes, com as pontas dos dedos juntas e os olhos no teto.","againastartledlookcameoverthesomewhatvac~ngsandcamerightawaytoyou~334":"Novamente um olhar assustado perpassou o rosto um tanto vazio da Srta. Mary Sutherland. “Sim, saí batendo a porta”, disse ela, “pois me deu raiva ver a maneira displicente com que o Sr. Windibank, quer dizer, meu pai, encarou tudo. Não quis ir à polícia, não quis ir ao senhor, e assim, por fim, como não queria fazer nada e ficava dizendo que não havia mal nenhum, aquilo me deixou furiosa, e simplesmente vesti as minhas coisas e vim direto ao senhor.”","yourfathersaidholmesyourstepfathersurely~ysincethenameisdifferent~63":"“Seu pai”, disse Holmes, “seu padrasto, certamente, já que o nome é diferente.”","yesmystepfathericallhimfatherthoughitsou~twomonthsolderthanmyself~98":"“Sim, meu padrasto. Chamo-o de pai, embora soe engraçado também, pois ele é apenas cinco anos e dois meses mais velho que eu.”","andyourmotherisalive~andyourmotherisalive~20":"“E sua mãe vive?”","ohyesmotherisaliveandwelliwasntbestpleas~dhavegotifhehadbeenalive~433":"“Oh, sim, mamãe está viva e bem. Não fiquei muito contente, Sr. Holmes, quando ela se casou de novo tão cedo depois da morte de papai, e com um homem quase quinze anos mais moço que ela. Papai era encanador na Tottenham Court Road e deixou um negócio bem arrumado, que mamãe levou adiante com o Sr. Hardy, o contramestre; mas quando o Sr. Windibank chegou, obrigou-a a vender o negócio, pois era muito superior, sendo viajante de vinhos. Receberam £4.700 pelo ponto e pelos interesses, o que não chegava nem perto do que papai teria conseguido se fosse vivo.”","ihadexpectedtoseesherlockholmesimpatient~concentrationofattention~152":"Eu esperara ver Sherlock Holmes impaciente com essa narrativa divagante e inconsequente, mas, pelo contrário, ele ouvira com a maior concentração de atenção.","yourownlittleincomeheaskeddoesitcomeouto~esitcomeoutofthebusiness~52":"“Sua pequena renda”, perguntou, “vem do negócio?”","ohnosiritisquiteseparateandwasleftmebymy~icanonlytouchtheinterest~160":"“Oh, não, senhor. É totalmente separada e foi-me deixada por meu tio Ned, em Auckland. Está em títulos da Nova Zelândia, que rendem 4½ por cento. O montante foi de duas mil e quinhentas libras, mas só posso tocar nos juros.”","youinterestmeextremelysaidholmesandsince~elyuponanincomeofabout60~215":"“A senhorita me interessa extremamente”, disse Holmes. “E como retira uma soma tão grande quanto cem por ano, e mais o que ganha, sem dúvida viaja um pouco e se permite todos os prazeres. Creio que uma senhora solteira pode passar muito bem com uma renda de cerca de £60.”","icoulddowithmuchlessthanthatmrholmesbuty~teentotwentysheetsinaday~371":"“Eu poderia passar com muito menos que isso, Sr. Holmes, mas o senhor entende que, enquanto moro em casa, não quero ser um peso para eles, e assim eles usam o dinheiro enquanto estou com eles. Claro que é só por ora. O Sr. Windibank retira meus juros todo trimestre e os entrega a mamãe, e vejo que posso me arranjar muito bem com o que ganho datilografando. Rende-me dois pence por folha, e muitas vezes consigo fazer de quinze a vinte folhas por dia.”","youhavemadeyourpositionverycleartomesaid~nectionwithmrhosmerangel~165":"“A senhorita deixou muito clara a sua situação”, disse Holmes. “Este é meu amigo, o Dr. Watson, diante de quem pode falar tão livremente quanto diante de mim. Tenha a bondade de nos contar agora tudo sobre a sua ligação com o Sr. Hosmer Angel.”","aflushstoleovermisssutherlandsfaceandshe~asthereimetmrhosmerangel~696":"Um rubor subiu ao rosto da Srta. Sutherland, e ela beliscou nervosamente a franja do casaco. “Conheci-o no baile dos instaladores de gás”, disse. “Costumavam mandar ingressos para papai quando era vivo e depois, mais tarde, lembraram-se de nós e mandaram-nos para mamãe. O Sr. Windibank não queria que fôssemos. Nunca quis que fôssemos a lugar nenhum. Ficava furioso se eu quisesse sequer participar de um passeio da escola dominical. Mas dessa vez eu estava decidida a ir, e iria; pois que direito tinha ele de impedir? Dizia que aquela gente não era própria para nós conhecermos, quando todos os amigos de papai estariam lá. E dizia que eu não tinha nada decente para vestir, quando tinha o meu vestido de pelúcia roxa, que nunca nem tirara da gaveta. Por fim, quando nada mais adiantou, ele foi à França a negócios da firma, mas nós fomos, mamãe e eu, com o Sr. Hardy, que fora nosso contramestre, e foi lá que conheci o Sr. Hosmer Angel.”","isupposesaidholmesthatwhenmrwindibankcam~tyourhavinggonetotheball~96":"“Suponho”, disse Holmes, “que quando o Sr. Windibank voltou da França ficou muito aborrecido por a senhorita ter ido ao baile.”","ohwellhewasverygoodaboutithelaughedireme~manforshewouldhaveherway~131":"“Oh, bem, ele foi muito bom a respeito. Riu, lembro-me, deu de ombros e disse que não adiantava negar nada a uma mulher, pois ela sempre faria a sua vontade.”","iseethenatthegasfittersballyoumetasiunde~lemancalledmrhosmerangel~75":"“Entendo. Então, no baile dos instaladores de gás, a senhorita conheceu, ao que entendo, um cavalheiro chamado Sr. Hosmer Angel.”","yessirimethimthatnightandhecallednextday~notcometothehouseanymore~201":"“Sim, senhor. Conheci-o naquela noite, e ele veio no dia seguinte perguntar se havíamos chegado bem em casa, e depois disso nos encontramos... quer dizer, Sr. Holmes, eu o encontrei duas vezes para passeios, mas depois papai voltou, e o Sr. Hosmer Angel não pôde mais vir à casa.”","no~no~2":"“Não?”","wellyouknowfatherdidntlikeanythingofthes~withandihadnotgotmineyet~220":"“Bem, o senhor sabe, papai não gostava de nada disso. Não queria visitas se pudesse evitar, e costumava dizer que uma mulher deve ser feliz no círculo de sua própria família. Mas então, como eu dizia a mamãe, uma mulher quer ter o seu próprio círculo para começar, e eu ainda não tinha o meu.”","buthowaboutmrhosmerangeldidhemakenoattem~dhemakenoattempttoseeyou~50":"“Mas e o Sr. Hosmer Angel? Não fez nenhuma tentativa de vê-la?”","wellfatherwasgoingofftofranceagaininawee~wasnoneedforfathertoknow~229":"“Bem, papai ia partir para a França de novo dentro de uma semana, e Hosmer escreveu dizendo que seria mais seguro e melhor não nos vermos até que ele partisse. Podíamos escrever-nos nesse meio-tempo, e ele escrevia todos os dias. Eu recolhia as cartas de manhã, de modo que não havia necessidade de papai saber.”","wereyouengagedtothegentlemanatthistime~tothegentlemanatthistime~38":"“A senhorita estava noiva do cavalheiro nessa época?”","ohyesmrholmeswewereengagedafterthefirstw~iceinleadenhallstreetand~108":"“Oh, sim, Sr. Holmes. Ficamos noivos depois do primeiro passeio que demos. Hosmer, o Sr. Angel, era caixa num escritório da Leadenhall Street, e...”","whatoffice~whatoffice~10":"“Que escritório?”","thatstheworstofitmrholmesidontknow~rstofitmrholmesidontknow~34":"“Esse é o pior, Sr. Holmes, não sei.”","wheredidhelivethen~wheredidhelivethen~18":"“Onde morava ele, então?”","hesleptonthepremises~hesleptonthepremises~20":"“Dormia no local de trabalho.”","andyoudontknowhisaddress~andyoudontknowhisaddress~24":"“E a senhorita não sabe o endereço dele?”","noexceptthatitwasleadenhallstreet~hatitwasleadenhallstreet~33":"“Não, só que era Leadenhall Street.”","wheredidyouaddressyourlettersthen~ouaddressyourlettersthen~33":"“Para onde endereçava as cartas, então?”","totheleadenhallstreetpostofficetobeleftt~thingsthathewouldthinkof~402":"“Para a agência do Correio da Leadenhall Street, para serem retiradas quando reclamadas. Ele disse que, se fossem enviadas ao escritório, seria zombado por todos os outros funcionários por receber cartas de uma dama, e então me ofereci para datilografá-las, como ele fazia com as dele, mas isso ele não quis, pois disse que, quando eu as escrevia à mão, pareciam vir de mim, mas, quando eram datilografadas, sentia sempre que a máquina se interpunha entre nós. Isso lhe mostra o quanto ele gostava de mim, Sr. Holmes, e as coisinhas em que pensava.”","itwasmostsuggestivesaidholmesithaslongbe~thingsaboutmrhosmerangel~155":"“Foi muito sugestivo”, disse Holmes. “Há muito é um axioma meu que as coisinhas são infinitamente as mais importantes. A senhorita se lembra de outras coisinhas sobre o Sr. Hosmer Angel?”","hewasaveryshymanmrholmeshewouldratherwal~edglassesagainsttheglare~391":"“Era um homem muito tímido, Sr. Holmes. Preferia passear comigo à noite a passear à luz do dia, pois dizia que detestava chamar a atenção. Muito reservado e cavalheiresco era ele. Até a voz era suave. Tivera angina e glândulas inchadas quando jovem, contou-me, e isso lhe deixara a garganta fraca e uma maneira hesitante, sussurrada, de falar. Estava sempre bem vestido, muito asseado e simples, mas tinha os olhos fracos, como os meus, e usava óculos escuros contra a claridade.”","wellandwhathappenedwhenmrwindibankyourst~epfatherreturnedtofrance~64":"“Bem, e o que aconteceu quando o Sr. Windibank, seu padrasto, voltou à França?”","mrhosmerangelcametothehouseagainandpropo~everymorningofthewedding~721":"“O Sr. Hosmer Angel veio à casa de novo e propôs que nos casássemos antes de papai voltar. Estava terrivelmente sério e fez-me jurar, com as mãos sobre o Testamento, que, acontecesse o que acontecesse, eu lhe seria sempre fiel. Mamãe disse que ele estava certo em me fazer jurar e que era sinal de sua paixão. Mamãe esteve a favor dele desde o início e gostava dele ainda mais do que eu. Então, quando falaram em casar dentro da semana, comecei a perguntar por papai; mas ambos disseram que não me importasse com papai, que apenas lhe contasse depois, e mamãe disse que acertaria tudo com ele. Não gostei muito disso, Sr. Holmes. Parecia estranho que eu pedisse licença a ele, que era apenas alguns anos mais velho que eu; mas não quis fazer nada às escondidas, de modo que escrevi a papai em Bordeaux, onde a companhia tem seus escritórios franceses, mas a carta voltou para mim na própria manhã do casamento.”","itmissedhimthen~itmissedhimthen~15":"“Não o encontrou, então?”","yessirforhehadstartedtoenglandjustbefore~glandjustbeforeitarrived~49":"“Sim, senhor; pois ele partira para a Inglaterra pouco antes de ela chegar.”","hathatwasunfortunateyourweddingwasarrang~efridaywasittobeinchurch~75":"“Ha! Que infelicidade. O casamento estava marcado, então, para a sexta-feira. Seria na igreja?”","yessirbutveryquietlyitwastobeatstsaviour~lightuponwhatbecameofhim~577":"“Sim, senhor, mas muito discretamente. Seria em St. Saviour’s, perto de King’s Cross, e depois tomaríamos o desjejum no Hotel St. Pancras. Hosmer veio nos buscar num cabriolé, mas, como éramos duas, pôs-nos ambas nele e entrou ele próprio num coche de quatro rodas, que por acaso era o único outro carro na rua. Chegamos primeiro à igreja e, quando o coche de quatro rodas chegou, esperamos que ele descesse, mas nunca desceu, e quando o cocheiro desceu da boleia e olhou, não havia ninguém lá! O cocheiro disse que não podia imaginar o que fora feito dele, pois o vira entrar com seus próprios olhos. Isso foi na sexta passada, Sr. Holmes, e nunca mais vi nem ouvi nada que lance alguma luz sobre o que foi feito dele.”","itseemstomethatyouhavebeenveryshamefully~mefullytreatedsaidholmes~57":"“Parece-me que a senhorita foi tratada de maneira vergonhosa”, disse Holmes.","ohnosirhewastoogoodandkindtoleavemesowhy~edsincegivesameaningtoit~315":"“Oh, não, senhor! Ele era bom e gentil demais para me deixar assim. Ora, a manhã inteira ele me dizia que, acontecesse o que acontecesse, eu devia ser fiel; e que, mesmo que algo totalmente imprevisto ocorresse para nos separar, eu devia sempre me lembrar de que estava comprometida com ele e que ele reclamaria seu compromisso mais cedo ou mais tarde. Parecia estranha conversa para uma manhã de casamento, mas o que aconteceu desde então lhe dá sentido.”","mostcertainlyitdoesyourownopinionisthent~astrophehasoccurredtohim~84":"“Certamente dá. A sua própria opinião é, então, que alguma catástrofe imprevista lhe sobreveio?”","yessiribelievethatheforesawsomedangerore~hatwhatheforesawhappened~103":"“Sim, senhor. Creio que ele previu algum perigo, senão não teria falado assim. E então creio que aconteceu o que ele previu.”","butyouhavenonotionastowhatitcouldhavebee~nastowhatitcouldhavebeen~41":"“Mas a senhorita não faz ideia do que possa ter sido?”","onemorequestionhowdidyourmothertakethema~dyourmothertakethematter~44":"“Mais uma pergunta. Como sua mãe encarou o assunto?”","shewasangryandsaidthatiwasnevertospeakof~rtospeakofthematteragain~54":"“Ficou zangada e disse que eu nunca mais devia falar no assunto.”","andyourfatherdidyoutellhim~dyourfatherdidyoutellhim~26":"“E seu pai? A senhorita lhe contou?”","yesandheseemedtothinkwithmethatsomething~dbegantosobheavilyintoit~496":"“Sim; e ele pareceu pensar, comigo, que algo acontecera e que eu teria notícias de Hosmer de novo. Como ele disse, que interesse poderia alguém ter em me levar até as portas da igreja e depois me deixar? Ora, se tivesse tomado meu dinheiro emprestado, ou se tivesse casado comigo e feito o meu dinheiro passar para ele, poderia haver alguma razão, mas Hosmer era muito independente em matéria de dinheiro e nunca quis olhar para um xelim meu. E no entanto, o que pode ter acontecido? E por que não pôde escrever? Oh, enlouqueço pela metade só de pensar nisso, e não consigo dormir um instante à noite.” Tirou um lencinho do regalo e começou a soluçar pesadamente nele.","ishallglanceintothecaseforyousaidholmesr~yashehasdonefromyourlife~239":"“Darei uma olhada no caso para a senhorita”, disse Holmes, levantando-se, “e não tenho dúvida de que chegaremos a algum resultado definido. Deixe agora o peso do assunto sobre mim e não deixe seu espírito demorar-se mais nele. Acima de tudo, procure deixar o Sr. Hosmer Angel desvanecer-se de sua memória, como se desvaneceu de sua vida.”","thenyoudontthinkillseehimagain~udontthinkillseehimagain~30":"“Então não acha que o verei de novo?”","ifearnot~ifearnot~8":"“Receio que não.”","thenwhathashappenedtohim~thenwhathashappenedtohim~24":"“Então o que aconteceu com ele?”","youwillleavethatquestioninmyhandsishould~ersofhiswhichyoucanspare~104":"“A senhorita deixará essa pergunta em minhas mãos. Gostaria de uma descrição exata dele e de quaisquer cartas dele que possa ceder.”","iadvertisedforhiminlastsaturdayschronicl~erearefourlettersfromhim~89":"“Anunciei procurando por ele no Chronicle de sábado passado”, disse ela. “Aqui está o recorte, e aqui estão quatro cartas dele.”","thankyouandyouraddress~thankyouandyouraddress~22":"“Obrigado. E o seu endereço?”","no31lyonplacecamberwell~no31lyonplacecamberwell~23":"“Lyon Place, nº 31, Camberwell.”","mrangelsaddressyouneverhadiunderstandwhe~urfathersplaceofbusiness~70":"“O endereço do Sr. Angel a senhorita nunca teve, entendo. Onde fica o local de trabalho de seu pai?”","hetravelsforwesthousemarbankthegreatclar~portersoffenchurchstreet~68":"“Ele viaja pela Westhouse & Marbank, os grandes importadores de clarete da Fenchurch Street.”","thankyouyouhavemadeyourstatementveryclea~tallowittoaffectyourlife~169":"“Obrigado. A senhorita fez sua exposição muito claramente. Deixará aqui os papéis e se lembrará do conselho que lhe dei. Que todo o incidente seja um livro fechado, e não permita que afete sua vida.”","youareverykindmrholmesbuticannotdothatis~ndmereadywhenhecomesback~91":"“O senhor é muito bondoso, Sr. Holmes, mas não posso fazer isso. Serei fiel a Hosmer. Ele me encontrará pronta quando voltar.”","forallthepreposteroushatandthevacuousfac~enevershemightbesummoned~219":"Apesar do chapéu despropositado e do rosto vazio, havia algo de nobre na fé simples de nossa visitante que impunha nosso respeito. Deixou sobre a mesa o seu pequeno maço de papéis e foi-se embora, com a promessa de voltar sempre que fosse chamada.","sherlockholmessatsilentforafewminuteswit~infinitelanguorinhisface~328":"Sherlock Holmes ficou calado por alguns minutos, com as pontas dos dedos ainda unidas, as pernas esticadas à frente e o olhar dirigido para o teto. Depois tirou do suporte o velho cachimbo de barro, gorduroso, que era para ele como um conselheiro e, depois de acendê-lo, recostou-se na poltrona, com as espessas volutas azuis de fumaça subindo dele e um olhar de infinita languidez no rosto.","quiteaninterestingstudythatmaidenheobser~erselfwasmostinstructive~318":"“Um estudo bastante interessante, essa donzela”, observou. “Achei-a mais interessante que o seu probleminha, que, aliás, é bem batido. O senhor encontrará casos paralelos, se consultar meu índice, em Andover em ’77, e houve algo do gênero em Haia no ano passado. Por mais velha que seja a ideia, contudo, havia um ou dois pormenores que eram novos para mim. Mas a própria donzela foi instrutivíssima.”","youappearedtoreadagooddealuponherwhichwa~teinvisibletomeiremarked~68":"“O senhor pareceu ler nela muita coisa que me era totalmente invisível”, observei.","notinvisiblebutunnoticedwatsonyoudidnotk~mansappearancedescribeit~257":"“Não invisível, mas despercebida, Watson. O senhor não sabia onde olhar, e assim perdeu tudo o que era importante. Jamais consigo fazê-lo perceber a importância das mangas, o poder de sugestão das unhas dos polegares ou as grandes questões que podem pender de um cadarço de bota. Agora, o que o senhor reuniu da aparência daquela mulher? Descreva-a.”","wellshehadaslatecolouredbroadbrimmedstra~rcomfortableeasygoingway~412":"“Bem, ela tinha um chapéu de palha de abas largas, cor de ardósia, com uma pluma de vermelho tijolo. O casaco era preto, com contas pretas costuradas e uma franja de pequenos enfeites de azeviche. O vestido era marrom, mais escuro que cor de café, com um pouco de pelúcia roxa no pescoço e nas mangas. As luvas eram acinzentadas e estavam gastas no indicador direito. As botas não observei. Tinha pequenos brincos de ouro, redondos e pendentes, e um ar geral de estar razoavelmente bem de vida, de um modo vulgar, confortável e despreocupado.”","sherlockholmesclappedhishandssoftlytoget~oftlytogetherandchuckled~54":"Sherlock Holmes bateu palmas suavemente e riu.","ponmywordwatsonyouarecomingalongwonderfu~whichseemedtosurpriseher~803":"“ Palavra, Watson, o senhor está progredindo maravilhosamente. Realmente se saiu muito bem. É verdade que deixou passar tudo o que era importante, mas atinou com o método e tem um olho rápido para cores. Nunca confie nas impressões gerais, meu rapaz, mas concentre-se nos pormenores. Meu primeiro olhar é sempre para a manga de uma mulher. No homem talvez seja melhor tomar primeiro o joelho da calça. Como o senhor observou, essa mulher tinha pelúcia nas mangas, material utilíssimo para mostrar vestígios. A linha dupla um pouco acima do pulso, onde a datilógrafa se apoia na mesa, estava belamente definida. A máquina de costura, do tipo manual, deixa marca semelhante, mas só no braço esquerdo e do lado mais afastado do polegar, em vez de atravessar a parte mais larga, como esta. Olhei então para o rosto dela e, observando a marca de um pincenê de cada lado do nariz, aventurei uma observação sobre vista curta e datilografia, que pareceu surpreendê-la.”","itsurprisedme~itsurprisedme~13":"“Surpreendeu-me.”","butsurelyitwasobviousiwasthenmuchsurpris~ythatshecameawayinahurry~434":"“Mas, certamente, era óbvio. Fiquei então muito surpreso e interessado ao olhar para baixo e observar que, embora as botas que ela calçava não fossem muito diferentes entre si, eram na verdade desparelhadas: uma com a biqueira ligeiramente decorada e a outra lisa. Uma estava abotoada apenas nos dois botões inferiores dos cinco, e a outra no primeiro, no terceiro e no quinto. Ora, quando se vê que uma jovem dama, de resto asseadamente vestida, saiu de casa com botas desparelhadas, meio abotoadas, não é grande dedução dizer que saiu apressada.”","andwhatelseiaskedkeenlyinterestedasialwa~friendsincisivereasoning~73":"“E o que mais?”, perguntei, vivamente interessado, como sempre ficava com o raciocínio incisivo de meu amigo.","inotedinpassingthatshehadwrittenanotebef~scriptionofmrhosmerangel~437":"“Notei de passagem que ela escrevera um bilhete antes de sair de casa, mas depois de estar totalmente vestida. O senhor observou que a luva direita estava rasgada no indicador, mas aparentemente não viu que tanto a luva quanto o dedo estavam manchados de tinta violeta. Ela escrevera às pressas e molhara a pena demais. Deve ter sido esta manhã, ou a mancha não ficaria nítida no dedo. Tudo isto é divertido, embora bastante elementar, mas devo voltar aos negócios, Watson. Importa-se de ler para mim a descrição anunciada do Sr. Hosmer Angel?”","iheldthelittleprintedsliptothelight~tleprintedsliptothelight~35":"Segurei o pequeno recorte impresso contra a luz.","missingitsaidonthemorningofthefourteenth~allstreetanybodybringing~431":"“Desaparecido”, dizia, “na manhã do dia catorze, um cavalheiro chamado Hosmer Angel. Altura de cerca de cinco pés e sete polegadas; constituição forte, tez amarelada, cabelos pretos, um pouco calvo no centro, suíças e bigode pretos e espessos; óculos escuros, ligeira dificuldade de fala. Vestia, quando visto pela última vez, sobrecasaca preta com forro de seda, colete preto, corrente Albert de ouro e calças de tweed Harris cinzento, com polainas marrons sobre botinas de lados elásticos. Sabe-se ter sido empregado num escritório da Leadenhall Street. Quem trouxer...”","thatwilldosaidholmesastothelettershecont~hichwillnodoubtstrikeyou~197":"“Basta”, disse Holmes. “Quanto às cartas”, continuou, correndo os olhos por elas, “são muito banais. Absolutamente nenhuma pista nelas sobre o Sr. Angel, exceto que ele cita Balzac uma vez. Há, porém, um ponto notável, que sem dúvida lhe chamará a atenção.”","theyaretypewritteniremarked~yaretypewritteniremarked~27":"“São datilografadas”, observei.","notonlythatbutthesignatureistypewrittenl~actwemaycallitconclusive~225":"“Não só isso, mas a assinatura é datilografada. Olhe o asseado ‘Hosmer Angel’ no pé. Há uma data, o senhor vê, mas nenhum endereço, exceto Leadenhall Street, o que é bastante vago. O ponto da assinatura é muito sugestivo; na verdade, podemos chamá-lo conclusivo.”","ofwhat~ofwhat~6":"“De quê?”","mydearfellowisitpossibleyoudonotseehowst~ronglyitbearsuponthecase~64":"“Meu caro amigo, é possível que não veja quão fortemente isso pesa sobre o caso?”","icannotsaythatidounlessitwerethathewishe~hofpromisewereinstituted~109":"“Não posso dizer que veja, a menos que fosse que ele desejava poder negar sua assinatura se uma ação por quebra de promessa de casamento fosse instaurada.”","nothatwasnotthepointhoweverishallwritetw~pontheshelffortheinterim~366":"“Não, esse não era o ponto. Contudo, escreverei duas cartas, que devem resolver a questão. Uma é para uma firma da City, a outra é para o padrasto da jovem, o Sr. Windibank, perguntando-lhe se poderia encontrar-nos aqui às seis horas de amanhã à tarde. É bom que tratemos de negócios com os parentes do sexo masculino. E agora, doutor, nada podemos fazer até que cheguem as respostas a essas cartas, de modo que podemos pôr o nosso probleminha na prateleira por ora.”","ihadhadsomanyreasonstobelieveinmyfriends~edwhichhecouldnotunravel~483":"Eu tivera tantas razões para crer nos sutis poderes de raciocínio de meu amigo e em sua extraordinária energia na ação que senti que ele devia ter algum fundamento sólido para a atitude segura e despreocupada com que tratava o singular mistério que fora chamado a esclarecer. Uma só vez o vira falhar, no caso do Rei da Boêmia e da fotografia de Irene Adler; mas, quando relembrava o estranho negócio de O Signo dos Quatro e as extraordinárias circunstâncias ligadas a Um Estudo em Vermelho, sentia que seria de fato um estranho emaranhado aquele que ele não pudesse desfazer.","ilefthimthenstillpuffingathisblackclaypi~roomofmissmarysutherland~210":"Deixei-o então, ainda a tragar o cachimbo preto de barro, com a convicção de que, quando voltasse na noite seguinte, encontraria nas mãos dele todas as pistas que conduziriam à identidade do noivo desaparecido da Srta. Mary Sutherland.","aprofessionalcaseofgreatgravitywasengagi~lworkwhichwassodeartohim~527":"Um caso profissional de grande gravidade ocupava minha atenção na época, e todo o dia seguinte passei à cabeceira do doente. Só perto das seis horas me vi livre e pude saltar para um cabriolé e seguir para a Baker Street, meio receoso de chegar tarde demais para assistir ao desenlace do pequeno mistério. Encontrei Sherlock Holmes sozinho, contudo, meio adormecido, com a longa e magra figura enroscada nos recessos da poltrona. Uma formidável fileira de frascos e tubos de ensaio, com o cheiro penetrante e limpo de ácido clorídrico, disse-me que ele passara o dia no trabalho químico que lhe era tão caro.","wellhaveyousolveditiaskedasientered~solveditiaskedasientered~35":"“Então, resolveu?”, perguntei ao entrar.","yesitwasthebisulphateofbaryta~wasthebisulphateofbaryta~29":"“Sim. Era o bissulfato de baryta.”","nonothemysteryicried~nonothemysteryicried~20":"“Não, não, o mistério!”, exclamei.","ohthatithoughtofthesaltthatihavebeenwork~thatcantouchthescoundrel~194":"“Oh, isso! Pensei no sal em que tenho trabalhado. Nunca houve mistério algum no caso, embora, como disse ontem, alguns pormenores sejam de interesse. A única desvantagem é que não há lei, receio, que possa alcançar o canalha.”","whowashethenandwhatwashisobjectindeserti~ndesertingmisssutherland~56":"“Quem era ele, então, e qual era seu objetivo ao abandonar a Srta. Sutherland?”","thequestionwashardlyoutofmymouthandholme~epassageandatapatthedoor~123":"A pergunta mal saíra de minha boca, e Holmes ainda não abrira os lábios para responder, quando ouvimos um passo pesado no corredor e uma batida à porta.","thisisthegirlsstepfathermrjameswindibank~hewouldbehereatsixcomein~99":"“Este é o padrasto da moça, o Sr. James Windibank”, disse Holmes. “Escreveu-me dizendo que estaria aqui às seis. Entre!”","themanwhoenteredwasasturdymiddlesizedfel~ddownintothenearestchair~281":"O homem que entrou era um sujeito robusto, de estatura mediana, de uns trinta anos, de barba feita e pele amarelada, com maneiras brandas e insinuantes e um par de olhos cinzentos maravilhosamente agudos e penetrantes. Lançou um olhar interrogativo a cada um de nós, pôs a cartola lustrosa sobre o aparador e, com uma ligeira mesura, esgueirou-se para a cadeira mais próxima.","goodeveningmrjameswindibanksaidholmesith~ntmentwithmeforsixoclock~122":"“Boa noite, Sr. James Windibank”, disse Holmes. “Creio que esta carta datilografada é sua, na qual o senhor marcou um encontro comigo às seis horas?”","yessiriamafraidthatiamalittlelatebutiamn~siblyfindthishosmerangel~524":"“Sim, senhor. Receio estar um pouco atrasado, mas não sou inteiramente senhor de mim, o senhor sabe. Lamento que a Srta. Sutherland o tenha incomodado com este pequeno assunto, pois acho muito melhor não lavar roupa dessa espécie em público. Foi inteiramente contra a minha vontade que ela veio, mas é uma moça muito excitável e impulsiva, como o senhor pode ter notado, e não é facilmente controlada quando decidiu algum ponto. Claro, não me importei tanto com o senhor, já que não tem ligação com a polícia oficial, mas não é agradável ver uma desgraça de família como esta ser alardeada. Além disso, é uma despesa inútil, pois como poderia o senhor possivelmente encontrar esse Hosmer Angel?”","onthecontrarysaidholmesquietlyihaveevery~discoveringmrhosmerangel~97":"“Pelo contrário”, disse Holmes calmamente; “tenho todas as razões para crer que conseguirei descobrir o Sr. Hosmer Angel.”","mrwindibankgaveaviolentstartanddroppedhi~mdelightedtohearithesaid~73":"O Sr. Windibank teve um violento sobressalto e deixou cair as luvas. “Fico encantado em ouvir isso”, disse.","itisacuriousthingremarkedholmesthatatype~utthosearethemoreobvious~384":"“É curioso”, comentou Holmes, “que uma máquina de escrever tenha realmente tanta individualidade quanto a letra de um homem. A menos que sejam novíssimas, não há duas que escrevam exatamente igual. Algumas letras se gastam mais que outras, e algumas só se gastam de um lado. Ora, o senhor observa nesta nota sua, Sr. Windibank, que em todos os casos há um certo borrão no e e um ligeiro defeito na cauda do r. Há catorze outras características, mas essas são as mais óbvias.”","wedoallourcorrespondencewiththismachinea~swithhisbrightlittleeyes~138":"“Fazemos toda a correspondência com esta máquina no escritório, e sem dúvida está um pouco gasta”, respondeu nosso visitante, fitando Holmes atentamente com seus olhinhos brilhantes.","andnowiwillshowyouwhatisreallyaveryinter~avealludedarethereaswell~454":"“E agora mostrarei ao senhor o que é realmente um estudo muito interessante, Sr. Windibank”, continuou Holmes. “Penso em escrever outra monografiazinha um destes dias sobre a máquina de escrever e sua relação com o crime. É um assunto a que dediquei alguma pequena atenção. Tenho aqui quatro cartas que pretendem vir do homem desaparecido. Todas são datilografadas. Em cada caso, não só os e’s estão borrados e os r’s sem cauda, como o senhor observará, se quiser usar minha lente de aumento, que as catorze outras características a que aludi estão presentes também.”","mrwindibanksprangoutofhischairandpickedu~tmeknowwhenyouhavedoneit~160":"O Sr. Windibank saltou da cadeira e apanhou o chapéu. “Não posso perder tempo com essa espécie de conversa fantasiosa, Sr. Holmes”, disse. “Se o senhor consegue apanhar o homem, apanhe-o e avise-me quando o tiver feito.”","certainlysaidholmessteppingoverandturnin~owthenthatihavecaughthim~89":"“Certamente”, disse Holmes, aproximando-se e girando a chave na porta. “Aviso-o, então, de que o apanhei!”","whatwhereshoutedmrwindibankturningwhitet~gabouthimlikearatinatrap~82":"“Quê! Onde?”, gritou o Sr. Windibank, ficando branco até os lábios e olhando em volta como um rato na ratoeira.","ohitwontdoreallyitwontsaidholmessuavelyt~itdownandletustalkitover~224":"“Oh, não adianta, realmente não adianta”, disse Holmes suavemente. “Não há meio possível de escapar, Sr. Windibank. É transparente demais, e foi um péssimo cumprimento o senhor dizer que me era impossível resolver questão tão simples. Assim mesmo! Sente-se e conversemos.”","ourvisitorcollapsedintoachairwithaghastl~notactionablehestammered~104":"Nosso visitante desabou numa cadeira, com o rosto lívido e um brilho de umidade na testa. “Não... não é passível de ação judicial”, gaguejou.","iamverymuchafraidthatitisnotbutbetweenou~llcontradictmeifigowrong~193":"“Receio muitíssimo que não seja. Mas, entre nós, Windibank, foi um truque tão cruel, egoísta e desalmado, em pequena escala, quanto os que já vieram à minha presença. Agora deixe-me repassar o curso dos acontecimentos, e o senhor me contradirá se eu errar.”","themansathuddledupinhischairwithhisheads~imselfasitseemedthantous~212":"O homem ficou encolhido na cadeira, com a cabeça afundada no peito, como quem está inteiramente esmagado. Holmes pôs os pés no canto do console da lareira e, recostando-se com as mãos nos bolsos, começou a falar, mais para si mesmo, ao que parecia, do que para nós.","themanmarriedawomanverymucholderthanhims~oversbymakinglovehimself~1132":"“O homem casou-se com uma mulher muito mais velha que ele pelo dinheiro dela”, disse, “e gozou do uso do dinheiro da filha enquanto ela vivesse com eles. Era uma soma considerável, para gente na posição deles, e a perda dela teria feito séria diferença. Valia um esforço para preservá-la. A filha era de índole boa e amável, mas afetuosa e de coração caloroso em seus modos, de modo que era evidente que, com suas boas vantagens pessoais e sua pequena renda, não lhe seria permitido ficar solteira por muito tempo. Ora, o casamento dela significaria, naturalmente, a perda de cem libras por ano; que faz então o padrasto para impedi-lo? Toma o caminho óbvio de mantê-la em casa e proibi-la de buscar a companhia de pessoas de sua idade. Mas logo descobriu que isso não bastaria para sempre. Ela tornou-se rebelde, insistiu em seus direitos e por fim anunciou sua intenção positiva de ir a certo baile. Que faz então o seu esperto padrasto? Concebe uma ideia mais creditável à sua cabeça do que ao seu coração. Com a conivência e a ajuda da esposa, disfarçou-se, cobriu aqueles olhos agudos com óculos escuros, mascarou o rosto com um bigode e um par de suíças espessas, reduziu aquela voz clara a um sussurro insinuante e, duplamente seguro por causa da vista curta da moça, apresenta-se como o Sr. Hosmer Angel e afasta outros pretendentes fazendo ele próprio a corte.”","itwasonlyajokeatfirstgroanedourvisitorwe~uldhavebeensocarriedaway~85":"“No começo foi só uma brincadeira”, gemeu nosso visitante. “Nunca pensamos que ela se deixaria levar tanto.”","verylikelynothoweverthatmaybetheyounglad~chainofeventsmrwindibank~1224":"“Muito provavelmente não. Seja como for, a jovem dama deixou-se levar decididamente, e, tendo firmado por completo a convicção de que o padrasto estava na França, a suspeita de traição jamais lhe passou pela mente, nem por um instante. Estava lisonjeada com as atenções do cavalheiro, e o efeito foi aumentado pela admiração ruidosamente expressa da mãe. Então o Sr. Angel começou a visitá-la, pois era óbvio que o assunto devia ser levado tão longe quanto fosse possível, para produzir um efeito real. Houve encontros e um noivado, que por fim asseguraria que as afeições da moça não se voltassem para ninguém mais. Mas o engano não podia ser mantido para sempre. Essas pretensas viagens à França eram um tanto incômodas. O que havia a fazer era claramente pôr fim ao negócio de modo tão dramático que deixasse uma impressão permanente na mente da jovem e a impedisse de olhar para qualquer outro pretendente por algum tempo. Daí aqueles votos de fidelidade exigidos sobre um Testamento, e daí também as alusões à possibilidade de algo acontecer na própria manhã do casamento. James Windibank queria que a Srta. Sutherland ficasse tão presa a Hosmer Angel, e tão incerta quanto ao destino dele, que por dez anos, pelo menos, não desse ouvidos a outro homem. Até a porta da igreja ele a trouxe e então, como não podia ir mais longe, desapareceu convenientemente pelo velho truque de entrar por uma porta de um coche de quatro rodas e sair pela outra. Creio que foi essa a cadeia de acontecimentos, Sr. Windibank!”","ourvisitorhadrecoveredsomethingofhisassu~coldsneeruponhispaleface~123":"Nosso visitante recobrara algo de sua segurança enquanto Holmes falava e levantou-se agora da cadeira com um sorriso de escárnio frio no rosto pálido.","itmaybesooritmaynotmrholmessaidhebutifyo~aultandillegalconstraint~254":"“Pode ser que sim, pode ser que não, Sr. Holmes”, disse, “mas, se o senhor é tão perspicaz, devia ser perspicaz o bastante para saber que é o senhor que está infringindo a lei agora, e não eu. Nada fiz de passível de ação desde o início, mas, enquanto mantiver aquela porta trancada, o senhor se expõe a uma ação por agressão e constrangimento ilegal.”","thelawcannotasyousaytouchyousaidholmesun~topofhisspeeddowntheroad~531":"“A lei não pode, como o senhor diz, tocá-lo”, disse Holmes, destrancando e abrindo a porta de par em par, “e no entanto jamais houve homem que merecesse mais um castigo. Se a jovem dama tem um irmão ou um amigo, ele devia lhe passar um chicote pelas costas. Por Júpiter!”, continuou, corando ao ver o amargo escárnio no rosto do homem, “não faz parte dos meus deveres para com a minha cliente, mas aqui está um chicote de caça à mão, e creio que vou me dar o prazer de...” Deu dois passos rápidos até o chicote, mas antes que pudesse agarrá-lo ouviu-se um tropel desordenado na escada, a pesada porta da rua bateu, e da janela vimos o Sr. James Windibank correndo a toda a velocidade pela rua.","theresacoldbloodedscoundrelsaidholmeslau~entirelydevoidofinterest~218":"“Eis um canalha de sangue-frio!”, disse Holmes, rindo, enquanto se atirava na poltrona mais uma vez. “Esse sujeito subirá de crime em crime até fazer algo muito ruim e acabar numa forca. O caso, em alguns aspectos, não foi inteiramente desprovido de interesse.”","icannotnowentirelyseeallthestepsofyourre~ofyourreasoningiremarked~56":"“Não consigo agora ver inteiramente todos os passos do seu raciocínio”, observei.","wellofcourseitwasobviousfromthefirstthat~ointedinthesamedirection~643":"“Bem, claro que era óbvio desde o início que esse Sr. Hosmer Angel devia ter algum forte objetivo para sua curiosa conduta, e era igualmente claro que o único homem que realmente lucrava com o incidente, até onde podíamos ver, era o padrasto. Depois, o fato de os dois homens nunca estarem juntos, mas de um aparecer sempre que o outro estava ausente, era sugestivo. Assim também os óculos escuros e a voz curiosa, que ambos insinuavam um disfarce, como o faziam as suíças espessas. Todas as minhas suspeitas foram confirmadas pela peculiar ação de datilografar a assinatura, o que, naturalmente, implicava que a letra dele era tão familiar a ela que reconheceria até a menor amostra. O senhor vê que todos esses fatos isolados, juntamente com muitos menores, apontavam na mesma direção.”","andhowdidyouverifythem~andhowdidyouverifythem~22":"“E como os verificou?”","havingoncespottedmymanitwaseasytogetcorr~ejameswindibankvoilatout~664":"“Uma vez localizado meu homem, foi fácil obter corroboração. Eu conhecia a firma para a qual esse homem trabalhava. Tomei a descrição impressa, eliminei dela tudo o que pudesse ser resultado de um disfarce, as suíças, os óculos, a voz, e enviei-a à firma, com o pedido de que me informassem se correspondia à descrição de algum de seus viajantes. Eu já notara as peculiaridades da máquina de escrever e escrevi ao próprio homem, no endereço comercial, perguntando se poderia vir aqui. Como esperava, a resposta dele foi datilografada e revelava os mesmos defeitos triviais, mas característicos. O mesmo correio trouxe-me uma carta da Westhouse & Marbank, da Fenchurch Street, dizendo que a descrição coincidia em todos os aspectos com a de seu empregado, James Windibank. Voilà tout!”","andmisssutherland~andmisssutherland~17":"“E a Srta. Sutherland?”","ifitellhershewillnotbelievemeyoumayremem~smuchknowledgeoftheworld~212":"“Se eu lhe contar, ela não acreditará em mim. O senhor talvez se lembre do velho provérbio persa: ‘Há perigo para quem toma o filhote de tigre, e há perigo também para quem arranca uma ilusão a uma mulher.’ Há tanto bom senso em Hafiz quanto em Horácio, e tanto conhecimento do mundo.”"}$tr$::jsonb, 608)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- arthur-conan-doyle_the-hound-of-the-baskervilles (244 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('arthur-conan-doyle_the-hound-of-the-baskervilles', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"mrsherlockholmes":"O Sr. Sherlock Holmes","thecurseofthebaskervilles":"A Maldição dos Baskerville","theproblem":"O Problema"}$tr$::jsonb, $tr${"mrsherlockholmeswhowasusuallyverylateint~nifiedsolidandreassuring~511":"O Sr. Sherlock Holmes, que costumava levantar-se muito tarde, exceto nas ocasiões nada raras em que passava a noite inteira em claro, estava sentado à mesa do desjejum. Eu, de pé diante da lareira, apanhei a bengala que nosso visitante deixara para trás na noite anterior. Era uma bela peça de madeira grossa, de cabo bulboso, do tipo conhecido como “Penang lawyer”. Logo abaixo do cabo havia uma larga faixa de prata, de quase uma polegada. “A James Mortimer, M.R.C.S., de seus amigos do C.C.H.”, estava gravado nela, com a data “1884”. Era exatamente o tipo de bengala que o velho médico de família costumava carregar: digna, sólida e tranquilizadora.","wellwatsonwhatdoyoumakeofit~lwatsonwhatdoyoumakeofit~27":"— Pois bem, Watson, o que o senhor deduz dela?","holmeswassittingwithhisbacktomeandihadgi~nhimnosignofmyoccupation~66":"Holmes estava sentado de costas para mim, e eu não lhe dera nenhum sinal da minha ocupação.","howdidyouknowwhatiwasdoingibelieveyouhav~eeyesinthebackofyourhead~64":"— Como soube o que eu estava fazendo? Creio que o senhor tem olhos na nuca.","ihaveatleastawellpolishedsilverplatedcof~hemanbyanexaminationofit~263":"— Tenho, pelo menos, uma cafeteira de prata bem polida bem à minha frente — disse ele. — Mas diga-me, Watson, o que deduz da bengala do nosso visitante? Já que tivemos o azar de não encontrá-lo e não fazemos ideia do que o trazia aqui, esta lembrança acidental ganha importância. Deixe-me ouvi-lo reconstruir o homem pelo exame dela.","ithinksaidifollowingasfarasicouldthemeth~smarkoftheirappreciation~166":"— Penso — disse eu, seguindo o mais fielmente que pude o método de meu companheiro — que o Dr. Mortimer é um médico bem-sucedido, de certa idade, e estimado, já que aqueles que o conhecem lhe dão esta prova de apreço.","goodsaidholmesexcellent~goodsaidholmesexcellent~23":"— Bom! — disse Holmes. — Excelente!","ithinkalsothattheprobabilityisinfavourof~tdealofhisvisitingonfoot~104":"— Penso também que é provável que seja um médico do campo, que faz grande parte de suas visitas a pé.","whyso~whyso~5":"— Por quê?","becausethisstickthoughoriginallyaveryhan~eatamountofwalkingwithit~199":"— Porque esta bengala, embora originalmente muito bonita, está tão maltratada que mal posso imaginar um médico da cidade carregando-a. A grossa ponteira de ferro está gasta, de modo que é evidente que ele caminhou muitíssimo com ela.","perfectlysoundsaidholmes~perfectlysoundsaidholmes~24":"— Perfeitamente correto! — disse Holmes.","andthenagainthereisthefriendsofthecchish~mallpresentationinreturn~183":"— E há ainda os “amigos do C.C.H.”. Suponho que seja o Clube de Caça de Tal Lugar, a caça local, a cujos membros ele talvez tenha prestado algum auxílio cirúrgico, e que lhe fez em troca um pequeno presente.","reallywatsonyouexcelyourselfsaidholmespu~hatiamverymuchinyourdebt~383":"— Realmente, Watson, o senhor se supera — disse Holmes, empurrando a cadeira para trás e acendendo um cigarro. — Sou obrigado a dizer que, em todos os relatos que o senhor teve a bondade de fazer de minhas modestas realizações, habitualmente subestimou suas próprias capacidades. Pode ser que o senhor mesmo não seja luminoso, mas é um condutor de luz. Algumas pessoas, sem possuir o gênio, têm um poder notável de estimulá-lo. Confesso, meu caro amigo, que estou em grande dívida com o senhor.","hehadneversaidasmuchbeforeandimustadmitt~eritagainwithaconvexlens~452":"Ele nunca dissera tanto antes, e devo admitir que suas palavras me deram um prazer intenso, pois eu muitas vezes me ressentira da indiferença dele diante de minha admiração e das tentativas que eu fizera de dar publicidade a seus métodos. Eu também me orgulhava de pensar que dominara seu sistema a ponto de aplicá-lo de um modo que lhe merecia a aprovação. Ele tomou então a bengala de minhas mãos e a examinou por alguns minutos a olho nu. Depois, com uma expressão de interesse, pousou o cigarro e, levando a bengala até a janela, voltou a examiná-la com uma lente convexa.","interestingthoughelementarysaidheasheret~asisforseveraldeductions~161":"— Interessante, ainda que elementar — disse ele, ao voltar para o seu canto favorito do sofá. — Há certamente um ou dois indícios na bengala. Ela nos dá base para várias deduções.","hasanythingescapedmeiaskedwithsomeselfim~encewhichihaveoverlooked~105":"— Algo me escapou? — perguntei, com certa presunção. — Espero que não haja nada de importante que eu tenha deixado passar.","iamafraidmydearwatsonthatmostofyourconcl~ionerandhewalksagooddeal~260":"— Receio, meu caro Watson, que a maior parte de suas conclusões era errônea. Quando disse que o senhor me estimulava, queria dizer, para ser franco, que, ao notar as suas falácias, eu era por vezes conduzido à verdade. Não que o senhor esteja inteiramente equivocado neste caso. O homem é certamente um médico do campo. E caminha bastante.","theniwasright~theniwasright~13":"“Então eu estava certo.”","tothatextent~tothatextent~12":"“Até esse ponto.”","butthatwasall~butthatwasall~13":"“Mas isso foi tudo.”","nonomydearwatsonnotallbynomeansalliwould~turallysuggestthemselves~228":"“Não, não, meu caro Watson, nem tudo, de modo algum. Eu sugeriria, por exemplo, que um presente a um médico tem mais probabilidade de vir de um hospital do que de uma caçada, e que, quando as iniciais ‘C.C.’ são postas antes desse hospital, as palavras ‘Charing Cross’ se sugerem muito naturalmente.”","youmayberight~youmayberight~13":"“O senhor pode ter razão.”","theprobabilityliesinthatdirectionandifwe~tionofthisunknownvisitor~136":"“A probabilidade está nessa direção. E se tomarmos isto como hipótese de trabalho, temos uma base nova a partir da qual começar a construir esse visitante desconhecido.”","wellthensupposingthatcchdoesstandforchar~rtherinferencesmaywedraw~86":"“Bem, então, supondo que ‘C.C.H.’ signifique de fato ‘Charing Cross Hospital’, que outras inferências podemos tirar?”","dononesuggestthemselvesyouknowmymethodsa~ouknowmymethodsapplythem~48":"“Nenhuma se sugere por si? O senhor conhece meus métodos. Aplique-os!”","icanonlythinkoftheobviousconclusionthatt~nbeforegoingtothecountry~86":"“Só consigo pensar na conclusão óbvia de que o homem clinicou na cidade antes de ir para o campo.”","ithinkthatwemightventurealittlefartherth~ontheoccasionofthechange~470":"“Creio que podemos aventurar-nos um pouco além disso. Veja por esta luz. Em que ocasião seria mais provável que tal presente fosse feito? Quando seus amigos se uniriam para lhe dar um penhor de sua boa vontade? Obviamente no momento em que o Dr. Mortimer se afastou do serviço do hospital para estabelecer clínica própria. Sabemos que houve um presente. Acreditamos que houve uma mudança de um hospital urbano para uma clínica rural. Será, então, esticar demais nossa inferência dizer que o presente foi dado por ocasião da mudança?”","itcertainlyseemsprobable~itcertainlyseemsprobable~24":"“Certamente parece provável.”","nowyouwillobservethathecouldnothavebeeno~erandsmallerthanamastiff~578":"“Ora, o senhor observará que ele não poderia ter pertencido ao corpo clínico do hospital, pois somente um homem bem estabelecido na clínica de Londres poderia ocupar tal posição, e um homem assim não iria parar no campo. O que era ele, então? Se estava no hospital e contudo não pertencia ao corpo clínico, só poderia ter sido cirurgião residente ou médico residente, pouco mais que um estudante adiantado. E partiu há cinco anos; a data está na bengala. Assim, seu grave clínico de família, de meia-idade, desvanece no ar, meu caro Watson, e emerge um rapaz de menos de trinta anos, amável, sem ambição, distraído, e dono de um cão favorito, que eu descreveria grosso modo como maior que um terrier e menor que um mastim.”","ilaughedincredulouslyassherlockholmeslea~ngsofsmokeuptotheceiling~105":"Ri com incredulidade enquanto Sherlock Holmes se recostava no canapé e soprava para o teto pequenos anéis oscilantes de fumaça.","astothelatterpartihavenomeansofcheckingy~sitorireadhisrecordaloud~276":"“Quanto à última parte, não tenho meios de verificar”, disse eu, “mas pelo menos não é difícil descobrir alguns pormenores sobre a idade do homem e sua carreira profissional.” Da minha pequena estante médica tirei o Anuário Médico e procurei o nome. Havia vários Mortimer, mas apenas um que poderia ser o nosso visitante. Li seu registro em voz alta.","mortimerjamesmrcs1882grimpendartmoordevo~penthorsleyandhighbarrow~356":"“Mortimer, James, M.R.C.S., 1882, Grimpen, Dartmoor, Devon. Cirurgião residente, de 1882 a 1884, no Charing Cross Hospital. Vencedor do prêmio Jackson de Patologia Comparada, com ensaio intitulado ‘A Doença é uma Reversão?’ Membro correspondente da Sociedade Sueca de Patologia. Autor de ‘Algumas Extravagâncias do Atavismo’ (Lancet, 1882). ‘Progredimos?’ (Journal of Psychology, março de 1883). Médico oficial das paróquias de Grimpen, Thorsley e High Barrow.”","nomentionofthatlocalhuntwatsonsaidholmes~rwaitinganhourinyourroom~437":"“Nenhuma menção àquela caçada local, Watson”, disse Holmes com um sorriso travesso, “mas um médico do campo, como o senhor observou muito argutamente. Creio estar razoavelmente justificado em minhas inferências. Quanto aos adjetivos, disse, se bem me lembro, amável, sem ambição e distraído. É minha experiência que neste mundo só um homem amável recebe testemunhos de apreço, só um sem ambição abandona uma carreira em Londres pelo campo, e só um distraído deixa a bengala, e não o cartão de visita, depois de esperar uma hora em sua sala.”","andthedog~andthedog~9":"“E o cão?”","hasbeeninthehabitofcarryingthisstickbehi~eitisacurlyhairedspaniel~291":"“Tem o hábito de carregar esta bengala atrás do dono. Sendo uma bengala pesada, o cão a segurou firmemente pelo meio, e as marcas de seus dentes são muito claramente visíveis. A mandíbula do cão, como mostra o espaço entre essas marcas, é, em minha opinião, larga demais para um terrier e não larga o bastante para um mastim. Pode ter sido... sim, por Júpiter, é um spaniel de pelo encaracolado.”","hehadrisenandpacedtheroomashespokenowheh~thatiglancedupinsurprise~130":"Levantara-se e andava pela sala enquanto falava. Agora parou no vão da janela. Havia tal tom de convicção em sua voz que ergui os olhos, surpreso.","mydearfellowhowcanyoupossiblybesosureoft~oupossiblybesosureofthat~43":"“Meu caro amigo, como pode estar tão seguro disso?”","fortheverysimplereasonthatiseethedoghims~especialistincrimecomein~378":"“Pela razão muito simples de que vejo o próprio cão na nossa soleira, e ali está a campainha do dono. Não se mova, peço-lhe, Watson. Ele é um colega de profissão seu, e sua presença pode ser-me útil. É agora o momento dramático do destino, Watson, em que se ouve na escada um passo que está entrando em nossa vida, sem sabermos se para o bem ou para o mal. Que pede o Dr. James Mortimer, o homem da ciência, a Sherlock Holmes, o especialista em crime? Entre!”","theappearanceofourvisitorwasasurprisetom~losethatstickfortheworld~627":"A aparência de nosso visitante foi uma surpresa para mim, pois eu esperara um típico clínico do campo. Era um homem muito alto e magro, de nariz longo como um bico, que se projetava entre dois olhos cinzentos e aguçados, muito juntos e brilhando vivamente por trás de um par de óculos de aro de ouro. Vestia-se de modo profissional, mas bastante desleixado, pois a sobrecasaca era desbotada e as calças, puídas. Embora jovem, a longa espinha já estava curvada, e ele andava com a cabeça projetada para a frente e um ar geral de benevolência perscrutadora. Ao entrar, seus olhos caíram sobre a bengala na mão de Holmes, e ele correu para ela com uma exclamação de alegria. “Fico muitíssimo contente”, disse. “Não tinha certeza se a deixara aqui ou no Escritório de Navegação. Não perderia essa bengala por nada deste mundo.”","apresentationiseesaidholmes~esentationiseesaidholmes~27":"“Um presente, vejo”, disse Holmes.","yessir~yessir~6":"“Sim, senhor.”","fromcharingcrosshospital~fromcharingcrosshospital~24":"“Do Charing Cross Hospital?”","fromoneortwofriendsthereontheoccasionofm~ntheoccasionofmymarriage~49":"“De um ou dois amigos de lá, por ocasião do meu casamento.”","deardearthatsbadsaidholmesshakinghishead~saidholmesshakinghishead~40":"“Ora, ora, isso é ruim!”, disse Holmes, balançando a cabeça.","drmortimerblinkedthroughhisglassesinmild~dastonishmentwhywasitbad~63":"O Dr. Mortimer piscou através dos óculos em branda surpresa. “Por que é ruim?”","onlythatyouhavedisarrangedourlittlededuc~ctionsyourmarriageyousay~63":"“Apenas porque o senhor desarranjou nossas pequenas deduções. O seu casamento, diz?”","yessirimarriedandsoleftthehospitalandwit~essarytomakeahomeofmyown~104":"“Sim, senhor. Casei-me e assim deixei o hospital, e com ele todas as esperanças de uma clínica de consultas. Era necessário fazer um lar próprio.”","comecomewearenotsofarwrongafterallsaidho~mesandnowdrjamesmortimer~65":"“Vamos, vamos, não estávamos tão errados, afinal”, disse Holmes. “E agora, Dr. James Mortimer...”","mistersirmisterahumblemrcs~stersirmisterahumblemrcs~26":"“Senhor, apenas senhor, senhor... um humilde M.R.C.S.”","andamanofprecisemindevidently~anofprecisemindevidently~29":"“E um homem de espírito preciso, evidentemente.”","adabblerinsciencemrholmesapickerupofshel~swhomiamaddressingandnot~130":"“Um diletante da ciência, Sr. Holmes, um colhedor de conchas nas praias do grande oceano desconhecido. Presumo que é ao Sr. Sherlock Holmes que me dirijo, e não a...”","nothisismyfrienddrwatson~nothisismyfrienddrwatson~24":"“Não, este é meu amigo, o Dr. Watson.”","gladtomeetyousirihaveheardyournamementio~nfessthaticovetyourskull~399":"“Prazer em conhecê-lo, senhor. Ouvi seu nome mencionado em ligação com o de seu amigo. O senhor me interessa muitíssimo, Sr. Holmes. Eu mal esperava um crânio tão dolicocéfalo ou um desenvolvimento supraorbital tão marcado. Teria alguma objeção a que eu passasse o dedo ao longo de sua fissura parietal? Um molde do seu crânio, senhor, até que o original esteja disponível, seria um ornamento para qualquer museu antropológico. Não é minha intenção ser adulador, mas confesso que cobiço o seu crânio.”","sherlockholmeswavedourstrangevisitorinto~ohesitationinlightingone~195":"Sherlock Holmes indicou uma cadeira ao nosso estranho visitante. “O senhor é um entusiasta em sua linha de pensamento, percebo, senhor, como eu o sou na minha”, disse. “Observo pelo seu indicador que o senhor mesmo faz seus cigarros. Não hesite em acender um.”","themandrewoutpaperandtobaccoandtwirledth~sastheantennaeofaninsect~145":"O homem tirou papel e tabaco e enrolou um no outro com surpreendente destreza. Tinha dedos longos e trêmulos, tão ágeis e inquietos quanto as antenas de um inseto.","holmeswassilentbuthislittledartingglance~relastnightandagaintoday~222":"Holmes ficou calado, mas seus pequenos olhares fulgurantes mostraram-me o interesse que tomava por nosso curioso companheiro. “Presumo, senhor”, disse por fim, “que não foi meramente com o propósito de examinar meu crânio que o senhor me fez a honra de visitar-me ontem à noite e de novo hoje?”","nosirnothoughiamhappytohavehadtheopportu~ondhighestexpertineurope~252":"“Não, senhor, não; embora eu esteja feliz por ter tido a oportunidade de fazer isso também. Vim ao senhor, Sr. Holmes, porque reconheci que sou eu mesmo um homem pouco prático e porque me vejo subitamente diante de um problema seriíssimo e extraordinário. Reconhecendo, como reconheço, que o senhor é o segundo maior perito da Europa...”","indeedsirmayiinquirewhohasthehonourtobet~edholmeswithsomeasperity~74":"“Realmente, senhor! Posso perguntar quem tem a honra de ser o primeiro?”, perguntou Holmes com certa aspereza.","tothemanofpreciselyscientificmindthework~mustalwaysappealstrongly~83":"“Ao homem de espírito rigorosamente científico, o trabalho de Monsieur Bertillon deve sempre atrair fortemente.”","thenhadyounotbetterconsulthim~adyounotbetterconsulthim~29":"“Então não seria melhor consultá-lo?”","isaidsirtothepreciselyscientificmindbuta~hatihavenotinadvertently~130":"“Disse, senhor, ao espírito rigorosamente científico. Mas como homem prático de negócios, é reconhecido que o senhor está sozinho. Espero, senhor, não ter inadvertidamente...”","justalittlesaidholmesithinkdrmortimeryou~ichyoudemandmyassistance~156":"“Só um pouco”, disse Holmes. “Creio, Dr. Mortimer, que o senhor agiria sabiamente se, sem mais rodeios, tivesse a bondade de me dizer claramente qual é a natureza exata do problema em que solicita minha assistência.”","ihaveinmypocketamanuscriptsaiddrjamesmor~criptsaiddrjamesmortimer~45":"— Trago no bolso um manuscrito — disse o Dr. James Mortimer.","iobserveditasyouenteredtheroomsaidholmes~enteredtheroomsaidholmes~40":"— Reparei nele assim que o senhor entrou na sala — disse Holmes.","itisanoldmanuscript~itisanoldmanuscript~19":"— É um manuscrito antigo.","earlyeighteenthcenturyunlessitisaforgery~enturyunlessitisaforgery~40":"— Do início do século XVIII, a menos que seja uma falsificação.","howcanyousaythatsir~howcanyousaythatsir~19":"— Como pode dizer isso, senhor?","youhavepresentedaninchortwoofittomyexami~thesubjectiputthatat1730~215":"— O senhor tem me exibido uns cinco ou dez centímetros dele durante todo o tempo em que fala. Seria um perito bem medíocre aquele que não soubesse datar um documento com margem de uma década, mais ou menos. Talvez o senhor tenha lido a minha pequena monografia sobre o assunto. Eu o situo em 1730.","theexactdateis1742drmortimerdrewitfromhi~dideventuallyovertakehim~413":"— A data exata é 1742. — O Dr. Mortimer tirou-o do bolso do peito. — Este papel de família foi confiado aos meus cuidados por Sir Charles Baskerville, cuja morte súbita e trágica, há cerca de três meses, causou tanta comoção em Devonshire. Posso dizer que eu era seu amigo pessoal, além de seu médico. Era um homem de mente forte, senhor, arguto, prático e tão desprovido de imaginação quanto eu mesmo. Contudo, levava este documento muito a sério, e seu espírito estava preparado para um fim exatamente como o que acabou por alcançá-lo.","holmesstretchedouthishandforthemanuscrip~ichenabledmetofixthedate~177":"Holmes estendeu a mão para o manuscrito e alisou-o sobre o joelho. — Observe, Watson, o emprego alternado do s longo e do curto. É um dos vários indícios que me permitiram fixar a data.","ilookedoverhisshoulderattheyellowpaperan~argescrawlingfigures1742~124":"Olhei por cima do ombro dele para o papel amarelado e a escrita desbotada. No alto estava escrito: “Baskerville Hall”, e abaixo, em grandes algarismos garranchosos: “1742”.","itappearstobeastatementofsomesort~tobeastatementofsomesort~33":"— Parece ser uma espécie de relato.","yesitisastatementofacertainlegendwhichru~nsinthebaskervillefamily~64":"— Sim, é o relato de uma certa lenda que corre na família Baskerville.","butiunderstandthatitissomethingmoremoder~nwhichyouwishtoconsultme~80":"— Mas pelo que entendi, o assunto sobre o qual deseja me consultar é algo mais moderno e prático, não?","mostmodernamostpracticalpressingmatterwh~rmissioniwillreadittoyou~171":"— Modernissimo. Um assunto muito prático e urgente, que deve ser decidido dentro de vinte e quatro horas. Mas o manuscrito é curto e está intimamente ligado ao caso. Com a sua permissão, vou lê-lo para o senhor.","holmesleanedbackinhischairplacedhisfinge~curiousoldworldnarrative~193":"Holmes recostou-se na poltrona, juntou as pontas dos dedos e fechou os olhos, com ar de resignação. O Dr. Mortimer voltou o manuscrito para a luz e leu, numa voz aguda e rachada, a seguinte curiosa narrativa de outros tempos:","oftheoriginofthehoundofthebaskervillesth~gainbeloosedtoourundoing~547":"“Sobre a origem do Cão dos Baskerville muito se tem dito; contudo, como descendo em linha direta de Hugo Baskerville, e como ouvi a história de meu pai, que a ouvira do seu, pus-me a registrá-la na plena crença de que se passou tal como aqui é relatada. E quero que acrediteis, meus filhos, que a mesma Justiça que pune o pecado pode também perdoá-lo com a maior graça, e que nenhuma interdição é tão pesada que não possa ser removida pela prece e pelo arrependimento. Aprendei, pois, com esta história a não temer os frutos do passado, mas antes a ser circunspectos no futuro, para que aquelas torpes paixões, por cujo efeito nossa família tão gravemente sofreu, não sejam de novo soltas para nossa perdição.","knowthenthatinthetimeofthegreatrebellion~thehallandherfathersfarm~1368":"“Sabei, então, que no tempo da Grande Rebelião (cuja história, escrita pelo douto Lorde Clarendon, vos recomendo com todo o empenho à atenção) este Solar de Baskerville era possuído por Hugo, desse nome, e não se pode negar que fosse homem dos mais desregrados, blasfemos e ímpios. Isso, em verdade, seus vizinhos poderiam perdoar-lhe, visto que santos nunca floresceram por aquelas bandas; mas havia nele um certo humor devasso e cruel que fez de seu nome um escárnio por todo o Oeste. Sucedeu que esse Hugo veio a amar (se é que paixão tão sombria pode ser conhecida sob nome tão luminoso) a filha de um pequeno proprietário que tinha terras próximas à propriedade dos Baskerville. Mas a jovem donzela, sendo discreta e de boa reputação, sempre o evitava, pois temia-lhe o mau nome. Assim aconteceu que, num dia de São Miguel, esse Hugo, com cinco ou seis de seus ociosos e perversos companheiros, desceu sorrateiro sobre a granja e levou a donzela, estando o pai e os irmãos dela fora de casa, como ele bem sabia. Quando a trouxeram ao Solar, a donzela foi posta num aposento do andar de cima, enquanto Hugo e os amigos se sentavam a uma longa bebedeira, como era seu costume todas as noites. Ora, a pobre moça lá em cima esteve a ponto de perder o juízo com o canto, os gritos e os terríveis juramentos que lhe subiam de baixo, pois dizem que as palavras usadas por Hugo Baskerville, quando em vinho, eram tais que poderiam fulminar o homem que as proferisse. Por fim, no auge do medo, ela fez o que teria intimidado o homem mais bravo ou mais ágil, pois, com o auxílio da hera que cobria (e ainda cobre) a parede sul, desceu de debaixo dos beirais e assim tomou o rumo de casa através da charneca, havendo três léguas entre o Solar e a granja de seu pai.","itchancedthatsomelittletimelaterhugoleft~nthemoonlightoverthemoor~732":"“Sucedeu que, algum tempo depois, Hugo deixou os convivas para levar comida e bebida — e talvez outras coisas piores — à sua cativa, e achou assim a gaiola vazia e o pássaro fugido. Então, ao que parece, ficou como quem tem o demônio no corpo, pois, precipitando-se escada abaixo para o salão de jantar, saltou sobre a grande mesa, com jarros e travessas voando diante dele, e bradou diante de toda a companhia que naquela mesma noite entregaria corpo e alma aos Poderes do Mal, se ao menos pudesse alcançar a rapariga. E enquanto os foliões se quedavam atônitos diante da fúria do homem, um deles, mais perverso ou, quem sabe, mais embriagado que os demais, gritou que lançassem os cães atrás dela. Ao que Hugo correu para fora da casa, gritando aos seus cavalariços que selassem sua égua e soltassem a matilha, e, dando aos cães um lenço da donzela, atiçou-os à pista e partiu a toda, com a matilha em plena grita, sob o luar, pela charneca.","nowforsomespacetherevellersstoodagapeuna~sheweretoreachherownhome~496":"“Ora, por algum tempo os foliões ficaram de boca aberta, incapazes de compreender tudo o que fora feito com tanta pressa. Mas logo seus espíritos enevoados despertaram para a natureza do ato que ameaçava consumar-se nas charnecas. Tudo era agora tumulto: uns pediam suas pistolas, outros seus cavalos, e outros mais outro frasco de vinho. Por fim, porém, algum juízo voltou àquelas mentes desvairadas, e todos eles, em número de treze, montaram a cavalo e partiram em perseguição. A lua brilhava clara sobre eles, e cavalgavam velozes, lado a lado, tomando o caminho que a donzela por força teria tomado para alcançar a própria casa.","theyhadgoneamileortwowhentheypassedoneof~bidshouldeverbeatmyheels~397":"“Tinham percorrido uma milha ou duas quando passaram por um dos pastores da noite na charneca, e gritaram-lhe perguntando se tinha visto a caçada. E o homem, segundo conta a história, estava tão louco de medo que mal conseguia falar, mas por fim disse que vira, sim, a infeliz donzela, com os cães em seu rastro. ‘Mas vi mais do que isso’, disse ele, ‘pois Hugo Baskerville passou por mim em sua égua negra, e corria mudo atrás dele um tal cão do inferno que Deus não permita jamais que esteja em meus calcanhares.’","sothedrunkensquirescursedtheshepherdandr~henarrowvalleybeforethem~601":"“Os fidalgos bêbados, então, amaldiçoaram o pastor e seguiram adiante. Mas logo sua pele gelou, pois ouviu-se um galope pela charneca, e a égua negra, salpicada de espuma branca, passou com as rédeas arrastando e a sela vazia. Então os foliões cavalgaram bem juntos, pois grande medo havia caído sobre eles, mas ainda assim continuaram a seguir pela charneca, ainda que cada um, estivesse só, de bom grado tivesse virado a cabeça do cavalo. Cavalgando devagar dessa maneira, chegaram por fim aos cães. Estes, embora conhecidos por seu valor e sua raça, gemiam encolhidos num grupo à beira de uma funda depressão, ou ‘goyal’, como a chamamos, na charneca; uns esgueiravam-se para longe e outros, de pelos eriçados e olhos arregalados, fitavam o estreito vale diante de si.","thecompanyhadcometoahaltmoresobermenasyo~menfortherestoftheirdays~987":"“A companhia havia parado, composta de homens mais sóbrios, como podeis imaginar, do que quando partira. A maior parte deles recusou-se terminantemente a avançar, mas três, os mais ousados ou, talvez, os mais embriagados, desceram a cavalo pelo goyal. Ora, este se abria num amplo espaço onde se erguiam duas daquelas grandes pedras, ainda hoje ali vistas, colocadas por certos povos esquecidos nos dias de outrora. A lua brilhava forte sobre a clareira, e ali no centro jazia a infeliz donzela onde havia caído, morta de medo e de fadiga. Mas não foi a visão de seu corpo, nem tampouco a do corpo de Hugo Baskerville estendido junto dela, que arrepiou os cabelos daqueles três temerários arruaceiros, e sim o que estava de pé sobre Hugo, a lhe dilacerar a garganta: uma coisa imunda, uma grande besta negra, com forma de cão, porém maior do que qualquer cão que olhos mortais já tenham visto. E enquanto ainda olhavam, a coisa arrancou a garganta de Hugo Baskerville, e, ao voltar contra eles os olhos flamejantes e as mandíbulas gotejantes, os três soltaram gritos de pavor e fugiram a toda brida, ainda berrando, pela charneca. Um deles, dizem, morreu naquela mesma noite do que vira, e os outros dois ficaram apenas homens arruinados pelo resto de seus dias.","suchisthetalemysonsofthecomingofthehound~hepowersofevilareexalted~585":"“Tal é a história, meus filhos, da vinda do cão que dizem ter atormentado tão duramente a família desde então. Se a registrei, é porque aquilo que se conhece claramente tem menos terror do que aquilo que apenas se insinua e se conjectura. Nem se pode negar que muitos da família tiveram mortes infelizes, súbitas, sangrentas e misteriosas. Contudo, podemos abrigar-nos na infinita bondade da Providência, que não castigaria para sempre o inocente além daquela terceira ou quarta geração de que fala a Sagrada Escritura. A essa Providência, meus filhos, eu vos encomendo, e aconselho-vos, a título de precaução, que vos abstenhais de atravessar a charneca naquelas horas escuras em que os poderes do mal estão exaltados.","thisfromhugobaskervilletohissonsrodgeran~oftotheirsisterelizabeth~108":"“[Isto de Hugo Baskerville a seus filhos Rodger e John, com instruções de que nada digam a respeito a sua irmã Elizabeth.]”","whendrmortimerhadfinishedreadingthissing~fhiscigaretteintothefire~177":"Quando o Dr. Mortimer terminou de ler essa singular narrativa, empurrou os óculos para a testa e encarou o Sr. Sherlock Holmes. Este bocejou e atirou a ponta do cigarro no fogo.","wellsaidhe~wellsaidhe~10":"— E então? — disse ele.","doyounotfinditinteresting~oyounotfinditinteresting~25":"— O senhor não a acha interessante?","toacollectoroffairytales~toacollectoroffairytales~24":"— Para um colecionador de contos de fadas.","drmortimerdrewafoldednewspaperoutofhispo~dnewspaperoutofhispocket~44":"O Dr. Mortimer tirou do bolso um jornal dobrado.","nowmrholmeswewillgiveyousomethingalittle~edafewdaysbeforethatdate~201":"— Agora, Sr. Holmes, vamos lhe dar algo um pouco mais recente. Este é o Devon County Chronicle de 14 de maio deste ano. É um breve relato dos fatos apurados por ocasião da morte de Sir Charles Baskerville, ocorrida poucos dias antes dessa data.","myfriendleanedalittleforwardandhisexpres~justedhisglassesandbegan~94":"Meu amigo inclinou-se um pouco para a frente e sua expressão tornou-se atenta. Nosso visitante reajustou os óculos e começou:","therecentsuddendeathofsircharlesbaskervi~chronicledinthesecolumns~1121":"“A recente morte súbita de Sir Charles Baskerville, cujo nome fora mencionado como provável candidato liberal por Mid-Devon nas próximas eleições, lançou um manto de tristeza sobre o condado. Embora Sir Charles residisse em Baskerville Hall por um período comparativamente curto, a amabilidade de seu caráter e a extrema generosidade haviam-lhe granjeado a afeição e o respeito de todos os que tiveram contato com ele. Nestes dias de novos-ricos, é reconfortante encontrar um caso em que o rebento de uma velha família do condado, decaída em tempos difíceis, consegue fazer fortuna por si mesmo e trazê-la consigo para restaurar a grandeza perdida de sua linhagem. Sir Charles, como é sabido, ganhou grandes somas em especulações sul-africanas. Mais sensato que aqueles que prosseguem até que a roda se volte contra eles, realizou seus lucros e voltou à Inglaterra com eles. Faz apenas dois anos que fixou residência em Baskerville Hall, e é assunto corrente quão vastos eram os planos de reconstrução e melhoramento que sua morte interrompeu. Não tendo filhos, era seu desejo abertamente expresso que toda a região, ainda em vida dele, se beneficiasse de sua boa sorte, e muitos terão razões pessoais para lamentar seu fim prematuro. Suas generosas doações a obras de caridade locais e do condado têm sido frequentemente registradas nestas colunas.","thecircumstancesconnectedwiththedeathofs~nevidencetothesameeffect~861":"“Não se pode dizer que as circunstâncias ligadas à morte de Sir Charles tenham sido inteiramente esclarecidas pelo inquérito, mas ao menos fez-se o bastante para dissipar os boatos a que a superstição local deu origem. Não há razão alguma para suspeitar de crime, nem para imaginar que a morte pudesse advir de outras causas que não naturais. Sir Charles era viúvo e homem que se pode dizer ter sido, em certos aspectos, de espírito excêntrico. Apesar de sua considerável riqueza, tinha gostos pessoais simples, e a criadagem doméstica de Baskerville Hall consistia num casal de sobrenome Barrymore, o marido servindo de mordomo e a mulher de governanta. O testemunho deles, corroborado pelo de vários amigos, tende a mostrar que a saúde de Sir Charles estava havia algum tempo abalada, e aponta em especial para alguma afecção cardíaca, manifestada em mudanças de cor, falta de ar e agudos acessos de depressão nervosa. O Dr. James Mortimer, amigo e médico do falecido, prestou depoimento no mesmo sentido.","thefactsofthecasearesimplesircharlesbask~rminghimofhisgoodfortune~2169":"“Os fatos do caso são simples. Sir Charles Baskerville tinha o hábito, toda noite antes de deitar-se, de caminhar pela famosa alameda de teixos de Baskerville Hall. O depoimento dos Barrymore mostra que esse era o seu costume. No dia quatro de maio, Sir Charles declarara sua intenção de partir no dia seguinte para Londres e ordenara a Barrymore que preparasse a sua bagagem. Naquela noite saiu como de costume para o passeio noturno, durante o qual tinha o hábito de fumar um charuto. Nunca mais voltou. À meia-noite, Barrymore, encontrando ainda aberta a porta do vestíbulo, alarmou-se e, acendendo uma lanterna, saiu em busca do patrão. O dia fora úmido, e as pegadas de Sir Charles foram facilmente seguidas pela alameda. A meio caminho desse passeio há um portão que dá para a charneca. Havia indícios de que Sir Charles se detivera ali por algum tempo. Depois prosseguira alameda abaixo, e foi na extremidade dela que seu corpo foi encontrado. Um fato que não foi explicado é a declaração de Barrymore de que as pegadas do patrão mudavam de caráter a partir do momento em que passou o portão da charneca, e que dali em diante parecia ter caminhado nas pontas dos pés. Um certo Murphy, cigano negociante de cavalos, estava na charneca a não grande distância àquela hora, mas parece, por sua própria confissão, ter estado embriagado. Declara ter ouvido gritos, mas não é capaz de dizer de que direção vinham. Nenhum sinal de violência foi encontrado na pessoa de Sir Charles e, embora o testemunho do médico apontasse uma distorção facial quase inacreditável — tão grande que o Dr. Mortimer recusou-se a princípio a crer que fosse de fato seu amigo e paciente quem jazia diante dele —, explicou-se que esse é um sintoma não incomum em casos de dispneia e de morte por exaustão cardíaca. Essa explicação foi confirmada pela autópsia, que revelou doença orgânica de longa data, e o júri do legista emitiu veredicto de acordo com a prova médica. É bom que assim seja, pois é obviamente da maior importância que o herdeiro de Sir Charles se instale no Solar e dê continuidade à boa obra tão tristemente interrompida. Se a prosaica conclusão do legista não tivesse posto fim às histórias românticas que se murmuravam a respeito do caso, talvez fosse difícil achar inquilino para Baskerville Hall. Entende-se que o parente mais próximo é o Sr. Henry Baskerville, se ainda for vivo, filho do irmão mais novo de Sir Charles Baskerville. O jovem, quando se teve notícia dele pela última vez, estava na América, e estão sendo feitas diligências no sentido de informá-lo de sua boa fortuna.”","drmortimerrefoldedhispaperandreplacediti~hofsircharlesbaskerville~127":"O Dr. Mortimer dobrou de novo o jornal e recolocou-o no bolso. — Esses são os fatos públicos, Sr. Holmes, relativos à morte de Sir Charles Baskerville.","imustthankyousaidsherlockholmesforcallin~ontainsallthepublicfacts~324":"— Devo agradecer-lhe — disse Sherlock Holmes — por chamar minha atenção para um caso que certamente apresenta alguns aspectos de interesse. Eu havia notado alguns comentários nos jornais à época, mas estava extremamente absorvido por aquele pequeno caso dos camafeus do Vaticano e, em minha ânsia de servir ao Papa, perdi o contato com vários casos ingleses interessantes. Este artigo, o senhor diz, contém todos os fatos públicos?","itdoes~itdoes~6":"— Contém.","thenletmehavetheprivateonesheleanedbackp~iveandjudicialexpression~110":"— Então passe-me os particulares. — Recostou-se, uniu as pontas dos dedos e assumiu sua expressão mais impassível e judicial.","indoingsosaiddrmortimerwhohadbeguntoshow~houldnotbeperfectlyfrank~558":"— Ao fazê-lo — disse o Dr. Mortimer, que começara a dar sinais de forte emoção —, conto algo que não confiei a ninguém. Meu motivo para omiti-lo do inquérito do legista é que um homem de ciência recua diante da ideia de colocar-se publicamente na posição de parecer endossar uma superstição popular. Tive ainda o motivo adicional de que Baskerville Hall, como diz o jornal, certamente ficaria sem inquilino se algo fosse feito para aumentar sua já bastante sinistra reputação. Por ambas as razões julguei-me justificado em dizer um pouco menos do que sabia, uma vez que nenhum bem prático poderia resultar disso; mas com o senhor não há motivo para que eu não seja perfeitamente franco.","themoorisverysparselyinhabitedandthosewh~hebushmanandthehottentot~507":"“A charneca é muito escassamente habitada, e os que moram perto uns dos outros são levados a conviver muito. Por essa razão vi bastante Sir Charles Baskerville. Com exceção do Sr. Frankland, de Lafter Hall, e do Sr. Stapleton, o naturalista, não há outros homens instruídos num raio de muitas milhas. Sir Charles era um homem retraído, mas o acaso de sua doença nos aproximou, e uma comunidade de interesses científicos nos manteve assim. Trouxera da África do Sul muita informação científica, e muitas noites encantadoras passamos juntos discutindo a anatomia comparada do bosquímano e do hotentote.","withinthelastfewmonthsitbecameincreasing~chvibratedwithexcitement~676":"“Nos últimos meses, tornou-se cada vez mais claro para mim que o sistema nervoso de Sir Charles estava tenso até o ponto de ruptura. Ele levara a lenda que li para o senhor extremamente a peito — a tal ponto que, embora caminhasse em suas próprias terras, nada o induziria a sair à charneca à noite. Por incrível que lhe pareça, Sr. Holmes, estava honestamente convencido de que um destino terrível pairava sobre sua família, e certamente os registros que podia dar de seus antepassados não eram animadores. A ideia de alguma presença medonha o assombrava constantemente, e em mais de uma ocasião perguntou-me se, em minhas viagens médicas noturnas, eu alguma vez vira alguma criatura estranha ou ouvira o latido de um cão. Esta última pergunta ele me fez diversas vezes, e sempre com a voz vibrando de excitação.","icanwellrememberdrivinguptohishouseinthe~tementhadnojustification~856":"“Lembro-me bem de ter ido de carro à casa dele, ao anoitecer, cerca de três semanas antes do fatal acontecimento. Calhou de ele estar à porta do vestíbulo. Eu havia descido do meu cabriolé e estava parado diante dele, quando vi seus olhos se fixarem por sobre o meu ombro e fitarem além de mim com uma expressão do mais terrível horror. Girei sobre os calcanhares e tive apenas tempo de vislumbrar algo que tomei por um grande bezerro negro passando na entrada da alameda de acesso. Tão excitado e alarmado estava ele que fui obrigado a ir até o ponto onde estivera o animal e procurá-lo em volta. Havia desaparecido, no entanto, e o incidente pareceu causar a pior impressão em seu espírito. Fiquei com ele toda a noite, e foi nessa ocasião, para explicar a emoção que demonstrara, que me confiou a guarda daquela narrativa que li para o senhor quando cheguei. Menciono este pequeno episódio porque ele assume alguma importância em vista da tragédia que se seguiu, mas eu estava convencido, na época, de que o assunto era inteiramente trivial e de que sua excitação não tinha justificativa.","itwasatmyadvicethatsircharleswasabouttog~ethisterriblecatastrophe~383":"“Foi por conselho meu que Sir Charles estava prestes a ir a Londres. O coração dele, eu sabia, estava afetado, e a constante ansiedade em que vivia, por quimérica que fosse a causa, estava evidentemente tendo sério efeito sobre sua saúde. Pensei que alguns meses entre as distrações da cidade o devolveriam renovado. O Sr. Stapleton, amigo comum que se preocupava muito com o estado de saúde dele, era da mesma opinião. No último instante veio essa terrível catástrofe.","onthenightofsircharlessdeathbarrymorethe~tanceoffbutfreshandclear~876":"“Na noite da morte de Sir Charles, Barrymore, o mordomo, que fez a descoberta, enviou Perkins, o cavalariço, a cavalo, em meu encalço, e como eu estava acordado até tarde, pude chegar a Baskerville Hall menos de uma hora depois do ocorrido. Verifiquei e corroborei todos os fatos mencionados no inquérito. Segui as pegadas pela alameda de teixos, vi o ponto no portão da charneca onde ele parecia ter esperado, notei a mudança na forma das marcas depois daquele ponto, observei que não havia outras pegadas senão as de Barrymore no cascalho macio e, por fim, examinei cuidadosamente o corpo, que não fora tocado até a minha chegada. Sir Charles jazia de bruços, os braços estendidos, os dedos cravados no chão, e as feições convulsionadas por alguma forte emoção a tal ponto que eu dificilmente poderia ter jurado quanto à sua identidade. Certamente não havia lesão física de espécie alguma. Mas Barrymore fez uma declaração falsa no inquérito. Disse que não havia vestígios no chão em torno do corpo. Ele não observou nenhum. Mas eu observei — a pequena distância, mas frescos e nítidos.”","footprints~footprints~10":"— Pegadas.","amansorawomans~amansorawomans~14":"— De homem ou de mulher?","drmortimerlookedstrangelyatusforaninstan~sttoawhisperasheanswered~84":"O Dr. Mortimer olhou-nos de modo estranho por um instante, e a voz desceu quase a um sussurro ao responder.","mrholmestheywerethefootprintsofagigantic~otprintsofagigantichound~45":"— Sr. Holmes, eram as pegadas de um cão gigantesco!","iconfessatthesewordsashudderpassedthroug~henhewaskeenlyinterested~238":"Confesso que, ao ouvir essas palavras, um calafrio me percorreu. Havia um tremor na voz do doutor que mostrava que ele próprio estava profundamente comovido com o que nos contava. Holmes inclinou-se para a frente em sua excitação, e seus olhos tinham o brilho duro e seco que deles saltava quando se interessava vivamente.","yousawthis~yousawthis~10":"— O senhor viu isto?","asclearlyasiseeyou~asclearlyasiseeyou~18":"— Tão claramente quanto vejo o senhor.","andyousaidnothing~andyousaidnothing~17":"— E não disse nada?","whatwastheuse~whatwastheuse~13":"— De que adiantaria?","howwasitthatnooneelsesawit~wwasitthatnooneelsesawit~26":"— Como é que ninguém mais viu?","themarksweresometwentyyardsfromthebodyan~sohadinotknownthislegend~113":"— As marcas estavam a uns vinte jardas do corpo e ninguém lhes deu atenção. Não creio que eu mesmo o tivesse feito, se não conhecesse esta lenda.","therearemanysheepdogsonthemoor~remanysheepdogsonthemoor~30":"— Há muitos cães pastores na charneca?","nodoubtbutthiswasnosheepdog~oubtbutthiswasnosheepdog~27":"— Sem dúvida, mas este não era um cão pastor.","yousayitwaslarge~yousayitwaslarge~16":"— O senhor diz que era grande?","enormous~enormous~8":"— Enorme.","butithadnotapproachedthebody~thadnotapproachedthebody~28":"— Mas não havia se aproximado do corpo?","no~no~2":"— Não.","whatsortofnightwasit~whatsortofnightwasit~20":"— Que tipo de noite era?","dampandraw~dampandraw~10":"— Úmida e crua.","butnotactuallyraining~butnotactuallyraining~21":"— Mas não chovia de fato?","whatisthealleylike~whatisthealleylike~18":"— Como é a alameda?","therearetwolinesofoldyewhedgetwelvefeeth~reisabouteightfeetacross~98":"— Há duas fileiras de velhas sebes de teixo, de doze pés de altura e impenetráveis. O caminho central tem cerca de oito pés de largura.","isthereanythingbetweenthehedgesandthewal~tweenthehedgesandthewalk~41":"— Há alguma coisa entre as sebes e o caminho?","yesthereisastripofgrassaboutsixfeetbroad~sixfeetbroadoneitherside~52":"— Sim, há uma faixa de grama de uns seis pés de largura de cada lado.","iunderstandthattheyewhedgeispenetratedat~etratedatonepointbyagate~55":"— Entendo que a sebe de teixo é interrompida num ponto por um portão?","yesthewicketgatewhichleadsontothemoor~atewhichleadsontothemoor~37":"— Sim, a porteira que dá para a charneca.","isthereanyotheropening~isthereanyotheropening~22":"— Há alguma outra abertura?","none~none~4":"— Nenhuma.","sothattoreachtheyewalleyoneeitherhastoco~setoenteritbythemoorgate~88":"— De modo que, para chegar à alameda de teixos, ou se desce por ela a partir da casa, ou se entra pelo portão da charneca?","thereisanexitthroughasummerhouseatthefar~hasummerhouseatthefarend~43":"— Há uma saída por um caramanchão na extremidade oposta.","hadsircharlesreachedthis~hadsircharlesreachedthis~24":"— Sir Charles chegara até ela?","nohelayaboutfiftyyardsfromit~layaboutfiftyyardsfromit~28":"— Não; ele jazia a uns cinquenta jardas dela.","nowtellmedrmortimerandthisisimportantthe~nthepathandnotonthegrass~85":"— Agora diga-me, Dr. Mortimer, e isto é importante: as marcas que o senhor viu estavam no caminho e não na grama?","nomarkscouldshowonthegrass~markscouldshowonthegrass~26":"— Nenhuma marca poderia aparecer na grama.","weretheyonthesamesideofthepathasthemoorg~deofthepathasthemoorgate~43":"— Estavam do mesmo lado do caminho que o portão da charneca?","yestheywereontheedgeofthepathonthesamesi~thesamesideasthemoorgate~55":"— Sim; estavam na borda do caminho, do mesmo lado do portão da charneca.","youinterestmeexceedinglyanotherpointwast~ntwasthewicketgateclosed~58":"— O senhor me interessa extremamente. Outro ponto. A porteira estava fechada?","closedandpadlocked~closedandpadlocked~18":"— Fechada e com cadeado.","howhighwasit~howhighwasit~12":"— Que altura tinha?","aboutfourfeethigh~aboutfourfeethigh~17":"— Cerca de quatro pés.","thenanyonecouldhavegotoverit~anyonecouldhavegotoverit~28":"— Então qualquer um poderia tê-la transposto?","yes~yes~3":"— Sim.","andwhatmarksdidyouseebythewicketgate~didyouseebythewicketgate~36":"— E que marcas o senhor viu junto à porteira?","noneinparticular~noneinparticular~16":"— Nenhuma em particular.","goodheavendidnooneexamine~oodheavendidnooneexamine~25":"— Santo Deus! Ninguém examinou?","yesiexaminedmyself~yesiexaminedmyself~18":"— Sim, eu mesmo examinei.","andfoundnothing~andfoundnothing~15":"— E não achou nada?","itwasallveryconfusedsircharleshadevident~thereforfiveortenminutes~71":"— Estava tudo muito confuso. Sir Charles evidentemente ficara ali de pé por cinco ou dez minutos.","howdoyouknowthat~howdoyouknowthat~16":"— Como sabe disso?","becausetheashhadtwicedroppedfromhiscigar~twicedroppedfromhiscigar~40":"— Porque a cinza de seu charuto caíra duas vezes.","excellentthisisacolleaguewatsonafterouro~erourownheartbutthemarks~58":"— Excelente! Eis um colega, Watson, depois do nosso próprio coração. Mas as marcas?","hehadlefthisownmarksalloverthatsmallpatc~velicoulddiscernnoothers~70":"— Ele deixara as suas próprias marcas por todo aquele pequeno trecho de cascalho. Não pude discernir outras.","sherlockholmesstruckhishandagainsthiskne~eewithanimpatientgesture~63":"Sherlock Holmes bateu com a mão no joelho, num gesto impaciente.","ifihadonlybeentherehecrieditisevidentlya~aveindeedmuchtoanswerfor~329":"— Se eu ao menos tivesse estado lá! — exclamou. — É evidentemente um caso de extraordinário interesse e que oferecia imensas oportunidades ao perito científico. Aquela página de cascalho em que eu poderia ter lido tanta coisa já foi há muito borrada pela chuva e desfigurada pelos tamancos de camponeses curiosos. Ah, Dr. Mortimer, Dr. Mortimer, pensar que não me chamou! O senhor tem de fato muito a responder.","icouldnotcallyouinmrholmeswithoutdisclos~hingtodosobesidesbesides~125":"— Eu não podia chamá-lo, Sr. Holmes, sem revelar esses fatos ao mundo, e já expus minhas razões para não desejar fazê-lo. Além disso, além disso...","whydoyouhesitate~whydoyouhesitate~16":"— Por que hesita?","thereisarealminwhichthemostacuteandmoste~edofdetectivesishelpless~72":"— Há um reino em que o mais arguto e experiente dos detetives fica impotente.","youmeanthatthethingissupernatural~atthethingissupernatural~33":"— Quer dizer que a coisa é sobrenatural?","ididnotpositivelysayso~ididnotpositivelysayso~22":"— Não afirmei isso positivamente.","nobutyouevidentlythinkit~nobutyouevidentlythinkit~24":"— Não, mas evidentemente o pensa.","sincethetragedymrholmestherehavecometomy~hthesettledorderofnature~110":"— Desde a tragédia, Sr. Holmes, chegaram aos meus ouvidos vários incidentes difíceis de conciliar com a ordem estabelecida da Natureza.","forexample~forexample~10":"— Por exemplo?","ifindthatbeforetheterribleeventoccurreds~owillcrossthemooratnight~502":"— Descubro que, antes de ocorrer o terrível acontecimento, várias pessoas tinham visto na charneca uma criatura que corresponde a este demônio dos Baskerville e que não poderia de modo algum ser qualquer animal conhecido pela ciência. Todas concordaram em que era uma criatura enorme, luminosa, medonha e espectral. Interroguei esses homens, um deles um camponês de cabeça dura, outro um ferrador e outro um lavrador da charneca, e todos contam a mesma história dessa pavorosa aparição, correspondendo exatamente ao cão infernal da lenda. Asseguro-lhe que há um reinado de terror no distrito, e que é preciso ser homem destemido para atravessar a charneca à noite.","andyouatrainedmanofsciencebelieveittobes~elieveittobesupernatural~51":"— E o senhor, homem de ciência treinado, crê que seja sobrenatural?","idonotknowwhattobelieve~idonotknowwhattobelieve~23":"— Não sei em que crer.","holmesshruggedhisshouldersihavehithertoc~hatthefootmarkismaterial~213":"Holmes encolheu os ombros. — Até aqui confinei minhas investigações a este mundo — disse. — De modo modesto, tenho combatido o mal, mas enfrentar o próprio Pai do Mal seria, talvez, tarefa ambiciosa demais. Contudo, o senhor há de admitir que a pegada é material.","theoriginalhoundwasmaterialenoughtotugam~yethewasdiabolicalaswell~79":"— O cão original era material o bastante para arrancar a garganta de um homem, e no entanto era também diabólico.","iseethatyouhavequitegoneovertothesuperna~andthatyoudesiremetodoit~216":"— Vejo que o senhor passou inteiramente para os sobrenaturalistas. Mas agora, Dr. Mortimer, diga-me isto. Se sustenta esses pontos de vista, por que veio consultar-me? O senhor me diz no mesmo fôlego que é inútil investigar a morte de Sir Charles e que deseja que eu o faça.","ididnotsaythatidesiredyoutodoit~saythatidesiredyoutodoit~31":"— Não disse que desejava que o senhor o fizesse.","thenhowcaniassistyou~thenhowcaniassistyou~20":"— Então como posso ajudá-lo?","byadvisingmeastowhatishoulddowithsirhenr~xactlyonehourandaquarter~132":"— Aconselhando-me sobre o que devo fazer com Sir Henry Baskerville, que chega à estação de Waterloo — o Dr. Mortimer olhou o relógio — dentro de exatamente uma hora e um quarto.","hebeingtheheir~hebeingtheheir~14":"— Ele sendo o herdeiro?","yesonthedeathofsircharlesweinquiredforth~xecutorofsircharlesswill~222":"— Sim. Por ocasião da morte de Sir Charles, procuramos esse jovem cavalheiro e descobrimos que ele estivera lavrando a terra no Canadá. Pelas informações que nos chegaram, é um excelente rapaz em todos os sentidos. Falo agora não como médico, mas como curador e testamenteiro de Sir Charles.","thereisnootherclaimantipresume~snootherclaimantipresume~30":"— Não há outro pretendente, presumo?","nonetheonlyotherkinsmanwhomwehavebeenabl~ldyouadvisemetodowithhim~564":"— Nenhum. O único outro parente que conseguimos rastrear foi Rodger Baskerville, o mais novo de três irmãos, dos quais o pobre Sir Charles era o mais velho. O segundo irmão, que morreu jovem, é o pai deste rapaz, Henry. O terceiro, Rodger, era a ovelha negra da família. Vinha da velha estirpe dominadora dos Baskerville e era a própria imagem, dizem-me, do retrato de família do velho Hugo. Fez da Inglaterra um lugar quente demais para si, fugiu para a América Central e morreu lá em 1876, de febre amarela. Henry é o último dos Baskerville. Dentro de uma hora e cinco minutos vou encontrá-lo em Waterloo. Recebi um telegrama dizendo que ele chegou a Southampton esta manhã. Agora, Sr. Holmes, que me aconselha a fazer com ele?","whyshouldhenotgotothehomeofhisfathers~tgotothehomeofhisfathers~37":"— Por que não deveria ir para a casa de seus pais?","itseemsnaturaldoesitnotandyetconsidertha~reyouandaskforyouradvice~541":"— Parece natural, não é? E no entanto, considere que todo Baskerville que vai para lá encontra um destino funesto. Tenho certeza de que, se Sir Charles tivesse podido falar comigo antes de morrer, ter-me-ia advertido contra trazer este, o último da velha raça e herdeiro de grande fortuna, àquele lugar mortal. E contudo não se pode negar que a prosperidade de toda esta pobre e árida região depende de sua presença. Toda a boa obra realizada por Sir Charles ruirá por terra se não houver inquilino no Solar. Receio deixar-me influenciar demais por meu óbvio interesse no assunto, e é por isso que trago o caso ao senhor e peço o seu conselho.","holmesconsideredforalittletime~consideredforalittletime~30":"Holmes refletiu por algum tempo.","putintoplainwordsthematteristhissaidhein~ervillethatisyouropinion~138":"— Em palavras simples, o caso é este — disse. — Na sua opinião, há uma agência diabólica que faz de Dartmoor uma morada insegura para um Baskerville. É essa a sua opinião?","atleastimightgothelengthofsayingthatther~eevidencethatthismaybeso~70":"— Ao menos eu poderia chegar a dizer que há alguma evidência de que isso possa ser assim.","exactlybutsurelyifyoursupernaturaltheory~betooinconceivableathing~178":"— Exatamente. Mas certamente, se a sua teoria sobrenatural estiver correta, ela poderia fazer mal ao rapaz em Londres tão facilmente quanto em Devonshire. Um diabo de poderes meramente locais, como uma junta paroquial, seria coisa inconcebível demais.","youputthemattermoreflippantlymrholmestha~teswhatwouldyourecommend~231":"— O senhor coloca o assunto de modo mais leviano, Sr. Holmes, do que provavelmente faria se fosse posto em contato pessoal com essas coisas. Seu conselho, então, tal como o entendo, é que o rapaz estará tão seguro em Devonshire quanto em Londres. Ele chega em cinquenta minutos. Que me recomenda?","irecommendsirthatyoutakeacabcalloffyours~omeetsirhenrybaskerville~119":"— Recomendo, senhor, que tome um cabriolé, chame de volta o seu spaniel que está arranhando a minha porta da frente, e vá a Waterloo encontrar Sir Henry Baskerville.","andthen~andthen~7":"— E depois?","andthenyouwillsaynothingtohimatalluntili~deupmymindaboutthematter~70":"— E depois não diga absolutamente nada a ele até que eu tenha formado minha opinião sobre o assunto.","howlongwillittakeyoutomakeupyourmind~ttakeyoutomakeupyourmind~36":"— Quanto tempo levará para formá-la?","twentyfourhoursattenoclocktomorrowdrmort~rhenrybaskervillewithyou~172":"— Vinte e quatro horas. Às dez horas de amanhã, Dr. Mortimer, ficarei muito grato se o senhor me visitar aqui, e será de ajuda para meus planos futuros que traga Sir Henry Baskerville consigo.","iwilldosomrholmeshescribbledtheappointme~edhimattheheadofthestair~142":"— Assim farei, Sr. Holmes. — Rabiscou o compromisso no punho da camisa e saiu apressado, a seu modo estranho, míope e distraído. Holmes o deteve no alto da escada.","onlyonemorequestiondrmortimeryousaythatb~hisapparitionuponthemoor~113":"— Só mais uma pergunta, Dr. Mortimer. O senhor diz que, antes da morte de Sir Charles Baskerville, várias pessoas viram essa aparição na charneca?","threepeopledid~threepeopledid~14":"— Três pessoas viram.","didanyseeitafter~didanyseeitafter~16":"— Alguma a viu depois?","ihavenotheardofany~ihavenotheardofany~18":"— Não tenho notícia de nenhuma.","thankyougoodmorning~thankyougoodmorning~19":"— Obrigado. Bom dia.","holmesreturnedtohisseatwiththatquietlook~dacongenialtaskbeforehim~102":"Holmes voltou ao seu assento com aquele olhar sereno de satisfação íntima que significava ter diante de si uma tarefa do seu agrado.","goingoutwatson~goingoutwatson~14":"— Vai sair, Watson?","unlessicanhelpyou~unlessicanhelpyou~17":"— A menos que eu possa ajudá-lo.","nomydearfellowitisatthehourofactionthati~submittedtousthismorning~356":"— Não, meu caro, é na hora da ação que recorro a você. Mas isto é esplêndido, realmente único sob certos aspectos. Quando passar pela loja do Bradley, poderia pedir-lhe que mande uma libra do fumo picado mais forte? Obrigado. Seria bom se pudesse arranjar para não voltar antes do anoitecer. Então ficarei muito contente em comparar impressões sobre este interessantíssimo problema que nos foi apresentado esta manhã.","iknewthatseclusionandsolitudewereverynec~inthesittingroomoncemore~388":"Eu sabia que o isolamento e a solidão eram muito necessários a meu amigo naquelas horas de intensa concentração mental em que pesava cada partícula de evidência, construía teorias alternativas, equilibrava umas contra as outras e decidia quais pontos eram essenciais e quais irrelevantes. Passei, portanto, o dia em meu clube e só voltei a Baker Street ao anoitecer. Eram quase nove horas quando me vi de novo na sala de estar.","myfirstimpressionasiopenedthedoorwasthat~rollsofpaperlayaroundhim~391":"Minha primeira impressão, ao abrir a porta, foi a de que um incêndio se declarara, pois a sala estava tão cheia de fumaça que a luz do lampião sobre a mesa ficava turva. Ao entrar, porém, meus temores se dissiparam, pois eram os acres vapores de um tabaco forte e grosseiro que me tomavam pela garganta e me faziam tossir. Através da névoa tive uma vaga visão de Holmes em seu roupão, enrodilhado numa poltrona, com o cachimbo preto de barro entre os lábios. Vários rolos de papel jaziam ao seu redor.","caughtcoldwatsonsaidhe~caughtcoldwatsonsaidhe~22":"— Resfriou-se, Watson? — disse ele.","noitsthispoisonousatmosphere~sthispoisonousatmosphere~28":"— Não, é esta atmosfera envenenada.","isupposeitisprettythicknowthatyoumention~thicknowthatyoumentionit~42":"— Suponho que esteja bastante carregada, agora que você menciona.","thickitisintolerable~thickitisintolerable~20":"— Carregada! É intolerável.","openthewindowthenyouhavebeenatyourclubal~tyourcluballdayiperceive~53":"— Abra a janela, então! Percebo que você passou o dia no clube.","mydearholmes~mydearholmes~12":"— Meu caro Holmes!","amiright~amiright~8":"— Estou certo?","certainlybuthow~certainlybuthow~15":"— Certamente, mas como?","helaughedatmybewilderedexpressionthereis~hehavebeenisitnotobvious~351":"Riu-se da minha expressão perplexa. — Há em você, Watson, um frescor delicioso que faz ser um prazer exercitar quaisquer pequenos poderes que eu possua às suas custas. Um cavalheiro sai num dia de chuvas e lama. Volta imaculado à noite, com o lustre ainda no chapéu e nas botas. Esteve, portanto, parado o dia todo. Não é homem de amigos íntimos. Onde, então, poderia ter estado? Não é óbvio?","wellitisratherobvious~wellitisratherobvious~21":"— Bem, é bastante óbvio.","theworldisfullofobviousthingswhichnobody~edoyouthinkthatihavebeen~91":"— O mundo está cheio de coisas óbvias que ninguém, por acaso, jamais observa. Onde você acha que estive?","afixturealso~afixturealso~12":"— Parado também.","onthecontraryihavebeentodevonshire~aryihavebeentodevonshire~34":"— Pelo contrário, estive em Devonshire.","inspirit~inspirit~8":"— Em espírito?","exactlymybodyhasremainedinthisarmchairan~thaticouldfindmywayabout~271":"— Exatamente. Meu corpo permaneceu nesta poltrona e, lamento observar, consumiu em minha ausência dois grandes bules de café e uma quantidade incrível de tabaco. Depois que você saiu, mandei buscar na Stamford’s o mapa do Estado-Maior desta parte da charneca, e meu espírito pairou sobre ele o dia todo. Lisonjeio-me de que saberia orientar-me por lá.","alargescalemapipresume~alargescalemapipresume~22":"— Um mapa em grande escala, presumo?","verylarge~verylarge~9":"— Grandíssimo.","heunrolledonesectionandhelditoverhisknee~skervillehallinthemiddle~119":"Desenrolou uma seção e a segurou sobre o joelho. — Aqui está o distrito particular que nos interessa. Aquele é Baskerville Hall, no meio.","withawoodroundit~withawoodroundit~16":"— Com um bosque em torno?","exactlyifancytheyewalleythoughnotmarkedu~chwemayhelptoplayitagain~669":"— Exatamente. Imagino que a alameda de teixos, embora não marcada com esse nome, deva estender-se ao longo desta linha, com a charneca, como você percebe, à direita dela. Este pequeno aglomerado de edifícios é o povoado de Grimpen, onde nosso amigo Dr. Mortimer tem seu quartel-general. Num raio de cinco milhas há, como vê, apenas umas poucas moradias esparsas. Aqui está Lafter Hall, mencionado na narrativa. Há uma casa indicada aqui que pode ser a residência do naturalista — Stapleton, se bem me lembro, era o nome dele. Aqui estão duas fazendas da charneca, High Tor e Foulmire. Depois, a catorze milhas, a grande prisão de condenados de Princetown. Entre esses pontos dispersos e ao redor deles estende-se a charneca desolada e sem vida. Este, então, é o palco em que a tragédia foi representada e em que podemos ajudar a representá-la de novo.","itmustbeawildplace~itmustbeawildplace~18":"— Deve ser um lugar selvagem.","yesthesettingisaworthyoneifthedevildidde~veahandintheaffairsofmen~72":"— Sim, o cenário é digno. Se o diabo desejasse realmente meter a mão nos negócios dos homens...","thenyouareyourselfincliningtothesupernat~esupernaturalexplanation~55":"— Então você mesmo está se inclinando para a explicação sobrenatural.","thedevilsagentsmaybeoffleshandbloodmayth~nedthecaseoverinyourmind~622":"— Os agentes do diabo podem ser de carne e osso, não podem? Duas perguntas nos aguardam de início. Uma é se algum crime foi cometido; a segunda é qual é o crime e como foi cometido. É claro que, se a conjectura do Dr. Mortimer estiver correta e estivermos lidando com forças alheias às leis ordinárias da Natureza, está terminada a nossa investigação. Mas somos obrigados a esgotar todas as outras hipóteses antes de recorrer a esta. Creio que vamos fechar aquela janela de novo, se não se importa. É coisa singular, mas acho que uma atmosfera concentrada ajuda a concentração do pensamento. Não levei a coisa ao extremo de entrar numa caixa para pensar, mas esse é o desfecho lógico de minhas convicções. Você ruminou o caso?","yesihavethoughtagooddealofitinthecourseo~lofitinthecourseoftheday~47":"— Sim, pensei bastante nele no decorrer do dia.","whatdoyoumakeofit~whatdoyoumakeofit~17":"— O que acha dele?","itisverybewildering~itisverybewildering~19":"— É muito desconcertante.","ithascertainlyacharacterofitsownthereare~amplewhatdoyoumakeofthat~120":"— Tem certamente um caráter próprio. Há pontos de distinção nele. Aquela mudança nas pegadas, por exemplo. O que você acha disso?","mortimersaidthatthemanhadwalkedontiptoed~ownthatportionofthealley~64":"— Mortimer disse que o homem caminhara na ponta dos pés por aquele trecho da alameda.","heonlyrepeatedwhatsomefoolhadsaidatthein~walkontiptoedownthealley~82":"— Ele apenas repetiu o que algum tolo dissera no inquérito. Por que um homem andaria na ponta dos pés pela alameda?","whatthen~whatthen~8":"— O que então?","hewasrunningwatsonrunningdesperatelyrunn~rtandfelldeaduponhisface~102":"— Ele corria, Watson — corria desesperadamente, corria para salvar a vida, corria até estourar o coração — e caiu morto de bruços.","runningfromwhat~runningfromwhat~15":"— Corria de quê?","thereliesourproblemthereareindicationsth~arbeforeeverhebegantorun~87":"— Aí está o nosso problema. Há indícios de que o homem estava louco de medo antes mesmo de começar a correr.","howcanyousaythat~howcanyousaythat~16":"— Como pode dizer isso?","iampresumingthatthecauseofhisfearscameto~yratherthaninhisownhouse~351":"— Presumo que a causa de seus temores lhe veio através da charneca. Se assim foi, e parece o mais provável, só um homem que perdera o juízo teria corrido para longe da casa em vez de em direção a ela. Se o testemunho do cigano puder ser tido por verdadeiro, ele correu, com gritos de socorro, na direção em que o socorro era menos provável. Depois, mais uma vez, por quem esperava ele naquela noite, e por que o esperava na alameda de teixos em vez de em sua própria casa?","youthinkthathewaswaitingforsomeone~athewaswaitingforsomeone~34":"— Você pensa que ele esperava alguém?","themanwaselderlyandinfirmwecanunderstand~ordeducedfromthecigarash~238":"— O homem era idoso e enfermo. Compreendemos que desse um passeio noturno, mas o solo estava úmido e a noite inclemente. É natural que ele ficasse parado por cinco ou dez minutos, como o Dr. Mortimer, com mais senso prático do que eu lhe teria creditado, deduziu pela cinza do charuto?","buthewentouteveryevening~buthewentouteveryevening~24":"— Mas ele saía todas as noites.","ithinkitunlikelythathewaitedatthemoorgat~ybaskervilleinthemorning~365":"— Acho improvável que esperasse todas as noites no portão da charneca. Pelo contrário, o testemunho é de que evitava a charneca. Naquela noite esperou ali. Era a noite anterior à sua partida para Londres. A coisa toma forma, Watson. Torna-se coerente. Poderia pedir-lhe que me passe o violino, e adiaremos todo pensamento ulterior sobre este negócio até que tenhamos a vantagem de nos encontrar com o Dr. Mortimer e Sir Henry Baskerville pela manhã."}$tr$::jsonb, 244)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- charles-dickens_a-christmas-carol (464 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('charles-dickens_a-christmas-carol', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"marleysghost":"O fantasma de Marley","thefirstofthethreespirits":"O Primeiro dos Três Espíritos","thesecondofthethreespirits":"O Segundo dos Três Espíritos"}$tr$::jsonb, $tr${"marleywasdeadtobeginwiththereisnodoubtwh~rleywasasdeadasadoornail~247":"Marley estava morto, para começar. Quanto a isso não havia a menor dúvida. O registro de seu enterro fora assinado pelo clérigo, pelo sacristão, pelo agente funerário e pelo principal enlutado. Scrooge o assinara. E o nome de Scrooge valia ouro na Bolsa para qualquer coisa em que ele resolvesse pôr a mão. O velho Marley estava morto como um prego de porta.","mindidontmeantosaythatiknowofmyownknowle~rleywasasdeadasadoornail~341":"Atenção! Não pretendo dizer que sei, por conhecimento próprio, o que há de particularmente morto num prego de porta. Eu mesmo seria levado a considerar o prego de caixão como a peça de ferragem mais morta de todo o comércio. Mas a sabedoria de nossos antepassados está na comparação, e minhas mãos profanas não hão de perturbá-la, ou o país está perdido. Permitam-me, portanto, repetir com ênfase que Marley estava morto como um prego de porta.","scroogeknewhewasdeadofcoursehedidhowcoul~itwithanundoubtedbargain~357":"Scrooge sabia que ele estava morto? Claro que sabia. Como poderia ser de outro modo? Scrooge e ele foram sócios por não sei quantos anos. Scrooge era seu único testamenteiro, seu único administrador, seu único cessionário, seu único legatário universal, seu único amigo e único enlutado. E mesmo Scrooge não ficou tão terrivelmente abalado com o triste acontecimento que deixasse de ser excelente homem de negócios no próprio dia do funeral, que solenizou com uma pechincha indiscutível.","thementionofmarleysfuneralbringsmebackto~oastonishhissonsweakmind~480":"A menção ao funeral de Marley me traz de volta ao ponto de onde parti. Não há dúvida de que Marley estava morto. Isso deve ficar bem entendido, ou nada de maravilhoso poderá resultar da história que vou contar. Se não estivéssemos perfeitamente convencidos de que o pai de Hamlet morreu antes de a peça começar, não haveria nada de mais notável em vê-lo passear à noite, com vento leste, sobre as próprias muralhas, do que em qualquer outro cavalheiro de meia-idade que se aventurasse imprudentemente depois de escurecer num lugar ventoso — o adro da Catedral de São Paulo, por exemplo — literalmente para assombrar o espírito fraco do filho.","scroogeneverpaintedoutoldmarleysnamether~amesitwasallthesametohim~246":"Scrooge nunca apagou o nome do velho Marley. Lá continuou, anos depois, sobre a porta do armazém: Scrooge & Marley. A firma era conhecida como Scrooge & Marley. Às vezes as pessoas novas no ramo chamavam Scrooge de Scrooge, e às vezes de Marley, mas ele respondia a ambos os nomes. Para ele dava no mesmo.","ohbuthewasatightfistedhandatthegrindston~awitonedegreeatchristmas~530":"Ah! mas que mão-de-vaca na pedra de amolar, esse Scrooge! Um velho pecador que espremia, arrancava, agarrava, raspava, tomava e cobiçava! Duro e afiado como sílex, do qual aço nenhum jamais tirara fogo generoso; fechado, contido e solitário como uma ostra. O frio que trazia dentro de si congelava-lhe as velhas feições, beliscava-lhe o nariz pontudo, enrugava-lhe a face, endurecia-lhe o andar; deixava-lhe os olhos vermelhos, os lábios finos azulados; e falava com astúcia em sua voz áspera. Uma geada cobria-lhe a cabeça, as sobrancelhas e o queixo hirsuto. Levava sempre consigo a própria baixa temperatura; gelava o escritório nos dias de canícula e não o descongelava um grau sequer no Natal.","externalheatandcoldhadlittleinfluenceons~somelyandscroogeneverdid~351":"O calor e o frio de fora pouco influíam sobre Scrooge. Nenhum calor podia aquecê-lo, nenhum tempo invernal o enregelava. Nenhum vento que soprasse era mais amargo do que ele, nenhuma neve que caísse mais obstinada em seu propósito, nenhuma chuva torrencial menos aberta a súplicas. O mau tempo não sabia por onde pegá-lo. A mais pesada chuva, a neve, o granizo e a geada miúda só podiam gabar-se de uma vantagem sobre ele. Muitas vezes “desciam” com generosidade, e Scrooge nunca.","nobodyeverstoppedhiminthestreettosaywith~rthananevileyedarkmaster~425":"Ninguém jamais o parou na rua para dizer, com ar jovial: “Meu caro Scrooge, como vai? Quando virá me visitar?” Nenhum mendigo lhe implorava um trocado, nenhuma criança lhe perguntava que horas eram, nenhum homem ou mulher jamais, em toda a sua vida, indagou de Scrooge o caminho para este ou aquele lugar. Até os cães dos cegos pareciam conhecê-lo; e, quando o viam aproximar-se, puxavam os donos para dentro de portas e vielas; e depois abanavam o rabo como se dissessem: “Nenhum olho é melhor do que um olho mau, sinistro patrão!”","butwhatdidscroogecareitwastheverythinghe~ingonescallnutstoscrooge~161":"Mas que lhe importava a Scrooge? Era justamente o que ele apreciava. Abrir caminho aos cotovelos pelas veredas apinhadas da vida, avisando toda simpatia humana de que mantivesse distância, era o que os entendidos chamam de “um prato cheio” para Scrooge.","onceuponatimeofallthegooddaysintheyearon~dwasbrewingonalargescale~693":"Era uma vez — dentre todos os bons dias do ano, na véspera de Natal — o velho Scrooge, sentado, atarefado, em seu escritório. Fazia um tempo frio, sombrio, cortante, e além disso enevoado; e ele podia ouvir as pessoas no pátio lá fora andando de um lado para o outro, ofegantes, batendo as mãos contra o peito e pateando as pedras do calçamento para se aquecer. Os relógios da City acabavam de bater três horas, mas já estava bem escuro — não havia clareado o dia inteiro — e velas tremulavam nas janelas dos escritórios vizinhos, como manchas rubras sobre o ar pardo e palpável. A névoa entrava aos borbotões por todas as frestas e buracos de fechadura, e era tão densa lá fora que, embora o pátio fosse dos mais estreitos, as casas do outro lado eram meros fantasmas. Ao ver a nuvem encardida descer em flocos, obscurecendo tudo, qualquer um poderia pensar que a natureza morava ali pertinho e estava fabricando cerveja em grande escala.","thedoorofscroogescountinghousewasopentha~trongimaginationhefailed~484":"A porta do escritório de Scrooge estava aberta, para que ele pudesse vigiar seu empregado, que, numa cela lúgubre e minúscula mais além, uma espécie de aquário, copiava cartas. Scrooge tinha um fogo muito pequeno, mas o do empregado era tão menor ainda que parecia um único carvão. Ele, porém, não podia reabastecê-lo, pois Scrooge guardava a caixa de carvão em sua própria sala; e tão certo quanto o empregado entrar com a pá, o patrão predizia que seria necessário que se separassem. Por isso o empregado envolveu o pescoço no cachecol branco e tentou aquecer-se na vela; esforço em que, por não ser homem de forte imaginação, fracassou.","amerrychristmasunclegodsaveyoucriedachee~mationhehadofhisapproach~148":"— Feliz Natal, tio! Deus o guarde! — exclamou uma voz alegre. Era a voz do sobrinho de Scrooge, que o surpreendeu tão depressa que esse foi o primeiro aviso que ele teve de sua aproximação.","bahsaidscroogehumbug~bahsaidscroogehumbug~20":"— Bah! — disse Scrooge. — Tolice!","hehadsoheatedhimselfwithrapidwalkinginth~dandhisbreathsmokedagain~155":"Esquentara-se tanto, este sobrinho de Scrooge, com a caminhada rápida na névoa e na geada, que estava todo afogueado; o rosto corado e bonito, os olhos faiscando, e o hálito fumegando sem parar.","christmasahumbugunclesaidscroogesnephewy~ewyoudontmeanthatiamsure~61":"— O Natal uma tolice, tio! — disse o sobrinho de Scrooge. — O senhor não quer dizer isso, tenho certeza.","idosaidscroogemerrychristmaswhatrighthav~tobemerryyourepoorenough~94":"— Quero, sim — disse Scrooge. — Feliz Natal! Que direito tem você de ser feliz? Que motivo tem para ser feliz? Você é pobre o bastante.","comethenreturnedthenephewgailywhatrighth~obemoroseyourerichenough~98":"— Ora, então — retrucou o sobrinho, alegre. — Que direito tem o senhor de ser tristonho? Que motivo tem para ser rabugento? O senhor é rico o bastante.","scroogehavingnobetteranswerreadyonthespu~ndfolloweditupwithhumbug~89":"Scrooge, não tendo melhor resposta pronta na ocasião, disse “Bah!” de novo, e acrescentou “Tolice!”.","dontbecrossunclesaidthenephew~ecrossunclesaidthenephew~29":"— Não se zangue, tio! — disse o sobrinho.","whatelsecanibereturnedtheunclewhenilivei~ythroughhisheartheshould~473":"— O que mais posso ser — retrucou o tio — vivendo num mundo de tolos como este? Feliz Natal! Fora com o feliz Natal! O que é o Natal para você senão uma época de pagar contas sem dinheiro; uma época de se descobrir um ano mais velho e nem uma hora mais rico; uma época de fechar os livros e ver cada item deles, ao longo de uma dúzia redonda de meses, apresentado contra você? Se dependesse de mim — disse Scrooge, indignado —, todo idiota que anda por aí com “Feliz Natal” nos lábios devia ser cozido no próprio pudim e enterrado com uma estaca de azevinho cravada no coração. Devia mesmo!","unclepleadedthenephew~unclepleadedthenephew~21":"— Tio! — implorou o sobrinho.","nephewreturnedtheunclesternlykeepchristm~nwayandletmekeepitinmine~74":"— Sobrinho! — retrucou o tio, severo. — Celebre o Natal à sua maneira e deixe que eu o celebre à minha.","keepitrepeatedscroogesnephewbutyoudontke~esnephewbutyoudontkeepit~44":"— Celebrar! — repetiu o sobrinho de Scrooge. — Mas o senhor não o celebra.","letmeleaveitalonethensaidscroogemuchgood~muchgoodithaseverdoneyou~74":"— Então deixe-me em paz com ele — disse Scrooge. — Bom proveito lhe faça! Muito bom proveito sempre lhe fez!","therearemanythingsfromwhichimighthaveder~omegoodandisaygodblessit~663":"— Há muitas coisas das quais eu poderia ter tirado proveito e não tirei, ouso dizer — retrucou o sobrinho —, o Natal entre elas. Mas tenho certeza de que sempre pensei no tempo do Natal, quando ele chega — pondo de lado a veneração devida ao seu nome e origem sagrados, se é que alguma coisa a ele pertencente pode ficar à parte disso —, como uma boa época; uma época bondosa, clemente, caridosa, agradável; a única que conheço, no longo calendário do ano, em que homens e mulheres parecem, por consentimento geral, abrir livremente seus corações fechados, e pensar nas pessoas abaixo deles como se fossem realmente companheiros de viagem rumo ao túmulo, e não outra raça de criaturas destinadas a outras jornadas. E por isso, tio, embora nunca tenha posto um grão de ouro ou prata no meu bolso, creio que me fez bem e me fará bem; e digo: Deus o abençoe!","theclerkinthetankinvoluntarilyapplaudedb~thelastfrailsparkforever~135":"O empregado no aquário aplaudiu involuntariamente. Dando-se conta de imediato da inconveniência, atiçou o fogo e extinguiu para sempre a última frágil centelha.","letmehearanothersoundfromyousaidscroogea~ryoudontgointoparliament~169":"— Se eu ouvir mais um som seu — disse Scrooge —, você vai celebrar o seu Natal perdendo o emprego! O senhor é um orador de peso — acrescentou, voltando-se para o sobrinho. — Admira-me que não entre para o Parlamento.","dontbeangryunclecomedinewithustomorrow~lecomedinewithustomorrow~38":"— Não se zangue, tio. Vamos! Jante conosco amanhã.","scroogesaidthathewouldseehimyesindeedhed~ehiminthatextremityfirst~121":"Scrooge disse que o veria — sim, de fato disse. Foi até o fim da expressão e disse que o veria antes nesse extremo.","butwhycriedscroogesnephewwhy~hycriedscroogesnephewwhy~28":"— Mas por quê? — exclamou o sobrinho de Scrooge. — Por quê?","whydidyougetmarriedsaidscrooge~yougetmarriedsaidscrooge~30":"— Por que você se casou? — disse Scrooge.","becauseifellinlove~becauseifellinlove~18":"— Porque me apaixonei.","becauseyoufellinlovegrowledscroogeasifth~rychristmasgoodafternoon~117":"— Porque se apaixonou! — rosnou Scrooge, como se essa fosse a única coisa no mundo mais ridícula do que um feliz Natal. — Boa tarde!","nayunclebutyounevercametoseemebeforethat~asareasonfornotcomingnow~81":"— Ora, tio, mas o senhor nunca foi me visitar antes de isso acontecer. Por que dar isso como razão para não vir agora?","goodafternoonsaidscrooge~goodafternoonsaidscrooge~24":"— Boa tarde! — disse Scrooge.","iwantnothingfromyouiasknothingofyouwhyca~fyouwhycannotwebefriends~55":"— Nada quero do senhor; nada lhe peço; por que não podemos ser amigos?","iamsorrywithallmyhearttofindyousoresolut~stsoamerrychristmasuncle~184":"— Lamento de todo o coração encontrá-lo tão resoluto. Nunca tivemos nenhuma desavença em que eu tivesse parte. Mas fiz a tentativa em homenagem ao Natal, e manterei meu humor natalino até o fim. Então, feliz Natal, tio!","andahappynewyear~andahappynewyear~16":"— E feliz Ano-Novo!","hisnephewlefttheroomwithoutanangrywordno~rhereturnedthemcordially~177":"Seu sobrinho, no entanto, deixou a sala sem uma palavra irritada. Parou na porta de fora para dirigir ao empregado os cumprimentos da estação, o qual, por mais frio que estivesse, era mais caloroso que Scrooge, pois os retribuiu cordialmente.","theresanotherfellowmutteredscroogewhoove~ristmasillretiretobedlam~142":"— Aí está outro sujeito — murmurou Scrooge, que o ouviu —, meu empregado, com quinze xelins por semana, mulher e família, falando de feliz Natal. Vou me recolher a Bedlam.","thislunaticinlettingscroogesnephewouthad~ntheirhandsandbowedtohim~187":"Esse lunático, ao deixar sair o sobrinho de Scrooge, deixara entrar duas outras pessoas. Eram cavalheiros corpulentos, de aspecto agradável, e estavam agora, de chapéu na mão, no escritório de Scrooge. Traziam livros e papéis nas mãos e o cumprimentaram com uma reverência.","scroogeandmarleysibelievesaidoneofthegen~ssingmrscroogeormrmarley~111":"— Scrooge e Marley, creio — disse um dos cavalheiros, consultando sua lista. — Tenho o prazer de falar com o Sr. Scrooge ou com o Sr. Marley?","mrmarleyhasbeendeadthesesevenyearsscroog~venyearsagothisverynight~80":"— O Sr. Marley está morto há sete anos — respondeu Scrooge. — Morreu há sete anos, nesta mesma noite.","wehavenodoubthisliberalityiswellrepresen~presentinghiscredentials~104":"— Não temos dúvida de que sua generosidade está bem representada por seu sócio sobrevivente — disse o cavalheiro, apresentando suas credenciais.","itcertainlywasfortheyhadbeentwokindredsp~handedthecredentialsback~127":"Certamente estava; pois haviam sido dois espíritos afins. Diante da palavra agourenta “generosidade”, Scrooge franziu o cenho, balançou a cabeça e devolveu as credenciais.","atthisfestiveseasonoftheyearmrscroogesai~nwantofcommoncomfortssir~270":"— Nesta festiva estação do ano, Sr. Scrooge — disse o cavalheiro, tomando uma pena —, é mais que usualmente desejável que façamos alguma pequena provisão para os pobres e desvalidos, que sofrem muito no momento presente. Muitos milhares carecem do necessário mais comum; centenas de milhares carecem do conforto mais comum, senhor.","aretherenoprisonsaskedscrooge~erenoprisonsaskedscrooge~29":"— Não há prisões? — perguntou Scrooge.","plentyofprisonssaidthegentlemanlayingdow~manlayingdownthepenagain~52":"— Muitas prisões — disse o cavalheiro, pousando de novo a pena.","andtheunionworkhousesdemandedscroogearet~earetheystillinoperation~59":"— E os asilos da Lei dos Pobres? — indagou Scrooge. — Continuam em funcionamento?","theyarestillreturnedthegentlemaniwishico~wishicouldsaytheywerenot~57":"— Continuam. Ainda assim — retrucou o cavalheiro —, gostaria de poder dizer que não.","thetreadmillandthepoorlawareinfullvigour~ullvigourthensaidscrooge~55":"— O Moinho de Pisar e a Lei dos Pobres estão em pleno vigor, então? — disse Scrooge.","bothverybusysir~bothverybusysir~15":"— Ambas muito ativas, senhor.","ohiwasafraidfromwhatyousaidatfirstthatso~roogeiamverygladtohearit~117":"— Ah! Receei, pelo que o senhor disse a princípio, que algo tivesse ocorrido para detê-las em seu útil curso — disse Scrooge. — Alegro-me muito em saber.","undertheimpressionthattheyscarcelyfurnis~swhatshalliputyoudownfor~286":"— Sob a impressão de que mal fornecem à multidão um alento cristão de corpo ou de espírito — retrucou o cavalheiro —, alguns de nós estamos procurando levantar um fundo para comprar aos pobres um pouco de carne e bebida e meios de aquecimento. Escolhemos esta época porque é, de todas, aquela em que a Carência é vivamente sentida e a Abundância se regozija. Com quanto devo anotá-lo?","nothingscroogereplied~nothingscroogereplied~21":"— Com nada! — respondeu Scrooge.","youwishtobeanonymous~youwishtobeanonymous~20":"— O senhor deseja permanecer anônimo?","iwishtobeleftalonesaidscroogesinceyouask~hoarebadlyoffmustgothere~232":"— Desejo que me deixem em paz — disse Scrooge. — Já que me perguntam o que desejo, cavalheiros, essa é a minha resposta. Eu mesmo não faço festa no Natal, e não posso me dar ao luxo de fazer festa para gente ociosa. Ajudo a sustentar os estabelecimentos que mencionei — custam bastante; e os que estão mal de vida devem ir para lá.","manycantgothereandmanywouldratherdie~ereandmanywouldratherdie~36":"— Muitos não podem ir para lá; e muitos preferem morrer.","iftheywouldratherdiesaidscroogetheyhadbe~desexcusemeidontknowthat~107":"— Se preferem morrer — disse Scrooge —, melhor que o façam, e diminuam o excedente da população. Além disso — com licença —, não sei nada disso.","butyoumightknowitobservedthegentleman~owitobservedthegentleman~37":"— Mas o senhor poderia saber — observou o cavalheiro.","itsnotmybusinessscroogereturneditsenough~lygoodafternoongentlemen~152":"— Não é da minha conta — retrucou Scrooge. — Basta a um homem entender de seus próprios negócios e não se meter nos dos outros. Os meus me ocupam constantemente. Boa tarde, cavalheiros!","seeingclearlythatitwouldbeuselesstopursu~emperthanwasusualwithhim~169":"Vendo claramente que seria inútil insistir, os cavalheiros se retiraram. Scrooge retomou seus labores com uma opinião melhorada de si mesmo e de humor mais jocoso do que lhe era habitual.","meanwhilethefoganddarknessthickenedsotha~bysalliedouttobuythebeef~1287":"Entrementes, a névoa e a escuridão se adensaram tanto que as pessoas corriam com tochas flamejantes, oferecendo seus serviços para ir à frente dos cavalos das carruagens e guiá-los pelo caminho. A velha torre de uma igreja, cujo velho sino rouco vivia espiando Scrooge, matreiro, de uma janela gótica na parede, tornou-se invisível, e dava as horas e os quartos entre as nuvens, com trêmulas vibrações depois, como se os dentes batessem em sua cabeça gelada lá no alto. O frio tornou-se intenso. Na rua principal, na esquina do pátio, uns operários consertavam os canos de gás e haviam acendido uma grande fogueira num braseiro, em torno do qual se reunira um bando de homens e meninos esfarrapados, que aqueciam as mãos e piscavam os olhos em êxtase diante das chamas. O hidrante, deixado na solidão, teve seu transbordamento subitamente congelado e transformado em gelo misantropo. O brilho das lojas, onde ramos e bagas de azevinho estalavam ao calor dos lampiões nas vitrines, tornava rubros os rostos pálidos que passavam. O comércio dos aviários e das mercearias se tornou uma esplêndida brincadeira: um cortejo glorioso, com o qual era quase impossível crer que princípios tão enfadonhos quanto o de compra e venda tivessem alguma coisa a ver. O Lorde Prefeito, na fortaleza da poderosa Mansion House, deu ordens a seus cinquenta cozinheiros e mordomos para celebrarem o Natal como deve fazê-lo a casa de um Lorde Prefeito; e até o pequeno alfaiate, a quem ele multara em cinco xelins na segunda-feira anterior por estar bêbado e sanguinário nas ruas, mexia o pudim do dia seguinte em seu sótão, enquanto a magra esposa e o bebê saíam para comprar a carne.","foggieryetandcolderpiercingsearchingbiti~arolbutatthefirstsoundof~354":"Ainda mais nevoeiro, e mais frio! Frio penetrante, esquadrinhador, mordaz. Se o bom São Dunstan tivesse apenas beliscado o nariz do Espírito Maligno com um toque de tempo como aquele, em vez de usar suas armas habituais, então sim ele teria rugido com ótimo efeito. O dono de um escasso narizinho jovem, roído e mastigado pelo frio faminto como ossos são roídos por cães, curvou-se à fechadura de Scrooge para regalá-lo com uma canção de Natal; mas, ao primeiro som de","godblessyoumerrygentlemanmaynothingyoudi~lemanmaynothingyoudismay~44":"“Deus lhe guarde, bom senhor,\nQue nada o faça tremer!”","scroogeseizedtherulerwithsuchenergyofact~ndevenmorecongenialfrost~118":"Scrooge agarrou a régua com tal energia de ação que o cantor fugiu aterrorizado, deixando a fechadura para a névoa e para a geada ainda ainda mais acolhedora.","atlengththehourofshuttingupthecountingho~scandleoutandputonhishat~190":"Por fim chegou a hora de fechar o escritório. De má vontade Scrooge desceu de seu banquinho e admitiu tacitamente o fato ao empregado expectante no aquário, que instantaneamente apagou a vela e pôs o chapéu.","youllwantalldaytomorrowisupposesaidscroo~orrowisupposesaidscrooge~42":"— Você vai querer o dia inteiro de amanhã, suponho? — disse Scrooge.","ifquiteconvenientsir~ifquiteconvenientsir~20":"— Se for perfeitamente conveniente, senhor.","itsnotconvenientsaidscroogeanditsnotfair~ourselfillusedillbebound~101":"— Não é conveniente — disse Scrooge —, e não é justo. Se eu descontasse meia coroa por isso, você se acharia maltratado, aposto?","theclerksmiledfaintly~theclerksmiledfaintly~21":"O empregado sorriu debilmente.","andyetsaidscroogeyoudontthinkmeillusedwh~nipayadayswagesfornowork~65":"— E no entanto — disse Scrooge —, você não acha que eu sou maltratado quando pago um dia de salário por nenhum trabalho.","theclerkobservedthatitwasonlyonceayear~edthatitwasonlyonceayear~38":"O empregado observou que era apenas uma vez por ano.","apoorexcuseforpickingamanspocketeverytwe~alltheearliernextmorning~162":"— Pobre desculpa para meter a mão no bolso de um homem todo vinte e cinco de dezembro! — disse Scrooge, abotoando o sobretudo até o queixo. — Mas suponho que você deva ter o dia todo. Esteja aqui bem mais cedo na manhã seguinte.","theclerkpromisedthathewouldandscroogewal~elttoplayatblindmansbuff~327":"O empregado prometeu que estaria; e Scrooge saiu rosnando. O escritório foi fechado num piscar de olhos, e o empregado, com as longas pontas do cachecol branco pendendo abaixo da cintura (pois não ostentava sobretudo), deslizou vinte vezes num escorregador em Cornhill, no fim de uma fila de meninos, em honra da véspera de Natal, e depois correu para casa, em Camden Town, o mais depressa que pôde, para brincar de cabra-cega.","scroogetookhismelancholydinnerinhisusual~meditationonthethreshold~727":"Scrooge tomou seu melancólico jantar em sua habitual melancólica taverna; e, tendo lido todos os jornais e entretido o resto da noite com a caderneta do banco, foi para casa dormir. Morava em aposentos que haviam pertencido ao seu falecido sócio. Eram uma lúgubre sequência de cômodos, num prédio sombrio ao fundo de um pátio, onde tinha tão pouco que fazer que mal se podia deixar de imaginar que ali chegara correndo quando era uma casa nova, brincando de esconde-esconde com outras casas, e esquecera o caminho de volta. Agora era velha o bastante e tristonha o bastante; pois ninguém morava nela senão Scrooge, estando os outros cômodos todos alugados como escritórios. O pátio era tão escuro que até Scrooge, que lhe conhecia cada pedra, era forçado a tatear com as mãos. A névoa e a geada pairavam de tal modo sobre o velho portal negro da casa que parecia que o Gênio do Tempo estava sentado em mortificada meditação na soleira.","nowitisafactthattherewasnothingatallpart~otaknockerbutmarleysface~615":"Ora, é fato que não havia nada de particular na aldrava da porta, exceto que era muito grande. É também fato que Scrooge a vira, noite e manhã, durante toda a sua residência naquele lugar; também que Scrooge tinha tão pouco do que se chama fantasia quanto qualquer homem da City de Londres, incluindo mesmo — o que é ousadia — a corporação, os vereadores e as associações de ofício. Tenha-se em mente, ainda, que Scrooge não dedicara um só pensamento a Marley desde a última menção ao seu sócio morto havia sete anos naquela tarde. E então que me explique qualquer homem, se puder, como foi que Scrooge, tendo a chave na fechadura da porta, viu na aldrava, sem que esta passasse por qualquer processo intermediário de mudança — não uma aldrava, mas o rosto de Marley.","marleysfaceitwasnotinimpenetrableshadowa~napartofitsownexpression~457":"O rosto de Marley. Não estava em sombra impenetrável, como os demais objetos do pátio, mas tinha em torno de si uma luz lúgubre, como uma lagosta estragada numa adega escura. Não estava irado nem feroz, mas olhava para Scrooge como Marley costumava olhar: com óculos fantasmagóricos erguidos sobre a testa fantasmagórica. O cabelo agitava-se curiosamente, como por um sopro ou ar quente; e, embora os olhos estivessem bem abertos, eram perfeitamente imóveis. Isso, e a cor lívida, tornava-o horrível; mas seu horror parecia ser a despeito do rosto, e fora de seu controle, em vez de parte de sua própria expressão.","asscroogelookedfixedlyatthisphenomenonit~omenonitwasaknockeragain~56":"Enquanto Scrooge fitava esse fenômeno, voltou a ser uma aldrava.","tosaythathewasnotstartledorthathisbloodw~kedinandlightedhiscandle~208":"Dizer que não se assustou, ou que seu sangue não teve consciência de uma terrível sensação a que fora estranho desde a infância, seria inverídico. Mas pôs a mão na chave que havia abandonado, girou-a com firmeza, entrou e acendeu a vela.","hedidpausewithamomentsirresolutionbefore~poohandcloseditwithabang~283":"Deteve-se, sim, com um momento de irresolução, antes de fechar a porta; e olhou, sim, com cautela atrás dela primeiro, como se esperasse meio a meio ser aterrorizado pela visão do rabicho de Marley projetando-se no vestíbulo. Mas não havia nada nas costas da porta, exceto os parafusos e porcas que prendiam a aldrava, de modo que disse: “Pshh, pshh!” e a fechou com um estrondo.","thesoundresoundedthroughthehouselikethun~rimminghiscandleashewent~268":"O som ressoou pela casa como trovão. Todos os cômodos de cima, e todos os tonéis nas adegas do negociante de vinhos lá embaixo, pareciam ter um repique de ecos próprio. Scrooge não era homem para se assustar com ecos. Trancou a porta, atravessou o vestíbulo e subiu a escada: devagar, também: aparando o pavio da vela enquanto ia.","youmaytalkvaguelyaboutdrivingacoachandsi~rettydarkwithscroogesdip~487":"Podem falar vagamente em levar uma carruagem de seis cavalos escada acima de um bom e velho lance de degraus, ou através de uma má e jovem lei do Parlamento; mas eu quero dizer que se poderia ter feito subir um carro funerário por aquela escadaria, de través, com a travessa para a parede e a porta para o corrimão: e fazê-lo com facilidade. Havia largura de sobra para isso, e espaço de reserva; o que talvez seja a razão pela qual Scrooge pensou ver um carro funerário em movimento seguindo à sua frente na penumbra. Meia dúzia de lampiões de gás da rua não teriam iluminado muito bem a entrada, de modo que podem imaginar que estava bem escuro com a vela de sebo de Scrooge.","upscroogewentnotcaringabuttonforthatdark~fthefacetodesiretodothat~190":"Subiu Scrooge, sem se importar um botão com isso. A escuridão é barata, e Scrooge gostava dela. Mas, antes de fechar a pesada porta, percorreu seus aposentos para ver se tudo estava em ordem. Conservava lembrança suficiente do rosto para desejar fazê-lo.","sittingroombedroomlumberroomallastheysho~tandonthreelegsandapoker~373":"Sala de estar, quarto, depósito. Tudo como devia ser. Ninguém debaixo da mesa, ninguém debaixo do sofá; um fogo pequeno na grelha; colher e tigela prontas; e a caçarolinha de mingau (Scrooge estava resfriado) sobre a chapa. Ninguém debaixo da cama; ninguém no armário; ninguém dentro do roupão, que estava pendurado numa atitude suspeita contra a parede. Depósito como de costume. Velho guarda-fogo, sapatos velhos, dois cestos de peixe, lavatório de três pernas e um atiçador.","quitesatisfiedheclosedhisdoorandlockedhi~orethefiretotakehisgruel~214":"Plenamente satisfeito, fechou a porta e trancou-se por dentro; trancou-se com duas voltas, o que não era seu costume. Assim garantido contra surpresas, tirou a gravata; vestiu o roupão, os chinelos e o gorro de dormir; e sentou-se diante do fogo para tomar o mingau.","itwasaverylowfireindeednothingonsuchabit~oldmarleysheadoneveryone~735":"Era um fogo muito baixo, de fato; nada para uma noite tão amarga. Foi obrigado a sentar-se bem perto e a cismar sobre ele, antes de poder extrair a menor sensação de calor de um punhado de combustível como aquele. A lareira era antiga, construída por algum mercador holandês muito tempo atrás, e revestida por todos os lados de curiosos azulejos holandeses, desenhados para ilustrar as Escrituras. Havia Cains e Abéis, filhas de Faraó, Rainhas de Sabá, mensageiros angélicos descendo pelo ar em nuvens como colchões de pena, Abraãos, Baltazares, apóstolos zarpando ao mar em manteigueiras, centenas de figuras para atrair-lhe os pensamentos; e no entanto aquele rosto de Marley, morto havia sete anos, veio como a vara do antigo Profeta, e engoliu o conjunto. Se cada azulejo liso tivesse sido a princípio um espaço em branco, com poder de formar alguma imagem em sua superfície a partir dos fragmentos desconexos de seus pensamentos, haveria uma cópia da cabeça do velho Marley em cada um.","humbugsaidscroogeandwalkedacrosstheroom~geandwalkedacrosstheroom~39":"— Tolice! — disse Scrooge; e atravessou a sala.","afterseveralturnshesatdownagainashethrew~sodideverybellinthehouse~402":"Depois de várias voltas, sentou-se de novo. Ao jogar a cabeça para trás na cadeira, seu olhar por acaso pousou numa campainha, uma campainha em desuso, que pendia na sala e comunicava-se, para algum fim agora esquecido, com um aposento no andar mais alto do edifício. Foi com grande assombro, e com um pavor estranho e inexplicável, que, ao olhar, viu essa campainha começar a balançar. Balançou tão suavemente no começo que mal fazia som; mas logo soou alto, e o mesmo fez cada campainha da casa.","thismighthavelastedhalfaminuteoraminuteb~escribedasdraggingchains~297":"Isso pode ter durado meio minuto, ou um minuto, mas pareceu uma hora. As campainhas cessaram, como haviam começado, todas juntas. Foram sucedidas por um ruído de correntes lá embaixo, bem no fundo, como se alguém arrastasse uma pesada corrente sobre os tonéis na adega do negociante de vinhos. Scrooge então lembrou-se de ter ouvido dizer que os fantasmas em casas assombradas eram descritos arrastando correntes.","thecellardoorflewopenwithaboomingsoundan~ngstraighttowardshisdoor~139":"A porta da adega abriu-se de súbito com um estrondo, e então ele ouviu o ruído muito mais alto nos andares de baixo; depois subindo a escada; depois vindo direto para a sua porta.","itshumbugstillsaidscroogeiwontbelieveit~aidscroogeiwontbelieveit~39":"— Ainda é tolice! — disse Scrooge. — Não vou acreditar.","hiscolourchangedthoughwhenwithoutapausei~marleysghostandfellagain~182":"Mudou de cor, porém, quando, sem uma pausa, o ruído atravessou a pesada porta e entrou na sala diante de seus olhos. Ao entrar, a chama moribunda saltou, como se gritasse: “Eu o conheço! O Fantasma de Marley!”, e tornou a cair.","thesamefacetheverysamemarleyinhispigtail~wobuttonsonhiscoatbehind~434":"O mesmo rosto: exatamente o mesmo. Marley com seu rabicho, colete habitual, calções justos e botas; as borlas destas eriçadas, como o rabicho, as abas do casaco e o cabelo da cabeça. A corrente que arrastava estava presa em volta da cintura. Era longa e enrolava-se em torno dele como uma cauda; e era feita (pois Scrooge a observou de perto) de caixas-fortes, chaves, cadeados, livros-razão, escrituras e pesadas bolsas forjadas em aço. Seu corpo era transparente: de modo que Scrooge, ao observá-lo e olhar através do colete, podia ver os dois botões nas costas do casaco.","scroogehadoftenhearditsaidthatmarleyhadn~dneverbelievedituntilnow~78":"Scrooge ouvira dizer muitas vezes que Marley não tinha entranhas, mas nunca acreditara nisso até agora.","nonordidhebelieveitevennowthoughhelooked~ndfoughtagainsthissenses~288":"Não, nem agora acreditava. Embora olhasse o fantasma de lado a lado e o visse parado diante de si; embora sentisse a influência gélida de seus olhos frios como a morte e notasse a própria textura do lenço dobrado atado em torno da cabeça e do queixo, envoltório que não havia observado antes, continuava incrédulo e lutava contra os próprios sentidos.","hownowsaidscroogecausticandcoldaseverwha~severwhatdoyouwantwithme~56":"— Então! — disse Scrooge, cáustico e frio como sempre. — O que quer de mim?","muchmarleysvoicenodoubtaboutit~rleysvoicenodoubtaboutit~30":"— Muito! — A voz de Marley; não havia dúvida.","whoareyou~whoareyou~9":"— Quem é você?","askmewhoiwas~askmewhoiwas~12":"— Pergunte quem eu fui.","whowereyouthensaidscroogeraisinghisvoice~tedthisasmoreappropriate~122":"— Quem foi você, então? — disse Scrooge, levantando a voz. — É exigente, para uma sombra. — Ia dizer “para uma sombra”, mas substituiu por esta fórmula, por mais apropriada.","inlifeiwasyourpartnerjacobmarley~asyourpartnerjacobmarley~32":"— Em vida, fui seu sócio, Jacob Marley.","canyoucanyousitdownaskedscroogelookingdo~gelookingdoubtfullyathim~53":"— Você pode... você pode sentar-se? — perguntou Scrooge, olhando-o com dúvida.","ican~ican~4":"— Posso.","doitthen~doitthen~8":"— Então sente-se.","scroogeaskedthequestionbecausehedidntkno~easifhewerequiteusedtoit~273":"Scrooge fez a pergunta porque não sabia se um fantasma tão transparente estaria em condições de ocupar uma cadeira; e sentia que, caso fosse impossível, isso poderia exigir uma explicação embaraçosa. Mas o Fantasma sentou-se do lado oposto da lareira, como se estivesse perfeitamente habituado.","youdontbelieveinmeobservedtheghost~ieveinmeobservedtheghost~34":"— Tu não crês em mim — observou o Fantasma.","idontsaidscrooge~idontsaidscrooge~16":"— Não acredito — disse Scrooge.","whatevidencewouldyouhaveofmyrealitybeyon~eyondthatofyourownsenses~60":"— Que prova quererias da minha realidade, além da de teus próprios sentidos?","idontknowsaidscrooge~idontknowsaidscrooge~20":"— Não sei — disse Scrooge.","whydoyoudoubtyoursenses~whydoyoudoubtyoursenses~23":"— Por que duvidas de teus sentidos?","becausesaidscroogealittlethingaffectsthe~veaboutyouwhateveryouare~218":"— Porque — disse Scrooge — uma coisinha qualquer os afeta. Um leve distúrbio do estômago os faz trapacear. Você pode ser um pedaço de carne mal digerido, uma mancha de mostarda, uma migalha de queijo, um fragmento de batata mal cozida. Há mais de molho do que de túmulo em você, seja o que for!","scroogewasnotmuchinthehabitofcrackingjok~dtheverymarrowinhisbones~225":"Scrooge não tinha muito o hábito de fazer gracejos, nem se sentia de modo algum brincalhão no fundo do coração naquele momento. A verdade é que tentava ser espirituoso como meio de distrair a própria atenção e dominar o terror; pois a voz do espectro lhe perturbava o próprio tutano dos ossos.","tositstaringatthosefixedglazedeyesinsile~bythehotvapourfromanoven~339":"Ficar sentado em silêncio, a fitar aqueles olhos fixos e vidrados, por um instante, faria, Scrooge sentia, um diabo de estrago nele. Havia também algo muito pavoroso no fato de o espectro ser dotado de uma atmosfera infernal própria. Scrooge não podia senti-la, mas era claramente o caso; pois, embora o Fantasma estivesse perfeitamente imóvel, seu cabelo, abas e borlas continuavam agitados como pelo vapor quente de um forno.","youseethistoothpicksaidscroogereturningq~ionsstonygazefromhimself~155":"— Está vendo este palito de dentes? — disse Scrooge, voltando prontamente à carga, pela razão há pouco apontada, e desejando, ainda que por um só segundo, desviar de si o olhar pétreo da visão.","idorepliedtheghost~idorepliedtheghost~18":"— Estou — respondeu o Fantasma.","youarenotlookingatitsaidscrooge~otlookingatitsaidscrooge~31":"— Você não está olhando para ele — disse Scrooge.","butiseeitsaidtheghostnotwithstanding~dtheghostnotwithstanding~36":"— Mas o vejo — disse o Fantasma —, apesar disso.","wellreturnedscroogeihavebuttoswallowthis~tionhumbugitellyouhumbug~129":"— Pois bem! — retrucou Scrooge. — Basta eu engolir isto e ser perseguido, pelo resto dos meus dias, por uma legião de duendes, todos de minha própria criação. Tolice, digo-lhe: tolice!","atthisthespiritraisedafrightfulcryandsho~droppeddownuponitsbreast~285":"Diante disso o espírito soltou um grito pavoroso e sacudiu a corrente com um ruído tão lúgubre e apavorante que Scrooge agarrou-se firme à cadeira, para não cair desmaiado. Mas quão maior foi o seu horror quando o fantasma, tirando a bandagem em torno da cabeça, como se fosse quente demais para usar dentro de casa, teve o maxilar inferior caído sobre o peito!","scroogefelluponhiskneesandclaspedhishand~pedhishandsbeforehisface~54":"Scrooge caiu de joelhos e uniu as mãos diante do rosto.","mercyhesaiddreadfulapparitionwhydoyoutro~aritionwhydoyoutroubleme~46":"— Piedade! — disse. — Aparição terrível, por que me atormentas?","manoftheworldlymindrepliedtheghostdoyoub~ostdoyoubelieveinmeornot~55":"— Homem de mente mundana! — replicou o Fantasma. — Crês em mim ou não?","idosaidscroogeimustbutwhydospiritswalkth~arthandwhydotheycometome~66":"— Creio — disse Scrooge —; devo crer. Mas por que os espíritos andam pela terra, e por que vêm a mim?","itisrequiredofeverymantheghostreturnedth~arthandturnedtohappiness~288":"— É exigido de todo homem — retornou o Fantasma — que o espírito dentro dele ande entre seus semelhantes e viaje por toda parte; e, se esse espírito não sai em vida, está condenado a fazê-lo depois da morte. Está fadado a vagar pelo mundo — ai de mim! — e testemunhar o que não pode partilhar, mas poderia ter partilhado na terra e transformado em felicidade!","againthespectreraisedacryandshookitschai~nandwrungitsshadowyhands~64":"De novo o espectro soltou um grito, sacudiu a corrente e torceu as mãos sombrias.","youarefetteredsaidscroogetremblingtellme~croogetremblingtellmewhy~43":"— Estás agrilhoado — disse Scrooge, tremendo. — Diz-me por quê.","iwearthechainiforgedinliferepliedtheghos~isitspatternstrangetoyou~146":"— Visto a corrente que forjei em vida — respondeu o Fantasma. — Fiz elo por elo, e jarda por jarda; cingi-a por minha livre vontade, e por minha livre vontade a usei. O desenho dela te é estranho?","scroogetrembledmoreandmore~roogetrembledmoreandmore~26":"Scrooge tremia cada vez mais.","orwouldyouknowpursuedtheghosttheweightan~sinceitisaponderouschain~172":"— Ou quererias saber — prosseguiu o Fantasma — o peso e o comprimento da forte espiral que tu mesmo carregas? Era tão pesada e tão longa quanto esta, sete vésperas de Natal atrás. Tens trabalhado nela desde então. É uma corrente ponderosa!","scroogeglancedabouthimonthefloorintheexp~ablebuthecouldseenothing~130":"Scrooge olhou em torno de si, no chão, na expectativa de encontrar-se cercado por cinquenta ou sessenta braças de cabo de ferro; mas nada pôde ver.","jacobhesaidimploringlyoldjacobmarleytell~orespeakcomforttomejacob~67":"— Jacob! — disse suplicante. — Velho Jacob Marley, diz-me mais! Dá-me uma palavra de consolo, Jacob!","ihavenonetogivetheghostreplieditcomesfro~wearyjourneysliebeforeme~355":"— Não tenho nenhuma para dar — respondeu o Fantasma. — Ela vem de outras regiões, Ebenezer Scrooge, e é levada por outros ministros a outras espécies de homens. Nem posso dizer-te o que quereria. Muito pouco mais me é permitido. Não posso descansar, não posso ficar, não posso demorar-me em lugar algum. Meu espírito nunca andou além de nosso escritório — repara bem — em vida meu espírito nunca vagou além dos estreitos limites de nosso covil de cambistas; e cansativas jornadas jazem diante de mim!","itwasahabitwithscroogewheneverhebecameth~eyesorgettingoffhisknees~167":"Era hábito de Scrooge, sempre que ficava pensativo, meter as mãos nos bolsos dos calções. Ponderando o que o Fantasma dissera, fê-lo agora, mas sem levantar os olhos nem erguer-se dos joelhos.","youmusthavebeenveryslowaboutitjacobscroo~withhumilityanddeference~101":"— Deves ter sido muito lento nisso, Jacob — observou Scrooge, em tom de negócios, embora com humildade e deferência.","slowtheghostrepeated~slowtheghostrepeated~20":"— Lento! — repetiu o Fantasma.","sevenyearsdeadmusedscroogeandtravellinga~eandtravellingallthetime~49":"— Morto há sete anos — ponderou Scrooge. — E viajando o tempo todo?","thewholetimesaidtheghostnorestnopeaceinc~ncessanttortureofremorse~62":"— O tempo todo — disse o Fantasma. — Sem descanso, sem paz. Incessante tortura do remorso.","youtravelfastsaidscrooge~youtravelfastsaidscrooge~24":"— Viajas depressa? — disse Scrooge.","onthewingsofthewindrepliedtheghost~ofthewindrepliedtheghost~34":"— Nas asas do vento — respondeu o Fantasma.","youmighthavegotoveragreatquantityofgroun~dinsevenyearssaidscrooge~64":"— Poderias ter percorrido uma enorme quantidade de terreno em sete anos — disse Scrooge.","theghostonhearingthissetupanothercryandc~nindictingitforanuisance~149":"O Fantasma, ao ouvir isso, soltou outro grito e fez tinir a corrente de modo tão hediondo no silêncio morto da noite que a Vizinhança teria sido justificada em processá-lo por perturbação.","ohcaptiveboundanddoubleironedcriedthepha~sedyetsuchwasiohsuchwasi~403":"— Oh! cativo, atado e de ferros em dobro — exclamou o fantasma —, não saber que eras de incessante labor, por criaturas imortais, para esta terra, devem passar para a eternidade antes que todo o bem de que ela é suscetível se desenvolva! Não saber que qualquer espírito cristão que trabalhe com bondade em sua pequena esfera, seja ela qual for, achará sua vida mortal curta demais para seus vastos meios de utilidade! Não saber que nenhum espaço de arrependimento pode reparar as oportunidades de uma vida mal empregadas! E no entanto assim fui eu! Oh, assim fui eu!","butyouwerealwaysagoodmanofbusinessjacobf~egantoapplythistohimself~85":"— Mas sempre foste um bom homem de negócios, Jacob — balbuciou Scrooge, que agora começava a aplicar isso a si mesmo.","businesscriedtheghostwringingitshandsaga~hensiveoceanofmybusiness~219":"— Negócios! — exclamou o Fantasma, torcendo de novo as mãos. — A humanidade era o meu negócio. O bem comum era o meu negócio; a caridade, a misericórdia, a tolerância e a benevolência eram, todas, o meu negócio. As transações do meu ofício eram apenas uma gota d’água no oceano abrangente do meu negócio!","itheldupitschainatarmslengthasifthatwere~eavilyuponthegroundagain~106":"Ergueu a corrente à distância do braço, como se ela fosse a causa de toda a sua dor inútil, e atirou-a pesadamente ao chão de novo.","atthistimeoftherollingyearthespectresaid~ightwouldhaveconductedme~228":"— Nesta época do ano que gira — disse o espectro — é que mais sofro. Por que andei por multidões de semelhantes com os olhos baixos, e nunca os ergui àquela abençoada estrela que levou os Magos a uma pobre morada? Não havia lares pobres aos quais sua luz me teria conduzido?","scroogewasverymuchdismayedtohearthespect~dbegantoquakeexceedingly~85":"Scrooge ficou muito consternado ao ouvir o espectro prosseguir nesse tom, e começou a tremer excessivamente.","hearmecriedtheghostmytimeisnearlygone~eghostmytimeisnearlygone~37":"— Ouve-me! — gritou o Fantasma. — Meu tempo está quase esgotado.","iwillsaidscroogebutdontbeharduponmedontb~medontbefloweryjacobpray~57":"— Ouvirei — disse Scrooge. — Mas não sejas duro comigo! Não sejas floreado, Jacob! Por favor!","howitisthatiappearbeforeyouinashapethaty~besideyoumanyandmanyaday~100":"— Como é que apareço diante de ti numa forma que podes ver, não posso dizer. Estive sentado invisível a teu lado muitos e muitos dias.","itwasnotanagreeableideascroogeshiveredan~eperspirationfromhisbrow~72":"Não era uma ideia agradável. Scrooge estremeceu e enxugou o suor da testa.","thatisnolightpartofmypenancepursuedthegh~opeofmyprocuringebenezer~145":"— Essa não é uma parte leve da minha penitência — prosseguiu o Fantasma. — Estou aqui esta noite para avisar-te de que ainda tens uma chance e uma esperança de escapar ao meu destino. Uma chance e uma esperança que obtive para ti, Ebenezer.","youwerealwaysagoodfriendtomesaidscrooget~ndtomesaidscroogethankee~46":"— Sempre foste bom amigo para mim — disse Scrooge. — Obrigado!","youwillbehauntedresumedtheghostbythreesp~edtheghostbythreespirits~45":"— Serás assombrado — retomou o Fantasma — por três espíritos.","scroogescountenancefellalmostaslowastheg~taslowastheghostshaddone~52":"O semblante de Scrooge caiu quase tão baixo quanto o do Fantasma.","isthatthechanceandhopeyoumentionedjacobh~emandedinafalteringvoice~66":"— É essa a chance e a esperança que mencionaste, Jacob? — perguntou ele com voz trêmula.","itis~itis~4":"— É.","iithinkidrathernotsaidscrooge~nkidrathernotsaidscrooge~29":"— Eu... eu acho que preferiria que não — disse Scrooge.","withouttheirvisitssaidtheghostyoucannoth~orrowwhenthebelltollsone~103":"— Sem as visitas deles — disse o Fantasma — não podes esperar evitar o caminho que trilho. Espera o primeiro amanhã, quando o sino bater uma hora.","couldntitakeemallatonceandhaveitoverjaco~itoverjacobhintedscrooge~54":"— Não poderia recebê-los todos de uma vez, e acabar logo com isso, Jacob? — insinuou Scrooge.","expectthesecondonthenextnightatthesameho~erwhathaspassedbetweenus~184":"— Espera o segundo na noite seguinte, à mesma hora. O terceiro, na noite depois desta, quando a última badalada das doze tiver cessado de vibrar. Não esperes ver-me mais; e cuida que, para teu próprio bem, te lembres do que se passou entre nós!","whenithadsaidthesewordsthespectretookits~nwoundoverandaboutitsarm~298":"Ao dizer essas palavras, o espectro tomou da mesa o seu lenço e atou-o em torno da cabeça como antes. Scrooge soube-o pelo estalido seco que seus dentes fizeram quando as mandíbulas foram juntadas pela bandagem. Aventurou-se a erguer os olhos de novo e encontrou seu visitante sobrenatural postado diante dele em atitude ereta, com a corrente enrolada sobre o braço e em torno dele.","theapparitionwalkedbackwardfromhimandate~menonearerscroogestopped~261":"A aparição recuou de costas; e, a cada passo que dava, a janela se erguia um pouco, de modo que, quando o espectro a alcançou, estava escancarada. Acenou a Scrooge que se aproximasse, o que ele fez. Quando estavam a dois passos um do outro, o Fantasma de Marley ergueu a mão, advertindo-o de que não se aproximasse mais. Scrooge parou.","notsomuchinobedienceasinsurpriseandfearf~outuponthebleakdarknight~280":"Não tanto por obediência quanto por surpresa e medo; pois, ao erguer-se a mão, tornou-se ciente de ruídos confusos no ar; sons incoerentes de lamento e pesar; gemidos inexprimivelmente tristes e autoacusatórios. O espectro, depois de escutar por um momento, juntou-se ao fúnebre canto; e flutuou para fora, na noite sombria e desolada.","scroogefollowedtothewindowdesperateinhis~nhiscuriosityhelookedout~60":"Scrooge seguiu até a janela: desesperado em sua curiosidade. Olhou para fora.","theairwasfilledwithphantomswanderinghith~ndhadlostthepowerforever~525":"O ar estava repleto de fantasmas, vagando de cá para lá em pressa inquieta e gemendo ao passar. Cada um deles usava correntes como o Fantasma de Marley; alguns poucos (podiam ser governos culpados) estavam atados uns aos outros; nenhum era livre. Muitos haviam sido pessoalmente conhecidos de Scrooge em vida. Ele fora bastante íntimo de um velho fantasma de colete branco, com um monstruoso cofre de ferro preso ao tornozelo, que chorava lastimosamente por não poder ajudar uma mulher miserável com um bebê, que via embaixo num degrau de porta. A desgraça de todos era claramente que procuravam interferir, para o bem, nos assuntos humanos, e haviam perdido o poder para sempre.","whetherthesecreaturesfadedintomistormist~thadbeenwhenhewalkedhome~152":"Se essas criaturas se desfizeram em névoa, ou se a névoa as envolveu, ele não saberia dizer. Mas elas e suas vozes espirituais desvaneceram-se juntas; e a noite ficou como estava quando ele voltara para casa.","scroogeclosedthewindowandexaminedthedoor~fellasleepupontheinstant~405":"Scrooge fechou a janela e examinou a porta por onde o Fantasma entrara. Estava trancada com duas voltas, como ele mesmo a trancara, e os ferrolhos intactos. Tentou dizer “Tolice!”, mas parou na primeira sílaba. E, sentindo grande necessidade de repouso, fosse pelas emoções por que passara, ou pelas fadigas do dia, ou por seu vislumbre do mundo invisível, ou pela conversa enfadonha do Fantasma, ou pela hora tardia, foi direto para a cama sem se despir e adormeceu no mesmo instante.","whenscroogeawokeitwassodarkthatlookingou~rssohelistenedforthehour~252":"Quando Scrooge despertou, estava tão escuro que, olhando para fora da cama, mal conseguia distinguir a janela transparente das paredes opacas de seu quarto. Esforçava-se por varar a escuridão com seus olhos de furão quando os carrilhões de uma igreja vizinha bateram os quatro quartos. Pôs-se então a escutar a hora.","tohisgreatastonishmenttheheavybellwenton~avegotintotheworkstwelve~192":"Para seu grande assombro, o pesado sino foi de seis a sete, de sete a oito, e regularmente até doze; depois parou. Doze! Passava das duas quando ele fora deitar-se. O relógio estava errado. Algum pingente de gelo devia ter entrado na maquinaria. Doze!","hetouchedthespringofhisrepeatertocorrect~ulsebeattwelveandstopped~104":"Tocou a mola do seu repetidor, para corrigir esse relógio disparatadíssimo. Seu rápido pulsinho bateu doze e parou.","whyitisntpossiblesaidscroogethaticanhave~sunandthisistwelveatnoon~149":"— Ora, não é possível — disse Scrooge — que eu tenha dormido um dia inteiro e boa parte de outra noite. Não é possível que algo tenha acontecido ao sol, e que sejam doze horas do meio-dia!","theideabeinganalarmingonehescrambledouto~therewerenodaystocountby~564":"Sendo a ideia alarmante, ele saltou da cama e foi tateando até a janela. Foi obrigado a esfregar a geada com a manga do roupão antes de poder ver qualquer coisa; e viu muito pouco, então. Tudo o que pôde distinguir foi que ainda havia muita neblina e um frio extremo, e que não se ouvia barulho de gente correndo de um lado para o outro, nem grande agitação, como sem dúvida haveria se a noite tivesse expulsado o claro dia e tomado posse do mundo. Foi um grande alívio, porque “A três dias da vista desta Primeira de Câmbio pague-se ao Sr. Ebenezer Scrooge ou à sua ordem”, e assim por diante, teria se tornado mero título dos Estados Unidos se não houvesse dias pelos quais contar.","scroogewenttobedagainandthoughtandthough~ttothinkthemorehethought~173":"Scrooge voltou para a cama, e pensou, e pensou, e pensou e repensou, e nada conseguiu concluir. Quanto mais pensava, mais perplexo ficava; e, quanto mais se esforçava por não pensar, mais pensava.","marleysghostbotheredhimexceedinglyeveryt~lthroughwasitadreamornot~227":"O Fantasma de Marley o incomodava imensamente. Toda vez que resolvia consigo mesmo, depois de maduro exame, que tudo fora um sonho, seu espírito voltava, como uma forte mola solta, à posição primeira, e apresentava o mesmo problema a resolver por inteiro: “Foi um sonho ou não?”","scroogelayinthisstateuntilthechimehadgon~sestresolutioninhispower~278":"Scrooge ficou nesse estado até que o carrilhão marcasse mais três quartos, quando se lembrou, de súbito, de que o Fantasma o avisara de uma visita quando o sino batesse uma hora. Resolveu ficar acordado até a hora passar; e, considerando que não podia mais dormir do que ir para o céu, essa era, talvez, a mais sensata resolução ao seu alcance.","thequarterwassolongthathewasmorethanonce~brokeuponhislisteningear~136":"O quarto de hora foi tão longo que ele mais de uma vez se convenceu de que devia ter mergulhado num cochilo sem perceber e perdido o relógio. Por fim ele irrompeu em seu ouvido atento.","dingdong~dingdong~8":"— Ding, dong!","aquarterpastsaidscroogecounting~rpastsaidscroogecounting~31":"— Um quarto — disse Scrooge, contando.","halfpastsaidscrooge~halfpastsaidscrooge~19":"— Meia hora — disse Scrooge.","aquartertoitsaidscrooge~aquartertoitsaidscrooge~23":"— Faltando um quarto — disse Scrooge.","thehouritselfsaidscroogetriumphantlyandn~iumphantlyandnothingelse~50":"— A hora em si — disse Scrooge, triunfante — e nada mais!","hespokebeforethehourbellsoundedwhichitno~urtainsofhisbedweredrawn~144":"Falou antes que o sino das horas soasse, o que fez agora, com um profundo, surdo, oco, melancólico Um. A luz irrompeu no quarto no mesmo instante, e as cortinas de sua cama foram abertas.","thecurtainsofhisbedweredrawnasideitellyo~nginthespiritatyourelbow~323":"As cortinas de sua cama foram abertas, digo-lhes, por uma mão. Não as cortinas aos seus pés, nem as às suas costas, mas aquelas para as quais o seu rosto estava voltado. As cortinas de sua cama foram abertas; e Scrooge, sentando-se de um salto numa atitude meio reclinada, viu-se face a face com o visitante sobrenatural que as abrira: tão perto dele como estou agora de vós, e estou em espírito ao vosso cotovelo.","itwasastrangefigurelikeachildyetnotsolik~hichitnowheldunderitsarm~881":"Era uma figura estranha — como uma criança; contudo não tanto como uma criança quanto como um velho, visto através de algum meio sobrenatural que lhe dava a aparência de ter recuado da vista e diminuído a proporções de criança. O cabelo, que lhe pendia em torno do pescoço e pelas costas, era branco, como de velhice; e no entanto o rosto não tinha uma ruga, e o mais terno viço estava na pele. Os braços eram muito longos e musculosos; as mãos também, como se sua pegada fosse de força incomum. As pernas e os pés, delicadíssimos de forma, estavam nus, como aqueles membros superiores. Vestia uma túnica do mais puro branco; e em torno da cintura trazia um cinto lustroso, cujo brilho era belo. Segurava na mão um ramo de azevinho verde e fresco; e, em singular contradição com esse emblema invernal, tinha o vestido guarnecido de flores de verão. Mas o mais estranho nele era que do alto da cabeça jorrava um jato brilhante e claro de luz, pelo qual tudo isso era visível; e que era sem dúvida a razão de ele usar, em seus momentos mais sombrios, um grande apagador por gorro, que agora segurava debaixo do braço.","eventhisthoughwhenscroogelookedatitwithi~indistinctandclearasever~479":"Nem isso, porém, quando Scrooge o olhou com firmeza crescente, era sua qualidade mais estranha. Pois, assim como o cinto cintilava e reluzia, ora numa parte, ora noutra, e o que era luz num instante era escuro em outro, assim a própria figura flutuava em sua nitidez; sendo ora uma coisa com um braço, ora com uma perna, ora com vinte pernas, ora um par de pernas sem cabeça, ora uma cabeça sem corpo: dessas partes em dissolução nenhum contorno se via na densa penumbra em que se desfaziam. E, no próprio assombro disso, voltava a ser ele mesmo; distinto e nítido como sempre.","areyouthespiritsirwhosecomingwasforetold~foretoldtomeaskedscrooge~56":"— É o senhor o Espírito cuja vinda me foi predita? — perguntou Scrooge.","iam~iam~3":"— Sou!","thevoicewassoftandgentlesingularlylowasi~hindhimitwereatadistance~88":"A voz era suave e gentil. Singularmente baixa, como se, em vez de estar tão perto atrás dele, estivesse à distância.","whoandwhatareyouscroogedemanded~hatareyouscroogedemanded~31":"— Quem e o que é o senhor? — quis saber Scrooge.","iamtheghostofchristmaspast~mtheghostofchristmaspast~26":"— Sou o Fantasma do Natal Passado.","longpastinquiredscroogeobservantofitsdwa~vantofitsdwarfishstature~52":"— Passado há muito? — indagou Scrooge, atento à sua estatura anã.","noyourpast~noyourpast~10":"— Não. O teu passado.","perhapsscroogecouldnothavetoldanybodywhy~pandbeggedhimtobecovered~133":"Talvez Scrooge não soubesse dizer a ninguém por quê, se alguém lho pudesse perguntar; mas tinha um desejo especial de ver o Espírito com o gorro, e pediu-lhe que se cobrisse.","whatexclaimedtheghostwouldyousosoonputou~arstowearitlowuponmybrow~183":"— O quê! — exclamou o Fantasma. — Quererias tão cedo apagar, com mãos mundanas, a luz que dou? Não basta que sejas um dos que, com suas paixões, fizeram este gorro e me forçam, por séries inteiras de anos, a usá-lo baixo sobre a fronte?","scroogereverentlydisclaimedallintentiont~tbusinessbroughthimthere~164":"Scrooge reverentemente negou toda intenção de ofender, ou qualquer conhecimento de ter deliberadamente “encapuzado” o Espírito em qualquer época da vida. Ousou então perguntar que negócio o trazia ali.","yourwelfaresaidtheghost~yourwelfaresaidtheghost~23":"— O teu bem-estar! — disse o Fantasma.","scroogeexpressedhimselfmuchobligedbutcou~kingforitsaidimmediately~169":"Scrooge declarou-se muito obrigado, mas não pôde deixar de pensar que uma noite de repouso ininterrupto seria mais conducente a esse fim. O Espírito deve ter ouvido seu pensamento, pois disse imediatamente:","yourreclamationthentakeheed~rreclamationthentakeheed~27":"— A tua regeneração, então. Toma cuidado!","itputoutitsstronghandasitspokeandclasped~claspedhimgentlybythearm~57":"Estendeu a mão forte enquanto falava e segurou-o gentilmente pelo braço.","riseandwalkwithme~riseandwalkwithme~17":"— Levanta-te! e anda comigo!","itwouldhavebeeninvainforscroogetopleadth~peditsrobeinsupplication~369":"Teria sido em vão Scrooge alegar que o tempo e a hora não se prestavam a fins pedestres; que a cama era quente e o termômetro estava muito abaixo de zero; que estava vestido apenas de leve, de chinelos, roupão e gorro de dormir; e que estava resfriado naquele momento. A pegada, embora gentil como a mão de uma mulher, não podia ser resistida. Ele se levantou; mas, vendo que o Espírito se dirigia à janela, agarrou-lhe a túnica em súplica.","iamamortalscroogeremonstratedandliableto~onstratedandliabletofall~44":"— Sou mortal — objetou Scrooge — e sujeito a cair.","bearbutatouchofmyhandtheresaidthespiritl~llbeupheldinmorethanthis~92":"— Suporta apenas um toque da minha mão aqui — disse o Espírito, pousando-a sobre o coração dele — e serás amparado em mais do que isto!","asthewordswerespokentheypassedthroughthe~daywithsnowupontheground~233":"Ditas as palavras, atravessaram a parede e se encontraram numa estrada aberta do campo, com campos de ambos os lados. A cidade desaparecera por completo. Nem vestígio dela se via. A escuridão e a névoa haviam desaparecido com ela, pois era um dia de inverno, claro e frio, com neve no chão.","goodheavensaidscroogeclaspinghishandstog~dinthisplaceiwasaboyhere~94":"— Santo Deus! — disse Scrooge, apertando as mãos, ao olhar em volta. — Fui criado neste lugar. Fui menino aqui!","thespiritgazeduponhimmildlyitsgentletouc~ndcareslonglongforgotten~247":"O Espírito o contemplou com brandura. Seu toque gentil, embora tivesse sido leve e instantâneo, parecia ainda presente ao sentido do tato do velho. Ele estava consciente de mil odores flutuando no ar, cada um ligado a mil pensamentos, e esperanças, e alegrias, e cuidados há muito, muito esquecidos!","yourlipistremblingsaidtheghostandwhatist~dwhatisthatuponyourcheek~56":"— Teu lábio está tremendo — disse o Fantasma. — E o que é isso em tua face?","scroogemutteredwithanunusualcatchinginhi~osttoleadhimwherehewould~100":"Scrooge murmurou, com um embargo incomum na voz, que era uma espinha; e pediu ao Fantasma que o levasse aonde quisesse.","yourecollectthewayinquiredthespirit~tthewayinquiredthespirit~35":"— Recordas o caminho? — indagou o Espírito.","rememberitcriedscroogewithfervouricouldw~ouricouldwalkitblindfold~54":"— Se me lembro! — exclamou Scrooge com fervor. — Poderia percorrê-lo de olhos vendados.","strangetohaveforgottenitforsomanyyearsob~bservedtheghostletusgoon~63":"— Estranho tê-lo esquecido por tantos anos! — observou o Fantasma. — Sigamos.","theywalkedalongtheroadscroogerecognising~ecrispairlaughedtohearit~389":"Caminharam pela estrada, Scrooge reconhecendo cada porteira, e poste, e árvore, até que uma pequena cidade de mercado apareceu ao longe, com sua ponte, sua igreja e seu rio sinuoso. Alguns pôneis felpudos foram vistos agora, trotando em sua direção com meninos nas costas, que chamavam outros meninos em cabriolés e carroças de campo, guiados por fazendeiros. Todos esses meninos estavam em ótimo humor e gritavam uns para os outros, até que os vastos campos ficaram tão cheios de alegre música que o ar fresco ria ao ouvi-la.","thesearebutshadowsofthethingsthathavebee~yhavenoconsciousnessofus~80":"— São apenas sombras das coisas que foram — disse o Fantasma. — Não têm consciência de nós.","thejocundtravellerscameonandastheycamesc~atgoodhaditeverdonetohim~361":"Os alegres viajantes vinham chegando; e, à medida que vinham, Scrooge os conhecia e nomeava, um por um. Por que se rejubilava além de todos os limites ao vê-los? Por que seu olho frio reluzia e seu coração saltava quando passavam? Por que se enchia de contentamento ao ouvi-los desejarem uns aos outros Feliz Natal, ao se despedirem nas encruzilhadas e atalhos rumo às suas várias casas? Que era o feliz Natal para Scrooge? Fora com o feliz Natal! Que bem ele lhe fizera algum dia?","theschoolisnotquitedesertedsaidtheghosta~sfriendsislefttherestill~90":"— A escola não está de todo deserta — disse o Fantasma. — Uma criança solitária, abandonada por seus amigos, ainda é deixada ali.","scroogesaidheknewitandhesobbed~esaidheknewitandhesobbed~30":"Scrooge disse que a conhecia. E soluçou.","theyleftthehighroadbyawellrememberedlane~elightandnottoomuchtoeat~644":"Deixaram a estrada principal por uma alameda bem lembrada e logo se aproximaram de uma mansão de tijolo vermelho e sem brilho, com uma pequena cúpula encimada por um cata-vento no telhado, e um sino pendurado nela. Era uma casa grande, mas de fortunas arruinadas; pois as amplas dependências eram pouco usadas, suas paredes eram úmidas e cobertas de musgo, as janelas quebradas e os portões decadentes. Galinhas cacarejavam e se pavoneavam nos estábulos; e as cocheiras e galpões estavam tomados pelo capim. Nem era mais conservadora do seu antigo estado por dentro; pois, ao entrar no soturno vestíbulo e olhar pelas portas abertas de muitos cômodos, encontraram-nos pobremente mobiliados, frios e vastos. Havia um sabor de terra no ar, uma nudez gélida no lugar, que se associava de algum modo a levantar-se demais à luz de velas e a comer de menos.","theywenttheghostandscroogeacrossthehallt~ottenselfashehadusedtobe~283":"Foram, o Fantasma e Scrooge, através do vestíbulo, até uma porta nos fundos da casa. Ela se abriu diante deles e revelou uma sala comprida, nua e melancólica, tornada ainda mais nua por fileiras de simples bancos e carteiras de pinho. Numa delas um menino solitário lia perto de um fogo débil; e Scrooge sentou-se num banco e chorou ao ver seu pobre eu esquecido como outrora fora.","notalatentechointhehousenotasqueakandscu~eafreerpassagetohistears~322":"Nem um eco latente na casa, nem um guincho e um corre-corre dos camundongos atrás do lambri, nem um gotejar da calha meio degelada no pátio sombrio dos fundos, nem um suspiro entre os ramos desfolhados de um álamo desalentado, nem o balançar ocioso da porta de um armazém vazio, não, nem um estalar no fogo, que não caísse sobre o coração de Scrooge com influência abrandadora e desse livre passagem mais ampla às suas lágrimas.","thespirittouchedhimonthearmandpointedtoh~bridleanassladenwithwood~219":"O Espírito tocou-lhe o braço e apontou o seu eu mais jovem, absorto na leitura. De repente um homem em trajes estrangeiros, maravilhosamente real e distinto de se ver, postou-se do lado de fora da janela, com um machado enfiado no cinto e conduzindo pela rédea um burro carregado de lenha.","whyitsalibabascroogeexclaimedinecstasyit~tobemarriedtotheprincess~435":"— Ora, é Ali Babá! — exclamou Scrooge em êxtase. — É o querido e velho Ali Babá honesto! Sim, sim, eu sei. Numa época de Natal, quando aquela criança solitária ali foi deixada sozinha, ele veio, sim, pela primeira vez, exatamente assim. Pobre menino! E Valentim — disse Scrooge —, e seu irmão selvagem, Orson; lá vão eles! E como é mesmo o nome daquele que foi posto de ceroulas, adormecido, às portas de Damasco; não o vês? E o Cavalariço do Sultão, virado de cabeça para baixo pelos Gênios; lá está ele de cabeça para baixo! Bem feito! Fico contente. Que negócio tinha ele em casar com a Princesa?","tohearscroogeexpendingalltheearnestnesso~ssfriendsinthecityindeed~205":"Ouvir Scrooge gastar toda a seriedade de sua natureza com tais assuntos, numa voz extraordinária entre o riso e o choro; e ver seu rosto afogueado e excitado; teria sido, de fato, uma surpresa para seus colegas de negócios na City.","therestheparrotcriedscroogegreenbodyandy~tlecreekhalloahoophalloo~341":"— Lá está o Papagaio! — gritou Scrooge. — Corpo verde e cauda amarela, com uma coisa como uma alface brotando do alto da cabeça; lá está ele! Pobre Robinson Crusoé, chamou-o ele, quando voltou para casa depois de navegar em torno da ilha. ‘Pobre Robinson Crusoé, onde estiveste, Robinson Crusoé?’ O homem pensou que sonhava, mas não sonhava. Era o Papagaio, sabes. Lá vai Sexta-Feira, correndo pela vida até a pequena enseada! Olá! Hup! Ôôô!","thenwitharapidityoftransitionveryforeign~selfpoorboyandcriedagain~107":"Então, com uma rapidez de transição muito alheia ao seu caráter habitual, disse, com pena do seu eu antigo: “Pobre menino!”, e chorou de novo.","iwishscroogemutteredputtinghishandinhisp~hhiscuffbutitstoolatenow~108":"— Eu queria — murmurou Scrooge, pondo a mão no bolso e olhando em volta, depois de enxugar os olhos com o punho — mas agora é tarde.","whatisthematteraskedthespirit~sthematteraskedthespirit~29":"— Qual é o problema? — perguntou o Espírito.","nothingsaidscroogenothingtherewasaboysin~ivenhimsomethingthatsall~118":"— Nada — disse Scrooge. — Nada. Havia um menino cantando uma canção de Natal à minha porta ontem à noite. Eu gostaria de ter-lhe dado alguma coisa: só isso.","theghostsmiledthoughtfullyandwaveditshan~letusseeanotherchristmas~80":"O Fantasma sorriu, pensativo, e agitou a mão, dizendo ao fazê-lo: — Vejamos outro Natal!","scroogesformerselfgrewlargeratthewordsan~ehomeforthejollyholidays~365":"O eu antigo de Scrooge cresceu ao ouvir as palavras, e a sala se tornou um pouco mais escura e mais suja. Os lambris encolheram, as janelas racharam; fragmentos de reboco caíram do teto, e as ripas nuas apareceram em seu lugar; mas como tudo isso se deu Scrooge sabia tanto quanto vós. Só sabia que estava perfeitamente certo; que tudo acontecera assim; que ali estava ele, sozinho de novo, quando todos os outros meninos tinham ido para casa nas alegres férias.","hewasnotreadingnowbutwalkingupanddowndes~danxiouslytowardsthedoor~134":"Não estava lendo agora, mas andando de um lado para o outro, desesperado. Scrooge olhou para o Fantasma e, com um balançar de cabeça pesaroso, lançou um olhar ansioso para a porta.","itopenedandalittlegirlmuchyoungerthanthe~dhimasherdeardearbrother~135":"Ela se abriu; e uma menina, muito mais nova que o menino, entrou correndo e, atirando os braços ao pescoço dele e beijando-o muitas vezes, chamou-o de “querido, querido irmão”.","ihavecometobringyouhomedearbrothersaidth~ghtobringyouhomehomehome~109":"— Vim levá-lo para casa, querido irmão! — disse a criança, batendo as mãozinhas e inclinando-se para rir. — Levá-lo para casa, para casa, para casa!","homelittlefanreturnedtheboy~elittlefanreturnedtheboy~27":"— Para casa, pequena Fan? — retrucou o menino.","yessaidthechildbrimfulofgleehomeforgooda~erriesttimeinalltheworld~409":"— Sim! — disse a criança, transbordando de alegria. — Para casa de vez. Para casa para sempre. O pai está tão mais bondoso do que costumava ser que a casa é como o céu! Falou tão gentilmente comigo numa noite querida, quando eu ia dormir, que não tive medo de lhe perguntar mais uma vez se você poderia voltar para casa; e ele disse ‘Sim, deve’; e me mandou numa carruagem para buscá-lo. E você vai ser um homem! — disse a criança, arregalando os olhos — e nunca mais voltar para cá; mas primeiro vamos ficar juntos todo o Natal, e ter o tempo mais alegre do mundo inteiro.","youarequiteawomanlittlefanexclaimedthebo~littlefanexclaimedtheboy~41":"— Você já é uma verdadeira mulher, pequena Fan! — exclamou o menino.","sheclappedherhandsandlaughedandtriedtoto~gloathtogoaccompaniedher~199":"Ela bateu palmas, riu e tentou tocar-lhe a cabeça; mas, sendo pequena demais, riu de novo e ergueu-se na ponta dos pés para abraçá-lo. Depois começou a arrastá-lo, em seu ardor infantil, para a porta; e ele, nada relutante em ir, acompanhou-a.","aterriblevoiceinthehallcriedbringdownmas~oftheevergreenslikespray~911":"Uma voz terrível no vestíbulo gritou: “Tragam o baú do Mestre Scrooge aqui!”, e no vestíbulo apareceu o próprio mestre-escola, que lançou ao Mestre Scrooge um olhar de feroz condescendência e o lançou num estado de espírito terrível apertando-lhe a mão. Conduziu-o então, com a irmã, ao mais autêntico poço gelado de uma sala de visitas que jamais se viu, onde os mapas na parede e os globos celeste e terrestre nas janelas estavam cerosos de frio. Ali trouxe uma garrafa de vinho curiosamente leve e um bloco de bolo curiosamente pesado, e administrou prestações dessas iguarias aos jovens; ao mesmo tempo mandando um criado magro oferecer um copo de “alguma coisa” ao postilhão, o qual respondeu que agradecia ao cavalheiro, mas, se era a mesma torneira que provara antes, preferia não. Estando a essa altura o baú do Mestre Scrooge amarrado no alto da caleche, as crianças disseram adeus ao mestre-escola de muito bom grado; e, entrando nela, desceram alegremente a curva do jardim; as rodas ligeiras lançando a geada e a neve das folhas escuras dos sempre-vivas como espuma.","alwaysadelicatecreaturewhomabreathmighth~hostbutshehadalargeheart~83":"— Sempre uma criatura delicada, que um sopro poderia ter murchado — disse o Fantasma. — Mas tinha um grande coração!","soshehadcriedscroogeyourerightiwillnotga~gainsayitspiritgodforbid~62":"— Tinha mesmo — exclamou Scrooge. — Tens razão. Não o negarei, Espírito. Deus me livre!","shediedawomansaidtheghostandhadasithinkc~standhadasithinkchildren~47":"— Morreu mulher feita — disse o Fantasma — e teve, creio, filhos.","onechildscroogereturned~onechildscroogereturned~23":"— Um filho — retrucou Scrooge.","truesaidtheghostyournephew~uesaidtheghostyournephew~26":"— É verdade — disse o Fantasma. — O teu sobrinho!","scroogeseemeduneasyinhismindandansweredb~indandansweredbrieflyyes~49":"Scrooge pareceu inquieto e respondeu brevemente: — Sim.","althoughtheyhadbutthatmomentlefttheschoo~dthestreetswerelightedup~330":"Embora tivessem deixado a escola atrás de si naquele mesmo instante, estavam agora nas movimentadas vias de uma cidade, onde passageiros sombrios passavam e repassavam; onde carroças e coches sombrios disputavam o caminho, e havia toda a luta e o tumulto de uma cidade real. Via-se bem, pelo ornato das lojas, que ali, também, era de novo época de Natal; mas era noite e as ruas estavam iluminadas.","theghoststoppedatacertainwarehousedooran~ndaskedscroogeifheknewit~63":"O Fantasma parou à porta de um certo armazém e perguntou a Scrooge se a conhecia.","knowitsaidscroogewasiapprenticedhere~roogewasiapprenticedhere~36":"— Se a conheço! — disse Scrooge. — Não fui aprendiz aqui?","theywentinatsightofanoldgentlemaninawels~gecriedingreatexcitement~170":"Entraram. À vista de um velho cavalheiro de peruca galesa, sentado atrás de uma escrivaninha tão alta que, se fosse duas polegadas mais alto, teria batido a cabeça no teto, Scrooge exclamou em grande excitação:","whyitsoldfezziwigblesshisheartitsfezziwi~artitsfezziwigaliveagain~51":"— Ora, é o velho Fezziwig! Deus abençoe seu coração, é Fezziwig vivo de novo!","oldfezziwiglaiddownhispenandlookedupatth~leoilyrichfatjovialvoice~223":"O velho Fezziwig pousou a pena e olhou para o relógio, que marcava sete horas. Esfregou as mãos; ajustou o colete amplo; riu-se todo, dos sapatos ao órgão da benevolência; e gritou, com uma voz confortável, oleosa, rica, gorda e jovial:","yohothereebenezerdick~yohothereebenezerdick~21":"— Ei, ô de casa! Ebenezer! Dick!","scroogesformerselfnowgrownayoungmancameb~aniedbyhisfellowprentice~78":"O antigo eu de Scrooge, agora um jovem crescido, entrou vivamente, acompanhado de seu colega aprendiz.","dickwilkinstobesuresaidscroogetotheghost~ewasdickpoordickdeardear~107":"— Dick Wilkins, é claro! — disse Scrooge ao Fantasma. — Valha-me Deus, sim. Lá está ele. Era muito apegado a mim, o Dick. Pobre Dick! Ai, ai!","yohomyboyssaidfezziwignomoreworktonightc~reamancansayjackrobinson~161":"— Ei, rapazes! — disse Fezziwig. — Chega de trabalho esta noite. Véspera de Natal, Dick. Natal, Ebenezer! Vamos pôr as venezianas — gritou o velho Fezziwig, com uma sonora palmada — antes que um homem possa dizer Jack Robinson!","youwouldntbelievehowthosetwofellowswenta~lvepantinglikeracehorses~218":"Não acreditariam como aqueles dois sujeitos se atiraram à tarefa! Investiram rua afora com as venezianas — um, dois, três — puseram-nas nos lugares — quatro, cinco, seis — travaram-nas e pregaram-nas — sete, oito, nove — e voltaram antes que se pudesse contar até doze, arquejando como cavalos de corrida.","hillihocriedoldfezziwigskippingdownfromt~llihodickchirrupebenezer~136":"— Hilli-ho! — gritou o velho Fezziwig, saltando da escrivaninha alta com maravilhosa agilidade. — Limpem tudo, rapazes, e vamos ter bastante espaço aqui! Hilli-ho, Dick! Ânimo, Ebenezer!","clearawaytherewasnothingtheywouldnthavec~retoseeuponawintersnight~346":"Limpar tudo! Não havia nada que não tivessem limpado, ou não pudessem ter limpado, com o velho Fezziwig olhando. Foi feito num minuto. Todo móvel foi removido, como se fosse despedido da vida pública para todo o sempre; o chão foi varrido e molhado, os lampiões aparados, combustível amontoado no fogo; e o armazém ficou um salão de baile tão aconchegante, quente, seco e luminoso quanto se poderia desejar ver numa noite de inverno.","incameafiddlerwithamusicbookandwentuptot~eathimoutofsightorperish~1309":"Entrou um violinista com um livro de música, foi até a alta escrivaninha, fez dela uma orquestra e afinou o instrumento como cinquenta dores de barriga. Entrou a Sra. Fezziwig, um vasto e sólido sorriso. Entraram as três Senhoritas Fezziwig, radiantes e amáveis. Entraram os seis jovens pretendentes cujos corações elas partiam. Entraram todos os rapazes e moças empregados no negócio. Entrou a criada, com o primo padeiro. Entrou a cozinheira com o amigo particular do irmão dela, o leiteiro. Entrou o menino da casa em frente, de quem se suspeitava que não recebia comida suficiente do patrão; tentando esconder-se atrás da menina da casa ao lado da vizinha, comprovadamente com as orelhas puxadas pela patroa. Entraram todos, um após outro; uns tímidos, uns ousados, uns graciosos, uns desajeitados, uns empurrando, uns puxando; entraram todos, de qualquer jeito e de todo jeito. Foram-se todos, vinte pares de uma vez; as mãos meio voltas e de volta ao outro lado; descendo pelo meio e subindo de novo; rodando e rodando em vários estágios de agrupamento afetuoso; o velho primeiro par sempre aparecendo no lugar errado; o novo primeiro par recomeçando assim que chegava; todos primeiros pares afinal, e nenhum último para ajudá-los! Quando se chegou a esse resultado, o velho Fezziwig, batendo palmas para parar a dança, gritou: “Muito bem!”, e o violinista mergulhou o rosto afogueado num caneco de cerveja preta, especialmente providenciado para esse fim. Mas, desprezando o descanso ao reaparecer, recomeçou instantaneamente, embora ainda não houvesse dançarinos, como se o outro violinista tivesse sido levado para casa, exausto, sobre uma tábua, e ele fosse um homem novinho em folha, decidido a derrotá-lo ou perecer.","thereweremoredancesandtherewereforfeitsa~eandhadnonotionofwalking~562":"Houve mais danças, e houve prendas, e mais danças, e houve bolo, e houve ponche quente, e houve um grande pedaço de assado frio, e houve um grande pedaço de cozido frio, e houve tortinhas de frutas, e muita cerveja. Mas o grande efeito da noite veio depois do assado e do cozido, quando o violinista (um cachorro astuto, reparem! o tipo de homem que conhecia o ofício melhor do que vós ou eu poderíamos ter-lho dito!) atacou “Sir Roger de Coverley”. Então o velho Fezziwig saiu para dançar com a Sra. Fezziwig. Primeiro par também; com um bom e rijo trabalho a seu encargo; três ou quatro e vinte pares de companheiros; gente com quem não se brincava; gente que queria dançar e não tinha ideia de caminhar.","butiftheyhadbeentwiceasmanyahfourtimesol~feetagainwithoutastagger~587":"Mas se fossem o dobro — ah! o quádruplo — o velho Fezziwig teria sido páreo para eles, e a Sra. Fezziwig também. Quanto a ela, era digna de ser sua parceira em todos os sentidos do termo. Se isso não é alto elogio, digam-me um mais alto, e eu o usarei. Uma luz positiva parecia emanar das panturrilhas de Fezziwig. Brilhavam em todas as partes da dança como luas. Não se poderia prever, a qualquer momento, o que seria delas em seguida. E quando o velho Fezziwig e a Sra. Fezziwig percorreram toda a dança; avançar e recuar, as duas mãos à parceira, mesura e reverência, saca-rolhas, enfia-a-agulha e de volta ao seu lugar: Fezziwig “cortou” — cortou tão habilmente que parecia piscar com as pernas, e voltou a pousar nos pés sem um tropeço.","whentheclockstruckeleventhisdomesticball~deracounterinthebackshop~346":"Quando o relógio bateu onze horas, esse baile doméstico terminou. O Sr. e a Sra. Fezziwig tomaram seus postos, um de cada lado da porta, e, apertando a mão de cada pessoa individualmente à medida que saía, desejaram-lhe um Feliz Natal. Quando todos se haviam retirado, exceto os dois aprendizes, fizeram o mesmo com eles; e assim as vozes alegres se foram extinguindo, e os rapazes foram deixados às suas camas; que ficavam debaixo de um balcão no fundo da loja.","duringthewholeofthistimescroogehadactedl~ponitsheadburntveryclear~383":"Durante todo esse tempo Scrooge agira como um homem fora de si. Seu coração e sua alma estavam na cena e com o seu eu antigo. Corroborava tudo, lembrava tudo, desfrutava tudo e passava pela mais estranha agitação. Só agora, quando os rostos radiantes do seu eu antigo e de Dick se voltaram para outro lado, é que se lembrou do Fantasma e tomou consciência de que este o fitava em cheio, enquanto a luz em sua cabeça ardia muito clara.","asmallmattersaidtheghosttomakethesesilly~lyfolkssofullofgratitude~62":"— Uma ninharia — disse o Fantasma — para deixar essa gente tola tão cheia de gratidão.","smallechoedscrooge~smallechoedscrooge~18":"— Ninharia! — ecoou Scrooge.","thespiritsignedtohimtolistentothetwoappr~igandwhenhehaddonesosaid~115":"O Espírito fez-lhe sinal para escutar os dois aprendizes, que derramavam o coração em louvor a Fezziwig; e, quando ele o fez, disse:","whyisitnothehasspentbutafewpoundsofyourm~thathedeservesthispraise~104":"— Ora! Não é? Ele gastou apenas algumas libras de vosso dinheiro mortal: três ou quatro, talvez. É tanto assim que mereça esse louvor?","itisntthatsaidscroogeheatedbytheremarkan~sgreatasifitcostafortune~353":"— Não é isso — disse Scrooge, exaltado pela observação e falando inconscientemente como seu eu antigo, e não o recente. — Não é isso, Espírito. Ele tem o poder de nos fazer felizes ou infelizes; de tornar nosso serviço leve ou pesado; um prazer ou uma labuta. Digamos que seu poder reside em palavras e olhares; em coisas tão ligeiras e insignificantes que é impossível somá-las e contá-las: e então? A felicidade que ele dá é tão grande quanto se custasse uma fortuna.","hefeltthespiritsglanceandstopped~espiritsglanceandstopped~32":"Sentiu o olhar do Espírito e parou.","whatisthematteraskedtheghost~isthematteraskedtheghost~28":"— Qual é o problema? — perguntou o Fantasma.","nothingparticularsaidscrooge~ingparticularsaidscrooge~28":"— Nada de particular — disse Scrooge.","somethingithinktheghostinsisted~ngithinktheghostinsisted~31":"— Algo, creio? — insistiu o Fantasma.","nosaidscroogenoishouldliketobeabletosaya~tomyclerkjustnowthatsall~73":"— Não — disse Scrooge —, não. Gostaria de poder dizer uma ou duas palavras ao meu empregado agora mesmo. Só isso.","hisformerselfturneddownthelampsashegaveu~odsidebysideintheopenair~110":"Seu eu antigo baixou os lampiões ao dar expressão ao desejo; e Scrooge e o Fantasma de novo estavam lado a lado ao ar livre.","mytimegrowsshortobservedthespiritquick~rtobservedthespiritquick~38":"— Meu tempo se esgota — observou o Espírito. — Depressa!","thiswasnotaddressedtoscroogeortoanyonewh~fthegrowingtreewouldfall~351":"Isso não foi dirigido a Scrooge, nem a ninguém que ele pudesse ver, mas produziu efeito imediato. Pois de novo Scrooge viu a si mesmo. Estava mais velho agora; um homem no vigor da vida. Seu rosto não tinha as linhas duras e rígidas dos anos posteriores; mas começara a ostentar os sinais da preocupação e da avareza. Havia um movimento ávido, ganancioso, inquieto no olhar, que mostrava a paixão que criara raízes e onde cairia a sombra da árvore em crescimento.","hewasnotalonebutsatbythesideofafairyoung~ftheghostofchristmaspast~145":"Não estava só, mas sentava-se ao lado de uma bela jovem em vestido de luto: em cujos olhos havia lágrimas, que cintilavam na luz que emanava do Fantasma do Natal Passado.","itmatterslittleshesaidsoftlytoyouverylit~ihavenojustcausetogrieve~153":"— Pouco importa — disse ela baixinho. — Para você, muito pouco. Outro ídolo me substituiu; e, se ele puder alegrá-lo e confortá-lo nos tempos vindouros como eu teria tentado fazer, não tenho justa causa para me afligir.","whatidolhasdisplacedyouherejoined~asdisplacedyouherejoined~33":"— Que ídolo a substituiu? — retrucou ele.","agoldenone~agoldenone~10":"— Um de ouro.","thisistheevenhandeddealingoftheworldhesa~rityasthepursuitofwealth~155":"— Eis a equanimidade do mundo! — disse ele. — Não há nada com que seja tão duro quanto com a pobreza; e nada que professe condenar com tal severidade quanto a busca da riqueza!","youfeartheworldtoomuchsheansweredgentlya~gainengrossesyouhaveinot~208":"— Você teme demais o mundo — respondeu ela gentilmente. — Todas as suas outras esperanças se fundiram na esperança de estar fora do alcance de sua sórdida reprovação. Vi suas aspirações mais nobres caírem uma a uma, até que a paixão-mestra, o Ganho, o absorvesse. Não é verdade?","whatthenheretortedevenifihavegrownsomuch~niamnotchangedtowardsyou~76":"— E daí? — retorquiu ele. — Mesmo que eu tenha ficado tão mais sensato, e daí? Não mudei para com você.","sheshookherhead~sheshookherhead~15":"Ela balançou a cabeça.","ami~ami~3":"— Mudei?","ourcontractisanoldoneitwasmadewhenwewere~wasmadeyouwereanotherman~175":"— Nosso compromisso é antigo. Foi feito quando ambos éramos pobres e contentes de sê-lo, até que, em boa hora, pudéssemos melhorar nossa fortuna mundana por nossa paciente laboriosidade. Você mudou. Quando foi feito, você era outro homem.","iwasaboyhesaidimpatiently~wasaboyhesaidimpatiently~25":"— Eu era um menino — disse ele, impaciente.","yourownfeelingtellsyouthatyouwerenotwhat~ughtofitandcanreleaseyou~235":"— Seu próprio sentimento lhe diz que você não era o que é — retrucou ela. — Eu sou. Aquilo que prometia felicidade quando éramos um só coração está carregado de miséria agora que somos dois. Quantas vezes e quão intensamente pensei nisso não direi. Basta que tenha pensado, e possa libertá-lo.","haveieversoughtrelease~haveieversoughtrelease~22":"— Alguma vez pedi libertação?","inwordsnonever~inwordsnonever~14":"— Em palavras. Não. Nunca.","inwhatthen~inwhatthen~10":"— Em quê, então?","inachangednatureinanalteredspiritinanoth~eoutandtrytowinmenowahno~254":"— Numa natureza mudada; num espírito alterado; noutra atmosfera de vida; noutra esperança como seu grande fim. Em tudo o que dava algum valor ou preço ao meu amor a seus olhos. Se isto nunca tivesse existido entre nós — disse a moça, olhando-o com brandura, mas com firmeza —, diga-me, você me procuraria e tentaria me conquistar agora? Ah, não!","heseemedtoyieldtothejusticeofthissupposi~withastruggleyouthinknot~93":"Ele pareceu ceder à justeza dessa suposição, a despeito de si mesmo. Mas disse, com esforço: — Você acha que não.","iwouldgladlythinkotherwiseificouldsheans~rtheloveofhimyouoncewere~447":"— De bom grado pensaria de outro modo, se pudesse — respondeu ela. — Deus sabe! Quando aprendi uma Verdade como esta, sei quão forte e irresistível ela deve ser. Mas se você fosse livre hoje, amanhã, ontem, posso eu mesma acreditar que escolheria uma moça sem dote — você que, na própria confiança com ela, pesa tudo pelo Ganho: ou, escolhendo-a, se por um momento fosse infiel o bastante ao seu único princípio orientador para fazê-lo, não sei eu que seu arrependimento e pesar certamente se seguiriam? Sei; e liberto-o. De coração pleno, pelo amor daquele que você já foi.","hewasabouttospeakbutwithherheadturnedfro~dturnedfromhimsheresumed~54":"Ele ia falar; mas, com a cabeça voltada para o outro lado, ela retomou:","youmaythememoryofwhatispasthalfmakesmeho~pyinthelifeyouhavechosen~214":"— Você pode — a memória do que passou me faz quase esperar que sim — sentir dor nisto. Um tempo muito, muito breve, e você dispensará a lembrança disso com prazer, como um sonho inútil, do qual foi bom que acordasse. Que seja feliz na vida que escolheu!","shelefthimandtheyparted~shelefthimandtheyparted~23":"Ela o deixou, e separaram-se.","spiritsaidscroogeshowmenomoreconductmeho~ydoyoudelighttotortureme~68":"— Espírito! — disse Scrooge. — Não me mostres mais! Leva-me para casa. Por que te comprazes em torturar-me?","oneshadowmoreexclaimedtheghost~dowmoreexclaimedtheghost~30":"— Mais uma sombra! — exclamou o Fantasma.","nomorecriedscroogenomoreidontwishtoseeit~twishtoseeitshowmenomore~52":"— Não mais! — gritou Scrooge. — Não mais! Não desejo ver. Não me mostres mais!","buttherelentlessghostpinionedhiminbothhi~oobservewhathappenednext~82":"Mas o implacável Fantasma o prendeu pelos dois braços e o forçou a observar o que acontecia a seguir.","theywereinanothersceneandplacearoomnotve~nmanenoughtoknowitsvalue~1371":"Estavam em outra cena e lugar; um aposento, não muito grande nem elegante, mas cheio de conforto. Perto do fogo de inverno sentava-se uma bela jovem, tão parecida com a última que Scrooge acreditou ser a mesma, até vê-la, agora uma matrona graciosa, sentada em frente à filha. O barulho nessa sala era perfeitamente tumultuoso, pois havia ali mais crianças do que Scrooge, em seu estado de espírito agitado, era capaz de contar; e, diferentemente do célebre rebanho do poema, não eram quarenta crianças comportando-se como uma só, mas cada criança comportando-se como quarenta. As consequências eram escandalosas além de qualquer crença; mas ninguém parecia se importar; pelo contrário, a mãe e a filha riam de coração e se divertiam muito; e esta última, logo começando a misturar-se às brincadeiras, foi saqueada pelos jovens bandoleiros da maneira mais impiedosa. O que eu não teria dado para ser um deles! Embora jamais pudesse ter sido tão rude, não, não! Não teria por toda a riqueza do mundo amassado aquele cabelo trançado e o desmanchado; e quanto ao precioso sapatinho, não o teria arrancado, Deus me abençoe! nem para salvar a vida. Quanto a medir-lhe a cintura de brincadeira, como faziam, ousada ninhada, eu não poderia tê-lo feito; esperaria que meu braço crescesse em torno dela como castigo e nunca mais voltasse a ficar reto. E no entanto eu teria gostado imensamente, confesso, de lhe ter tocado os lábios; de a ter interrogado, para que os abrisse; de ter olhado os cílios de seus olhos baixos, sem fazê-la corar; de ter soltado ondas de cabelo, uma polegada do qual seria uma lembrança sem preço: em suma, eu teria gostado, confesso, de ter a mais leve licença de uma criança, e no entanto ser homem o bastante para saber o seu valor.","butnowaknockingatthedoorwasheardandsucha~eywenttobedandsosubsided~969":"Mas agora se ouviu uma batida à porta, e seguiu-se imediatamente tamanha correria que ela, de rosto sorridente e vestido saqueado, foi levada até lá no centro de um grupo corado e barulhento, bem a tempo de saudar o pai, que chegava acompanhado de um homem carregado de brinquedos e presentes de Natal. Então os gritos e a luta, e o assalto feito ao indefeso carregador! Escalá-lo, com cadeiras por escadas, para mergulhar-lhe nos bolsos, despojá-lo dos pacotes de papel pardo, agarrar-se firme à sua gravata, abraçar-lhe o pescoço, esmurrar-lhe as costas e chutar-lhe as pernas em afeto irreprimível! Os gritos de espanto e deleite com que era recebida a abertura de cada pacote! O terrível anúncio de que o bebê fora apanhado em flagrante a pôr na boca uma frigideira de boneca, e era mais que suspeito de ter engolido um peru fictício, colado a uma travessa de madeira! O imenso alívio de descobrir que era alarme falso! A alegria, a gratidão e o êxtase! São todos igualmente indescritíveis. Basta que, aos poucos, as crianças e suas emoções saíram da sala e, um degrau de cada vez, subiram até o alto da casa, onde foram para a cama, e assim se aquietaram.","andnowscroogelookedonmoreattentivelythan~issightgrewverydimindeed~310":"E agora Scrooge olhava com mais atenção que nunca, quando o dono da casa, tendo a filha carinhosamente apoiada nele, sentou-se com ela e a mãe junto à sua própria lareira; e quando pensou que uma outra criatura assim, igualmente graciosa e cheia de promessas, poderia tê-lo chamado de pai e sido uma primavera no inverno sombrio de sua vida, sua vista ficou de fato muito turva.","bellesaidthehusbandturningtohiswifewitha~iendofyoursthisafternoon~80":"— Belle — disse o marido, voltando-se para a esposa com um sorriso —, vi hoje à tarde um velho amigo seu.","whowasit~whowasit~8":"— Quem era?","guess~guess~5":"— Adivinhe!","howcanitutdontiknowsheaddedinthesamebrea~hingashelaughedmrscrooge~70":"— Como posso? Ora, não sei? — acrescentou no mesmo fôlego, rindo como ele ria. — O Sr. Scrooge.","mrscroogeitwasipassedhisofficewindowanda~loneintheworldidobelieve~189":"— O Sr. Scrooge era. Passei pela janela do escritório dele; e como não estava fechada e ele tinha uma vela lá dentro, mal pude deixar de vê-lo. Seu sócio está à beira da morte, ouço dizer; e lá estava ele sentado, sozinho. Completamente sozinho no mundo, acredito.","spiritsaidscroogeinabrokenvoiceremovemef~iceremovemefromthisplace~52":"— Espírito! — disse Scrooge com voz entrecortada. — Tira-me deste lugar.","itoldyouthesewereshadowsofthethingsthath~ewhattheyaredonotblameme~93":"— Eu te disse que estas eram sombras das coisas que foram — disse o Fantasma. — Que sejam o que são, não me culpes!","removemescroogeexclaimedicannotbearit~geexclaimedicannotbearit~37":"— Tira-me daqui! — exclamou Scrooge. — Não suporto!","heturnedupontheghostandseeingthatitlooke~adshownhimwrestledwithit~138":"Voltou-se para o Fantasma e, vendo que este o olhava com um rosto no qual, de algum modo estranho, havia fragmentos de todos os rostos que lhe mostrara, lutou com ele.","leavemetakemebackhauntmenolonger~akemebackhauntmenolonger~32":"— Deixa-me! Leva-me de volta. Não me assombres mais!","inthestruggleifthatcanbecalledastrugglei~presseditdownuponitshead~291":"Na luta — se é que se pode chamar de luta aquela em que o Fantasma, sem oferecer resistência visível, permanecia imperturbável a qualquer esforço do adversário —, Scrooge reparou que a luz do Espírito ardia alta e brilhante; e, ligando vagamente esse fato à influência que ele exercia sobre si, agarrou o apagador e, num gesto brusco, enfiou-o na cabeça do Espírito.","thespiritdroppedbeneathitsothattheexting~brokenfloodupontheground~185":"O Espírito se afundou sob ele, de modo que o apagador lhe cobriu o corpo inteiro; mas, embora Scrooge o pressionasse com toda a força, não conseguiu esconder a luz, que jorrava por baixo dele, em torrente ininterrupta, sobre o chão.","hewasconsciousofbeingexhaustedandovercom~orehesankintoaheavysleep~201":"Sentiu-se exausto, vencido por uma sonolência irresistível e, além disso, de volta ao seu próprio quarto. Deu ao apagador um último aperto, no qual a mão lhe fraquejou, e mal teve tempo de cambalear até a cama antes de mergulhar num sono pesado.","awakinginthemiddleofaprodigiouslytoughsn~bysurpriseandmadenervous~614":"Despertando no meio de um ronco prodigiosamente rijo e sentando-se na cama para pôr as ideias em ordem, Scrooge não precisou que lhe dissessem que o sino estava de novo a ponto de bater uma hora. Sentiu que recobrara a consciência no momento exato, com o propósito especial de conferenciar com o segundo mensageiro enviado a ele por intercessão de Jacob Marley. Mas, ao perceber que sentia um frio desagradável só de pensar qual das cortinas aquele novo espectro iria afastar, afastou-as todas, uma por uma, com as próprias mãos e, deitando-se de novo, pôs-se de sentinela, olhando em volta da cama. Pois queria desafiar o Espírito no instante em que aparecesse, sem ser apanhado de surpresa e deixar-se tomar de nervosismo.","gentlemenofthefreeandeasysortwhoplumethe~aveastonishedhimverymuch~512":"Os cavalheiros de gênio desembaraçado, que se gabam de conhecer um truque ou dois e de estar em geral à altura do que der e vier, exprimem a vasta amplitude de sua capacidade para a aventura dizendo que servem para tudo, desde o cara ou coroa até o homicídio; entre esses dois extremos opostos, sem dúvida, jaz uma gama bastante larga e abrangente de assuntos. Sem me aventurar por Scrooge tão ousadamente quanto isso, não me incomodo de pedir que acreditem que ele estava preparado para um bom e amplo campo de aparições estranhas, e que nada entre um bebê e um rinoceronte o teria espantado muito.","nowbeingpreparedforalmostanythinghewasno~edinhisslipperstothedoor~947":"Ora, preparado para quase tudo, ele não estava de modo algum preparado para nada; e, por conseguinte, quando o sino bateu uma hora e nenhuma figura apareceu, foi tomado por um violento acesso de tremor. Passaram-se cinco minutos, dez minutos, um quarto de hora, e nada veio. Durante todo esse tempo ele ficou deitado na cama, bem no âmago e no centro de um clarão de luz avermelhada que a inundara quando o relógio anunciou a hora; e essa luz, sendo apenas luz, era mais alarmante que uma dúzia de fantasmas, pois ele não tinha como atinar com o que significava ou o que pretendia, e por vezes temia estar naquele exato momento sendo um interessante caso de combustão espontânea, sem ter sequer o consolo de saber disso. Por fim, no entanto, começou a pensar — como você ou eu teríamos pensado logo de início, pois é sempre a pessoa que não está na situação que sabe o que deveria ter sido feito nela, e sem dúvida o teria feito — por fim, dizia eu, começou a pensar que a fonte e o segredo daquela luz fantasmagórica poderiam estar no aposento contíguo, de onde, seguindo-lhe o rastro, parecia vir. Tomando essa ideia posse total do seu espírito, levantou-se de mansinho e arrastou-se de chinelos até a porta.","themomentscroogeshandwasonthelockastrang~eandbadehimenterheobeyed~87":"No instante em que a mão de Scrooge tocou a fechadura, uma voz estranha o chamou pelo nome e o mandou entrar. Ele obedeceu.","itwashisownroomtherewasnodoubtaboutthatb~ecamepeepingroundthedoor~913":"Era o seu próprio quarto. Disso não havia dúvida. Mas passara por uma transformação surpreendente. As paredes e o teto estavam de tal modo cobertos de verdura viva que parecia um bosque perfeito, de cada canto do qual reluziam bagas brilhantes. As folhas crespas de azevinho, visco e hera refletiam a luz como se uma multidão de pequenos espelhos tivesse sido espalhada ali; e subia pela chaminé um fogaréu tão poderoso quanto aquela petrificação soturna de lareira jamais conhecera no tempo de Scrooge, nem no de Marley, nem em muitos e muitos invernos passados. Amontoados no chão, de modo a formar uma espécie de trono, havia perus, gansos, caça, aves, queijo de cabeça, grandes peças de carne, leitõezinhos, longas guirlandas de salsichas, tortas de frutas picadas, pudins de ameixa, barris de ostras, castanhas em brasa, maçãs de faces coradas, laranjas suculentas, peras saborosas, imensos bolos de Reis e fumegantes tigelas de ponche, que enevoavam o aposento com seu delicioso vapor. Confortavelmente instalado nesse divã, sentava-se um gigante jovial, magnífico de ver, que trazia uma tocha ardente, de forma não muito diferente da cornucópia da Abundância, e a erguia, bem alto, para lançar sua luz sobre Scrooge, que vinha espiando por trás da porta.","comeinexclaimedtheghostcomeinandknowmebe~comeinandknowmebetterman~47":"— Entre! — exclamou o Fantasma. — Entre! E conheça-me melhor, homem!","scroogeenteredtimidlyandhunghisheadbefor~ndhedidnotliketomeetthem~145":"Scrooge entrou timidamente e baixou a cabeça diante daquele Espírito. Já não era o Scrooge obstinado de antes; e, embora os olhos do Espírito fossem claros e bondosos, não gostava de encará-los.","iamtheghostofchristmaspresentsaidthespir~tsaidthespiritlookuponme~52":"— Eu sou o Fantasma do Natal Presente — disse o Espírito. — Olhe para mim!","scroogereverentlydidsoitwasclothedinones~sheathwaseatenupwithrust~566":"Scrooge o fez, reverente. O Espírito vestia uma simples túnica, ou manto, de um verde profundo, orlada de pele branca. A veste caía tão solta sobre a figura que o peito amplo ficava à mostra, como se desdenhasse de ser protegido ou ocultado por qualquer artifício. Os pés, visíveis sob as amplas dobras do traje, também estavam nus; e na cabeça não trazia outra cobertura senão uma coroa de azevinho, aqui e ali salpicada de pingentes de gelo cintilantes. Os cachos castanho-escuros eram longos e soltos; soltos como o semblante afável, o olhar faiscante, a mão aberta, a voz alegre, o porte desembaraçado e o ar jubiloso. À cintura, trazia uma antiga bainha; mas não havia espada dentro, e o velho estojo estava roído de ferrugem.","youhaveneverseenthelikeofmebeforeexclaim~beforeexclaimedthespirit~51":"— Nunca viu ninguém como eu! — exclamou o Espírito.","neverscroogemadeanswertoit~verscroogemadeanswertoit~26":"— Nunca — respondeu Scrooge.","haveneverwalkedforthwiththeyoungermember~eryearspursuedthephantom~126":"— Nunca andou com os membros mais jovens da minha família; refiro-me (pois sou muito jovem) aos meus irmãos mais velhos, nascidos nestes últimos anos? — prosseguiu o fantasma.","idontthinkihavesaidscroogeiamafraidihave~youhadmanybrothersspirit~71":"— Creio que não — disse Scrooge. — Receio que não. Teve muitos irmãos, Espírito?","morethaneighteenhundredsaidtheghost~hteenhundredsaidtheghost~35":"— Mais de mil e oitocentos — disse o Fantasma.","atremendousfamilytoprovideformutteredscr~rovideformutteredscrooge~44":"— Uma família tremenda para sustentar — resmungou Scrooge.","theghostofchristmaspresentrose~stofchristmaspresentrose~30":"O Fantasma do Natal Presente levantou-se.","spiritsaidscroogesubmissivelyconductmewh~toteachmeletmeprofitbyit~161":"— Espírito — disse Scrooge, submisso —, leve-me aonde quiser. Ontem à noite saí por obrigação e aprendi uma lição que agora faz efeito. Esta noite, se tiver algo a me ensinar, deixe-me aproveitar.","touchmyrobe~touchmyrobe~11":"— Toque o meu manto!","scroogedidashewastoldandhelditfast~ashewastoldandhelditfast~34":"Scrooge fez como lhe mandaram e segurou-o com firmeza.","hollymistletoeredberriesivyturkeysgeeseg~tificiallittlesnowstorms~488":"Azevinho, visco, bagas vermelhas, hera, perus, gansos, caça, aves, queijo de cabeça, carne, leitões, salsichas, ostras, tortas, pudins, frutas e ponche, tudo sumiu num instante. O mesmo se deu com o quarto, o fogo, o clarão avermelhado e a hora da noite, e os dois se viram nas ruas da cidade na manhã de Natal, onde (pois o tempo estava rigoroso) as pessoas faziam uma espécie de música áspera, mas animada e não desagradável, raspando a neve do calçamento diante de suas casas e dos telhados, de onde era uma alegria desvairada para os meninos vê-la despencar na rua lá embaixo, desfazendo-se em pequenas tempestades de neve artificiais.","thehousefrontslookedblackenoughandthewin~deavouredtodiffuseinvain~764":"As fachadas das casas pareciam bem negras, e as janelas mais negras ainda, em contraste com o lençol liso e branco de neve sobre os telhados e com a neve mais suja sobre o chão; esta última camada fora sulcada em fundos regos pelas rodas pesadas de carroças e carros: regos que se cruzavam e recruzavam centenas de vezes onde as grandes ruas se bifurcavam, formando canais intrincados, difíceis de seguir na espessa lama amarela e na água gelada. O céu estava sombrio, e as ruas mais curtas se achavam entupidas por uma névoa suja, meio derretida, meio congelada, cujas partículas mais pesadas desciam numa chuva de átomos de fuligem, como se todas as chaminés da Grã-Bretanha, de comum acordo, tivessem pegado fogo e ardessem a seu inteiro contento. Nada havia de muito alegre no clima nem na cidade, e no entanto pairava no ar uma alegria que o ar mais límpido do verão e o sol mais brilhante do verão teriam tentado em vão difundir.","forthepeoplewhowereshovellingawayontheho~andpassionlessexcitement~1422":"Pois as pessoas que removiam a neve dos telhados estavam joviais e cheias de júbilo; gritavam umas para as outras dos parapeitos e de vez em quando trocavam uma bola de neve jocosa — projétil muito mais bem-humorado que muita pilhéria verbosa —, rindo de bom grado se acertava, e não menos de bom grado se errava. As casas de aves ainda estavam entreabertas, e as de frutas resplandeciam em sua glória. Havia grandes cestos redondos e barrigudos de castanhas, com a forma dos coletes de velhos cavalheiros joviais, refestelados às portas e tombando para a rua em sua opulência apoplética; havia cebolas espanholas, rubras, de rosto moreno e largas de cintura, reluzindo na gordura do seu viço como frades espanhóis e piscando das prateleiras, com libertina malícia, para as moças que passavam e lançavam olhares recatados ao visco pendurado; havia peras e maçãs empilhadas bem alto em pirâmides floridas; havia cachos de uvas que a benevolência dos lojistas fizera pender de ganchos bem à vista, para que a boca das pessoas se enchesse d’água de graça ao passarem; havia montes de avelãs, musgosas e castanhas, a evocar, em seu aroma, antigos passeios pelos bosques e agradáveis arrastares de pés, até os tornozelos, em folhas secas; havia maçãs Biffin de Norfolk, atarracadas e morenas, realçando o amarelo das laranjas e dos limões e, na grande compacidade de suas suculentas pessoas, rogando e suplicando com insistência que as levassem para casa em sacos de papel e as comessem depois do jantar. Até os peixinhos dourados e prateados, postos numa tigela entre essas frutas escolhidas, embora membros de uma raça apática e de sangue parado, pareciam saber que algo se passava; e, todos eles, nadavam arfando em volta do seu pequeno mundo, numa excitação lenta e sem paixão.","thegrocersohthegrocersnearlyclosedwithpe~sdawstopeckatiftheychose~1176":"As mercearias! Ah, as mercearias! Quase fechadas, com talvez duas portas de ferro baixadas, ou uma; mas que vislumbres por essas frestas! Não era só que as balanças, descendo sobre o balcão, faziam um som alegre, ou que o barbante e o carretel se despediam com tanta presteza, ou que as latas eram sacudidas para cima e para baixo como truques de malabarista, ou nem mesmo que os cheiros misturados de chá e café fossem tão gratos ao nariz, ou que as passas fossem tão fartas e raras, as amêndoas tão extremamente brancas, os paus de canela tão longos e retos, as outras especiarias tão deliciosas, as frutas cristalizadas tão empedradas e salpicadas de açúcar derretido a ponto de dar tontura, e depois enjoo, ao mais frio dos espectadores. Nem que os figos fossem úmidos e polpudos, ou que as ameixas francesas corassem em modesta acidez nas caixas ricamente enfeitadas, ou que tudo fosse bom de comer e vestido de Natal; mas os fregueses estavam todos tão apressados e tão ansiosos na esperançosa promessa do dia que se atropelavam à porta, entrechocando loucamente os cestos de vime, deixavam as compras no balcão e voltavam correndo para buscá-las, e cometiam centenas de enganos semelhantes, no melhor humor possível; ao passo que o merceeiro e seus empregados eram tão francos e viçosos que os corações polidos com que prendiam o avental nas costas bem poderiam ser os seus próprios, usados do lado de fora para inspeção geral e para os gaios do Natal bicarem, se quisessem.","butsoonthesteeplescalledgoodpeoplealltoc~dsoitwasgodloveitsoitwas~713":"Mas logo os campanários chamaram toda a boa gente à igreja e à capela, e lá se foram eles, em bando pelas ruas, com suas melhores roupas e seus semblantes mais alegres. E ao mesmo tempo emergiram, de dezenas de travessas, vielas e esquinas sem nome, inumeráveis pessoas que levavam o jantar às padarias. A visão desses pobres festeiros pareceu interessar muito ao Espírito, pois ele parou com Scrooge ao lado, à porta de uma padaria, e, destampando as travessas à passagem de quem as levava, espargia incenso sobre os jantares com sua tocha. E era uma tocha muito incomum, pois uma ou duas vezes, quando houve palavras ásperas entre alguns carregadores de jantar que haviam esbarrado uns nos outros, ele derramou sobre eles algumas gotas de água, e o bom humor lhes voltou de imediato. Pois disseram que era uma vergonha brigar no dia de Natal. E era mesmo! Deus abençoe, era mesmo!","intimethebellsceasedandthebakerswereshut~fitsstoneswerecookingtoo~212":"Com o tempo os sinos cessaram e as padarias fecharam; e, no entanto, havia uma afável insinuação de todos aqueles jantares e do andamento do seu cozimento na mancha úmida e degelada sobre o forno de cada padeiro, onde o calçamento fumegava como se as pedras também estivessem cozinhando.","isthereapeculiarflavourinwhatyousprinkle~romyourtorchaskedscrooge~65":"— Há um sabor peculiar no que o senhor espalha com a tocha? — perguntou Scrooge.","thereismyown~thereismyown~12":"— Há. O meu próprio.","woulditapplytoanykindofdinneronthisdayas~neronthisdayaskedscrooge~50":"— Serviria para qualquer tipo de jantar neste dia? — perguntou Scrooge.","toanykindlygiventoapooronemost~indlygiventoapooronemost~30":"— Para qualquer um dado com bondade. E mais ainda para um jantar pobre.","whytoapooronemostaskedscrooge~apooronemostaskedscrooge~29":"— Por que mais ainda para um jantar pobre? — perguntou Scrooge.","becauseitneedsitmost~becauseitneedsitmost~20":"— Porque é o que mais precisa.","spiritsaidscroogeafteramomentsthoughtiwo~itiesofinnocentenjoyment~146":"— Espírito! — disse Scrooge, depois de um momento de reflexão. — Admira-me que o senhor, entre todos os seres dos muitos mundos que nos cercam, deseje restringir a essa gente a oportunidade de um divertimento inocente.","icriedthespirit~icriedthespirit~15":"— Eu! — exclamou o Espírito.","youwoulddeprivethemoftheirmeansofdininge~allsaidscroogewouldntyou~121":"— O senhor os privaria dos meios de jantar a cada sétimo dia, muitas vezes o único dia em que se pode dizer que jantam — disse Scrooge. — Não é verdade?","youseektoclosetheseplacesontheseventhday~anditcomestothesamething~75":"— O senhor procura fechar estes lugares no Sétimo Dia — disse Scrooge. — E dá no mesmo.","iseekexclaimedthespirit~iseekexclaimedthespirit~23":"— Eu procuro! — exclamou o Espírito.","forgivemeifiamwrongithasbeendoneinyourna~tofyourfamilysaidscrooge~80":"— Perdoe-me se me engano. Isso foi feito em seu nome, ou ao menos no de sua família — disse Scrooge.","therearesomeuponthisearthofyoursreturned~rdoingsonthemselvesnotus~255":"— Há alguns sobre esta sua terra — replicou o Espírito — que afirmam nos conhecer e que praticam suas ações de paixão, orgulho, malevolência, ódio, inveja, intolerância e egoísmo em nosso nome, e que são tão estranhos a nós e a toda a nossa parentela como se nunca tivessem vivido. Lembre-se disso e atribua os atos deles a eles próprios, não a nós.","scroogepromisedthathewouldandtheywentoni~ldhavedoneinanyloftyhall~352":"Scrooge prometeu que o faria; e prosseguiram, invisíveis como antes, rumo aos subúrbios da cidade. Era uma qualidade notável do Fantasma (que Scrooge observara na padaria) que, apesar do seu tamanho gigantesco, se acomodava com facilidade a qualquer lugar; e que ficava sob um teto baixo com tanta graça e tanto ar de criatura sobrenatural quanto lhe teria sido possível num salão elevado.","andperhapsitwasthepleasurethegoodspirith~lessedhisfourroomedhouse~482":"E talvez fosse o prazer que o bom Espírito sentia em exibir esse poder, ou então sua natureza bondosa, generosa e cordial, e sua simpatia por todos os homens pobres, que o levou direto à casa do empregado de Scrooge; pois para lá foi, levando Scrooge consigo, agarrado ao seu manto; e no limiar da porta o Espírito sorriu e parou para abençoar a morada de Bob Cratchit com as aspersões da sua tocha. Imaginem só! Bob ganhava apenas quinze “bobs” por semana; embolsava aos sábados somente quinze cópias do seu nome de batismo; e no entanto o Fantasma do Natal Presente abençoou a sua casa de quatro cômodos!","thenuprosemrscratchitcratchitswifedresse~anlidtobeletoutandpeeled~849":"Então levantou-se a Sra. Cratchit, mulher de Cratchit, vestida de modo pobre num vestido virado duas vezes, mas garbosa nas fitas, que são baratas e fazem boa figura por seis pence; e pôs a toalha na mesa, ajudada por Belinda Cratchit, segunda de suas filhas, também garbosa nas fitas; enquanto o jovem Peter Cratchit espetava um garfo na panela de batatas e, enfiando na boca as pontas do seu monstruoso colarinho (propriedade particular de Bob, concedida ao filho e herdeiro em honra do dia), regozijava-se por se ver tão galantemente trajado e ansiava por exibir sua roupa branca nos parques da moda. E agora dois Cratchits menores, menino e menina, entraram em disparada, gritando que, diante da padaria, tinham sentido o cheiro do ganso e o reconheceram como sendo o deles; e, banhando-se em luxuosos pensamentos de sálvia e cebola, esses jovens Cratchits dançavam em torno da mesa e exaltavam o jovem Peter Cratchit até as nuvens, enquanto ele (sem orgulho, embora os colarinhos quase o sufocassem) soprava o fogo, até que as batatas lentas, borbulhando, bateram forte na tampa da panela para serem soltas e descascadas.","whathasevergotyourpreciousfatherthensaid~christmasdaybyhalfanhour~120":"— Mas que será que reteve o seu precioso pai? — disse a Sra. Cratchit. — E o seu irmão, Tiny Tim? E a Martha não chegou tão tarde no último Natal, nem por meia hora!","heresmarthamothersaidagirlappearingasshe~agirlappearingasshespoke~45":"— Aqui está a Martha, mãe! — disse uma moça, aparecendo enquanto falava.","heresmarthamothercriedthetwoyoungcratchi~ahtheressuchagoosemartha~70":"— Aqui está a Martha, mãe! — gritaram os dois pequenos Cratchits. — Hurra! Tem um ganso, Martha, que ganso!","whyblessyourheartalivemydearhowlateyouar~tforherwithofficiouszeal~129":"— Ora, Deus te abençoe, minha querida, como chegou tarde! — disse a Sra. Cratchit, beijando-a uma dúzia de vezes e tirando-lhe o xale e a touca com zelo solícito.","wedadealofworktofinishuplastnightreplied~earawaythismorningmother~81":"— Tínhamos muito trabalho para acabar ontem à noite — respondeu a moça — e tivemos de arrumar tudo esta manhã, mãe!","wellnevermindsolongasyouarecomesaidmrscr~randhaveawarmlordblessye~97":"— Bem! Não importa, contanto que tenha vindo — disse a Sra. Cratchit. — Sente-se junto ao fogo, minha querida, e aqueça-se, Deus te abençoe!","nonotheresfathercomingcriedthetwoyoungcr~hereatoncehidemarthahide~84":"— Não, não! Lá vem o pai — gritaram os dois pequenos Cratchits, que estavam em toda parte ao mesmo tempo. — Esconda-se, Martha, esconda-se!","somarthahidherselfandincamelittlebobthef~bssupportedbyanironframe~267":"Assim, Martha se escondeu, e entrou o pequeno Bob, o pai, com pelo menos um metro de cachecol, sem contar a franja, pendendo à frente, e as roupas surradas remendadas e escovadas para parecerem apresentáveis, e Tiny Tim sobre o ombro. Ai de Tiny Tim, trazia uma pequena muleta e as pernas sustentadas por uma armação de ferro!","whywheresourmarthacriedbobcratchitlookin~dbobcratchitlookinground~46":"— Ora, onde está a nossa Martha? — gritou Bob Cratchit, olhando em volta.","notcomingsaidmrscratchit~notcomingsaidmrscratchit~24":"— Não vem — disse a Sra. Cratchit.","notcomingsaidbobwithasuddendeclensioninh~otcominguponchristmasday~144":"— Não vem! — disse Bob, com uma súbita queda no seu bom humor; pois fora o cavalo de Tim durante todo o caminho desde a igreja e chegara em casa empinando. — Não vem no dia de Natal!","marthadidntliketoseehimdisappointedifitw~uddingsinginginthecopper~227":"Martha não quis vê-lo desapontado, ainda que fosse só de brincadeira; então saiu antes da hora de trás da porta do armário e correu para os braços dele, enquanto os dois pequenos Cratchits empurravam Tiny Tim e o levavam para a lavanderia, para que ouvisse o pudim cantando na caldeira.","andhowdidlittletimbehaveaskedmrscratchit~ughtertohisheartscontent~118":"— E como se comportou o pequeno Tim? — perguntou a Sra. Cratchit, depois de zombar de Bob pela sua credulidade e de Bob abraçar a filha à vontade.","asgoodasgoldsaidbobandbettersomehowheget~eggarswalkandblindmensee~275":"— Como um anjo — disse Bob — e melhor ainda. De alguma forma, ele fica pensativo, sentado sozinho tanto tempo, e pensa as coisas mais estranhas que já se ouviram. Disse-me, na volta, que esperava que o pessoal o tivesse visto na igreja, porque era aleijado, e talvez lhes fosse agradável lembrar, no dia de Natal, quem fez os mendigos coxos andarem e os cegos verem.","bobsvoicewastremulouswhenhetoldthemthisa~asgrowingstrongandhearty~100":"A voz de Bob tremia quando lhes contou isso, e tremeu mais quando disse que Tiny Tim estava ficando forte e robusto.","hisactivelittlecrutchwashearduponthefloo~returnedinhighprocession~414":"Ouviu-se no chão a sua ativa mulinha de muleta, e voltou Tiny Tim, antes que outra palavra fosse dita, escoltado pelo irmão e pela irmã até o seu banquinho junto ao fogo; e, enquanto Bob, arregaçando os punhos — como se, pobre homem, fossem capazes de ficar mais surrados —, preparava uma mistura quente numa jarra com gim e limões, mexia-a de um lado para o outro e a punha na trempe para ferver em fogo brando, o jovem Peter e os dois onipresentes pequenos Cratchits foram buscar o ganso, com o qual logo voltaram em solene procissão.","suchabustleensuedthatyoumighthavethought~nifeandfeeblycriedhurrah~910":"Seguiu-se tal alvoroço que se poderia pensar que um ganso era a mais rara de todas as aves, um fenômeno emplumado, perto do qual um cisne negro era coisa corriqueira — e, na verdade, era algo muito parecido com isso naquela casa. A Sra. Cratchit fez o molho (preparado de antemão numa pequena panela) chiar de quente; o jovem Peter amassou as batatas com vigor incrível; a Srta. Belinda adoçou o molho de maçã; Martha limpou o pó dos pratos quentes; Bob acomodou Tiny Tim a seu lado num cantinho da mesa; os dois pequenos Cratchits puseram cadeiras para todos, sem esquecer de si mesmos, e, montando guarda em seus postos, enfiaram colheres na boca, para não gritarem por ganso antes de chegar a vez de serem servidos. Por fim os pratos foram postos e se disse a oração. Seguiu-se uma pausa sem fôlego, enquanto a Sra. Cratchit, olhando devagar ao longo da faca de trinchar, preparava-se para cravá-la no peito; mas quando o fez, e quando jorrou o tão esperado recheio, ergueu-se um murmúrio de deleite em volta da mesa, e até Tiny Tim, excitado pelos dois pequenos Cratchits, bateu na mesa com o cabo da faca e gritou fracamente: “Hurra!”","thereneverwassuchagoosebobsaidhedidntbel~thepuddingupandbringitin~539":"Nunca houve um ganso assim. Bob disse que não acreditava que alguma vez se tivesse cozinhado um ganso assim. A maciez e o sabor, o tamanho e o preço baixo eram os temas da admiração geral. Completado com molho de maçã e purê de batatas, foi jantar suficiente para a família toda; aliás, como disse a Sra. Cratchit com grande deleite (examinando um pequeno átomo de osso no prato), não tinham comido tudo, afinal! Contudo, todos estavam satisfeitos, e os Cratchits mais novos, em particular, estavam encharcados de sálvia e cebola até as sobrancelhas! Mas agora, trocados os pratos pela Srta. Belinda, a Sra. Cratchit deixou a sala sozinha — nervosa demais para suportar testemunhas — para ir buscar o pudim e trazê-lo.","supposeitshouldnotbedoneenoughsupposeits~rtsofhorrorsweresupposed~234":"E se não estivesse bem cozido! E se se despedaçasse ao desenformar! E se alguém tivesse pulado o muro do quintal e o roubado, enquanto eles se divertiam com o ganso — suposição que deixou lívidos os dois pequenos Cratchits! Supuseram-se horrores de todo tipo.","halloagreatdealofsteamthepuddingwasoutof~tmashollystuckintothetop~379":"Oba! Muito vapor! O pudim saíra da caldeira. Um cheiro de dia de lavagem! Era o pano. Um cheiro de restaurante e de confeitaria lado a lado, com uma lavadeira ao lado desta! Era o pudim! Em meio minuto entrou a Sra. Cratchit — ruborizada, mas sorrindo orgulhosa — com o pudim, qual bala de canhão salpicada, duro e firme, ardendo em meio quartilho de conhaque em chamas e enfeitado com azevinho de Natal espetado no alto.","ohawonderfulpuddingbobcratchitsaidandcal~lushedtohintatsuchathing~387":"Ah, que pudim maravilhoso! Bob Cratchit disse, e com toda a calma, que o considerava o maior sucesso alcançado pela Sra. Cratchit desde o casamento. A Sra. Cratchit disse que, agora que o peso lhe saíra da consciência, confessaria que tivera dúvidas quanto à quantidade de farinha. Todos tiveram algo a dizer a respeito, mas ninguém disse nem pensou que fosse um pudim pequeno para uma família grande. Seria pura heresia fazê-lo. Qualquer Cratchit teria corado só de insinuar tal coisa.","atlastthedinnerwasalldonetheclothwasclea~custardcupwithoutahandle~368":"Por fim o jantar terminou, tirou-se a toalha, varreu-se a lareira e avivou-se o fogo. Provada a mistura da jarra e considerada perfeita, puseram-se maçãs e laranjas na mesa e uma pá cheia de castanhas no fogo. Então toda a família Cratchit se reuniu em torno da lareira no que Bob Cratchit chamava de círculo, querendo dizer meio círculo; e junto ao cotovelo de Bob ficava a exibição de vidro da família. Dois copos e uma xícara de creme sem alça.","theseheldthehotstufffromthejughoweverasw~ednoisilythenbobproposed~171":"Estes, porém, continham a bebida quente da jarra tão bem quanto teriam contido cálices de ouro; e Bob a serviu com olhar radiante, enquanto as castanhas no fogo estalavam e crepitavam ruidosamente. Então Bob propôs:","amerrychristmastousallmydearsgodblessus~tousallmydearsgodblessus~39":"— Um feliz Natal a todos nós, meus queridos. Deus nos abençoe!","whichallthefamilyreechoed~hichallthefamilyreechoed~25":"Ao que toda a família fez eco.","godblessuseveryonesaidtinytimthelastofal~esaidtinytimthelastofall~41":"— Deus nos abençoe, a todos! — disse Tiny Tim, o último de todos.","hesatveryclosetohisfatherssideuponhislit~hathemightbetakenfromhim~162":"Sentava-se bem junto ao pai, em seu banquinho. Bob segurava a mãozinha mirrada dele na sua, como se amasse o menino, quisesse mantê-lo a seu lado e temesse que lhe fosse tirado.","spiritsaidscroogewithaninteresthehadneve~etellmeiftinytimwilllive~74":"— Espírito — disse Scrooge, com um interesse que nunca sentira antes —, diga-me se Tiny Tim viverá.","iseeavacantseatrepliedtheghostinthepoorc~thefuturethechildwilldie~149":"— Vejo um assento vazio — respondeu o Fantasma — no canto pobre da chaminé, e uma muleta sem dono, cuidadosamente conservada. Se essas sombras não forem alteradas pelo Futuro, a criança morrerá.","nonosaidscroogeohnokindspiritsayhewillbe~dspiritsayhewillbespared~46":"— Não, não — disse Scrooge. — Oh, não, bondoso Espírito! Diga que ele será poupado.","iftheseshadowsremainunalteredbythefuture~easethesurpluspopulation~157":"— Se essas sombras não forem alteradas pelo Futuro, nenhum outro da minha raça — replicou o Fantasma — o encontrará aqui. E daí? Se ele está para morrer, é melhor que o faça e diminua o excesso de população.","scroogehunghisheadtohearhisownwordsquote~omewithpenitenceandgrief~87":"Scrooge baixou a cabeça ao ouvir as próprias palavras citadas pelo Espírito e foi tomado de penitência e dor.","mansaidtheghostifmanyoubeinheartnotadama~shungrybrothersinthedust~340":"— Homem — disse o Fantasma —, se homem você é no coração, e não diamante, abstenha-se dessa hipocrisia perversa até descobrir qual é o excesso e onde ele está. Decidirá você quais homens hão de viver, quais hão de morrer? Pode ser que, aos olhos do Céu, você seja mais inútil e menos digno de viver do que milhões como o filho deste pobre homem. Ó Deus! Ouvir o inseto na folha pronunciar-se sobre o excesso de vida entre seus irmãos famintos no pó!","scroogebentbeforetheghostsrebukeandtremb~edilyonhearinghisownname~110":"Scrooge curvou-se diante da repreensão do Fantasma e, trêmulo, fixou os olhos no chão. Mas logo os ergueu ao ouvir o próprio nome.","mrscroogesaidbobillgiveyoumrscroogethefo~oogethefounderofthefeast~55":"— Sr. Scrooge! — disse Bob. — Brindo ao Sr. Scrooge, o Fundador da Festa!","thefounderofthefeastindeedcriedmrscratch~edhaveagoodappetiteforit~134":"— O Fundador da Festa, imagine só! — exclamou a Sra. Cratchit, enrubescendo. — Quisera tê-lo aqui. Daria a ele um pedaço do meu pensamento para banquetear-se, e espero que tivesse bom apetite.","mydearsaidbobthechildrenchristmasday~bthechildrenchristmasday~36":"— Minha querida — disse Bob —, as crianças! É Natal.","itshouldbechristmasdayiamsuresaidsheonwh~etterthanyoudopoorfellow~163":"— Há de ser Natal, com certeza — disse ela —, para se beber à saúde de um homem tão odioso, avarento, duro e insensível como o Sr. Scrooge. Você sabe que ele é, Robert! Ninguém sabe melhor que você, pobre homem!","mydearwasbobsmildanswerchristmasday~bsmildanswerchristmasday~35":"— Minha querida! — foi a resposta branda de Bob. — É Natal.","illdrinkhishealthforyoursakeandthedayssa~andveryhappyihavenodoubt~145":"— Beberei à saúde dele por você e pelo dia — disse a Sra. Cratchit —, não por ele. Vida longa a ele! Um feliz Natal e um próspero Ano-Novo! Ele há de estar muito feliz e muito próspero, não duvido!","thechildrendrankthetoastafterheritwasthe~pelledforfullfiveminutes~247":"As crianças beberam o brinde depois dela. Foi a primeira de suas ações em que não houve cordialidade. Tiny Tim bebeu por último, mas não ligou a mínima. Scrooge era o papão da família. A menção do seu nome lançou uma sombra escura sobre a reunião, que não se dissipou por uns bons cinco minutos.","afterithadpassedawaytheyweretentimesmerr~eandsangitverywellindeed~991":"Passada ela, ficaram dez vezes mais alegres que antes, pelo simples alívio de se terem livrado de Scrooge, o Funesto. Bob Cratchit contou-lhes que tinha em vista uma colocação para o jovem Peter, que renderia, se a obtivesse, bons cinco xelins e seis pence por semana. Os dois pequenos Cratchits riram tremendamente da ideia de Peter ser um homem de negócios; e o próprio Peter olhou pensativo para o fogo, por entre os colarinhos, como se estivesse deliberando que investimentos particulares favoreceria quando entrasse na posse daquela renda desnorteante. Martha, que era uma pobre aprendiz de modista, contou-lhes então que tipo de trabalho tinha de fazer, quantas horas trabalhava de uma vez e como pretendia ficar de cama na manhã seguinte para um bom e longo descanso, sendo o dia seguinte um feriado que passaria em casa. Contou também como vira uma condessa e um lorde alguns dias antes, e como o lorde “era mais ou menos da altura de Peter”; ao que Peter puxou o colarinho tão alto que não se teria visto sua cabeça se se estivesse ali. Durante todo esse tempo as castanhas e a jarra circulavam; e logo ouviram uma canção, sobre uma criança perdida viajando na neve, cantada por Tiny Tim, que tinha uma vozinha plangente e a cantou muito bem.","therewasnothingofhighmarkinthistheyweren~llyontinytimuntilthelast~407":"Nada havia de notável nisso. Não eram uma família bonita; não eram bem vestidos; seus sapatos estavam longe de ser impermeáveis; as roupas eram escassas; e Peter bem poderia conhecer, e muito provavelmente conhecia, o interior de uma casa de penhores. Mas eram felizes, agradecidos, contentes uns com os outros e satisfeitos com o momento; e quando se esvaneceram, parecendo ainda mais felizes nas brilhantes aspersões da tocha do Espírito à despedida, Scrooge não tirou os olhos deles, e especialmente de Tiny Tim, até o fim.","bythistimeitwasgettingdarkandsnowingpret~heswelltheyknewitinaglow~705":"Nessa altura escurecia e nevava forte; e, enquanto Scrooge e o Espírito percorriam as ruas, era maravilhoso o brilho dos fogos crepitantes nas cozinhas, nas salas e em toda sorte de aposentos. Aqui, o bruxulear das chamas mostrava os preparativos de um jantar aconchegante, com pratos quentes assando por inteiro diante do fogo, e cortinas vermelho-escuras prontas para serem corridas e deixarem do lado de fora o frio e a escuridão. Ali, todas as crianças da casa corriam para a neve ao encontro de irmãs, irmãos, primos, tios e tias casados, para serem as primeiras a saudá-los. Aqui, ainda, viam-se sombras de convidados reunindo-se nas cortinas das janelas; e ali um grupo de lindas moças, todas de capuz e botas forradas de pele, todas tagarelando ao mesmo tempo, corria levemente à casa de algum vizinho próximo; onde, ai do homem solteiro que as visse entrar — bruxas astutas, bem o sabiam —, em brasa!","butifyouhadjudgedfromthenumbersofpeopleo~adanycompanybutchristmas~590":"Mas, se julgasse pelo número de pessoas a caminho de reuniões amigáveis, pensaria que não havia ninguém em casa para recebê-las quando chegassem, em vez de cada casa esperar visitas e empilhar o fogo até a metade da chaminé. Bendito seja, como o Fantasma exultava! Como expunha a largura do peito, abria a palma imensa e flutuava, derramando com mão generosa sua alegria brilhante e inofensiva sobre tudo ao seu alcance! O próprio acendedor de lampiões, que corria à frente salpicando a rua escura de pontos de luz, e que estava vestido para passar a noite em algum lugar, riu alto à passagem do Espírito, embora o acendedor mal soubesse que tinha outra companhia além do Natal.","andnowwithoutawordofwarningfromtheghostt~thickgloomofdarkestnight~455":"E agora, sem uma palavra de aviso do Fantasma, viram-se numa charneca árida e deserta, onde massas monstruosas de pedra bruta jaziam espalhadas, como se fosse o cemitério de gigantes; e a água se espraiava para onde bem queria, ou o faria, não fosse a geada que a mantinha prisioneira; e nada crescia senão musgo, tojo e capim áspero e rançoso. Lá no poente, o sol que se punha deixara uma faixa de vermelho ardente, que fuzilou por um instante sobre a desolação, como um olho carrancudo e, franzindo-se mais baixo, mais baixo, mais baixo ainda, perdeu-se na densa escuridão da noite mais negra.","whatplaceisthisaskedscrooge~tplaceisthisaskedscrooge~27":"— Que lugar é este? — perguntou Scrooge.","aplacewhereminerslivewholabourinthebowel~hespiritbuttheyknowmesee~84":"— Um lugar onde vivem mineiros, que labutam nas entranhas da terra — respondeu o Espírito. — Mas eles me conhecem. Veja!","alightshonefromthewindowofahutandswiftly~toppedhisvigoursankagain~553":"Uma luz brilhava na janela de uma cabana, e eles avançaram depressa em sua direção. Atravessando a parede de barro e pedra, encontraram uma alegre companhia reunida em torno de um fogo cintilante. Um velho, velhíssimo homem e uma mulher, com os filhos, os filhos dos filhos e ainda outra geração além desta, todos alegremente adornados em trajes de festa. O velho, numa voz que raramente se alçava acima do uivo do vento sobre o ermo estéril, cantava-lhes uma canção de Natal; já era uma canção muito antiga quando ele era menino; e de vez em quando todos se juntavam ao refrão. Tão certo como levantavam a voz, o velho ficava bem animado e ruidoso; e tão certo como paravam, seu vigor tornava a baixar.","thespiritdidnottarryherebutbadescroogeho~triedtounderminetheearth~315":"O Espírito não se demorou ali, mas mandou Scrooge segurar-lhe o manto e, passando por cima da charneca, precipitou-se para onde? Não para o mar? Para o mar. Para horror de Scrooge, olhando para trás, viu a última terra, uma assustadora cadeia de rochedos, atrás deles; e seus ouvidos se ensurdeceram com o troar da água, que rolava, rugia e se enfurecia entre as cavernas terríveis que escavara, tentando ferozmente minar a terra.","builtuponadismalreefofsunkenrockssomelea~tlikethewavestheyskimmed~268":"Construído sobre um sombrio recife de rochas submersas, a uma légua ou pouco mais da costa, onde as águas se agitavam e se chocavam o ano inteiro, erguia-se um farol solitário. Grandes montes de algas agarravam-se à sua base, e pássaros de tempestade — nascidos do vento, poder-se-ia supor, como as algas da água — subiam e desciam em volta dele, como as ondas que roçavam.","butevenheretwomenwhowatchedthelighthadma~thatwaslikeagaleinitself~371":"Mas até ali dois homens que velavam a luz haviam feito fogo, que pela seteira na espessa parede de pedra lançava um raio de claridade sobre o mar pavoroso. Unindo as mãos calejadas por sobre a rude mesa em que se sentavam, desejaram-se Feliz Natal na sua caneca de grogue; e um deles — o mais velho, com o rosto todo castigado e marcado por cicatrizes do mau tempo, como a figura de proa de um navio antigo — entoou uma canção robusta, que era em si uma ventania.","againtheghostspedonabovetheblackandheavi~eydelightedtorememberhim~607":"De novo o Fantasma se precipitou, por cima do mar negro e encapelado — avante, avante — até que, estando longe, como disse a Scrooge, de qualquer costa, pousaram num navio. Ficaram ao lado do timoneiro na roda do leme, do vigia na proa, dos oficiais de quarto; figuras escuras e fantasmagóricas em seus diversos postos; mas todos os homens entre eles cantarolavam uma melodia de Natal, ou tinham um pensamento de Natal, ou falavam baixinho ao companheiro de algum Natal passado, com esperanças de volta ao lar que a ele pertenciam. E todo homem a bordo, desperto ou adormecido, bom ou mau, tivera nesse dia uma palavra mais gentil para os outros que em qualquer outro dia do ano; e participara em alguma medida de suas festividades; e se lembrara dos que lhe eram caros à distância, e soubera que eles se comprazem em lembrar-se dele.","itwasagreatsurprisetoscroogewhilelisteni~wwithapprovingaffability~434":"Foi grande surpresa para Scrooge, enquanto escutava o gemido do vento e pensava quão solene era avançar pela escuridão solitária sobre um abismo desconhecido, cujas profundezas eram segredos tão profundos quanto a morte: foi grande surpresa para Scrooge, assim ocupado, ouvir uma risada cordial. Foi surpresa muito maior reconhecê-la como a do seu próprio sobrinho e achar-se numa sala clara, seca e reluzente, com o Espírito sorrindo a seu lado e olhando para o mesmo sobrinho com afabilidade aprovadora!","hahalaughedscroogesnephewhahaha~ghedscroogesnephewhahaha~31":"— Ah, ah! — riu o sobrinho de Scrooge. — Ah, ah, ah!","ifyoushouldhappenbyanyunlikelychancetokn~cultivatehisacquaintance~164":"Se por acaso, por algum improvável acaso, você conhecer um homem mais abençoado numa risada que o sobrinho de Scrooge, só posso dizer que também gostaria de conhecê-lo. Apresente-o a mim, e cultivarei sua amizade.","itisafairevenhandednobleadjustmentofthin~hindhandroaredoutlustily~376":"É um ajuste justo, equânime e nobre das coisas que, enquanto há contágio na doença e na tristeza, nada no mundo seja tão irresistivelmente contagioso quanto o riso e o bom humor. Quando o sobrinho de Scrooge ria dessa maneira — segurando os lados, balançando a cabeça e torcendo o rosto nas contorções mais extravagantes —, a sobrinha de Scrooge por casamento ria tão de coração quanto ele. E os amigos reunidos, não ficando nem um pouco atrás, urravam com vigor.","hahahahahaha~hahahahahaha~12":"— Ah, ah! Ah, ah, ah, ah!","hesaidthatchristmaswasahumbugasilivecrie~gesnephewhebelievedittoo~70":"— Ele disse que o Natal era uma tolice, juro por tudo! — gritou o sobrinho de Scrooge. — E acreditava nisso também!","moreshameforhimfredsaidscroogesnieceindi~estheyarealwaysinearnest~111":"— Que vergonha para ele, Fred! — disse a sobrinha de Scrooge, indignada. Deus abençoe essas mulheres! Nunca fazem nada pela metade. Estão sempre falando sério.","shewasveryprettyexceedinglyprettywithadi~oohperfectlysatisfactory~353":"Era muito bonita; extremamente bonita. Com um rosto cheio de covinhas, de ar surpreso, excelente; uma boquinha madura que parecia feita para ser beijada — como sem dúvida era; todo tipo de boas pintinhas em volta do queixo, que se fundiam umas nas outras quando ela ria; e o par de olhos mais ensolarado que já se viu na cabeça de qualquer criaturinha. Em suma, era o que se chamaria de provocante, sabe; mas satisfatória também. Oh, perfeitamente satisfatória!","hesacomicaloldfellowsaidscroogesnephewth~venothingtosayagainsthim~149":"— É um velho engraçado — disse o sobrinho de Scrooge — e não tão agradável quanto poderia ser, é a verdade. Entretanto, suas ofensas trazem consigo o próprio castigo, e não tenho nada a dizer contra ele.","imsureheisveryrichfredhintedscroogesniec~atleastyoualwaystellmeso~65":"— Tenho certeza de que ele é muito rico, Fred — insinuou a sobrinha de Scrooge. — Pelo menos você sempre me diz isso.","whatofthatmydearsaidscroogesnephewhiswea~ergoingtobenefituswithit~184":"— E daí, minha querida? — disse o sobrinho de Scrooge. — A riqueza dele não lhe serve de nada. Ele não faz nenhum bem com ela. Não se põe confortável com ela. Não tem a satisfação de pensar — ah, ah, ah! — que algum dia vai nos beneficiar com ela.","ihavenopatiencewithhimobservedscroogesni~sexpressedthesameopinion~107":"— Não tenho paciência com ele — observou a sobrinha de Scrooge. As irmãs da sobrinha de Scrooge, e todas as outras damas, expressaram a mesma opinião.","ohihavesaidscroogesnephewiamsorryforhimi~ehedontlosemuchofadinner~208":"— Oh, eu tenho! — disse o sobrinho de Scrooge. — Tenho pena dele; não conseguiria me zangar com ele nem que tentasse. Quem sofre com seus maus caprichos? Ele mesmo, sempre. Aí ele enfia na cabeça que não gosta de nós e não quer vir jantar conosco. Qual a consequência? Não perde grande coisa de jantar.","indeedithinkhelosesaverygooddinnerinterr~droundthefirebylamplight~219":"— Na verdade, acho que perde um jantar muito bom — interrompeu a sobrinha de Scrooge. Todos os outros disseram o mesmo, e há que reconhecer que eram juízes competentes, porque tinham acabado de jantar e, com a sobremesa na mesa, estavam reunidos em volta do fogo, à luz de lampiões.","welliamverygladtohearitsaidscroogesnephe~eeperswhatdoyousaytopper~110":"— Bem! Fico muito contente em saber — disse o sobrinho de Scrooge —, porque não tenho grande fé nessas jovens donas de casa. O que você diz, Topper?","topperhadclearlygothiseyeupononeofscroog~heonewiththerosesblushed~226":"Topper evidentemente tinha posto os olhos numa das irmãs da sobrinha de Scrooge, pois respondeu que um solteirão era um pobre pária, sem direito algum de emitir opinião sobre o assunto. Ao que a irmã da sobrinha de Scrooge — a rechonchuda, de gola de renda; não a das rosas — corou.","dogoonfredsaidscroogesniececlappingherha~eissucharidiculousfellow~100":"— Continue, Fred — disse a sobrinha de Scrooge, batendo palmas. — Ele nunca termina o que começa a dizer! É um sujeito tão ridículo!","scroogesnephewrevelledinanotherlaughanda~lewasunanimouslyfollowed~163":"O sobrinho de Scrooge deleitou-se em outra gargalhada e, como era impossível manter o contágio afastado, embora a irmã rechonchuda se esforçasse para isso com vinagre aromático, seu exemplo foi seguido por unanimidade.","iwasonlygoingtosaysaidscroogesnephewthat~ithinkishookhimyesterday~575":"— Eu só ia dizer — disse o sobrinho de Scrooge — que a consequência de ele ter antipatia por nós e não se divertir conosco é, ao que penso, perder alguns momentos agradáveis, que não lhe fariam mal algum. Tenho certeza de que perde companhias mais agradáveis do que as que encontra nos próprios pensamentos, seja no seu bolorento velho escritório, seja nos seus aposentos empoeirados. Pretendo dar-lhe a mesma oportunidade todos os anos, queira ele ou não, pois tenho pena dele. Pode esbravejar contra o Natal até morrer, mas não pode deixar de pensar melhor dele — desafio-o — se me vir ir até lá, de bom humor, ano após ano, dizendo: ‘Tio Scrooge, como vai?’ Se isso só o puser no estado de ânimo de deixar cinquenta libras ao seu pobre empregado, já é alguma coisa; e creio que o abalei ontem.","itwastheirturntolaughnowatthenotionofhis~dpassedthebottlejoyously~200":"Agora era a vez deles de rir, da ideia de que ele abalasse Scrooge. Mas, sendo de boníssimo gênio e não se importando muito do que riam, contanto que rissem de alguma coisa, ele os animou em sua alegria e passou a garrafa, jovialmente.","afterteatheyhadsomemusicfortheywereamusi~adethatburiedjacobmarley~735":"Depois do chá fizeram música. Pois eram uma família musical e sabiam o que faziam quando cantavam um madrigal ou um cânone, posso lhes garantir: especialmente Topper, que sabia roncar no baixo como ninguém, sem inchar as grandes veias da testa nem ficar vermelho no rosto por isso. A sobrinha de Scrooge tocava bem a harpa; e tocou, entre outras melodias, uma simples cançãozinha (uma bobagem: aprende-se a assobiá-la em dois minutos) que fora familiar à criança que foi buscar Scrooge no internato, como o Fantasma do Natal Passado lhe lembrara. Quando soou essa melodia, tudo o que aquele Fantasma lhe mostrara voltou-lhe à mente; ele foi se abrandando mais e mais; e pensou que, se pudesse tê-la ouvido muitas vezes, anos atrás, teria cultivado as bondades da vida para a própria felicidade, com as próprias mãos, sem recorrer à pá do coveiro que enterrou Jacob Marley.","buttheydidntdevotethewholeeveningtomusic~ogetherbehindthecurtains~1379":"Mas não dedicaram a noite inteira à música. Passado um tempo, brincaram de prendas; pois é bom ser criança às vezes, e nunca melhor do que no Natal, quando o seu poderoso Fundador foi criança também. Esperem! Houve primeiro uma brincadeira de cabra-cega. Claro que houve. E não acredito mais que Topper estivesse realmente cego do que acredito que tivesse olhos nas botas. Minha opinião é que era coisa combinada entre ele e o sobrinho de Scrooge, e que o Fantasma do Natal Presente sabia. O modo como ele perseguia aquela irmã rechonchuda de gola de renda era um ultraje à credulidade da natureza humana. Derrubando os atiçadores, tropeçando nas cadeiras, esbarrando no piano, sufocando-se entre as cortinas, aonde quer que ela fosse, ia ele! Sabia sempre onde estava a irmã rechonchuda. Não apanhava mais ninguém. Se você tivesse esbarrado nele (como alguns fizeram) de propósito, ele teria fingido tentar agarrá-lo, o que seria um insulto à sua inteligência, e instantaneamente teria se esquivado na direção da irmã rechonchuda. Ela muitas vezes gritava que não era justo; e realmente não era. Mas quando, por fim, ele a pegou; quando, apesar de todos os seus frufrus de seda e de seus rápidos esvoaçares ao largo dele, a encurralou num canto de onde não havia escapatória, então sua conduta foi execrável. Pois o fingimento de não a conhecer; o fingimento de que era necessário tocar-lhe o toucado e, além disso, certificar-se da identidade dela apertando certo anel em seu dedo e certa corrente em seu pescoço, era vil, monstruoso! Sem dúvida ela lhe disse o que pensava disso quando, havendo outro cabra-cega em função, ficaram tão confidenciais atrás das cortinas.","scroogesniecewasnotoneoftheblindmansbuff~tashetookitinhisheadtobe~725":"A sobrinha de Scrooge não participava da cabra-cega, mas fora instalada com conforto numa grande poltrona e um escabelo, em um canto aconchegante onde o Fantasma e Scrooge ficavam logo atrás dela. Mas participou das prendas e amou seu amor de modo admirável com todas as letras do alfabeto. Também no jogo de Como, Quando e Onde ela era ótima e, para secreta alegria do sobrinho de Scrooge, derrotou as irmãs por goleada; embora fossem moças espertas também, como Topper poderia lhe dizer. Devia haver umas vinte pessoas ali, jovens e velhas, mas todas brincavam, e Scrooge também; pois, esquecendo por completo, no interesse que tinha no que se passava, que sua voz não soava aos ouvidos deles, às vezes soltava o palpite bem alto, e muito frequentemente acertava; pois a agulha mais afiada, a melhor de Whitechapel, com garantia de não cortar o fio no buraco, não era mais afiada que Scrooge, por obtuso que se tivesse metido na cabeça ser.","theghostwasgreatlypleasedtofindhiminthis~spiritsaidcouldnotbedone~167":"O Fantasma ficou muito satisfeito em encontrá-lo nesse estado de espírito e olhou-o com tal favor que ele implorou, como um menino, que lhe permitisse ficar até os convidados partirem. Mas isso, disse o Espírito, não podia ser feito.","hereisanewgamesaidscroogeonehalfhourspir~onehalfhourspiritonlyone~49":"— Eis um novo jogo — disse Scrooge. — Meia hora, Espírito, só meia hora!","itwasagamecalledyesandnowherescroogesnep~ntoasimilarstatecriedout~722":"Era um jogo chamado Sim e Não, em que o sobrinho de Scrooge tinha de pensar em algo e os demais deviam descobrir o quê, respondendo ele às perguntas apenas com sim ou não, conforme o caso. O fogo cerrado de perguntas a que foi exposto arrancou-lhe que estava pensando num animal, um animal vivo, um animal bastante desagradável, um animal selvagem, um animal que às vezes rosnava e grunhia, às vezes falava, e vivia em Londres, e andava pelas ruas, e não era exibido como espetáculo, e não era conduzido por ninguém, e não vivia num zoológico, e nunca era abatido num mercado, e não era um cavalo, nem um burro, nem uma vaca, nem um touro, nem um tigre, nem um cão, nem um porco, nem um gato, nem um urso. A cada nova pergunta que lhe faziam, o sobrinho explodia numa nova gargalhada; e sentia tantas cócegas inexprimíveis que era obrigado a levantar-se do sofá e bater os pés. Por fim a irmã rechonchuda, caindo em estado semelhante, gritou:","ihavefounditoutiknowwhatitisfrediknowwha~hatitisfrediknowwhatitis~45":"— Descobri! Sei o que é, Fred! Sei o que é!","whatisitcriedfred~whatisitcriedfred~17":"— O que é? — gritou Fred.","itsyourunclescroooooge~itsyourunclescroooooge~22":"— É o seu tio Scro-o-o-o-oge.","whichitcertainlywasadmirationwastheunive~verhadanytendencythatway~237":"Que era, sem dúvida. A admiração foi o sentimento geral, embora alguns objetassem que a resposta a “É um urso?” deveria ter sido “Sim”, visto que uma resposta negativa bastaria para desviar-lhes os pensamentos do Sr. Scrooge, supondo que alguma vez tivessem tido tendência a ele.","hehasgivenusplentyofmerrimentiamsuresaid~omentandisayunclescrooge~153":"— Ele nos deu muita alegria, tenho certeza — disse Fred — e seria ingratidão não beber à saúde dele. Eis um copo de vinho quente à mão neste instante; e eu digo: ‘Tio Scrooge!’","wellunclescroogetheycried~ellunclescroogetheycried~25":"— Bem! Tio Scrooge! — gritaram.","amerrychristmasandahappynewyeartotheoldm~neverthelessunclescrooge~131":"— Um feliz Natal e um próspero Ano-Novo ao velho, seja ele o que for! — disse o sobrinho de Scrooge. — Não o aceitaria de mim, mas que o tenha, ainda assim. Tio Scrooge!","unclescroogehadimperceptiblybecomesogaya~ereagainupontheirtravels~271":"O tio Scrooge se tornara, imperceptivelmente, tão alegre e leve de coração que teria retribuído o brinde à companhia inconsciente e lhe agradecido num discurso inaudível, se o Fantasma lhe tivesse dado tempo. Mas toda a cena se desfez no sopro da última palavra dita pelo sobrinho; e ele e o Espírito estavam outra vez a caminho.","muchtheysawandfartheywentandmanyhomesthe~taughtscroogehisprecepts~394":"Muito viram, longe foram, e muitos lares visitaram, mas sempre com final feliz. O Espírito se punha ao lado de leitos de enfermos, e eles ficavam animados; em terras estrangeiras, e estavam perto de casa; junto a homens em luta, e eram pacientes na sua esperança maior; junto à pobreza, e ela era rica. Em asilo, hospital e cadeia, em todos os refúgios da miséria, onde o homem vaidoso, na sua breve e pequena autoridade, não trancara a porta e barrara a entrada ao Espírito, ele deixou sua bênção e ensinou a Scrooge seus preceitos.","itwasalongnightifitwereonlyanightbutscro~oticedthatitshairwasgrey~404":"Foi uma longa noite, se é que foi apenas uma noite; mas Scrooge tinha suas dúvidas, porque as festas de Natal pareciam condensadas no espaço de tempo que passaram juntos. Era estranho, também, que, enquanto Scrooge permanecia inalterado em sua forma exterior, o Fantasma envelhecia, claramente envelhecia. Scrooge observara essa mudança, mas nunca falou dela até saírem de uma festa infantil da Noite de Reis, quando, olhando para o Espírito, de pé juntos num lugar aberto, notou que seu cabelo estava grisalho.","arespiritslivessoshortaskedscrooge~livessoshortaskedscrooge~34":"— A vida dos espíritos é tão curta? — perguntou Scrooge.","mylifeuponthisglobeisverybriefrepliedthe~iedtheghostitendstonight~58":"— Minha vida neste globo é brevíssima — respondeu o Fantasma. — Termina esta noite.","tonightcriedscrooge~tonightcriedscrooge~19":"— Esta noite! — exclamou Scrooge.","tonightatmidnightharkthetimeisdrawingnea~harkthetimeisdrawingnear~41":"— Esta noite, à meia-noite. Escute! A hora se aproxima.","thechimeswereringingthethreequarterspast~rspastelevenatthatmoment~58":"Os sinos davam, naquele momento, onze e três quartos.","forgivemeifiamnotjustifiedinwhatiasksaid~urskirtsisitafootoraclaw~166":"— Perdoe-me se não tenho justificativa no que pergunto — disse Scrooge, olhando fixamente para o manto do Espírito —, mas vejo algo estranho, que não pertence ao senhor, saindo de suas saias. É um pé ou uma garra?","itmightbeaclawforthefleshthereisuponitwa~tssorrowfulreplylookhere~73":"— Poderia ser uma garra, pela carne que tem — foi a triste resposta do Espírito. — Olhe aqui!","fromthefoldingsofitsrobeitbroughttwochil~ontheoutsideofitsgarment~139":"Das dobras do manto tirou duas crianças, miseráveis, abjetas, assustadoras, hediondas, lastimáveis. Ajoelharam-se a seus pés e agarraram-se ao lado de fora da veste.","omanlookherelooklookdownhereexclaimedthe~ownhereexclaimedtheghost~45":"— Ó Homem! Olhe aqui! Olhe, olhe para baixo! — exclamou o Fantasma.","theywereaboyandgirlyellowmeagreraggedsco~rshalfsohorribleanddread~440":"Eram um menino e uma menina. Amarelos, magros, esfarrapados, carrancudos, lupinos, mas também prostrados em sua humildade. Onde a graciosa juventude deveria ter preenchido seus traços e tocado neles com seus mais frescos matizes, uma mão murcha e enrugada, como a da velhice, os havia beliscado, torcido e reduzido a farrapos. Onde anjos poderiam estar entronizados, demônios espreitavam e fuzilavam ameaças. Nenhuma mudança, nenhuma degradação, nenhuma perversão da humanidade, em qualquer grau, por todos os mistérios da maravilhosa criação, tem monstros metade tão horríveis e pavorosos.","scroogestartedbackappalledhavingthemshow~eofsuchenormousmagnitude~162":"Scrooge recuou, aterrado. Mostrados a ele assim, tentou dizer que eram crianças belas, mas as palavras se sufocaram, antes de serem cúmplices de uma mentira de magnitude tão enorme.","spiritaretheyyoursscroogecouldsaynomore~ursscroogecouldsaynomore~39":"— Espírito! São suas? — Scrooge não conseguiu dizer mais.","theyaremanssaidthespiritlookingdownupont~makeitworseandbidetheend~372":"— São do Homem — disse o Espírito, olhando-as. — E agarram-se a mim, apelando contra os pais. Este menino é a Ignorância. Esta menina é a Miséria. Cuidado com os dois e com todos de sua espécie, mas acima de tudo cuidado com este menino, pois em sua fronte vejo escrito aquilo que é a Perdição, a menos que a escrita seja apagada. Neguem-no! — exclamou o Espírito, estendendo a mão para a cidade. — Caluniem os que vo-lo dizem! Admitam-no para seus fins facciosos e piorem-no! E aguardem o fim!","havetheynorefugeorresourcecriedscrooge~georresourcecriedscrooge~38":"— Não têm refúgio nem recurso? — exclamou Scrooge.","aretherenoprisonssaidthespiritturningonh~ordsaretherenoworkhouses~91":"— Não há prisões? — disse o Espírito, voltando-se contra ele pela última vez com suas próprias palavras. — Não há asilos de pobres?","thebellstrucktwelve~thebellstrucktwelve~19":"O sino bateu doze horas.","scroogelookedabouthimfortheghostandsawit~alongthegroundtowardshim~207":"Scrooge olhou em torno à procura do Fantasma e não o viu. Quando a última badalada cessou de vibrar, lembrou-se da predição do velho Jacob Marley e, erguendo os olhos, avistou um solene Espectro, envolto em panos e capuz, vindo como uma névoa pelo chão em sua direção."}$tr$::jsonb, 464)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- charles-dickens_hard-times (84 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('charles-dickens_hard-times', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"theonethingneedful":"A única coisa necessária","murderingtheinnocents":"Massacrando os Inocentes","aloophole":"Uma Brecha"}$tr$::jsonb, $tr${"nowwhatiwantisfactsteachtheseboysandgirl~echildrensticktofactssir~319":"“Pois bem, o que eu quero são Fatos. Não ensinem a estes meninos e meninas nada além de Fatos. Só os Fatos são necessários na vida. Não plantem mais nada, e arranquem tudo o mais. Só é possível formar a mente de animais racionais com Fatos: nenhuma outra coisa jamais lhes será de serventia. Este é o princípio segundo o qual crio os meus próprios filhos, e é o princípio segundo o qual crio estas crianças. Atenha-se aos Fatos, senhor!”","thescenewasaplainbaremonotonousvaultofas~twasallhelpedtheemphasis~862":"A cena era uma sala de aula simples, nua e monótona como uma abóbada, e o indicador quadrado do orador sublinhava cada frase com um traço na manga do mestre-escola, reforçando suas observações. A ênfase era ajudada pela testa quadrada do orador, uma muralha que tinha as sobrancelhas por base, enquanto seus olhos encontravam um porão espaçoso em duas cavernas escuras, à sombra da muralha. A ênfase era ajudada pela boca do orador, que era larga, fina e firmemente cerrada. A ênfase era ajudada pela voz do orador, que era inflexível, seca e ditatorial. A ênfase era ajudada pelo cabelo do orador, que se eriçava nas bordas da cabeça calva, uma plantação de abetos para proteger do vento a superfície reluzente, toda coberta de calombos, como a crosta de uma torta de ameixa, como se a cabeça mal tivesse espaço de armazém para os duros fatos guardados lá dentro. O porte obstinado do orador, o casaco quadrado, as pernas quadradas, os ombros quadrados — e até mesmo o lenço de pescoço, treinado para agarrá-lo pela garganta com um aperto intransigente, como um fato teimoso que era — tudo ajudava a ênfase.","inthislifewewantnothingbutfactssirnothin~tfactssirnothingbutfacts~49":"“Nesta vida, não queremos senão Fatos, senhor; nada senão Fatos!”","thespeakerandtheschoolmasterandthethirdg~tiltheywerefulltothebrim~225":"O orador, o mestre-escola e a terceira pessoa adulta presente recuaram um pouco, e percorreram com o olhar o plano inclinado de pequenos vasilhames ali dispostos em ordem, prontos para receber galões imperiais de fatos até transbordarem.","thomasgradgrindsiramanofrealitiesamanoff~adofthomasgradgrindnosir~609":"Thomas Gradgrind, senhor. Um homem de realidades. Um homem de fatos e cálculos. Um homem que procede segundo o princípio de que dois e dois são quatro, e nada mais, e que não se deixa convencer a admitir nenhum resto. Thomas Gradgrind, senhor — peremptoriamente Thomas —, Thomas Gradgrind. Com uma régua e um par de balanças, e a tabuada sempre no bolso, senhor, pronto a pesar e medir qualquer parcela da natureza humana e dizer-lhe exatamente a que monta. É mera questão de números, um caso de simples aritmética. O senhor poderia esperar meter alguma outra crença disparatada na cabeça de George Gradgrind, ou de Augustus Gradgrind, ou de John Gradgrind, ou de Joseph Gradgrind (todas pessoas supostas, inexistentes), mas na cabeça de Thomas Gradgrind — não, senhor!","insuchtermsmrgradgrindalwaysmentallyintr~etobefilledsofulloffacts~270":"Nesses termos o Sr. Gradgrind sempre se apresentava mentalmente, fosse ao seu círculo privado de conhecidos, fosse ao público em geral. Nesses termos, sem dúvida, substituindo a palavra “senhor” por “meninos e meninas”, Thomas Gradgrind apresentava agora Thomas Gradgrind aos pequenos cântaros diante dele, que deviam ser enchidos até a borda de fatos.","indeedasheeagerlysparkledatthemfromthece~sthatweretobestormedaway~295":"Com efeito, ao faiscar ansioso para eles do porão já mencionado, parecia uma espécie de canhão carregado até a boca de fatos e preparado para fazê-los voar para fora das regiões da infância num único disparo. Parecia também um aparelho galvanizador, carregado de um sombrio substituto mecânico para as ternas e jovens imaginações que deviam ser varridas.","girlnumbertwentysaidmrgradgrindsquarelyp~nowthatgirlwhoisthatgirl~100":"— Menina número vinte — disse o Sr. Gradgrind, apontando em linha reta com seu indicador quadrado —, não conheço essa menina. Quem é essa menina?","sissyjupesirexplainednumbertwentyblushin~gstandingupandcurtseying~64":"— Sissy Jupe, senhor — explicou a número vinte, corando, levantando-se e fazendo uma reverência.","sissyisnotanamesaidmrgradgrinddontcallyo~sissycallyourselfcecilia~70":"— Sissy não é um nome — disse o Sr. Gradgrind. — Não se chame Sissy. Chame-se Cecília.","itsfatherascallsmesissysirreturnedtheyou~iceandwithanothercurtsey~84":"— É o pai que me chama de Sissy, senhor — respondeu a menina com voz trêmula e outra reverência.","thenhehasnobusinesstodoitsaidmrgradgrind~letmeseewhatisyourfather~90":"— Então ele não tem o direito de fazê-lo — disse o Sr. Gradgrind. — Diga-lhe que não deve. Cecília Jupe. Deixe-me ver. Qual é a profissão de seu pai?","hebelongstothehorseridingifyoupleasesir~orseridingifyoupleasesir~39":"— Ele é do ramo da cavalaria, se o senhor me permite.","mrgradgrindfrownedandwavedofftheobjectio~onablecallingwithhishand~63":"O Sr. Gradgrind franziu a testa e afastou com a mão o ofício censurável.","wedontwanttoknowanythingaboutthathereyou~fatherbreakshorsesdonthe~93":"— Aqui não queremos saber nada disso. Não deve nos falar disso, aqui. Seu pai doma cavalos, não é?","ifyoupleasesirwhentheycangetanytobreakth~obreakhorsesintheringsir~67":"— Se o senhor me permite, quando conseguem cavalos para domar, eles domam cavalos no picadeiro, senhor.","youmustnttellusabouttheringhereverywellt~octorssickhorsesidaresay~103":"— Não deve nos falar de picadeiro, aqui. Muito bem, então. Descreva seu pai como domador de cavalos. Cura cavalos doentes, suponho?","ohyessir~ohyessir~8":"— Ah, sim, senhor.","verywellthenheisaveterinarysurgeonafarri~meyourdefinitionofahorse~85":"— Muito bem, então. É veterinário, ferrador e domador de cavalos. Dê-me a sua definição de cavalo.","sissyjupethrownintothegreatestalarmbythi~reatestalarmbythisdemand~47":"(Sissy Jupe lançada no maior alarme por essa exigência.)","girlnumbertwentyunabletodefineahorsesaid~itionofahorsebitzeryours~202":"— Menina número vinte incapaz de definir um cavalo! — disse o Sr. Gradgrind, para proveito geral de todos os pequenos cântaros. — Menina número vinte desprovida de fatos, a respeito de um dos animais mais comuns! A definição de cavalo de algum menino. Bitzer, a sua.","thesquarefingermovinghereandtherelighted~werecuthewouldbleedwhite~1002":"O dedo quadrado, movendo-se de lá para cá, pousou de repente em Bitzer, talvez porque ele calhasse de se sentar no mesmo raio de sol que, entrando por uma das janelas nuas da sala intensamente caiada, irradiava sobre Sissy. Pois os meninos e meninas se sentavam na face do plano inclinado em dois blocos compactos, divididos ao meio por um intervalo estreito; e Sissy, estando na ponta de uma fileira do lado ensolarado, recebia o início de um raio de sol, do qual Bitzer, na ponta de uma fileira do outro lado, algumas fileiras adiante, pegava o fim. Mas, enquanto a menina tinha olhos e cabelos tão escuros que parecia receber do sol uma cor mais profunda e lustrosa quando ele a iluminava, o menino tinha olhos e cabelos tão claros que os mesmos raios pareciam extrair dele a pouca cor que alguma vez possuíra. Seus olhos frios mal seriam olhos, não fossem as pontas curtas dos cílios que, colocando-os em contraste imediato com algo mais pálido que eles, exprimiam-lhes a forma. Seu cabelo cortado rente poderia ser mera continuação das sardas cor de areia da testa e do rosto. Sua pele era tão insalubremente carente da tonalidade natural que parecia que, se fosse cortado, sangraria branco.","bitzersaidthomasgradgrindyourdefinitiono~ndyourdefinitionofahorse~47":"— Bitzer — disse Thomas Gradgrind. — A sua definição de cavalo.","quadrupedgraminivorousfortyteethnamelytw~uththusandmuchmorebitzer~215":"— Quadrúpede. Graminívoro. Quarenta dentes, a saber, vinte e quatro molares, quatro caninos e doze incisivos. Muda de pelo na primavera; em países pantanosos, muda também os cascos. Cascos duros, mas que exigem ser ferrados. Idade conhecida pelas marcas na boca. — Assim (e muito mais) Bitzer.","nowgirlnumbertwentysaidmrgradgrindyoukno~grindyouknowwhatahorseis~53":"— Agora, menina número vinte — disse o Sr. Gradgrind. — Você sabe o que é um cavalo.","shecurtseyedagainandwouldhaveblusheddeep~dforeheadandsatdownagain~297":"Ela fez outra reverência e teria corado mais, se fosse possível corar mais do que corara durante todo aquele tempo. Bitzer, depois de piscar rapidamente para Thomas Gradgrind com os dois olhos ao mesmo tempo, e assim apanhando a luz nas pontas trêmulas dos cílios, que pareciam antenas de insetos atarefados, levou os nós dos dedos à testa sardenta e tornou a sentar-se.","thethirdgentlemannowsteppedforthamightym~nersshouldreignuponearth~753":"O terceiro cavalheiro adiantou-se agora. Era um grande homem em cortar e secar; um funcionário do governo; à sua maneira (e à da maioria das outras pessoas também), um pugilista profissional; sempre em treino, sempre com um sistema para empurrar goela abaixo do público como uma pílula, sempre a ser ouvido no balcão de sua repartição, pronto a lutar contra toda a Inglaterra. Para continuar no jargão do boxe, tinha gênio para se apresentar ao ringue, onde e o que quer que fosse, e provar-se um osso duro de roer. Entrava e castigava qualquer assunto que fosse com a direita, seguia com a esquerda, parava, trocava golpes, contra-atacava, encurralava o adversário (lutava sempre contra toda a Inglaterra) nas cordas e caía sobre ele com limpeza. Estava certo de tirar o fôlego do bom senso e tornar esse azarado adversário surdo ao gongo. E tinha a incumbência, da alta autoridade, de trazer o grande Milênio das repartições públicas, quando Comissários reinariam sobre a terra.","verywellsaidthisgentlemanbrisklysmilinga~hrepresentationsofhorses~138":"— Muito bem — disse esse cavalheiro, sorrindo vivamente e cruzando os braços. — Isso é um cavalo. Agora, deixem-me perguntar a vocês, meninas e meninos: Forrariam uma sala com papel de parede com representações de cavalos?","afterapauseonehalfofthechildrencriedinch~tomisintheseexaminations~164":"Depois de uma pausa, metade das crianças gritou em coro: “Sim, senhor!” Ao que a outra metade, vendo no rosto do cavalheiro que Sim estava errado, gritou em coro: “Não, senhor!” — como é costume nesses exames.","ofcoursenowhywouldntyou~ofcoursenowhywouldntyou~23":"— Claro que Não. Por que não forrariam?","apauseonecorpulentslowboywithawheezymann~roomatallbutwouldpaintit~116":"Uma pausa. Um menino corpulento e lento, de respiração chiada, aventurou a resposta de que não forraria a sala de modo algum, mas a pintaria.","youmustpaperitsaidthegentlemanratherwarm~thegentlemanratherwarmly~42":"— Você deve forrá-la — disse o cavalheiro, com certo calor.","youmustpaperitsaidthomasgradgrindwhether~tpaperitwhatdoyoumeanboy~97":"— Você deve forrá-la — disse Thomas Gradgrind — queira ou não. Não nos diga que não a forraria. O que quer dizer, menino?","illexplaintoyouthensaidthegentlemanafter~oomsinrealityinfactdoyou~181":"— Vou então explicar a vocês — disse o cavalheiro, depois de outra pausa, sombria — por que não forrariam uma sala com papel de parede com representações de cavalos. Já viram, alguma vez, cavalos caminhando para cima e para baixo pelas paredes das salas na realidade — de fato? Já?","yessirfromonehalfnosirfromtheother~onehalfnosirfromtheother~34":"— Sim, senhor! — de uma metade. — Não, senhor! — da outra.","ofcoursenosaidthegentlemanwithanindignan~rindnoddedhisapprobation~228":"— Claro que não — disse o cavalheiro, com um olhar indignado para a metade errada. — Pois então vocês não devem ver em lugar algum o que não veem de fato; não devem ter em lugar algum o que não têm de fato. O que se chama Gosto é apenas outro nome para Fato. — Thomas Gradgrind assentiu em aprovação.","thisisanewprincipleadiscoveryagreatdisco~sentationofflowersuponit~163":"— Este é um novo princípio, uma descoberta, uma grande descoberta — disse o cavalheiro. — Agora, vou testá-los de novo. Suponham que fossem forrar o chão de uma sala com carpete. Usariam um carpete com representações de flores?","therebeingageneralconvictionbythistimeth~aidyesamongthemsissyjupe~160":"Havendo a essa altura uma convicção geral de que “Não, senhor!” era sempre a resposta certa para esse cavalheiro, o coro de Não foi muito forte. Apenas uns poucos retardatários fracos disseram Sim: entre eles Sissy Jupe.","girlnumbertwentysaidthegentlemansmilingi~ecalmstrengthofknowledge~67":"— Menina número vinte — disse o cavalheiro, sorrindo na calma força do saber.","sissyblushedandstoodup~sissyblushedandstoodup~22":"Sissy corou e levantou-se.","soyouwouldcarpetyourroomoryourhusbandsro~dthegentlemanwhywouldyou~139":"— Então você forraria o chão da sua sala — ou da sala do seu marido, se fosse uma mulher feita e tivesse marido — com representações de flores, não é? — disse o cavalheiro. — Por quê?","ifyoupleasesiriamveryfondofflowersreturn~offlowersreturnedthegirl~49":"— Se o senhor me permite, gosto muito de flores — respondeu a menina.","andisthatwhyyouwouldputtablesandchairsup~ngoverthemwithheavyboots~88":"— E é por isso que poria mesas e cadeiras sobre elas e faria as pessoas andarem em cima delas com botas pesadas?","itwouldnthurtthemsirtheywouldntcrushandw~ndpleasantandiwouldfancy~125":"— Não as machucaria, senhor. Elas não seriam esmagadas nem murchariam, se o senhor me permite. Seriam a imagem de algo muito bonito e agradável, e eu imaginaria...","ayayaybutyoumustntfancycriedthegentleman~hatsityouarenevertofancy~103":"— Ah, ah, ah! Mas você não deve imaginar — exclamou o cavalheiro, bastante exaltado por ter chegado tão felizmente ao ponto. — É isso! Você nunca deve imaginar.","youarenotceciliajupethomasgradgrindsolem~edtodoanythingofthatkind~73":"— Você não deve, Cecília Jupe — repetiu Thomas Gradgrind, solene — fazer nada desse tipo.","factfactfactsaidthegentlemanandfactfactf~trepeatedthomasgradgrind~66":"— Fato, fato, fato! — disse o cavalheiro. E “Fato, fato, fato!” repetiu Thomas Gradgrind.","youaretobeinallthingsregulatedandgoverne~erythisisfactthisistaste~808":"— Vocês devem ser, em todas as coisas, regulados e governados — disse o cavalheiro — pelo fato. Esperamos ter, em breve, um conselho do fato, composto de comissários do fato, que obrigarão o povo a ser um povo de fato, e de nada senão fato. Devem descartar por completo a palavra Imaginação. Não têm nada a ver com ela. Não devem ter, em nenhum objeto de uso ou de adorno, o que seria uma contradição de fato. Vocês não andam sobre flores de fato; não se pode permitir que andem sobre flores em carpetes. Vocês não veem aves e borboletas estrangeiras virem pousar na sua louça; não se pode permitir que pintem aves e borboletas estrangeiras na louça. Vocês nunca encontram quadrúpedes subindo e descendo paredes; não devem ter quadrúpedes representados em paredes. Devem usar — disse o cavalheiro — para todos esses fins, combinações e modificações (em cores primárias) de figuras matemáticas suscetíveis de prova e demonstração. Esta é a nova descoberta. Isto é fato. Isto é gosto.","thegirlcurtseyedandsatdownshewasveryyoun~prospecttheworldafforded~115":"A menina fez uma reverência e sentou-se. Era muito jovem e parecia assustada com a perspectiva prosaica que o mundo oferecia.","nowifmrmchoakumchildsaidthegentlemanwill~bservehismodeofprocedure~135":"— Agora, se o Sr. M’Choakumchild — disse o cavalheiro — proceder a dar aqui a sua primeira lição, Sr. Gradgrind, terei prazer, a seu pedido, em observar o seu método.","mrgradgrindwasmuchobligedmrmchoakumchild~kumchildweonlywaitforyou~56":"O Sr. Gradgrind ficou muito agradecido. — Sr. M’Choakumchild, só esperamos pelo senhor.","somrmchoakumchildbeganinhisbestmannerhea~emighthavetaughtmuchmore~995":"Assim, o Sr. M’Choakumchild começou da melhor maneira. Ele e cerca de outros cento e quarenta mestres-escolas tinham sido recentemente torneados ao mesmo tempo, na mesma fábrica, segundo os mesmos princípios, como tantos pés de piano. Fora submetido a uma imensa variedade de provas e respondera a volumes de perguntas de quebrar a cabeça. Ortografia, etimologia, sintaxe e prosódia, biografia, astronomia, geografia e cosmografia geral, as ciências da regra de três composta, álgebra, agrimensura e nivelamento, música vocal e desenho de modelos estavam todos na ponta de seus dez dedos gelados. Abrira seu caminho pétreo até o Anexo B do Honorabilíssimo Conselho Privado de Sua Majestade e tirara o viço dos ramos superiores da matemática e da ciência física, do francês, do alemão, do latim e do grego. Sabia tudo sobre todas as bacias hidrográficas de todo o mundo (sejam elas o que forem), e todas as histórias de todos os povos, e todos os nomes de todos os rios e montanhas, e todas as produções, maneiras e costumes de todos os países, e todas as suas fronteiras e posições nos trinta e dois pontos da rosa dos ventos. Ah, M’Choakumchild, um tanto exagerado. Se tivesse aprendido um pouco menos, quão infinitamente melhor poderia ter ensinado muito mais!","hewenttoworkinthispreparatorylessonnotun~onlymaimhimanddistorthim~328":"Pôs-se a trabalhar nessa lição preparatória não à maneira de Morgiana nos Quarenta Ladrões: olhando dentro de todos os vasos alinhados diante dele, um após outro, para ver o que continham. Diz, bom M’Choakumchild. Quando de teu fervente estoque encheres cada jarro até a borda, daqui a pouco, pensas que sempre matarás de vez o ladrão Imaginação que ali se esconde — ou às vezes apenas o mutilarás e deformarás!","mrgradgrindwalkedhomewardfromtheschoolin~ggradgrindswereallmodels~182":"O Sr. Gradgrind caminhou de volta para casa, saindo da escola, num estado de considerável satisfação. Era a sua escola, e ele pretendia que fosse um modelo. Pretendia que cada criança nela fosse um modelo — assim como os jovens Gradgrinds eram todos modelos.","therewerefiveyounggradgrindsandtheywerem~gghastlywhitefiguresonit~319":"Eram cinco os jovens Gradgrinds, e eram modelos, todos eles. Tinham recebido sermões desde a mais tenra idade; perseguidos como pequenas lebres. Quase assim que puderam correr sozinhos, foram obrigados a correr para a sala de aulas. O primeiro objeto com que tiveram uma associação, ou de que tiveram uma lembrança, foi um grande quadro-negro no qual um ogro seco riscava com giz figuras de um branco horrendo.","notthattheyknewbynameornatureanythingabo~statisticaldensbythehair~222":"Não que soubessem, de nome ou natureza, qualquer coisa sobre um ogro. Fato nos livre! Uso a palavra apenas para exprimir um monstro num castelo de palestras, com Deus sabe quantas cabeças manipuladas numa só, que toma a infância cativa e a arrasta pelos cabelos para sombrios covis estatísticos.","nolittlegradgrindhadeverseenafaceinthemo~rupedwithseveralstomachs~651":"Nenhum pequeno Gradgrind jamais vira um rosto na lua; já estava lá em cima na lua antes de poder falar com clareza. Nenhum pequeno Gradgrind jamais aprendera a tola cantiga: Brilha, brilha, estrelinha; quanto me pergunto o que és! Nenhum pequeno Gradgrind jamais sentira espanto sobre o assunto, tendo cada pequeno Gradgrind, aos cinco anos, dissecado a Ursa Maior como um Professor Owen e conduzido o Carro de Carlos como um maquinista de locomotiva. Nenhum pequeno Gradgrind jamais associara uma vaca num campo àquela famosa vaca do chifre torto que arremessou o cão que atormentou o gato que matou o rato que comeu o malte, ou àquela vaca ainda mais famosa que engoliu o Polegar: nunca ouvira falar dessas celebridades e só fora apresentado a uma vaca como um quadrúpede ruminante graminívoro de vários estômagos.","tohismatteroffacthomewhichwascalledstone~presentfaithfulguidebook~328":"Para sua casa prosaica, chamada Stone Lodge, o Sr. Gradgrind dirigiu os passos. Retirara-se virtualmente do comércio atacadista de ferragens antes de construir Stone Lodge e procurava agora uma oportunidade adequada de fazer figura aritmética no Parlamento. Stone Lodge ficava numa charneca, a uma ou duas milhas de uma grande cidade — chamada Coketown neste fiel guia.","averyregularfeatureonthefaceofthecountry~hingthatheartcoulddesire~669":"Um traço muito regular na face do campo era Stone Lodge. Nem o menor disfarce suavizava ou esbatia aquele fato intransigente na paisagem. Uma grande casa quadrada, com um pesado pórtico escurecendo as janelas principais, assim como as pesadas sobrancelhas do dono lhe sombreavam os olhos. Uma casa calculada, somada, equilibrada e provada. Seis janelas deste lado da porta, seis daquele lado; um total de doze nesta ala, um total de doze na outra; vinte e quatro levadas para as alas dos fundos. Um gramado, um jardim e uma alameda infante, tudo traçado em linha reta como um livro-caixa botânico. Gás e ventilação, drenagem e serviço de águas, tudo da mais alta qualidade. Grampos e vigas de ferro, à prova de fogo de alto a baixo; elevadores mecânicos para as criadas, com todas as suas escovas e vassouras; tudo o que o coração pudesse desejar.","everythingwellisupposesothelittlegradgri~ittlegradgrindsgraspedit~551":"Tudo? Bem, suponho que sim. Os pequenos Gradgrinds também tinham gabinetes em vários ramos da ciência. Tinham um pequeno gabinete conquiliológico, um pequeno gabinete metalúrgico e um pequeno gabinete mineralógico; e os espécimes estavam todos arrumados e etiquetados, e os pedaços de pedra e minério pareciam ter sido arrancados das substâncias de origem por aqueles instrumentos tremendamente duros que eram os seus próprios nomes; e, parafraseando a ociosa lenda de Peter Piper, que nunca achara o caminho de seu quarto de criança, se os gananciosos pequenos Gradgrinds agarravam mais do que isto, para que diabos, santo Deus, os gananciosos pequenos Gradgrinds o agarravam!","theirfatherwalkedoninahopefulandsatisfie~uebuthisduewasacceptable~544":"O pai deles seguiu caminho num estado de espírito esperançoso e satisfeito. Era um pai afetuoso, à sua maneira; mas provavelmente se descreveria (se lhe pedissem, como a Sissy Jupe, uma definição) como um pai “eminentemente prático”. Tinha particular orgulho na expressão eminentemente prático, que se considerava ter aplicação especial a ele. Qualquer que fosse a reunião pública realizada em Coketown, e qualquer que fosse o assunto dela, algum habitante de Coketown havia de aproveitar a ocasião para aludir ao seu eminentemente prático amigo Gradgrind. Isso sempre agradava ao eminentemente prático amigo. Sabia que era seu direito, mas o direito era bem-vindo.","hehadreachedtheneutralgroundupontheoutsk~ailorsjourneytobrentford~1366":"Chegara ao terreno neutro nos arredores da cidade, que não era nem cidade nem campo, e no entanto estragava ambos, quando seus ouvidos foram invadidos pelo som de música. A banda estrepitosa e retumbante anexa ao estabelecimento de equitação, que ali estabelecera seu pouso num pavilhão de madeira, estava em pleno zurro. Uma bandeira, drapejando no alto do templo, proclamava à humanidade que era a “Cavalaria de Sleary” que reclamava seus sufrágios. O próprio Sleary, estátua moderna e robusta com uma caixa de dinheiro ao cotovelo, num nicho eclesiástico de primitiva arquitetura gótica, recebia o dinheiro. A Srta. Josephine Sleary, como anunciavam umas tiras de cartaz impresso muito longas e muito estreitas, inaugurava então os divertimentos com seu gracioso número equestre tirolês das flores. Entre as outras agradáveis, mas sempre estritamente morais maravilhas que só vendo para crer, o Signor Jupe iria nessa tarde “elucidar as divertidas habilidades de seu altamente adestrado cão artista Merrylegs”. Exibiria também “sua assombrosa façanha de arremessar setenta e cinco quintais, em rápida sucessão, de revés por cima da cabeça, formando assim uma fonte de ferro maciço no ar, façanha nunca antes tentada neste ou em qualquer outro país e que, tendo suscitado aplausos tão arrebatados de multidões entusiasmadas, não pode ser retirada”. O mesmo Signor Jupe iria “animar as variadas representações, a intervalos frequentes, com seus castos gracejos e réplicas shakespearianos”. Por fim, encerraria o espetáculo aparecendo em seu personagem favorito, o Sr. William Button, da Tooley Street, na “novíssima e hilariante hipo-comediota A Viagem do Alfaiate a Brentford”.","thomasgradgrindtooknoheedofthesetriviali~ehiddengloriesoftheplace~347":"Thomas Gradgrind, naturalmente, não deu atenção a essas ninharias, mas passou adiante como deve passar um homem prático, ou escovando os insetos barulhentos de seus pensamentos, ou remetendo-os à Casa de Correção. Mas a curva da estrada o levou aos fundos da barraca, e nos fundos da barraca um número de crianças estava reunido em um número de atitudes furtivas, esforçando-se por espiar as glórias ocultas do lugar.","thisbroughthimtoastopnowtothinkoftheseva~ngrabblefromamodelschool~93":"Isso o fez parar. — Imaginar só estes vagabundos — disse ele — atraindo a plebe jovem de uma escola modelo.","aspaceofstuntedgrassanddryrubbishbeingbe~estriantyroleanfloweract~390":"Havendo um espaço de grama raquítica e entulho seco entre ele e a plebe jovem, tirou o monóculo do bolso do colete para procurar alguma criança que conhecesse pelo nome e pudesse mandar embora. Fenômeno quase inacreditável, embora claramente visto, o que viu então senão a sua própria Louisa metalúrgica, espiando com todas as forças por um buraco numa tábua de pinho, e o seu próprio Thomas matemático rebaixando-se no chão para apanhar ao menos um casco do gracioso número equestre tirolês das flores!","dumbwithamazementmrgradgrindcrossedtothe~oneacherringchildandsaid~111":"Mudo de espanto, o Sr. Gradgrind atravessou até o lugar onde a sua família era assim desonrada, pôs a mão em cada criança desviada e disse:","louisathomas~louisathomas~12":"— Louisa!! Thomas!!","bothroseredanddisconcertedbutlouisalooke~obetakenhomelikeamachine~149":"Ambos se levantaram, vermelhos e desconcertados. Mas Louisa olhou para o pai com mais ousadia que Thomas. Na verdade, Thomas não o olhou, mas entregou-se para ser levado para casa como uma máquina.","inthenameofwonderidlenessandfollysaidmrg~aybyahandwhatdoyoudohere~85":"— Em nome do espanto, da ociosidade e da tolice! — disse o Sr. Gradgrind, levando cada um pela mão. — O que fazem aqui?","wantedtoseewhatitwaslikereturnedlouisash~ikereturnedlouisashortly~45":"— Queríamos ver como era — respondeu Louisa, secamente.","whatitwaslike~whatitwaslike~13":"— Como era?","yesfather~yesfather~9":"— Sim, pai.","therewasanairofjadedsullennessinthemboth~nablindfacegropingitsway~395":"Havia em ambos um ar de mau humor cansado, e particularmente na menina; no entanto, lutando por entre o descontentamento do rosto dela, havia uma luz sem nada em que repousar, um fogo sem nada para queimar, uma imaginação faminta que mantinha a vida em si de algum modo, a qual avivava sua expressão. Não com o brilho natural da juventude alegre, mas com clarões incertos, ansiosos, hesitantes, que tinham algo de doloroso, análogo às mudanças num rosto cego que tateia o caminho.","shewasachildnowoffifteenorsixteenbutatno~alwaybutforherbringingup~204":"Era uma criança agora, de quinze ou dezesseis anos; mas dentro de pouco tempo pareceria tornar-se mulher de uma só vez. O pai pensou assim ao olhar para ela. Era bonita. Teria sido voluntariosa (pensou ele, à sua maneira eminentemente prática), não fosse a educação que recebera.","thomasthoughihavethefactbeforemeifinditd~ursistertoascenelikethis~136":"— Thomas, embora tenha o fato diante de mim, acho difícil acreditar que você, com a sua educação e recursos, tenha levado sua irmã a uma cena como esta.","ibroughthimfathersaidlouisaquicklyiasked~saquicklyiaskedhimtocome~49":"— Fui eu que o trouxe, pai — disse Louisa, depressa. — Pedi a ele que viesse.","iamsorrytohearitiamverysorryindeedtohear~anditmakesyouworselouisa~87":"— Lamento ouvir isso. Lamento muitíssimo ouvir isso. Não melhora Thomas e piora você, Louisa.","shelookedatherfatheragainbutnotearfelldo~utnotearfelldownhercheek~50":"Ela olhou de novo para o pai, mas nenhuma lágrima lhe desceu pela face.","youthomasandyoutowhomthecircleofthescien~egradedpositioniamamazed~209":"— Você! Thomas e você, a quem o círculo das ciências está aberto; Thomas e você, que se pode dizer repletos de fatos; Thomas e você, que foram treinados para a exatidão matemática; Thomas e você, aqui! — exclamou o Sr. Gradgrind. — Nesta posição degradada! Estou espantado.","iwastiredfatherihavebeentiredalongtimesa~tiredalongtimesaidlouisa~48":"— Eu estava cansada, pai. Estou cansada há muito tempo — disse Louisa.","tiredofwhataskedtheastonishedfather~askedtheastonishedfather~35":"— Cansada? De quê? — perguntou o pai, atônito.","idontknowofwhatofeverythingithink~ofwhatofeverythingithink~33":"— Não sei de quê — de tudo, creio.","saynotanotherwordreturnedmrgradgrindyoua~ehadagaincastdownhereyes~396":"— Não diga mais uma palavra — replicou o Sr. Gradgrind. — Você está infantil. Não quero ouvir mais nada. — Não voltou a falar até terem caminhado cerca de meia milha em silêncio, quando irrompeu gravemente com: — O que diriam seus melhores amigos, Louisa? Não dá valor algum à boa opinião deles? O que diria o Sr. Bounderby? — À menção desse nome, a filha lançou-lhe um olhar furtivo, notável pelo seu caráter intenso e perscrutador. Ele nada viu, pois, antes que a olhasse, ela voltara a baixar os olhos!","whatherepeatedpresentlywouldmrbounderbys~ounderbyhadbeenmrsgrundy~186":"— O que — repetiu logo depois — diria o Sr. Bounderby? — Durante todo o caminho até Stone Lodge, enquanto com grave indignação levava os dois delinquentes para casa, repetiu a intervalos: “O que diria o Sr. Bounderby?” — como se o Sr. Bounderby fosse a Sra. Grundy."}$tr$::jsonb, 84)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- emily-bronte_wuthering-heights (161 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('emily-bronte_wuthering-heights', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"chapteri":"Capítulo I","chapterii":"Capítulo II","chapteriii":"Capítulo III"}$tr$::jsonb, $tr${"1801ihavejustreturnedfromavisittomylandl~stcoatasiannouncedmyname~538":"1801.— Acabo de voltar de uma visita ao meu senhorio — o único vizinho que terei para me importunar. Este é certamente um belo país! Em toda a Inglaterra, não creio que eu pudesse ter escolhido um lugar tão completamente afastado do bulício da sociedade. Um paraíso perfeito para o misantropo: e o Sr. Heathcliff e eu formamos um par tão apropriado para repartir entre nós a desolação. Um excelente sujeito! Mal imaginava ele como meu coração se aqueceu por ele quando vi seus olhos negros recuarem tão desconfiados sob as sobrancelhas, enquanto eu me aproximava a cavalo, e quando seus dedos se abrigaram, com ciumenta resolução, ainda mais fundo no colete, ao eu anunciar meu nome.","mrheathcliffisaid~mrheathcliffisaid~17":"— Sr. Heathcliff? — disse eu.","anodwastheanswer~anodwastheanswer~16":"Um aceno de cabeça foi a resposta.","mrlockwoodyournewtenantsiridomyselftheho~dayyouhadhadsomethoughts~224":"— Sr. Lockwood, o seu novo inquilino, senhor. Faço-me a honra de visitá-lo logo depois da minha chegada, para exprimir a esperança de não o ter incomodado com minha insistência em solicitar a ocupação de Thrushcross Grange: ouvi ontem que o senhor havia pensado em...","thrushcrossgrangeismyownsirheinterrupted~meificouldhinderitwalkin~107":"— Thrushcross Grange é minha, senhor — interrompeu ele, estremecendo. — Não permitiria que ninguém me incomodasse, se pudesse evitá-lo. Entre!","thewalkinwasutteredwithclosedteethandexp~atedlyreservedthanmyself~262":"O “entre” foi proferido entre dentes cerrados, e exprimia o sentimento “Vá para o diabo”; nem mesmo o portão em que ele se apoiava manifestou qualquer movimento de simpatia pelas palavras; e creio que essa circunstância me decidiu a aceitar o convite: senti interesse por um homem que parecia ainda mais exageradamente reservado do que eu.","whenhesawmyhorsesbreastfairlypushingtheb~shorseandbringupsomewine~183":"Quando viu o peito do meu cavalo empurrando a cancela, estendeu enfim a mão para soltar a corrente, e depois me precedeu, taciturno, pela calçada, gritando ao entrarmos no pátio: — Joseph, leve o cavalo do Sr. Lockwood; e traga vinho.","herewehavethewholeestablishmentofdomesti~learetheonlyhedgecutters~163":"— Aí temos, suponho, todo o corpo de criados da casa — foi a reflexão sugerida por essa ordem composta. — Não admira que o capim cresça entre as lajes, e que o gado seja o único podador de sebes.","josephwasanelderlynayanoldmanveryoldperh~encetomyunexpectedadvent~302":"Joseph era um homem idoso, ou melhor, um velho: muito velho, talvez, embora rijo e nervoso. — O Senhor nos ajude! — resmungou ele num tom baixo de enfado rabugento, enquanto me tomava o cavalo, e olhava-me o rosto tão azedamente que conjecturei, caridoso, que ele devia precisar de auxílio divino para digerir o jantar, e que sua pia exclamação nada tinha a ver com o meu inesperado advento.","wutheringheightsisthenameofmrheathcliffs~edwithlargejuttingstones~531":"Wuthering Heights é o nome da residência do Sr. Heathcliff. “Wuthering” é um adjetivo provincial expressivo, que descreve o tumulto atmosférico a que sua situação está exposta em tempo de tempestade. Ventilação pura e tonificante devem ter ali em cima a todas as horas, de fato: pode-se adivinhar a força do vento norte soprando por sobre a borda pela inclinação excessiva de uns poucos abetos raquíticos no fim da casa, e por uma fileira de espinheiros descarnados, todos estendendo os galhos para o mesmo lado, como que implorando esmola ao sol. Felizmente, o arquiteto teve a previdência de construí-la sólida: as janelas estreitas são fundas na parede, e os cantos são defendidos por grandes pedras salientes.","beforepassingthethresholdipausedtoadmire~inspectingthepenetralium~458":"Antes de transpor o limiar, parei para admirar uma quantidade de entalhes grotescos prodigalizados pela fachada, e especialmente em torno da porta principal; sobre ela, entre uma selva de grifos em ruínas e meninos despudorados, descobri a data “1500” e o nome “Hareton Earnshaw”. Teria feito alguns comentários e pedido ao rabugento dono uma breve história do lugar; mas sua atitude à porta parecia exigir minha pronta entrada ou minha retirada completa, e eu não tinha desejo de agravar-lhe a impaciência antes de inspecionar o santuário interior.","onestopbroughtusintothefamilysittingroom~dogshauntedotherrecesses~1126":"Um passo nos levou à sala de estar da família, sem qualquer vestíbulo ou corredor de entrada: chamam-na aqui “a casa” por excelência. Em geral inclui cozinha e salão; mas creio que em Wuthering Heights a cozinha foi obrigada a retirar-se de todo para outra parte: pelo menos distingui um vozerio e um tinir de utensílios culinários, lá no fundo; e não observei sinal de assar, ferver ou cozer junto à enorme lareira, nem qualquer brilho de panelas de cobre e escorredores de lata nas paredes. Uma das extremidades, de fato, refletia esplendidamente luz e calor de fileiras de imensos pratos de estanho, entremeados de jarras e canecas de prata, que se erguiam, fileira após fileira, num vasto aparador de carvalho, até o próprio teto. Este nunca fora forrado: toda a sua anatomia ficava exposta a um olhar curioso, exceto onde um engradado de madeira carregado de bolos de aveia e de cachos de pernis de boi, de carneiro e de presunto o escondia. Sobre a chaminé havia diversas velhas espingardas de aspecto sinistro e um par de pistolas de arção; e, a título de ornamento, três latas espalhafatosamente pintadas dispostas ao longo da cornija. O chão era de pedra lisa e branca; as cadeiras, rústicas estruturas de espaldar alto, pintadas de verde; uma ou duas pesadas, pretas, espreitavam na sombra. Num arco sob o aparador repousava uma enorme cadela perdigueira cor de fígado, cercada por um enxame de cachorrinhos guinchantes; e outros cães habitavam outros recantos.","theapartmentandfurniturewouldhavebeennot~lfperfectlyunworthyofone~1238":"O aposento e a mobília nada teriam de extraordinário se pertencessem a um simples fazendeiro do norte, de semblante teimoso e membros robustos, bem postos em calções até o joelho e polainas. Um indivíduo assim, sentado em sua poltrona, com a caneca de cerveja espumando sobre a mesa redonda à frente, vê-se em qualquer circuito de cinco ou seis milhas por estas colinas, se for na hora certa depois do jantar. Mas o Sr. Heathcliff forma um singular contraste com sua morada e seu modo de viver. Tem o aspecto de um cigano de pele escura, mas no vestir e nas maneiras é um cavalheiro: isto é, tão cavalheiro quanto muitos fidalgos do campo; um tanto desleixado, talvez, mas sem que o descuido lhe fique mal, porque tem a figura ereta e bem-feita; e bastante taciturno. Possivelmente algumas pessoas poderiam suspeitar nele um grau de orgulho mal-nascido; tenho em mim uma corda simpática que me diz não ser nada disso: sei, por instinto, que sua reserva nasce da aversão a demonstrações espalhafatosas de sentimento — a manifestações de mútua amabilidade. Ele amará e odiará igualmente às escondidas e julgará uma espécie de impertinência ser amado ou odiado em troca. Não, estou me adiantando demais: atribuo a ele, com liberalidade excessiva, as minhas próprias qualidades. O Sr. Heathcliff pode ter razões inteiramente diversas das que me movem para tirar a mão do caminho quando encontra um pretenso conhecido. Quero crer que minha constituição é quase singular: minha querida mãe costumava dizer que eu nunca teria um lar confortável; e no verão passado provei ser perfeitamente indigno de um.","whileenjoyingamonthoffineweatheratthesea~ervedialonecanappreciate~639":"Enquanto desfrutava um mês de bom tempo no litoral, vi-me na companhia de uma criatura fascinantíssima: uma verdadeira deusa aos meus olhos, enquanto ela não reparava em mim. Eu “nunca disse meu amor” em voz alta; ainda assim, se os olhares têm linguagem, o mais simples idiota teria adivinhado que eu estava perdido até o pescoço: ela por fim me entendeu e retribuiu com o olhar — o mais doce de todos os imagináveis. E o que fiz eu? Confesso com vergonha: encolhi-me glacialmente dentro de mim, como um caracol; a cada olhar recuava mais frio e mais longe; até que por fim a pobre inocente foi levada a duvidar dos próprios sentidos e, tomada de confusão pelo suposto engano, persuadiu a mamãe a levantar acampamento. Por essa curiosa inclinação de temperamento granjeei a reputação de frieza deliberada; quão imerecida, só eu posso avaliar.","itookaseatattheendofthehearthstoneopposi~ovokedalonggutturalgnarl~283":"Sentei-me na ponta da pedra da lareira oposta àquela para a qual meu anfitrião avançava e preenchi um intervalo de silêncio tentando acariciar a mãe canina, que deixara o berçário e se esgueirava como um lobo para trás das minhas pernas, o lábio arreganhado e os dentes brancos salivando por uma mordida. Minha carícia provocou um longo rosnado gutural.","youdbetterletthedogalonegrowledmrheathcl~doorheshoutedagainjoseph~184":"— É melhor deixar a cadela em paz — rosnou o Sr. Heathcliff em uníssono, contendo demonstrações mais ferozes com um pontapé. — Não está acostumada a ser mimada — não é criada como bicho de estimação. — Então, caminhando a passos largos para uma porta lateral, gritou de novo: — Joseph!","josephmumbledindistinctlyinthedepthsofth~oldinreestablishingpeace~823":"Joseph resmungou indistintamente nas profundezas do porão, mas não deu sinal de subir; assim o patrão mergulhou até ele, deixando-me frente a frente com a cadela rufiã e um par de sinistros cães pastores felpudos, que com ela partilhavam uma vigilância ciumenta sobre todos os meus movimentos. Sem ansiar por contato com suas presas, fiquei quieto; mas, imaginando que mal entenderiam insultos tácitos, entreguei-me infelizmente a piscar o olho e fazer caretas ao trio, e algum jeito de minha fisionomia irritou tanto a madame que ela de repente rompeu em fúria e saltou-me aos joelhos. Atirei-a para trás e apressei-me a interpor a mesa entre nós. Esse procedimento despertou toda a colmeia: meia dúzia de demônios de quatro patas, de vários tamanhos e idades, saíram de covis ocultos para o centro comum. Senti que meus calcanhares e as abas do casaco eram objetos peculiares de assalto; e, aparando os combatentes maiores o mais eficazmente que podia com o atiçador, fui constrangido a pedir em voz alta o auxílio de alguém da casa para restabelecer a paz.","mrheathcliffandhismanclimbedthecellarste~rmasterenteredonthescene~451":"O Sr. Heathcliff e seu empregado subiram os degraus do porão com uma fleuma irritante: não creio que se movessem um segundo mais depressa que de costume, embora a lareira fosse uma verdadeira tempestade de ataques e ganidos. Felizmente uma moradora da cozinha foi mais expedita: uma dona robusta, de saia arregaçada, braços nus e faces afogueadas pelo fogo, precipitou-se no meio de nós brandindo uma frigideira; e usou essa arma, e a língua, com tal propósito que a tormenta se acalmou como por magia, e só ela ficou, arfando como um mar depois de um vendaval, quando o patrão entrou em cena.","whatthedevilisthematterheaskedeyeingmein~hisinhospitabletreatment~96":"— Que diabo se passa? — perguntou, fitando-me de um modo que eu mal podia suportar, depois desse tratamento inóspito.","whatthedevilindeedimutteredtheherdofposs~rangerwithabroodoftigers~154":"— Que diabo, de fato! — resmunguei. — A manada de porcos possessos não poderia ter espíritos piores do que esses seus animais, senhor. Seria o mesmo deixar um estranho com uma ninhada de tigres!","theywontmeddlewithpersonswhotouchnothing~vigilanttakeaglassofwine~145":"— Não se metem com quem não toca em nada — observou ele, pondo a garrafa diante de mim e recolocando a mesa deslocada. — Os cães fazem bem em ser vigilantes. Aceita um copo de vinho?","nothankyou~nothankyou~10":"— Não, obrigado.","notbittenareyou~notbittenareyou~15":"— Não foi mordido, foi?","ifihadbeeniwouldhavesetmysignetonthebite~ntenancerelaxedintoagrin~79":"— Se tivesse sido, teria posto meu sinete no mordedor. — O semblante de Heathcliff relaxou-se num esgar.","comecomehesaidyouareflurriedmrlockwoodhe~receivethemyourhealthsir~162":"— Vamos, vamos — disse ele —, o senhor está agitado, Sr. Lockwood. Tome, beba um pouco de vinho. Visitas são tão excessivamente raras nesta casa que eu e meus cães, admito de bom grado, mal sabemos como recebê-las. À sua saúde, senhor?","ibowedandreturnedthepledgebeginningtoper~eelmyselfcomparedwithhim~694":"Inclinei-me e retribuí o brinde, começando a perceber que seria tolice ficar amuado pelo mau comportamento de uma matilha de vira-latas; além disso, relutava em dar ao sujeito mais divertimento à minha custa, já que o humor dele tomava esse rumo. Ele — provavelmente movido pela consideração prudente da tolice de ofender um bom inquilino — afrouxou um pouco o estilo lacônico de cortar pronomes e verbos auxiliares e introduziu o que supunha ser assunto de meu interesse — um discurso sobre as vantagens e desvantagens do meu atual lugar de retiro. Achei-o muito inteligente nos tópicos que tocamos; e, antes de ir para casa, fui animado a ponto de me oferecer para outra visita amanhã. Ele evidentemente não desejava repetição da minha intrusão. Irei, apesar disso. É espantoso quão sociável me sinto em comparação com ele.","yesterdayafternoonsetinmistyandcoldihadh~theryflakesofasnowshower~640":"A tarde de ontem começou enevoada e fria. Tive meia vontade de passá-la junto ao fogo do meu escritório, em vez de patinhar por urzais e lama até Wuthering Heights. Ao subir do jantar, porém (N.B. — janto entre meio-dia e uma hora; a governanta, uma senhora matronal, tomada como acessório junto com a casa, não podia, ou não queria, compreender meu pedido de que me servissem às cinco) — ao subir as escadas com essa preguiçosa intenção e entrar na sala, vi uma criada de joelhos, cercada de escovas e baldes de carvão, levantando uma poeira infernal enquanto apagava as chamas com montes de cinzas. Esse espetáculo me fez recuar de imediato; peguei o chapéu e, após uma caminhada de quatro milhas, cheguei ao portão do jardim de Heathcliff bem a tempo de escapar dos primeiros flocos plumosos de uma nevasca.","onthatbleakhilltoptheearthwashardwithabl~stingledandthedogshowled~254":"Naquele cume desolado a terra estava dura de geada negra, e o ar me fez tremer em todos os membros. Incapaz de soltar a corrente, pulei por cima e, correndo pela calçada de lajes bordada de moitas esparsas de groselheiras, bati em vão pedindo entrada, até os nós dos dedos formigarem e os cães uivarem.","wretchedinmatesiejaculatedmentallyyoudes~romaroundwindowofthebarn~274":"— Miseráveis moradores! — ejaculei mentalmente. — Merecem isolamento perpétuo da espécie pela grosseira falta de hospitalidade. Eu, pelo menos, não manteria as portas trancadas de dia. Não me importa: vou entrar! — Assim resolvido, agarrei o trinco e sacudi-o com veemência. Joseph, de cara de vinagre, pôs a cabeça para fora de uma janela redonda do celeiro.","whatareyeforheshoutedtmaistersdownitfowl~aithifyewenttospaketohim~82":"— Que é que o sinhô quer? — gritou. — O patrão tá lá embaixo no curral. Dê a volta pela ponta do celeiro, se quiser falar com ele.","istherenobodyinsidetoopenthedoorihallooe~oorihallooedresponsively~53":"— Não há ninguém dentro para abrir a porta? — bradei em resposta.","theresnobbuttmissisandshoollnotoppentany~erflaysomedinstillneeght~69":"— Só tem a sinhora, e ela num abre não, se o sinhô fizer essa gritaria assustadora até a noite.","whycannotyoutellherwhomiamehjoseph~outellherwhomiamehjoseph~34":"— Por quê? Não pode dizer a ela quem sou, hein, Joseph?","nornemeillhaenohendwitmutteredtheheadvan~mutteredtheheadvanishing~46":"— Eu não! Num quero me meter nisso — resmungou a cabeça, desaparecendo.","thesnowbegantodrivethicklyiseizedthehand~emainedmotionlessandmute~614":"A neve começou a cair espessa, impelida pelo vento. Agarrei a maçaneta para tentar outra vez, quando um rapaz sem casaco, com uma forquilha ao ombro, apareceu no pátio atrás de mim. Gritou que o seguisse e, depois de marcharmos através de uma lavanderia e de uma área calçada que continha um depósito de carvão, uma bomba e um pombal, chegamos por fim ao aposento enorme, quente e alegre onde eu fora recebido antes. Resplandecia deliciosamente no brilho de um imenso fogo, composto de carvão, turfa e lenha; e perto da mesa, posta para uma farta refeição da noite, tive o prazer de ver a “patroa”, indivíduo cuja existência eu jamais suspeitara. Inclinei-me e esperei, pensando que ela me convidaria a sentar. Ela olhou para mim, recostada na cadeira, e permaneceu imóvel e muda.","roughweatheriremarkedimafraidmrsheathcli~hardworktomakethemhearme~130":"— Tempo duro! — observei. — Receio, Sra. Heathcliff, que a porta tenha de suportar as consequências do vagar dos seus criados: custou-me muito fazer-me ouvir.","sheneveropenedhermouthistaredshestaredal~arrassinganddisagreeable~130":"Ela nunca abriu a boca. Eu fitei — ela fitou também: pelo menos manteve os olhos em mim de um modo frio e indiferente, extremamente embaraçoso e desagradável.","sitdownsaidtheyoungmangrufflyhellbeinsoo~ngmangrufflyhellbeinsoon~41":"— Sente-se — disse o rapaz, rudemente. — Ele vem já.","iobeyedandhemmedandcalledthevillainjunow~enofowningmyacquaintance~127":"Obedeci; e pigarreei, e chamei a malvada Juno, que se dignou, nessa segunda entrevista, a mover a ponta extrema da cauda, em sinal de admitir meu conhecimento.","abeautifulanimalicommencedagaindoyouinte~ngwiththelittleonesmadam~71":"— Belo animal! — recomecei. — A senhora pretende separar-se dos filhotes, madame?","theyarenotminesaidtheamiablehostessmorer~fhimselfcouldhavereplied~87":"— Não são meus — disse a amável anfitriã, de modo mais repelente do que o próprio Heathcliff poderia ter respondido.","ahyourfavouritesareamongtheseicontinuedt~nfullofsomethinglikecats~87":"— Ah, seus favoritos estão entre estes? — continuei, voltando-me para uma almofada obscura cheia de algo como gatos.","astrangechoiceoffavouritessheobservedsco~tessheobservedscornfully~47":"— Estranha escolha de favoritos! — observou ela com desdém.","unluckilyitwasaheapofdeadrabbitsihemmedo~nthewildnessoftheevening~114":"Infelizmente, era um monte de coelhos mortos. Pigarreei mais uma vez e aproximei-me da lareira, repetindo meu comentário sobre a selvageria da noite.","youshouldnothavecomeoutshesaidrisingandr~twoofthepaintedcanisters~90":"— O senhor não devia ter saído — disse ela, levantando-se e tirando do console da lareira duas das latas pintadas.","herpositionbeforewasshelteredfromtheligh~sisthimincountinghisgold~632":"A posição anterior dela era protegida da luz; agora eu tinha uma visão nítida de toda a sua figura e semblante. Era esbelta e aparentemente mal saída da meninice: uma forma admirável e o mais delicado rostinho que já tive o prazer de contemplar; feições pequenas, muito claras; cachos loiros, ou antes dourados, pendendo soltos sobre o pescoço delicado; e olhos que, tivessem sido agradáveis na expressão, seriam irresistíveis: felizmente para o meu coração suscetível, o único sentimento que revelavam pairava entre o desdém e uma espécie de desespero, singularmente antinatural de se ver ali. As latas estavam quase fora de seu alcance; fiz um movimento para ajudá-la; ela voltou-se para mim como um avarento se voltaria se alguém tentasse auxiliá-lo a contar seu ouro.","idontwantyourhelpshesnappedicangetthemfo~ppedicangetthemformyself~47":"— Não quero sua ajuda — retorquiu ela. — Posso pegá-las eu mesma.","ibegyourpardonihastenedtoreply~urpardonihastenedtoreply~30":"— Perdão! — apressei-me a responder.","wereyouaskedtoteashedemandedtyinganapron~ftheleafpoisedoverthepot~110":"— Foi convidado para o chá? — perguntou ela, amarrando um avental sobre o vestido preto bem-feito e parando com uma colher de folhas suspensa sobre o bule.","ishallbegladtohaveacupianswered~egladtohaveacupianswered~31":"— Terei prazer em tomar uma xícara — respondi.","wereyouaskedsherepeated~wereyouaskedsherepeated~23":"— Foi convidado? — repetiu.","noisaidhalfsmilingyouaretheproperpersont~retheproperpersontoaskme~46":"— Não — disse eu, meio sorrindo. — A senhora é a pessoa adequada para me convidar.","sheflungtheteabackspoonandallandresumedh~outlikeachildsreadytocry~121":"Ela atirou o chá de volta, colher e tudo, e retomou a cadeira num acesso de mau humor; a testa franzida e o lábio inferior vermelho projetado, como o de uma criança prestes a chorar.","meanwhiletheyoungmanhadslungontohisperso~frommyuncomfortablestate~744":"Entrementes, o rapaz atirara ao corpo uma veste superior decididamente surrada e, erguendo-se diante da chama, olhava-me de esguelha, como se houvesse entre nós alguma inimizade mortal por vingar. Comecei a duvidar se era criado ou não: a roupa e a fala eram ambas rudes, inteiramente desprovidas da superioridade observável no Sr. e na Sra. Heathcliff; os espessos cachos castanhos eram ásperos e incultos, as suíças invadiam as faces ursinamente, e as mãos eram tostadas como as de um trabalhador comum; contudo o porte era livre, quase altivo, e ele não mostrava nada da assiduidade de um doméstico em servir a senhora da casa. Na ausência de provas claras de sua condição, julguei melhor abster-me de reparar em sua curiosa conduta; e, cinco minutos depois, a entrada de Heathcliff me aliviou, em certa medida, do meu desconfortável estado.","youseesiriamcomeaccordingtopromiseiexcla~meshelterduringthatspace~142":"— Vê, senhor, que vim, conforme prometido! — exclamei, assumindo ares alegres. — E temo ficar retido pelo tempo por meia hora, se puder me dar abrigo nesse espaço.","halfanhourhesaidshakingthewhiteflakesfro~chanceofachangeatpresent~262":"— Meia hora? — disse ele, sacudindo os flocos brancos das roupas. — Admira-me que escolha o auge de uma nevasca para passear. Sabe que corre o risco de se perder nos pântanos? Pessoas familiarizadas com estas charnecas muitas vezes erram o caminho em tardes assim; e posso lhe dizer que não há chance de mudança por ora.","perhapsicangetaguideamongyourladsandhemi~orningcouldyousparemeone~87":"— Talvez eu consiga um guia entre os seus rapazes, e ele poderia ficar na Granja até de manhã — poderia dispensar-me um?","noicouldnot~noicouldnot~11":"— Não, não poderia.","ohindeedwellthenimusttrusttomyownsagacit~musttrusttomyownsagacity~41":"— Ah, é mesmo! Bem, então devo confiar na minha própria sagacidade.","umph~umph~4":"— Hum!","areyougoingtomaktheteademandedheofthesha~gazefrommetotheyounglady~91":"— Vai fazer o chá? — perguntou o da casaca surrada, desviando seu olhar feroz de mim para a jovem.","ishetohaveanysheaskedappealingtoheathcli~kedappealingtoheathcliff~42":"— Ele vai tomar? — perguntou ela, apelando a Heathcliff.","getitreadywillyouwastheanswerutteredsosa~gwhilewediscussedourmeal~334":"— Prepare-o, sim? — foi a resposta, proferida tão ferozmente que me sobressaltei. O tom em que as palavras foram ditas revelava uma genuína má natureza. Já não me sentia inclinado a chamar Heathcliff de excelente sujeito. Quando os preparativos terminaram, ele me convidou com: — Agora, senhor, traga a sua cadeira. — E todos nós, inclusive o jovem rústico, nos reunimos em torno da mesa: reinando um silêncio austero enquanto discutíamos nossa refeição.","ithoughtifihadcausedtheclouditwasmydutyt~theireverydaycountenance~206":"Pensei que, se eu causara a nuvem, era meu dever fazer um esforço para dissipá-la. Não podiam todos os dias ficar sentados tão carrancudos e taciturnos; e era impossível, por mais mal-humorados que fossem, que o franzir universal que ostentavam fosse o seu semblante de todos os dias.","itisstrangeibeganintheintervalofswallowi~niusoveryourhomeandheart~325":"— É estranho — comecei, no intervalo entre engolir uma xícara de chá e receber outra — é estranho como o costume pode moldar nossos gostos e ideias: muitos não conseguiriam imaginar a existência de felicidade numa vida de tão completo exílio do mundo como a que o senhor leva, Sr. Heathcliff; contudo, arrisco-me a dizer que, cercado pela família e com sua amável senhora como gênio presidente do seu lar e coração...","myamiableladyheinterruptedwithanalmostdi~ewhereisshemyamiablelady~85":"— Minha amável senhora! — interrompeu ele, com um sorriso de escárnio quase diabólico. — Onde está ela — minha amável senhora?","mrsheathcliffyourwifeimean~sheathcliffyourwifeimean~26":"— A Sra. Heathcliff, sua esposa, quero dizer.","wellyesohyouwouldintimatethatherspiritha~henherbodyisgoneisthatit~138":"— Bem, sim — ah, o senhor quer insinuar que o espírito dela assumiu o posto de anjo ministrante e guarda os destinos de Wuthering Heights, mesmo depois de partido o corpo. É isso?","perceivingmyselfinablunderiattemptedtoco~otherdidnotlookseventeen~325":"Percebendo-me em um erro, tentei corrigi-lo. Poderia ter visto que havia disparidade demasiado grande entre as idades das partes para ser provável que fossem marido e mulher. Um tinha cerca de quarenta anos: período de vigor mental em que os homens raramente acalentam a ilusão de serem amados por moças como esposos; esse sonho é reservado para o consolo dos nossos anos declinantes. A outra não parecia ter dezessete.","thenitflasheduponmetheclownatmyelbowwhoi~tiwastolerablyattractive~437":"Então o clarão me veio: “O palhaço a meu lado, que bebe o chá de uma tigela e come o pão com mãos não lavadas, pode ser o marido dela: Heathcliff júnior, claro. Eis a consequência de ser enterrada viva: ela se atirou a esse rústico por pura ignorância de que existiam indivíduos melhores! Uma triste pena — devo me acautelar para não fazê-la arrepender-se da escolha.” A última reflexão pode parecer presunçosa; não era. Meu vizinho me parecia beirar o repulsivo; eu sabia, por experiência, que era toleravelmente atraente.","mrsheathcliffismydaughterinlawsaidheathc~pretthelanguageofhissoul~227":"— A Sra. Heathcliff é minha nora — disse Heathcliff, corroborando minha suposição. Voltou, ao falar, um olhar peculiar na direção dela: um olhar de ódio; a menos que tenha um conjunto de músculos faciais perversíssimo, que não interpreta, como os de outras pessoas, a linguagem de sua alma.","ahcertainlyiseenowyouarethefavouredposse~rkedturningtomyneighbour~93":"— Ah, certamente — vejo agora: o senhor é o favorecido possuidor da fada benfazeja — observei, voltando-me para o meu vizinho.","thiswasworsethanbeforetheyouthgrewcrimso~everitookcarenottonotice~219":"Isso foi pior que antes: o rapaz ficou carmesim e cerrou o punho, com todas as aparências de um ataque premeditado. Mas pareceu recobrar-se logo e abafou a tempestade numa maldição brutal, murmurada em meu favor; a qual, no entanto, cuidei de não notar.","unhappyinyourconjecturessirobservedmyhos~eshemusthavemarriedmyson~162":"— Infeliz em suas conjecturas, senhor — observou meu anfitrião —, nenhum de nós dois tem o privilégio de possuir a sua boa fada; seu par está morto. Eu disse que ela era minha nora: portanto, deve ter casado com meu filho.","andthisyoungmanis~andthisyoungmanis~17":"— E este rapaz é...","notmysonassuredly~notmysonassuredly~17":"— Meu filho, certamente que não.","heathcliffsmiledagainasifitwererathertoo~paternityofthatbeartohim~87":"Heathcliff sorriu de novo, como se fosse brincadeira ousada demais atribuir-lhe a paternidade daquele urso.","mynameisharetonearnshawgrowledtheotheran~didcounselyoutorespectit~64":"— Meu nome é Hareton Earnshaw — rosnou o outro — e aconselho-o a respeitá-lo!","iveshownnodisrespectwasmyreplylaughingin~hwhichheannouncedhimself~87":"— Não mostrei desrespeito algum — foi minha resposta, rindo por dentro da dignidade com que ele se anunciou.","hefixedhiseyeonmelongerthanicaredtoretur~erthoseraftersathirdtime~328":"Fixou o olhar em mim por mais tempo do que me agradava retribuir o fitar, por medo de ser tentado a lhe dar um tabefe ou a tornar audível a minha hilaridade. Comecei a sentir-me inequivocamente deslocado naquele agradável círculo familiar. A atmosfera espiritual lúgubre superava, e mais que neutralizava, os cálidos confortos físicos à minha volta; e resolvi ser cauteloso quanto a me aventurar uma terceira vez sob aquelas vigas.","thebusinessofeatingbeingconcludedandnoon~ofwindandsuffocatingsnow~223":"Concluída a tarefa de comer, e não proferindo ninguém uma palavra de conversa sociável, aproximei-me de uma janela para examinar o tempo. Vi um espetáculo triste: a noite escura caindo prematuramente, e céu e colinas misturados num único amargo turbilhão de vento e neve sufocante.","idontthinkitpossibleformetogethomenowwit~istinguishafootinadvance~156":"— Não creio possível chegar em casa agora sem guia — não pude deixar de exclamar. — Os caminhos já estarão soterrados; e, se estivessem limpos, eu mal distinguiria um pé adiante.","haretondrivethosedozensheepintothebarnpo~beforethemsaidheathcliff~117":"— Hareton, leve aquelas doze ovelhas para o alpendre do celeiro. Ficarão cobertas se deixadas no redil a noite toda; e ponha uma tábua diante delas — disse Heathcliff.","howmustidoicontinuedwithrisingirritation~nuedwithrisingirritation~40":"— Que devo fazer? — continuei, com irritação crescente.","therewasnoreplytomyquestionandonlookingr~ivillikeyermotheraforeye~496":"Não houve resposta à minha pergunta; e, olhando em volta, vi apenas Joseph trazendo um balde de mingau para os cães e a Sra. Heathcliff debruçada sobre o fogo, divertindo-se em queimar um maço de fósforos que caíra do console da lareira quando ela recolocava a lata de chá no lugar. O primeiro, depois de depositar o fardo, fez um exame crítico da sala e, em tons rachados, resmungou áspero: — Eu me pergunto como é que vancê aguenta ficá aí na ociosidade e pió, quando todos eles saíro! Mas vancê num presta, e é inútil falá — vancê nunca vai se emendá dos seus maus jeitos, mas ir direitinho pro diabo, como sua mãe antes de vancê!","iimaginedforamomentthatthispieceofeloque~evercheckedmebyheranswer~187":"Imaginei, por um momento, que esse trecho de eloquência se dirigia a mim; e, suficientemente enraivecido, avancei para o velho patife com a intenção de pô-lo porta afora a pontapés. A Sra. Heathcliff, porém, me deteve com a sua resposta.","youscandalousoldhypocritesherepliedareyo~gprovidentialvisitations~406":"— Velho hipócrita escandaloso! — replicou ela. — Não tem medo de ser carregado de corpo e alma toda vez que menciona o nome do diabo? Advirto-o de que se abstenha de me provocar, ou pedirei o seu rapto como favor especial! Pare! Olhe aqui, Joseph — continuou, tirando de uma prateleira um longo livro escuro —, mostrarei até onde progredi na Arte Negra: logo estarei apta a fazer limpeza completa na casa. A vaca vermelha não morreu por acaso; e seu reumatismo dificilmente pode ser contado entre as visitações providenciais!","ohwickedwickedgaspedtheeldermaythelordde~thelorddeliverusfromevil~55":"— Ah, perversa, perversa! — arquejou o velho. — Que o Senhor nos livre do mal!","noreprobateyouareacastawaybeofforillhurt~youllseegoimlookingatyou~178":"— Não, réprobo! Você é um náufrago — fora daqui, ou lhe faço mal sério! Hei de modelar todos vocês em cera e barro! E o primeiro que passar dos limites que fixo será... não direi o que se fará com ele... mas verão! Vão, estou olhando para vocês!","thelittlewitchputamockmalignityintoherbe~ointerestherinmydistress~242":"A pequena bruxa pôs uma malignidade fingida nos belos olhos, e Joseph, tremendo de horror sincero, saiu apressado, rezando e ejaculando “perversa” ao ir. Pensei que a conduta dela devia ser inspirada por uma espécie de diversão sombria; e, agora que estávamos a sós, esforcei-me por interessá-la em minha aflição.","mrsheathcliffisaidearnestlyyoumustexcuse~ouldhavehowtogettolondon~226":"— Sra. Heathcliff — disse eu, com seriedade —, deve me desculpar por incomodá-la. Presumo, porque, com esse rosto, tenho certeza de que a senhora não pode deixar de ter bom coração. Aponte-me alguns pontos de referência pelos quais eu possa saber o caminho de casa: não tenho mais ideia de como chegar lá do que a senhora teria de como chegar a Londres!","taketheroadyoucamesheansweredensconcingh~vicebutassoundasicangive~127":"— Tome o caminho por onde veio — respondeu ela, instalando-se numa cadeira, com uma vela e o longo livro aberto à frente. — É conselho breve, mas tão sólido quanto posso dar.","thenifyouhearofmebeingdiscovereddeadinab~rthatitispartlyyourfault~106":"— Então, se ouvir dizer que fui encontrado morto num brejo ou numa cova cheia de neve, sua consciência não lhe sussurrará que a culpa é em parte sua?","howsoicannotescortyoutheywouldntletmegot~ototheendofthegardenwall~62":"— Como assim? Não posso escoltá-lo. Não me deixariam ir até o fim do muro do jardim.","youishouldbesorrytoaskyoutocrossthethres~heathclifftogivemeaguide~152":"— A senhora! Lamentaria pedir-lhe que cruzasse o limiar, para minha conveniência, numa noite como esta — exclamei. — Quero que me diga o caminho, não que o mostre: ou então que persuada o Sr. Heathcliff a me dar um guia.","whothereishimselfearnshawzillahjosephand~ephandiwhichwouldyouhave~58":"— Quem? Há ele próprio, Earnshaw, Zillah, Joseph e eu. Qual deles quer?","aretherenoboysatthefarm~aretherenoboysatthefarm~23":"— Não há rapazes na fazenda?","nothoseareall~nothoseareall~13":"— Não; são só esses.","thenitfollowsthatiamcompelledtostay~wsthatiamcompelledtostay~35":"— Então segue-se que sou obrigado a ficar.","thatyoumaysettlewithyourhostihavenothing~stihavenothingtodowithit~50":"— Isso o senhor acerta com o anfitrião. Eu não tenho nada a ver com isso.","ihopeitwillbealessontoyoutomakenomoreras~thharetonorjosephifyoudo~200":"— Espero que lhe sirva de lição para não fazer mais viagens temerárias por estas colinas — gritou a voz severa de Heathcliff da entrada da cozinha. — Quanto a ficar aqui, não mantenho acomodações para visitantes: terá de dividir a cama com Hareton ou Joseph, se ficar.","icansleeponachairinthisroomireplied~achairinthisroomireplied~35":"— Posso dormir numa cadeira nesta sala — repliquei.","nonoastrangerisastrangerbeherichorpoorit~dsaidtheunmannerlywretch~124":"— Não, não! Um estranho é um estranho, seja rico ou pobre: não me convém permitir a ninguém o livre trânsito do lugar enquanto estou fora de guarda! — disse o miserável sem modos.","withthisinsultmypatiencewasatanendiutter~ppearedabouttobefriendme~282":"Com esse insulto, minha paciência chegou ao fim. Proferi uma expressão de nojo e empurrei-o para passar ao pátio, esbarrando em Earnshaw na pressa. Estava tão escuro que não via o meio de sair; e, ao vagar em volta, ouvi outro espécime de sua civilizada conduta uns com os outros. A princípio o rapaz pareceu prestes a me ajudar.","illgowithhimasfarastheparkhesaid~hhimasfarastheparkhesaid~32":"— Vou com ele até o parque — disse.","youllgowithhimtohellexclaimedhismasteror~istolookafterthehorseseh~92":"— Você vai com ele para o inferno! — exclamou o patrão, ou fosse qual fosse a relação que tinha. — E quem vai cuidar dos cavalos, hein?","amanslifeisofmoreconsequencethanoneeveni~fmorekindlythaniexpected~119":"— A vida de um homem tem mais importância que uma noite de descuido com os cavalos: alguém tem de ir — murmurou a Sra. Heathcliff, com mais bondade do que eu esperava.","notatyourcommandretortedharetonifyousets~reonhimyoudbetterbequiet~66":"— Não por ordem sua! — retorquiu Hareton. — Se tem apreço por ele, é melhor ficar quieta.","thenihopehisghostwillhauntyouandihopemrh~saruinsheansweredsharply~112":"— Então espero que o fantasma dele assombre você; e espero que o Sr. Heathcliff nunca mais arranje outro inquilino até a Granja ser uma ruína — respondeu ela, azeda.","hearkenhearkenshooscursingonemmutteredjo~ardswhomihadbeensteering~71":"— Escuta, escuta, ela tá amaldiçoando eles! — murmurou Joseph, para quem eu vinha me dirigindo.","hesatwithinearshotmilkingthecowsbythelig~ushedtothenearestpostern~148":"Sentava-se ao alcance do ouvido, ordenhando as vacas à luz de uma lanterna, que agarrei sem cerimônia e, gritando que a devolveria no dia seguinte, corri para a porta lateral mais próxima.","maistermaisterhesstalingtlanthernshouted~gheywolfholldhimholldhim~106":"— Patrão, patrão, ele tá roubando a lanterna! — gritou o ancião, perseguindo minha retirada. — Eh, Gnasher! Eh, cão! Eh, Wolf, pega ele, pega ele!","onopeningthelittledoortwohairymonstersfl~rulencysmackedofkinglear~564":"Ao abrir a portinha, dois monstros peludos voaram à minha garganta, derrubando-me e apagando a luz; enquanto uma gargalhada mista de Heathcliff e Hareton pôs a pedra final em minha raiva e humilhação. Felizmente os bichos pareciam mais empenhados em esticar as patas, bocejar e abanar as caudas do que em me devorar vivo; mas não permitiam ressurreição, e fui forçado a ficar deitado até que seus malignos donos se dignassem a me libertar; então, sem chapéu e trêmulo de cólera, ordenei aos facínoras que me deixassem sair — sob pena de me reterem mais um minuto — com várias ameaças incoerentes de retaliação que, em sua profundidade indefinida de virulência, cheiravam a Rei Lear.","thevehemenceofmyagitationbroughtonacopio~ainsttheyoungerscoundrel~450":"A veemência da minha agitação trouxe uma copiosa hemorragia nasal, e Heathcliff ainda ria, e eu ainda ralhava. Não sei como teria terminado a cena, não houvesse uma pessoa à mão mais racional que eu e mais benévola que meu anfitrião. Era Zillah, a robusta dona de casa, que por fim saiu para indagar a natureza do tumulto. Pensou que alguns deles me haviam posto as mãos com violência; e, não ousando atacar o patrão, voltou sua artilharia vocal contra o patife mais jovem.","wellmrearnshawshecriediwonderwhatyoullha~ethattherenowholdyestill~212":"— Pois bem, Sr. Earnshaw — gritou —, que será que o senhor vai aprontar agora? Vamos assassinar gente na nossa própria soleira? Vejo que esta casa nunca vai servir pra mim — olhe só o pobre moço, tá quase sufocando! Psiu, psiu; não deve continuar assim. Entre, que eu curo isso: pronto, fique quieto.","withthesewordsshesuddenlysplashedapintof~yinhishabitualmoroseness~163":"Com essas palavras, despejou de repente um quartilho de água gelada pelo meu pescoço e puxou-me para a cozinha. O Sr. Heathcliff seguiu, sua alegria acidental expirando logo na habitual taciturnidade.","iwassickexceedinglyanddizzyandfaintandth~hatrevivedusheredmetobed~256":"Eu estava extremamente enjoado, tonto e fraco; e assim compelido, por força, a aceitar hospedagem sob o seu teto. Ele disse a Zillah que me desse um copo de conhaque e passou ao aposento interior; enquanto ela se condoía de minha lastimável situação e, tendo obedecido às ordens, com o que me reanimei um pouco, conduziu-me à cama.","whileleadingthewayupstairssherecommended~couldnotbegintobecurious~298":"Enquanto me guiava escada acima, ela recomendou que eu escondesse a vela e não fizesse barulho; pois o patrão tinha uma ideia esquisita sobre o quarto em que ela me poria e nunca deixava ninguém se hospedar ali de bom grado. Perguntei o motivo. Ela não sabia, respondeu: vivia ali havia só um ou dois anos; e havia tantas coisas estranhas acontecendo que ela não conseguia sequer começar a ser curiosa.","toostupefiedtobecuriousmyselfifastenedmy~eathcliffandeveryoneelse~561":"Atordoado demais para ser curioso eu mesmo, tranquei a porta e olhei em volta à procura da cama. A mobília toda consistia numa cadeira, um guarda-roupa e uma grande caixa de carvalho, com quadrados recortados perto do topo, semelhantes a janelas de carruagem. Aproximando-me dessa estrutura, olhei lá dentro e percebi que era uma singular espécie de leito à moda antiga, muito convenientemente concebido para evitar a necessidade de cada membro da família ter um quarto só para si. Na verdade, formava um pequeno armário, e o peitoril de uma janela, que ele encerrava, servia de mesa. Corri os lados almofadados, entrei com a minha luz, tornei a juntá-los e senti-me seguro contra a vigilância de Heathcliff e de todos os demais.","theledgewhereiplacedmycandlehadafewmilde~enagaintocatherinelinton~275":"No peitoril, onde pus a vela, havia alguns livros mofados empilhados num canto; e estava coberto de escritos arranhados na tinta. Esse escrito, porém, não era senão um nome repetido em toda sorte de caracteres, grandes e pequenos — Catherine Earnshaw, aqui e ali variado para Catherine Heathcliff e depois de novo para Catherine Linton.","invapidlistlessnessileantmyheadagainstth~herherfadedhieroglyphics~1261":"Em vazia apatia encostei a cabeça na janela e continuei soletrando Catherine Earnshaw — Heathcliff — Linton, até meus olhos se fecharem; mas não tinham descansado cinco minutos quando um clarão de letras brancas saltou da escuridão, vívido como espectros — o ar fervilhava de Catherines; e, despertando para dissipar o nome intruso, descobri o pavio da vela reclinado sobre um dos volumes antigos, perfumando o lugar com um odor de couro de bezerro assado. Apaguei-o com a espevitadeira e, muito mal à vontade sob a influência do frio e da náusea persistente, sentei-me e abri sobre o joelho o tomo danificado. Era um Novo Testamento, em tipo magro e cheirando horrivelmente a mofo: uma folha de guarda trazia a inscrição — “Catherine Earnshaw, seu livro”, e uma data de cerca de um quarto de século atrás. Fechei-o e peguei outro, e outro, até examinar todos. A biblioteca de Catherine era seleta, e seu estado de dilapidação provava que fora bem usada, ainda que não inteiramente para um fim legítimo: quase nenhum capítulo escapara a um comentário a pena e tinta — ao menos a aparência de um — cobrindo cada migalha de branco que o tipógrafo deixara. Alguns eram frases soltas; outras partes tomavam a forma de um diário regular, rabiscado em letra informe, infantil. No alto de uma folha extra (um verdadeiro tesouro, provavelmente, quando encontrada) diverti-me imensamente ao ver uma excelente caricatura do meu amigo Joseph — grosseiramente, mas poderosamente esboçada. Um interesse imediato acendeu-se em mim pela desconhecida Catherine, e comecei de pronto a decifrar seus hieróglifos desbotados.","anawfulsundaycommencedtheparagraphbeneat~nitiatorystepthisevening~184":"— Um domingo horrível — começava o parágrafo abaixo. — Quisera que meu pai estivesse de volta. Hindley é um substituto detestável — a conduta dele com Heathcliff é atroz — H. e eu vamos nos rebelar — demos nosso passo inicial esta noite.","alldayhadbeenfloodingwithrainwecouldnotg~cienttosendusintocorners~636":"— O dia inteiro choveu a cântaros; não pudemos ir à igreja, então Joseph teve de armar uma congregação no sótão; e, enquanto Hindley e a mulher se aqueciam lá embaixo diante de um fogo confortável — fazendo tudo menos ler suas Bíblias, eu respondo por isso —, Heathcliff, eu e o infeliz lavrador recebemos ordem de pegar nossos livros de oração e subir: fomos alinhados em fila, sobre um saco de milho, gemendo e tiritando, e esperando que Joseph também tiritasse, para que nos desse uma breve homilia no seu próprio interesse. Ideia vã! O culto durou precisamente três horas; e no entanto meu irmão teve a cara de exclamar, ao nos ver descer: ‘O quê, já acabaram?’ Nas noites de domingo costumávamos ter permissão de brincar, se não fizéssemos muito barulho; agora um mero risinho basta para nos mandar para os cantos.","youforgetyouhaveamasterheresaysthetyrant~workboxesmyearsandcroaks~559":"— ‘Esquecem que têm um senhor aqui’, diz o tirano. ‘Vou demolir o primeiro que me puser de mau humor! Exijo perfeita sobriedade e silêncio. Oh, menino! Foi você? Frances, querida, puxe-lhe o cabelo ao passar: ouvi-o estalar os dedos.’ Frances puxou-lhe o cabelo de bom grado, e depois foi sentar-se no joelho do marido, e ali ficaram, como dois bebês, beijando-se e dizendo tolices por horas — palavrório néscio de que deveríamos nos envergonhar. Acomodamo-nos tão aconchegados quanto nossos meios permitiam no arco do aparador. Eu acabara de prender nossos aventais uns aos outros e pendurá-los como cortina, quando entra Joseph, de uma incumbência nos estábulos. Arranca minha obra, dá-me um tabefe nas orelhas e grasna:","tmaisternobbutjustburiedandsabbathnotoer~tyedownandthinkoyersowls~177":"— ‘O patrão mal acabô de sê enterrado, e o Sabá num acabô, e o som do evangelho inda nos ouvido, e vocês ainda ousam brincá! Vergonha! Sentem, crianças ruins! Tem bons livros de sobra se quiserem lê: sentem e pensem nas suas alma!’","sayingthishecompelledussotosquareourposi~placethentherewasahubbub~283":"— Dizendo isso, obrigou-nos a ajeitar nossas posições de modo a receber do fogo distante um raio fosco que nos mostrasse o texto da tralha que nos impingia. Não suportei a ocupação. Peguei meu volume encardido pela capa e atirei-o ao canil, jurando que detestava um bom livro. Heathcliff chutou o seu para o mesmo lugar. Então foi um alvoroço!","maisterhindleyshoutedourchaplainmaisterc~acedemproperlybuthesgoan~233":"— ‘Patrão Hindley!’ gritou nosso capelão. ‘Patrão, venha cá! A sinhá Cathy rasgô as costas d’ “O Elmo da Salvação”, e o Heathcliff meteu o pé na primeira parte d’ “O Caminho Largo pra Destruição”! É de arrepiá que deixe eles continuá nesse rumo. Ai! O velho patrão ia amarrá eles direitinho — mas ele se foi!’","hindleyhurriedupfromhisparadiseonthehear~erintherainthanwearehere~599":"— Hindley subiu depressa do seu paraíso junto à lareira e, agarrando um de nós pelo colarinho e o outro pelo braço, atirou ambos à copa dos fundos; onde, Joseph asseverou, ‘o velho Nick’ viria nos buscar tão certo como estarmos vivos: e, assim consolados, cada um procurou um canto separado para aguardar sua vinda. Peguei este livro e um pote de tinta de uma prateleira e entreabri a porta da casa para me dar luz, e já passei vinte minutos escrevendo; mas meu companheiro está impaciente e propõe que nos apropriemos da capa da leiteira e demos uma disparada pelas charnecas, sob seu abrigo. Uma sugestão agradável — e então, se o velho rabugento entrar, poderá crer verificada a sua profecia — não podemos estar mais úmidos, nem mais frios, na chuva do que estamos aqui.","isupposecatherinefulfilledherprojectfort~ubjectshewaxedlachrymose~92":"Suponho que Catherine cumpriu seu projeto, pois a frase seguinte tomava outro assunto: ela se tornara lacrimosa.","howlittledididreamthathindleywouldeverma~reducehimtohisrightplace~380":"— Quão pouco sonhei que Hindley algum dia me faria chorar assim! — escrevera. — A cabeça me dói tanto que não consigo mantê-la no travesseiro; e ainda assim não consigo desistir. Pobre Heathcliff! Hindley o chama de vagabundo e não o deixa sentar conosco nem comer conosco nunca mais; e diz que ele e eu não devemos brincar juntos, e ameaça pô-lo para fora de casa se desobedecermos a suas ordens. Anda culpando nosso pai (como ousa?) por tratar H. com liberalidade demais; e jura que o reduzirá ao seu devido lugar...","ibegantonoddrowsilyoverthedimpagemyeyewa~ceiwascapableofsuffering~489":"Comecei a cabecear sonolento sobre a página esmaecida: o olhar vagou do manuscrito para o impresso. Vi um título ornamentado em vermelho — “Setenta Vezes Sete, e a Primeira das Setenta e Uma. Um Piedoso Discurso proferido pelo Reverendo Jabez Branderham, na Capela de Gimmerden Sough.” E enquanto eu, meio consciente, quebrava a cabeça tentando adivinhar o que Jabez Branderham faria do assunto, afundei de volta na cama e adormeci. Ai, os efeitos do chá ruim e do mau humor! O que mais poderia me ter feito passar uma noite tão terrível? Não me lembro de outra que se possa comparar com ela desde que sou capaz de sofrer.","ibegantodreamalmostbeforeiceasedtobesens~exposedandexcommunicated~686":"Comecei a sonhar quase antes de deixar de ter consciência do lugar onde estava. Pensei que era manhã; e eu partira para casa, tendo Joseph por guia. A neve jazia a jardas de profundidade em nosso caminho; e, enquanto chafurdávamos, meu companheiro me cansava com constantes censuras por eu não ter trazido um bordão de peregrino: dizendo-me que nunca entraria em casa sem um e brandindo com jactância um cacete de cabeça pesada, que entendi ser assim denominado. Por um momento achei absurdo que eu precisasse de tal arma para obter admissão na minha própria residência. Então uma nova ideia me atravessou. Eu não ia para lá: viajávamos para ouvir o famoso Jabez Branderham pregar, sobre o texto — “Setenta Vezes Sete”; e ou Joseph, o pregador, ou eu havíamos cometido a “Primeira das Setenta e Uma” e seríamos publicamente expostos e excomungados.","wecametothechapelihavepasseditreallyinmy~ineverimaginedpreviously~916":"Chegamos à capela. Passei por ela de fato em meus passeios, duas ou três vezes; fica numa depressão entre duas colinas: uma depressão elevada, perto de um pântano, cuja umidade turfosa dizem servir a todos os fins de embalsamamento para os poucos cadáveres ali depositados. O telhado foi mantido inteiro até agora; mas, como o estipêndio do clérigo é de apenas vinte libras por ano e uma casa de dois cômodos, que ameaça em breve resolver-se em um, nenhum clérigo assumirá os deveres de pastor: especialmente porque se diz correntemente que seu rebanho preferiria deixá-lo morrer de fome a aumentar o sustento em um único tostão do próprio bolso. Contudo, em meu sonho, Jabez tinha uma congregação cheia e atenta; e pregou — bom Deus! que sermão; dividido em quatrocentas e noventa partes, cada qual plenamente equivalente a uma alocução comum do púlpito, e cada qual discutindo um pecado separado! Onde os foi buscar, não sei dizer. Tinha sua maneira particular de interpretar a frase, e parecia necessário que o irmão pecasse pecados diferentes em cada ocasião. Eram do caráter mais curioso: estranhas transgressões que eu jamais imaginara.","ohhowwearyigrowhowiwrithedandyawnedandno~hatnochristianneedpardon~361":"Oh, como me cansei. Como me contorci, bocejei, cabeceei e revivi! Como me belisquei e piquei, esfreguei os olhos, levantei-me e sentei-me de novo, e cutuquei Joseph para que me informasse se algum dia ele terminaria. Estava condenado a ouvir tudo: por fim ele chegou à “Primeira das Setenta e Uma”. Nessa crise desceu sobre mim uma súbita inspiração; senti-me movido a levantar e denunciar Jabez Branderham como o pecador do pecado que nenhum cristão precisa perdoar.","siriexclaimedsittingherewithinthesefourw~knowshimmayknowhimnomore~377":"— Senhor — exclamei —, sentado aqui dentro destas quatro paredes, de uma só vez, suportei e perdoei as quatrocentas e noventa partes do seu discurso. Setenta vezes sete agarrei o chapéu e estive prestes a partir — setenta vezes sete o senhor me forçou, despropositadamente, a retomar o assento. A quatrocentésima nonagésima primeira é demais. Companheiros mártires, sobre ele! Arrastem-no para baixo e esmaguem-no em átomos, para que o lugar que o conhece não o conheça mais!","thouartthemancriedjabezafterasolemnpause~chhonourhaveallhissaints~297":"— Tu és o Homem! — bradou Jabez, depois de uma pausa solene, inclinando-se sobre a almofada. — Setenta vezes sete contorceste, boquiaberto, o teu rosto — setenta vezes sete aconselhei-me com a minha alma — Eis, esta é a fraqueza humana: também esta pode ser absolvida! A Primeira das Setenta e Uma chegou. Irmãos, executai sobre ele o juízo escrito. Tal honra têm todos os Seus santos!","withthatconcludingwordthewholeassemblyex~redisagreeablythanbefore~823":"Com essa palavra final, toda a assembleia, erguendo seus bordões de peregrino, precipitou-se em volta de mim em bloco; e eu, sem arma que levantar em minha defesa, comecei a lutar com Joseph, meu mais próximo e mais feroz assaltante, pela dele. Na confluência da multidão, vários porretes se cruzaram; golpes, dirigidos a mim, caíram em outros cocurutos. Logo a capela inteira ressoava de pancadas e contrapancadas: a mão de cada homem contra o seu vizinho; e Branderham, não querendo ficar ocioso, derramou seu zelo numa chuva de pancadas sonoras nas tábuas do púlpito, que respondiam tão vivamente que por fim, para meu inexprimível alívio, me despertaram. E o que sugerira o tremendo tumulto? O que desempenhara o papel de Jabez na confusão? Apenas o galho de um abeto que tocava minha vidraça quando a rajada passava gemendo e fazia chocalhar suas pinhas secas contra os vidros! Escutei por um instante, duvidoso; detectei o perturbador, então virei-me e cochilei, e sonhei de novo: se possível, ainda mais desagradavelmente que antes.","thistimeirememberediwaslyingintheoakclos~heeffectmyactionproduced~2174":"Dessa vez lembrei que estava deitado no armário de carvalho e ouvi distintamente o vento em rajadas e o açoite da neve; ouvi também o ramo de abeto repetir seu som provocador, e atribuí-o à causa certa: mas aquilo me incomodou tanto que resolvi silenciá-lo, se possível; e, pensei, levantei-me e tentei soltar o fecho da janela. O gancho estava soldado ao ferrolho: circunstância observada por mim acordado, mas esquecida. — Preciso detê-lo, apesar de tudo! — murmurei, batendo os nós dos dedos através do vidro e estendendo um braço para agarrar o ramo importuno; em vez disso, meus dedos se fecharam sobre os dedos de uma mãozinha gelada como o gelo! O intenso horror do pesadelo veio sobre mim: tentei retirar o braço, mas a mão se agarrou a ele, e uma voz melancolicíssima soluçou: — Deixe-me entrar — deixe-me entrar! — Quem é você? — perguntei, lutando, entretanto, para me desprender. — Catherine Linton — respondeu ela, trêmula (por que pensei em Linton? Eu lera Earnshaw vinte vezes em vez de Linton) — voltei para casa: perdi o caminho na charneca! — Enquanto falava, discerni, obscuramente, um rosto de criança olhando pela janela. O terror me fez cruel; e, achando inútil tentar sacudir a criatura, puxei seu pulso sobre o vidro quebrado e esfreguei-o para lá e para cá até o sangue escorrer e ensopar a roupa de cama: ainda assim ela gemia: — Deixe-me entrar! — e mantinha a pegada tenaz, quase me enlouquecendo de medo. — Como posso! — disse eu por fim. — Solte-me, se quer que eu a deixe entrar! — Os dedos se afrouxaram, arranquei os meus pelo buraco, empilhei apressado os livros em pirâmide contra ele e tapei os ouvidos para excluir a lamentável súplica. Pareceu-me mantê-los fechados por mais de um quarto de hora; no entanto, no instante em que tornei a escutar, lá estava o choro dolente a gemer! — Vá embora! — gritei. — Nunca a deixarei entrar, nem que implore por vinte anos. — Faz vinte anos — lamentou a voz —, vinte anos. Sou uma abandonada há vinte anos! — Com isso começou um fraco arranhar do lado de fora, e a pilha de livros se moveu como se empurrada para a frente. Tentei saltar, mas não consegui mexer um membro; e assim gritei alto, num frenesi de pavor. Para minha confusão, descobri que o grito não era ideal: passos apressados se aproximaram da porta do meu quarto; alguém a empurrou, com mão vigorosa, e uma luz tremeluziu pelos quadrados no alto da cama. Eu ainda estava sentado, estremecendo e enxugando o suor da testa: o intruso pareceu hesitar e murmurou consigo mesmo. Por fim disse, em meio sussurro, claramente sem esperar resposta: — Há alguém aqui? — Julguei melhor confessar minha presença; pois reconheci o sotaque de Heathcliff e temi que ele procurasse mais longe, se eu ficasse quieto. Com essa intenção, virei-me e abri os painéis. Não esquecerei tão cedo o efeito que minha ação produziu.","heathcliffstoodneartheentranceinhisshirt~hathecouldhardlypickitup~268":"Heathcliff estava perto da entrada, de camisa e calças; com uma vela gotejando sobre os dedos e o rosto tão branco quanto a parede atrás dele. O primeiro rangido do carvalho o sobressaltou como um choque elétrico: a luz saltou-lhe da mão a uma distância de alguns pés, e sua agitação era tão extrema que ele mal conseguiu apanhá-la.","itisonlyyourguestsiricalledoutdesirousto~mareimsorryidisturbedyou~171":"— É só o seu hóspede, senhor — gritei, desejoso de poupá-lo da humilhação de expor mais a sua covardia. — Tive o infortúnio de gritar durante o sono, devido a um pesadelo pavoroso. Lamento tê-lo perturbado.","ohgodconfoundyoumrlockwoodiwishyouwereat~moutofthehousethismoment~293":"— Oh, que Deus o confunda, Sr. Lockwood! Quisera que estivesse no... — começou meu anfitrião, pondo a vela numa cadeira, por achar impossível mantê-la firme. — E quem o fez subir para este quarto? — continuou, cravando as unhas nas palmas e rangendo os dentes para dominar as convulsões maxilares. — Quem foi? Estou com vontade de pô-los todos para fora de casa neste instante!","itwasyourservantzillahirepliedflingingmy~ankyouforadozeinsuchaden~316":"— Foi a sua criada Zillah — respondi, atirando-me ao chão e retomando depressa as roupas. — Não me importaria que o fizesse, Sr. Heathcliff; ela bem merece. Suponho que quisesse obter outra prova de que o lugar é assombrado, à minha custa. Pois é — fervilha de fantasmas e duendes! O senhor tem razão em mantê-lo fechado, garanto. Ninguém lhe agradecerá por um cochilo em tal covil!","whatdoyoumeanaskedheathcliffandwhatareyo~uwerehavingyourthroatcut~182":"— Que quer dizer? — perguntou Heathcliff. — E o que está fazendo? Deite-se e termine a noite, já que está aqui; mas, pelo amor de Deus, não repita aquele barulho horrível: nada o poderia desculpar, a menos que lhe estivessem cortando a garganta!","ifthelittlefiendhadgotinatthewindowshepr~transgressionsivenodoubt~395":"— Se a pequena demônia tivesse entrado pela janela, provavelmente me teria estrangulado! — retruquei. — Não vou suportar de novo as perseguições dos seus hospitaleiros antepassados. O Reverendo Jabez Branderham não era parente seu por parte de mãe? E aquela atrevida, Catherine Linton, ou Earnshaw, ou como quer que se chamasse — deve ter sido uma criança trocada — alminha perversa! Disse-me que andava pela terra há vinte anos: justo castigo por suas transgressões mortais, não duvido!","scarcelywerethesewordsutteredwhenirecoll~etmeasleeplikecountingor~547":"Mal foram proferidas essas palavras, lembrei-me da associação do nome de Heathcliff ao de Catherine no livro, que me escapara completamente da memória até ser assim despertado. Corei por minha falta de consideração: mas, sem mostrar maior consciência da ofensa, apressei-me a acrescentar: — A verdade, senhor, é que passei a primeira parte da noite em... — Aqui parei de novo — ia dizer “examinando aqueles velhos volumes”, o que teria revelado meu conhecimento do seu conteúdo manuscrito, além do impresso; então, corrigindo-me, prossegui: — em soletrar o nome arranhado naquele peitoril. Ocupação monótona, calculada para me pôr a dormir, como contar, ou...","whatcanyoumeanbytalkinginthiswaytomethun~truckhisforeheadwithrage~146":"— Que quer dizer, falando assim comigo! — trovejou Heathcliff com selvagem veemência. — Como... como ousa, sob o meu teto? Deus! Está louco para falar assim! — E bateu na testa com raiva.","ididnotknowwhethertoresentthislanguageor~haveretiredtorestateight~717":"Não sabia se devia ressentir-me dessa linguagem ou prosseguir com a explicação; mas ele parecia tão poderosamente afetado que tive pena e prossegui com meus sonhos; afirmando que nunca ouvira a designação “Catherine Linton” antes, mas que, de tanto lê-la, produziu-se uma impressão que se personificou quando eu já não tinha a imaginação sob controle. Heathcliff foi recuando gradualmente para o abrigo da cama, enquanto eu falava; por fim sentou-se quase escondido atrás dela. Adivinhei, porém, pela respiração irregular e entrecortada, que lutava para vencer um excesso de violenta emoção. Não gostando de lhe mostrar que ouvira o conflito, continuei minha toalete com bastante ruído, olhei o relógio e monologuei sobre a duração da noite: — Ainda não são três horas! Poderia jurar que eram seis. O tempo estagna aqui: certamente nos recolhemos às oito!","alwaysatnineinwinterandriseatfoursaidmyh~sentsleeptothedevilforme~247":"— Sempre às nove no inverno, e levanto às quatro — disse meu anfitrião, reprimindo um gemido e, como imaginei, pelo movimento da sombra do braço, enxugando uma lágrima dos olhos. — Sr. Lockwood — acrescentou —, pode ir para o meu quarto: só atrapalharia, descendo tão cedo; e seu grito pueril mandou o sono para o diabo, no meu caso.","andformetooirepliedillwalkintheyardtilld~fficientcompanyinhimself~211":"— E no meu também — respondi. — Caminharei no pátio até clarear e então partirei; e não precisa temer uma repetição da minha intrusão. Estou agora completamente curado de buscar prazer na sociedade, seja do campo ou da cidade. Um homem sensato deveria achar companhia suficiente em si mesmo.","delightfulcompanymutteredheathclifftaket~thyouillcomeintwominutes~242":"— Deliciosa companhia! — murmurou Heathcliff. — Leve a vela e vá aonde quiser. Eu o acompanharei já. Fique fora do pátio, porém, os cães estão soltos; e a casa — Juno monta sentinela ali, e... não, só pode vagar pelos degraus e corredores. Mas fora daqui! Irei em dois minutos!","iobeyedsofarastoquitthechamberwhenignora~ionandblowingoutthelight~501":"Obedeci, ao menos a ponto de deixar o quarto; quando, ignorando aonde levavam os estreitos vestíbulos, parei e fui testemunha, involuntária, de um ato de superstição por parte do meu senhorio que desmentia, curiosamente, seu aparente bom senso. Ele subiu na cama e arrancou a janela, irrompendo, ao puxá-la, num incontrolável pranto. — Entre! Entre! — soluçou. — Cathy, venha. Oh, venha — mais uma vez! Oh! Querida do meu coração! Ouça-me desta vez, Catherine, enfim! — O espectro mostrou o ordinário capricho de espectro: não deu sinal de existir; mas a neve e o vento rodopiaram selvagemente por ali, chegando até meu posto e apagando a luz.","therewassuchanguishinthegushofgriefthata~lutedmewithaquerulousmew~457":"Havia tal angústia na torrente de dor que acompanhava esse delírio que minha compaixão me fez ignorar a loucura dele, e retirei-me, meio zangado por ter escutado e aborrecido por ter relatado meu ridículo pesadelo, já que produzira aquela agonia; embora o porquê estivesse além da minha compreensão. Desci cautelosamente às regiões inferiores e aterrissei na copa dos fundos, onde um clarão de fogo, recolhido compactamente, me permitiu reacender a vela. Nada se movia, exceto um gato pardo, acinzentado, que rastejou das cinzas e me saudou com um miado queixoso.","twobenchesshapedinsectionsofacirclenearl~partedassolemnlyashecame~708":"Dois bancos, em forma de seções de círculo, quase cercavam a lareira; num deles me estendi, e Grimalkin subiu no outro. Ambos cabeceávamos antes que alguém invadisse nosso retiro, e então foi Joseph, descendo arrastando os pés por uma escada de madeira que desaparecia no teto, por um alçapão: a subida ao seu sótão, suponho. Lançou um olhar sinistro à chamazinha que eu atraíra para brincar entre as grades, varreu o gato de sua elevação e, acomodando-se no lugar vago, iniciou a operação de encher de tabaco um cachimbo de três polegadas. Minha presença em seu santuário foi evidentemente julgada uma impudência vergonhosa demais para comentário: silenciosamente levou o tubo aos lábios, cruzou os braços e tragou. Deixei-o gozar o luxo sem o importunar; e, depois de chupar sua última baforada e soltar um profundo suspiro, levantou-se e partiu tão solenemente quanto viera.","amoreelasticfootstepenterednextandnowiop~stgoifichangedmylocality~612":"Entrou em seguida um passo mais elástico; e agora abri a boca para um “bom dia”, mas fechei-a de novo, a saudação não realizada; pois Hareton Earnshaw fazia sua oração sotto voce, numa série de pragas dirigidas a cada objeto que tocava, enquanto revirava um canto à procura de uma pá ou enxada para cavar através dos montes de neve. Olhou por cima do encosto do banco, dilatando as narinas, e pensou tão pouco em trocar civilidades comigo quanto com meu companheiro, o gato. Adivinhei, por seus preparativos, que a saída era permitida e, deixando meu duro leito, fiz um movimento para segui-lo. Ele notou e empurrou uma porta interior com a ponta da pá, indicando por um som inarticulado que era ali o lugar aonde eu devia ir, se mudasse de lugar.","itopenedintothehousewherethefemaleswerea~andheaveanindignantgroan~583":"Abria para a casa, onde as mulheres já estavam de pé; Zillah avivando línguas de chama chaminé acima com um fole colossal; e a Sra. Heathcliff, ajoelhada na lareira, lendo um livro à luz das chamas. Mantinha a mão interposta entre o calor da fornalha e os olhos e parecia absorta em sua ocupação; desistindo dela apenas para repreender a criada por cobri-la de faíscas, ou para empurrar um cão que, de vez em quando, enfiava o focinho com excessiva ousadia em seu rosto. Surpreendi-me ao ver Heathcliff também ali. Estava junto ao fogo, de costas para mim, terminando uma cena tempestuosa com a pobre Zillah; a qual, de quando em quando, interrompia o trabalho para levantar a ponta do avental e soltar um gemido indignado.","andyouyouworthlesshebrokeoutasienteredtu~ghtdoyouheardamnablejade~327":"— E você, sua imprestável... — explodiu ele quando entrei, voltando-se para a nora e empregando um epíteto tão inofensivo quanto pato, ou ovelha, mas em geral representado por um traço —. — Aí está você, de novo com suas vadiagens! Os outros ao menos ganham o pão — você vive da minha caridade! Guarde essa porcaria e arranje o que fazer. Pagará a praga de tê-la eternamente diante dos meus olhos — está ouvindo, megera maldita?","illputmytrashawaybecauseyoucanmakemeifir~ngueoutexceptwhatiplease~169":"— Guardarei minha porcaria, porque o senhor pode me obrigar se eu recusar — respondeu a jovem, fechando o livro e atirando-o numa cadeira. — Mas não farei nada, ainda que o senhor jure até perder a língua, exceto o que me aprouver!","heathcliffliftedhishandandthespeakerspra~llandcoldasimpalpableice~607":"Heathcliff ergueu a mão, e a oradora saltou para uma distância mais segura, obviamente conhecedora do seu peso. Sem desejo de ser entretido por um combate de cão e gato, avancei vivamente, como ansioso por participar do calor da lareira e inocente de qualquer conhecimento da disputa interrompida. Cada um teve decoro suficiente para suspender novas hostilidades: Heathcliff pôs os punhos, para fugir à tentação, nos bolsos; a Sra. Heathcliff torceu o lábio e caminhou para um assento distante, onde cumpriu a palavra fazendo papel de estátua durante o resto da minha estada. Não foi longa. Recusei juntar-me ao café da manhã deles e, ao primeiro clarão da aurora, aproveitei uma oportunidade de escapar para o ar livre, agora limpo, parado e frio como gelo impalpável.","mylandlordhalloedformetostopereireachedt~ctlythewindingsoftheroad~834":"Meu senhorio gritou para que eu parasse antes de eu chegar ao fim do jardim e ofereceu-se para me acompanhar através da charneca. Foi bom que o fizesse, pois todo o dorso da colina era um oceano branco e ondulante; as vagas e quedas não indicando elevações e depressões correspondentes no terreno: muitos buracos, pelo menos, estavam nivelados; e cadeias inteiras de montículos, refugo das pedreiras, apagavam-se do mapa que minha caminhada de ontem deixara pintado em minha mente. Eu notara, de um lado da estrada, a intervalos de seis ou sete jardas, uma fileira de pedras erguidas, prolongada por toda a extensão do ermo: estas foram erguidas e caiadas de propósito para servir de guia no escuro, e também quando uma nevada como a presente confundia os pântanos profundos de ambos os lados com o caminho mais firme: mas, exceto por um ponto sujo aqui e ali apontando para cima, todos os vestígios de sua existência haviam sumido: e meu companheiro achou necessário advertir-me frequentemente para guiar à direita ou à esquerda, quando eu imaginava seguir corretamente as sinuosidades da estrada.","weexchangedlittleconversationandhehalted~lwayfromwutheringheights~539":"Trocamos pouca conversa, e ele parou à entrada de Thrushcross Park, dizendo que ali eu não poderia errar. Nossos adeuses limitaram-se a uma reverência apressada, e então segui adiante, confiando em meus próprios recursos; pois a guarita do porteiro ainda está desabitada. A distância do portão à granja é de duas milhas; creio que consegui fazê-la quatro, entre perder-me por entre as árvores e afundar até o pescoço na neve: situação que só quem a experimentou pode avaliar. Seja como for, quaisquer que fossem minhas andanças, o relógio batia doze horas quando entrei em casa; e isso dava exatamente uma hora por milha do caminho usual desde Wuthering Heights.","myhumanfixtureandhersatellitesrushedtowe~preparedformyrefreshment~494":"Minha companheira humana de instalação e seus satélites correram a me receber; exclamando, tumultuosamente, que tinham desistido de mim por completo: todos conjeturavam que eu perecera na noite passada; e perguntavam-se como deveriam proceder na busca dos meus restos. Pedi-lhes que se acalmassem, agora que me viam de volta e, entorpecido até o fundo do coração, arrastei-me escada acima; de onde, depois de vestir roupas secas e andar de lá para cá por trinta ou quarenta minutos para restaurar o calor animal, retirei-me ao escritório, fraco como um gatinho: quase fraco demais para apreciar o fogo alegre e o café fumegante que a criada preparara para meu reconforto."}$tr$::jsonb, 161)
